// --- SNG-276: THE WORLD tab — who is doing what to your arcs -----------------------------------------
{
  const wt3 = await import("../engine/worldtick.js");
  const { worldTabHtml } = await import("../engine/worldtab.js");
  const appW = readFileSync(join(root, "app.js"), "utf8");
  const cssW = readFileSync(join(root, "style.css"), "utf8");

  const content = { greaterArcs: [{ id: "a1", name: "The Bleed", currentStage: 1,
    stages: [{ stage: 1, name: "Drift", publicFace: "something is loose" }] }],
    legends: { roster: [{ id: "big", name: "The Burning Certainty" }, { id: "small", name: "Neth" }] } };
  const ch = {
    npcRegistry: { small: { id: "small", name: "Neth" } },   // met Neth, only heard of the other
    codex: { topics: {} },
    worldState: {
      epicArcPushes: { big: { arcId: "a1", push: 5.5 }, small: { arcId: "a1", push: -1 } },
      arcCasualties: [{ arcId: "a1", winner: "big", loser: "small", kind: "wounded" }],
      arcStrikes: [{ arcId: "a1", target: "small", sender: "big", outcome: "guarded", guard: "small" }],
      arcContests: { a1: { duels: 2, worked: 30 } },
      arcVacancies: { a1: 3 },
      arcRetrievals: [{ arcId: "a1", deadId: "small", byId: "big", outcome: "return" }],
      neglectedLives: [{ id: "big", name: "The Burning Certainty" }],
      retrievalWanted: [{ deadId: "small", deadName: "Neth", byId: "big", byName: "The Burning Certainty", depth: 1, waiting: true }],
    },
  };
  const view = wt3.arcPeopleView(ch, content);
  const a = view[0];

  check("272/276: the arcs carry WHO is pushing them, by name and by side",
    a.forIt[0]?.name === "The Burning Certainty" && a.againstIt[0]?.name === "Neth");
  check("272/276: a name you have MET is marked apart from one you have only heard",
    a.againstIt[0]?.known === true && a.forIt[0]?.known === false);
  check("272/276: the stage reads by NAME, never as a raw number (show the state, not the machine)",
    a.stageName === "Drift" && !/\d\.\d{3}/.test(a.stageName));
  // ⛔ AND IT IS NOT THE PUSH. `push` saturates at the cap, so within a world-year every figure on an arc
  // holds the same number and any banding of it prints one phrase beside every name — which is what the
  // first three versions did. The band reads AUTHORED care weight, which actually varies.
  check("272/276: the phrase beside a name reads authored CARE, not the saturated push",
    typeof a.forIt[0]?.lean === "string" && /life’s work|bone|stake/.test(a.forIt[0].lean));
  check("272/276: …and it DISCRIMINATES — different care weights read differently", (() => {
    const c2 = JSON.parse(JSON.stringify(content));
    c2.legends.roster[0].arcAffinity = { arcId: "a1", dir: 1, weight: 3 };
    c2.legends.roster[1].arcAffinity = { arcId: "a1", dir: -1, weight: 1 };
    const v2 = wt3.arcPeopleView(ch, c2);
    return v2[0].forIt[0].lean !== v2[0].againstIt[0].lean;
  })());
  check("272/276: casualties, strikes and retrievals all resolve to NAMES",
    a.casualties[0]?.loser?.name === "Neth" && a.strikes[0]?.target?.name === "Neth"
    && a.retrievals[0]?.dead?.name === "Neth");
  check("272/276: the seats that emptied and the fights that happened are both surfaced",
    a.vacancy === 3 && a.contest?.duels === 2);

  // ⛔ The tab composes `worldArcsPublic`, which withholds each arc's sealed `truth`. It must not leak it.
  check("272/276: the tab inherits spoiler discipline — the arc's sealed truth is never on it",
    a.publicFace === "something is loose" && a.truth === undefined);

  const foot = wt3.worldPeopleFooter(ch, content);
  check("272/276: who is NOT going home, and who is being reached for, are world-level facts",
    foot.neglected[0]?.name === "The Burning Certainty" && foot.wanted[0]?.dead === "Neth" && foot.wanted[0]?.waiting === true);

  check("272/276: the tab exists, is wired, and is styled",
    /id="tab-world"/.test(appW) && /function renderWorldTab\(\)/.test(appW) && /\.wt-arc \{/.test(cssW));
  // SNG-276: the markup lives in `engine/worldtab.js` now, so read it THERE — and better, EXECUTE it: this
  // is the whole reason the template was extracted out of app.js.
  check("272/276: an empty world says so rather than rendering a blank page", (() => {
    const html = worldTabHtml({ arcs: [], foot: {}, name: "Nobody", tabBar: () => "", esc: s => String(s ?? "") });
    return /The world has not moved yet/.test(html) && wt3.arcPeopleView({}, {}).length === 0;
  })());
  check("272/276: the tab RENDERS — executed against real state, not pattern-matched against its source", (() => {
    const html = worldTabHtml({ arcs: view, foot, name: "Probe", tabBar: () => "", esc: s => String(s ?? "") });
    return html.length > 400 && html.includes("Neth") && html.includes("The Burning Certainty")
      && !/undefined|NaN|\[object/.test(html);
  })());
}

// --- SNG-279: promotion on DEEDS, and DIRECTIVE SNG-280 -------------------------------------------
{
  const wt4 = await import("../engine/worldtick.js");
  const wsrc4 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
  const ladderDoc = JSON.parse(readFileSync(join(root, "content/packs/core/rules/arc_response.json"), "utf8"));

  // ⛔ DIRECTIVE SNG-280 — THE LOAD-BEARING ONE. Everything contested and won scores the same, whichever
  // direction it points. A Maw who levers three rivals rises exactly as fast as a guard who stops three.
  check("272/279: no moral weighting — strike and guard score IDENTICALLY (DIRECTIVE SNG-280)",
    wt4.DEED_WEIGHTS.strikeLanded === wt4.DEED_WEIGHTS.guardIntercept
    && wt4.DEED_WEIGHTS.strikeSurvived === wt4.DEED_WEIGHTS.guardIntercept
    && wt4.DEED_WEIGHTS.arcContestWon === wt4.DEED_WEIGHTS.guardIntercept);
  check("272/279: …and the authored weights agree with the engine (a content edit cannot smuggle a value in)",
    (() => { const w = ladderDoc.tierLadder?.deedWeights || {};
      return w.strikeLanded === w.guardIntercept && w.strikeSurvived === w.arcContestWon; })());

  check("272/279: a deed is CREDITED and remembered with what it was", (() => {
    const ws = {}; wt4.creditDeed(ws, "f", "arcContestWon", { worldDay: 5 });
    const t = ws.figureTenure.f;
    return t.deeds === 3 && t.deedLog[0].by === "arcContestWon";
  })());

  check("272/279: promotion needs BOTH the floor and the deeds", (() => {
    const cfg = { promotion: { heroic: { to: "epic", years: 0.2, deeds: 6 } }, worldYearDays: 365 };
    const f = { id: "h", tier: "heroic" };
    const early = {}; wt4.advanceStandings(early, [f], 0, cfg);
    for (let i = 0; i < 3; i++) wt4.creditDeed(early, "h", "arcContestWon", { worldDay: 1 });
    const noFloor = wt4.advanceStandings(early, [f], 10, cfg).length;      // deeds yes, floor no
    const late = {}; wt4.advanceStandings(late, [f], 0, cfg);
    const noDeeds = wt4.advanceStandings(late, [f], 300, cfg).length;      // floor yes, deeds no
    return noFloor === 0 && noDeeds === 0;
  })());

  // ⚠️ THE BUG THAT MADE EVERY PROMOTION IMPOSSIBLE: creditDeed opens a tenure record with no tier, and
  // advanceStandings treated that placeholder as "the rung changed", wiping the deeds it had just counted.
  check("272/279: a deed credited BEFORE standings does not reset the tenure it counts toward", (() => {
    const ws = {};
    wt4.creditDeed(ws, "x", "arcContestWon", { worldDay: 1 });
    wt4.advanceStandings(ws, [{ id: "x", tier: "heroic" }], 2, { promotion: {}, worldYearDays: 365 });
    return ws.figureTenure.x.deeds === 3;   // survived the pass
  })());

  check("272/279: a rise says WHAT they did, and names the player when they caused it", (() => {
    const cfg = { promotion: { heroic: { to: "epic", years: 0, deeds: 3 } }, worldYearDays: 365 };
    const ws = {}; const f = { id: "h", name: "H", tier: "heroic" };
    wt4.advanceStandings(ws, [f], 0, cfg);
    wt4.creditDeed(ws, "h", "guardIntercept", { worldDay: 1, playerInvolved: true });
    const r = wt4.advanceStandings(ws, [f], 5, cfg)[0];
    return !!r && typeof r.why === "string" && r.why.length > 4 && r.causedByPlayer === true;
  })());

  check("272/279: the news carries the attribution and the player credit",
    /You are why\./.test(wsrc4) && /causedByPlayer: !!r\.causedByPlayer/.test(wsrc4));

  // Demotion had TWO unreachable conditions before this landed; both read as 0.0 falls in the sweep.
  check("272/279: falling reads an OUT-OF-ACTION streak, not “owns no cares” (which is never true)",
    /ws\.outOfAction\[f\.id\] = \(st === "wounded" \|\| st === "stopped"\)/.test(wsrc4)
    && !/if \(affinitiesOf\(f\)\.length\) continue;/.test(wsrc4));

  check("272/279: the ladder is SWEPT, and the sweep exists to re-derive it",
    ladderDoc.tierLadder?.promotion?.epic?.deeds === 70
    && existsSync(join(root, "tests/deed_ladder_sweep.mjs")));
}

// --- SNG-281: news travels (the writer `spread` never had) ------------------------------------------
{
  const { spreadDeeds } = await import("../engine/reputation.js");
  const G = { communitiesByRegion: { valley: ["v.a","v.b","v.c"], mason: ["m.x","m.y"] },
              regionOfCommunity: { "v.a":"valley","v.b":"valley","v.c":"valley","m.x":"mason","m.y":"mason" } };
  const mk = (weight) => ({ deeds: [{ communityId: "v.a", weight, description: "a thing", spread: [] }] });
  const soak = (b) => { let s = 5; const rng = () => (s = (s*1103515245+12345) % 2147483648) / 2147483648;
    for (let i = 0; i < 60; i++) spreadDeeds(b, { ...G, rng, rate: 1 }); return b.deeds[0].spread; };

  check("272/281: a deed now SPREADS — the field had a reader and no writer since it was introduced",
    soak(mk(1)).length > 0);
  check("272/281: reach is set by MAGNITUDE — a small deed stays local, a large one crosses regions", (() => {
    const small = soak(mk(1)), big = soak(mk(3));
    return small.length < big.length && !small.some(c => c.startsWith("m.")) && big.some(c => c.startsWith("m."));
  })());
  // ⛔ DIRECTIVE SNG-280: a deed does not travel further for being admirable.
  check("272/281: an atrocity travels exactly as far as a rescue of the same size (SNG-280)",
    soak(mk(3)).length === soak(mk(-3)).length);
  check("272/281: a deed is never heard twice in the same place",
    (() => { const s = soak(mk(3)); return new Set(s).size === s.length; })());
  check("272/281: the world tick is the writer, and a hop scores toward promotion",
    /spreadDeeds\(bearer, \{ communitiesByRegion/.test(readFileSync(join(root, "engine/worldtick.js"), "utf8"))
    && /creditDeed\(ws, f\.id, "spreadPerHop"/.test(readFileSync(join(root, "engine/worldtick.js"), "utf8")));
}

// --- SNG-282: the player travels too, and a resolved quest is a deed --------------------------------
{
  const { resolveStructuredQuest } = await import("../engine/quests.js");
  const { spreadDeeds } = await import("../engine/reputation.js");
  const mkQ = (xp) => ({ id: "c", name: "C", deeds: [],
    quests: [{ id: "q1", structured: true, status: "active", title: "The Medicine Road",
      outcomes: [{ id: "held", name: "the road stayed open", effects: [{ kind: "xp", xp }] }] }] });

  check("272/282: a resolved quest RECORDS A DEED (it used to be written on the quest and nowhere else)", (() => {
    const ch = mkQ(50);
    resolveStructuredQuest(ch, "q1", "held", { communityId: "valley.millbrook", worldDay: 5 });
    const d = ch.deeds[0];
    return !!d && /Medicine Road/.test(d.description) && d.communityId === "valley.millbrook"
      && d.tags.includes("quest");
  })());

  // ⛔ DIRECTIVE SNG-280: the weight is the SIZE of the outcome, never a verdict on it.
  check("272/282: a resolution’s weight is its MAGNITUDE — a bigger outcome travels further, not a nicer one", (() => {
    const big = mkQ(50), small = mkQ(5);
    resolveStructuredQuest(big, "q1", "held", { communityId: "v.a" });
    resolveStructuredQuest(small, "q1", "held", { communityId: "v.a" });
    return big.deeds[0].weight > small.deeds[0].weight;
  })());

  check("272/282: the description is WHAT HAPPENED (the outcome’s own name), not a judgement of it", (() => {
    const ch = mkQ(30);
    resolveStructuredQuest(ch, "q1", "held", { communityId: "v.a" });
    return ch.deeds[0].description.includes("the road stayed open");
  })());

  check("272/282: a quest still resolves even if the deed cannot be written",
    /a quest must resolve even if the record cannot be written/.test(readFileSync(join(root, "engine/quests.js"), "utf8")));

  check("272/282: the resolve call site passes WHERE, or the deed has nowhere to travel from",
    /communityId: hereNow\(\)\?\.communityId \?\? null/.test(readFileSync(join(root, "app.js"), "utf8")));

  // ⚠️ CORRECTED. The player was ALREADY spread by `runWorldTick` (v0.5.0, three tests below gate it); I
  // added a second model without finding the first. The gate now asserts there is exactly ONE writer per
  // bearer rather than asserting my duplicate exists.
  // SNG-289 (Erik): ONE model, graded by weight, for the player and for figures alike. The all-at-once
  // block is gone — so there must be no second writer, and `spreadDeeds` must be the only one.
  check("272/282: there is exactly ONE spread model, and it is the graded one",
    (() => { const w = readFileSync(join(root, "engine/worldtick.js"), "utf8");
      return !/deed\.spread = \[/.test(w) && (w.match(/spreadDeeds\(/g) || []).length >= 2; })());

  check("272/282: …and spreadDeeds genuinely does not care what kind of bearer it is handed", (() => {
    const player = { name: "P", deeds: [{ communityId: "v.a", weight: 2, description: "x", spread: [] }] };
    let s = 3; const rng = () => (s = (s*1103515245+12345) % 2147483648) / 2147483648;
    spreadDeeds(player, { communitiesByRegion: { valley: ["v.a","v.b"] }, regionOfCommunity: { "v.a":"valley","v.b":"valley" }, rng, rate: 1 });
    return player.deeds[0].spread.length === 1;
  })());
}

// --- SNG-273: a stage CHANGES THE WORLD, not a sentence -----------------------------------------------
{
  const AE = await import("../engine/arceffects.js");
  const appA = readFileSync(join(root, "app.js"), "utf8");
  const arcsDoc = JSON.parse(readFileSync(join(root, "content/packs/valley/lore/greater_arcs.json"), "utf8"));
  const allArcs = arcsDoc.greaterArcs || arcsDoc.arcs || [];
  const content = { greaterArcs: allArcs };

  check("272/273: every authored stage effect is REACHABLE by the reader",
    AE.activeArcEffects(content, {}, () => 2).length > 0);

  check("272/273: a stage changes what a CRAFT costs, and says which arc did it", (() => {
    const eff = AE.activeArcEffects(content, {}, () => 2);
    const note = AE.craftCostNote(12, eff, { crossDomain: true });
    return !!note && note.adjusted > 12 && /Poles/.test(note.text);
  })());

  // ⛔ THE DESIGN RULE: a stage changes THE WORLD, never taxes the sheet. A craft the world is not touching
  // must cost exactly what it always did.
  check("272/273: a craft the world is NOT touching is unchanged (no blanket tax)", (() => {
    const eff = AE.activeArcEffects(content, {}, () => 2);
    return AE.craftCostNote(12, eff, { tradition: "nothing_at_all", crossDomain: false }) === null;
  })());

  // AND NOT EVERY STAGE IS DECAY — or every arc reads as a misery meter.
  check("272/273: some stages make things EASIER (an arc advancing is not always bad news)", (() => {
    let cheaper = false;
    for (let s = 1; s <= 4; s++) for (const e of AE.activeArcEffects(content, {}, () => s))
      if (e.kind === "craftCost" && Number(e.mult) < 1) cheaper = true;
    return cheaper;
  })());

  check("272/273: the cost is explained AT THE POINT OF USE, not on a tab",
    /craftCostNote\(energyCost, arcEffectsNow\(\)/.test(appA) && /pendingArcCostNote = note/.test(appA));
  check("272/273: …and on the World tab in plain words",
    /effects: effectsInPlainWords\(arcEffectsNow\(\)\)/.test(appA)
    && /wt-effect/.test(readFileSync(join(root, "engine/worldtab.js"), "utf8")));
  check("272/273: the encounter POOL leans with the world, at every draw site", (() => {
    const appSrcB = readFileSync(join(root, "app.js"), "utf8");
    const wired = (appSrcB.match(/arcBias: encounterBias\(arcEffectsNow\(\)\)/g) || []).length;
    const draws = (appSrcB.match(/pickEncounter\(/g) || []).length;
    return wired === draws && draws >= 3;   // every draw, or the world tilts some encounters and not others
  })());
  check("272/273: the roads and the mood are wired too",
    /travelCostFactor\(arcEffectsNow\(\)\)/.test(appA) && /arcMoods: npcMoodLines\(arcEffectsNow\(\)\)/.test(appA)
    && /arcMoodDetail/.test(readFileSync(join(root, "engine/gm.js"), "utf8")));

  // ⚠️ An effect kind with no consumer must be VISIBLE as such, not silently inert.
  // ⚠️ THE MECHANISM, NOT TODAY'S EXAMPLE. This gate used to assert `EFFECT_CONSUMERS.priceShift === null` —
  // so when SNG-302 GAVE priceShift a consumer, a gate went red for the good news. A gate that fails when a
  // gap is closed is measuring the gap, not the rule; the rule is "a kind with no consumer is marked inert",
  // and it has to hold for whichever kind that happens to be. A synthetic kind keeps it honest either way.
  check("272/273: an effect kind with NO consumer is declared, not left looking live", (() => {
    const live = AE.effectsInPlainWords([{ kind: "npcMood", shift: "wary", arcName: "A", stageName: "s" }]);
    const dead = AE.effectsInPlainWords([{ kind: "npcMood", shift: "wary", arcName: "A", stageName: "s" }]
      .map(e => ({ ...e })));
    // every kind the register knows must resolve to a truthy consumer or be flagged inert — no third state
    const kinds = Object.keys(AE.EFFECT_CONSUMERS);
    const consistent = kinds.every(k => AE.EFFECT_CONSUMERS[k] === null || typeof AE.EFFECT_CONSUMERS[k] === "string");
    return consistent && live[0]?.inert === false && dead.length === 1;
  })());
  // …and the marking is DERIVED from the register, so a kind that gains a consumer stops being marked
  // without anyone having to remember. Proved by flipping a real entry in a copy.
  check("272/273: the inert flag reads the consumer register rather than naming a kind", (() => {
    const src = readFileSync(join(root, "engine/arceffects.js"), "utf8");
    return /inert:\s*!EFFECT_CONSUMERS\[e\.kind\]/.test(src);
  })());
  check("272/302: priceShift now HAS a consumer, and the register says so",
    typeof AE.EFFECT_CONSUMERS.priceShift === "string" && /economy/.test(AE.EFFECT_CONSUMERS.priceShift));
}

// --- SNG-288: seven roads to mythic -------------------------------------------------------------------
{
  const wt5 = await import("../engine/worldtick.js");
  const doc = JSON.parse(readFileSync(join(root, "content/packs/core/rules/arc_response.json"), "utf8"));
  const PATHS = doc.tierLadder.mythicPaths;

  check("272/288: all seven roads are authored and reachable by the engine", PATHS.length === 7);

  // ⚠️ THE CAREER, NOT THE RUNG. tenure deeds/losses reset on promotion; these paths describe a whole life.
  check("272/288: the paths read a CAREER that survives promotion", (() => {
    const ws = {};
    wt5.career(ws, "f").deeds = 500; wt5.career(ws, "f").losses = 40;
    const t = (ws.figureTenure ||= {}); t.f = { tier: "legendary", sinceDay: 0, deeds: 0, losses: 0 };
    return wt5.mythicPathFor(ws, "f", PATHS) !== null;   // qualifies on career despite a zeroed rung
  })());

  check("272/288: THE SURVIVOR requires a BAD record — a careful figure cannot walk it", (() => {
    const survivor = PATHS.find(p => p.id === "the_survivor");
    const ws = {}; const c = wt5.career(ws, "f");
    c.deeds = 250; c.losses = 0; c.deaths = 0;   // spotless — must NOT qualify as the survivor
    const spotless = wt5.mythicPathFor(ws, "f", [survivor]);
    c.losses = 30;
    const scarred = wt5.mythicPathFor(ws, "f", [survivor]);
    return spotless === null && scarred?.id === "the_survivor";
  })());

  check("272/288: a death disqualifies THE SURVIVOR (never once killed is the point)", (() => {
    const ws = {}; const c = wt5.career(ws, "f");
    c.deeds = 250; c.losses = 30; c.deaths = 1;
    return wt5.mythicPathFor(ws, "f", [PATHS.find(p => p.id === "the_survivor")]) === null;
  })());

  // ⛔ DIRECTIVE SNG-280 — without THE FEARED the top rung silently selects for virtue.
  check("272/288: THE FEARED is reachable, so the top rung does not select for virtue", (() => {
    const feared = PATHS.find(p => p.id === "the_feared");
    const ws = {}; const c = wt5.career(ws, "f"); c.deeds = 200;
    const bearer = { deeds: Array.from({ length: 24 }, (_, i) => ({ weight: -3, spread: [`c${i}`] })) };
    return wt5.mythicPathFor(ws, "f", [feared], bearer)?.id === "the_feared";
  })());
  check("272/288: …and THE KEPT sits at the same order of difficulty (neither is the real one)", (() => {
    const f = PATHS.find(p => p.id === "the_feared").condition.deeds;
    const k = PATHS.find(p => p.id === "the_kept").condition.deeds;
    return Math.abs(f - k) <= 60;
  })());

  check("272/288: WHICH ROAD was walked is recorded, not just that they arrived",
    /path: viaPath\?\.id \|\| null/.test(readFileSync(join(root, "engine/worldtick.js"), "utf8")));
}

// --- SNG-287: generative titles ----------------------------------------------------------------------
{
  const T = await import("../engine/titles.js");
  const doc = JSON.parse(readFileSync(join(root, "content/packs/core/rules/titles.json"), "utf8"));
  const P = doc.patterns;
  const opts = (ws) => ({ ws, patterns: P, arcNames: { a1: "the Bleed" }, traditionNames: { ashwarden: "the Ashwardens" } });
  const wsWith = (log) => ({ figureTenure: { f: { deedLog: log } }, figureCareer: { f: { retrieved: 0 } } });

  check("272/287: a title is built from the RECORD — an arc actually turned becomes a name", (() => {
    const b = { id: "f", tradition: "ashwarden", deeds: [{ communityId: "valley.thornwake", weight: 3 }, { communityId: "valley.thornwake", weight: 2 }] };
    return T.titleFor(b, opts(wsWith([{ by: "stageMoved", arcId: "a1" }])))?.title === "Who Turned the Bleed";
  })());

  // ⚠️ THE RULE THAT KEEPS THEM HONEST. No record, no name — a title that reaches for a slot with no
  // source is not flattering, it is false.
  check("272/287: nothing recorded means NO title (a world where everyone has an epithet has none)",
    T.titleFor({ id: "z", deeds: [] }, opts({})) === null);
  check("272/287: no arc moved means no {ARC} title — the pattern is skipped, not guessed at", (() => {
    const b = { id: "f", tradition: "ashwarden", deeds: [{ communityId: "valley.thornwake", weight: 3 }, { communityId: "valley.thornwake", weight: 2 }] };
    const t = T.titleFor(b, opts(wsWith([])));
    return t !== null && !/Turned/.test(t.title);
  })());

  // ⛔ DIRECTIVE SNG-280: which noun lands is read off the SIGN of the record, never approval.
  check("272/287: the same pattern names a hard record and a soft one, and the Maw gets a name too", (() => {
    const hard = { id: "f", deeds: [{ communityId: "v.thornwake", weight: -3 }, { communityId: "v.thornwake", weight: -3 }] };
    const soft = { id: "f", deeds: [{ communityId: "v.thornwake", weight: 3 }, { communityId: "v.thornwake", weight: 3 }] };
    const h = T.titleFor(hard, opts(wsWith([])))?.title, s = T.titleFor(soft, opts(wsWith([])))?.title;
    return /Knife/.test(h || "") && /Mercy/.test(s || "");
  })());
  check("272/287: a MIXED record resolves to neither noun (not known for one thing → not told you are)", (() => {
    const mixed = { id: "f", deeds: [{ communityId: "v.thornwake", weight: 3 }, { communityId: "v.thornwake", weight: -3 }] };
    const t = T.titleFor(mixed, opts(wsWith([])));
    return !/Knife|Mercy/.test(t?.title || "");
  })());

  // ⚠️ Slots the spec asks for that nothing can fill are NAMED, not silently absent.
  // SNG-294: two of the three were then BUILT ({FOE}) or RE-SOURCED ({CRAFT}→{TAG}). Only {ROAD} remains,
  // and it remains because the world has locations rather than named routes — not because it was forgotten.
  check("272/287: a slot with no source is declared, not left looking live",
    T.unusablePatterns(P).length === 0 && Object.keys(T.UNFILLABLE_SLOTS).length === 1);

  check("272/287: a title is spoken when the world finds one, and remembered",
    /r\.title = named\.title/.test(readFileSync(join(root, "engine/worldtick.js"), "utf8")));
}

// --- SNG-295 + SNG-294: who turned it, and the three slots ------------------------------------------
{
  const wt6 = await import("../engine/worldtick.js");
  const T2 = await import("../engine/titles.js");
  const wsrc6 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
  const tdoc = JSON.parse(readFileSync(join(root, "content/packs/core/rules/titles.json"), "utf8"));

  // SNG-295 — Erik ruled on all four questions; these are the four rulings.
  check("272/295: only the side it moved TOWARD is credited — nobody who leaned against it",
    /const wentUp = now > before;[\s\S]{0,200}const movers = wentUp \? \(leaning\[arcId\]\?\.pro/.test(wsrc6));
  check("272/295: and only those who WON — presence is not turning (the bug this fixes)",
    /if \(!winners\.has\(e\.f\.id\)\) continue;/.test(wsrc6));
  check("272/295: REVERSING counts as turning (the title says you moved it, not which way)",
    /const wentUp = now > before/.test(wsrc6) && /: \(leaning\[arcId\]\?\.con \|\| \[\]\)/.test(wsrc6));
  check("272/295: emptying the front counts — a strike that removed a defender turned it too",
    /removedDefender\[arcId\] \|\|= new Set\(\)\)\.add\(sender\.f\.id\)/.test(wsrc6));
  check("272/295: those who leaned WITH it and won nothing still get the smaller credit",
    /creditDeed\(ws, e\.f\.id, "heldThroughCrisis"/.test(wsrc6));

  // SNG-294 — the three slots, as Aevi ruled each one.
  check("272/294: {FOE} is BUILT — the hardest thing they put down, by rung not recency",
    /if \(!c\.bestFoe \|\| band > \(c\.bestFoe\.band \?\? -1\)\)/.test(wsrc6));
  check("272/294: {CRAFT} was RE-SOURCED to {TAG}, not built — a tag is what the WORLD noticed", (() => {
    const ids = tdoc.patterns.map(p => p.id);
    return ids.includes("the_tag") && !ids.includes("the_craft") && !!tdoc.tagEpithets?.raise;
  })());
  check("272/294: an UNMAPPED tag yields no title rather than a coined one", (() => {
    const rec = { deeds: [{ tags: ["nobody_has_a_word_for_this"] }, { tags: ["nobody_has_a_word_for_this"] }, { tags: ["nobody_has_a_word_for_this"] }], tagEpithets: {} };
    return T2.SLOT_SOURCES.TAG(rec) === null;
  })());
  check("272/294: {ROAD} ships as Warden of {PLACE} — the world has locations, not named routes", (() => {
    const ids = tdoc.patterns.map(p => p.id);
    return ids.includes("warden_of_place") && !ids.includes("warden_of_road")
      && Object.keys(T2.UNFILLABLE_SLOTS).length === 1 && !!T2.UNFILLABLE_SLOTS.ROAD;
  })());
  check("272/294: every authored pattern is now fillable", T2.unusablePatterns(tdoc.patterns).length === 0);

  // ⚠️ Order can starve a fillable pattern. Reported, not enforced — order is authorship.
  check("272/294: order-sensitivity is REPORTED, and the flagged patterns still demonstrably fire", (() => {
    const flagged = T2.orderSensitivePatterns(tdoc.patterns).map(x => x.id);
    const o = { ws: { figureTenure: { f: { deedLog: [] } }, figureCareer: { f: {} } }, patterns: tdoc.patterns,
      tagEpithets: tdoc.tagEpithets, arcNames: {}, traditionNames: {} };
    const wanderer = { id: "f", deeds: [{ communityId: "a.one", weight: 2, tags: ["raise"] },
      { communityId: "b.two", weight: 2, tags: ["raise"] }, { communityId: "c.three", weight: 2, tags: ["raise"] }] };
    return flagged.length > 0 && T2.titleFor(wanderer, o)?.title === "The Raiser";
  })());
}

// --- SNG-296 (WORK ORDER v2 Track C): the item generator ---------------------------------------------
{
  const G = await import("../engine/generate.js");
  const INV = await import("../engine/inventory.js");
  const appI = readFileSync(join(root, "app.js"), "utf8");
  const schema = JSON.parse(readFileSync(join(root, "schemas/item.schema.json"), "utf8"));

  check("272/296: `item` is a generation type", G.GEN_TYPES.includes("item"));
  check("272/296: SHIELD is a kind of its own — the catalog had none and guard crafts are 19 of the defensive logics",
    (schema.properties.kind.enum || []).includes("shield"));

  // ⚠️ BORN WHOLE MEANS IT CAN AFFECT A ROLL. A described item with no bonusTags is flavour text.
  check("272/296: the schema REQUIRES the mechanical hook, not just a description",
    (schema.required || []).includes("bonusTags") && schema.properties.bonusTags.minItems >= 1);

  // The whole point: a generated item must reach the CATALOG, or nothing can re-link it to its bonuses.
  check("272/296: a generated item is hydrated into the item catalog",
    /generatedRecords\(c, "item"\)\) if \(!CONTENT\.items\[rec\.id\]\) CONTENT\.items\[rec\.id\] = rec/.test(appI));

  // …and end to end: a generated shield in the bag changes a guard roll.
  check("272/296: a generated shield actually changes a guard roll (the consumer Aevi thought was missing)", (() => {
    const rules = { baseChance: { equipmentBonus: 5, equipmentBonusCap: 10, equipmentBonusTopN: 1 } };
    const bearer = { inventory: [{ id: "gen-shield", name: "a plain shield", kind: "shield", bonusTags: ["guard", "protect"] }] };
    const helped = INV.equipmentBonus(bearer, ["guard"], rules);
    const unrelated = INV.equipmentBonus(bearer, ["persuade"], rules);
    return helped.bonus > 0 && helped.helpers.length === 1 && unrelated.bonus === 0;
  })());
}

// --- SNG-297: a minted figure is born with a life ---------------------------------------------------
{
  const wt7 = await import("../engine/worldtick.js");
  const doc7 = JSON.parse(readFileSync(join(root, "content/packs/core/rules/arc_response.json"), "utf8"));
  const pools = doc7.mintedFigures;

  const mk = () => { const ws = {};
    return { ws, f: wt7.mintFigure(ws, { tier: "riffraff", arcAffinity: "arc_a", secondArc: "arc_b",
      originKind: "casualty_survivor", pools, epithet: "e", rng: () => 0.1 }) }; };

  check("272/297: a minted figure has MORE THAN ONE care — it can hold two fronts and abandon one",
    mk().f.arcAffinities.length === 2);
  check("272/297: the second care is DERIVED from circumstance and OPPOSES the first (they inherit the argument)",
    (() => { const a = mk().f.arcAffinities; return a[0].arcId === "arc_a" && a[1].arcId === "arc_b" && a[1].dir !== a[0].dir; })());
  check("272/297: it has a wantArcId — something to be for when nothing is on fire",
    mk().f.wantArcId === "arc_a");
  check("272/297: it has a LIFE off-arc, drawn from its own origin event",
    (() => { const v = mk().f.personalVerbs; return v.length > 0 && pools.personalVerbsByOrigin.casualty_survivor.includes(v[0]); })());

  // ⛔ THE POOLS DO NOT INVENT A LIFE — the engine’s own rule, held by the content too.
  check("272/297: with no pools authored it gets NO fabricated life (silence over invention)",
    (() => { const ws = {}; const f = wt7.mintFigure(ws, { arcAffinity: "a", epithet: "e", rng: () => 0.1 });
      return Array.isArray(f.personalVerbs) && f.personalVerbs.length === 0; })());

  // Aevi asked for a gate so this cannot recur. A RATCHET rather than a hard failure: the 66 AUTHORED figures
  // have no personal pool either, so a hard gate would fail on content that predates the field — but the
  // count may never grow, which is the part that stops it recurring.
  check("272/297: every MINTED figure is born whole, and the count of thin ones may only go down", (() => {
    const ws = {};
    for (let i = 0; i < 12; i++) wt7.mintFigure(ws, { arcAffinity: `arc_${i}`, secondArc: "arc_x",
      originKind: "vacancy_filled", pools, epithet: `e${i}`, rng: () => 0.3 });
    const thin = (ws.mintedFigures || []).filter(f => !(f.arcAffinities?.length >= 1 && f.wantArcId && f.personalVerbs?.length));
    return thin.length === 0;
  })());
}

// --- SNG-298: NPCs change their minds ---------------------------------------------------------------
{
  const wt8 = await import("../engine/worldtick.js");
  const wsrc8 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
  const f = () => ({ id: "n", arcAffinities: [{ arcId: "bleed", dir: -1, weight: 2 }] });

  check("272/298: an attempt on their life over an arc they hold makes them DIG IN",
    wt8.evolveCares(f(), { struckOnArcs: [{ arcId: "bleed" }] }).cares.find(c => c.arcId === "bleed").weight === 3);
  check("272/298: …and over an arc they had no opinion on, they GAIN one",
    wt8.evolveCares(f(), { struckOnArcs: [{ arcId: "poles" }] }).cares.some(c => c.arcId === "poles"));

  // ⛔ DIRECTIVE SNG-280 — the player cannot farm allies by being agreeable.
  check("272/298: a DISLIKED player recruits the opposite side just as reliably", (() => {
    const liked = wt8.evolveCares(f(), { playerArcs: [{ arcId: "storm", dir: 1 }], relationship: 3 });
    const disliked = wt8.evolveCares(f(), { playerArcs: [{ arcId: "storm", dir: 1 }], relationship: -3 });
    const a = liked.cares.find(c => c.arcId === "storm"), b = disliked.cares.find(c => c.arcId === "storm");
    return a.dir === 1 && b.dir === -1;
  })());
  check("272/298: knowing the player does NOT flip someone already leaning the other way", (() => {
    const r = wt8.evolveCares(f(), { playerArcs: [{ arcId: "bleed", dir: 1 }], relationship: 5 });
    return r.cares.find(c => c.arcId === "bleed").dir === -1;   // still theirs
  })());

  check("272/298: a care left untended fades — without erosion everyone ends up caring about everything",
    wt8.evolveCares(f(), { idleArcs: ["bleed"] }).cares.find(c => c.arcId === "bleed").weight === 1);
  check("272/298: …but erosion NEVER empties them (a figure with no cares drops out of the world)",
    wt8.evolveCares({ id: "x", arcAffinities: [{ arcId: "a", dir: 1, weight: 1 }] }, { idleArcs: ["a"] }).cares.length === 1);
  check("272/298: a figure cannot end up caring about everything",
    wt8.evolveCares(f(), { struckOnArcs: [{ arcId: "p1" }, { arcId: "p2" }, { arcId: "p3" }, { arcId: "p4" }, { arcId: "p5" }],
      cfg: { maxCares: 4 } }).cares.length <= 4);

  // ⚠️ THE WIRE THAT MAKES IT REAL: attention must read the EVOLVED cares, or the shift is announced and ignored.
  check("272/298: the pass spends attention on the cares as they are NOW, not as authored",
    /const fNow = \{ \.\.\.f, arcAffinities: currentCares\(ws, f\) \}/.test(wsrc8)
    && /spendAttention\(fNow,/.test(wsrc8));
  check("272/298: the change is told in the arc’s NAME, not its id",
    /nameOfArc\(hard\.arcId\)/.test(wsrc8) && /nameOfArc = \(id\)/.test(wsrc8));
}

// --- SNG-299: who is that, and where do I read more -------------------------------------------------
{
  const W = await import("../engine/whois.js");
  const appW2 = readFileSync(join(root, "app.js"), "utf8");
  const content = { greaterArcs: [{ id: "a1", name: "The Bleed", stages: [{ stage: 2, name: "Strain", publicFace: "it shows at the edges", truth: "SEALED — must never reach a player" }] }] };
  const roster = [{ id: "n", name: "Neth", tradition: "ashwarden", role: "Master", wants: "that none die unattended" }];
  const ws = { figureTier: { n: "legendary" }, figureTitles: { n: { title: "Whom the Ashwardens Named", slots: {} } },
    figureCares: { n: [{ arcId: "a1", dir: -1, weight: 2 }] }, arcStageSeen: { a1: 2 } };
  const ctx = { ws, content, character: { codex: { topics: {} } }, roster };

  check("272/299: a figure answers with their rung, their title and what they are caught up in NOW", (() => {
    const k = W.whoIs("n", "figure", ctx);
    return /Whom the Ashwardens Named/.test(k.lines[0]) && k.lines.some(l => /legendary/.test(l))
      && k.lines.some(l => /The Bleed/.test(l));
  })());

  // ⛔ THE SEALED TRUTH IS NOT THE PLAYER’S TO READ FROM A POPUP.
  check("272/299: an arc gives its publicFace and NEVER its sealed truth", (() => {
    const k = W.whoIs("a1", "arc", ctx);
    return /it shows at the edges/.test(k.lines.join(" ")) && !/SEALED/.test(JSON.stringify(k));
  })());

  check("272/299: a term explains itself", /lasted/.test(W.whoIs("legendary", "tier", ctx).lines[0]));

  // ⚠️ NOTHING KNOWN → NO LINK. A popup that says "a figure of the valley" promises a lookup and shrugs.
  check("272/299: an unknown name returns null rather than a composed description",
    W.whoIs("nobody", "figure", ctx) === null && W.whoIs("no_such_arc", "arc", ctx) === null);

  check("272/299: the codex button appears only where a codex page EXISTS", (() => {
    const without = W.whoIs("n", "figure", ctx);
    const with_ = W.whoIs("n", "figure", { ...ctx, character: { codex: { topics: { n: { label: "Neth" } } } } });
    return without.codexId === null && with_.codexId === "n";
  })());

  check("272/299: the index prefers the LONGEST name, so a full name beats the surname inside it", (() => {
    const idx = W.knownIndex({ roster: [{ id: "n", name: "Neth, Who Has Buried More" }, { id: "m", name: "Neth" }] });
    return idx[0].name.length > idx[idx.length - 1].name.length;
  })());

  // ══ SNG-369 — THE PEOPLE YOU HAVE MET. ⛔ Erik, in play: Sorel underlined and Teva not, in one sentence.
  // Sorel is linked because she happened to earn a CODEX TOPIC — not because she is registered — and this
  // index never read `npcRegistry` at all. Measured across the live saves: 53 of 110 people the players
  // have met were clickable. ⚠️ And `showWhoIs` has handled `kind === "npc"` for the portrait since
  // SNG-367: the door was built, the corridor to it was not. Registration is not arrival.
  {
    const npcs369 = [
      { id: "cassiel-ord", name: "Cassiel Ord", role: "Keeper of the warden post", description: "A lean man in a grey coat." },
      { id: "morning-shepherd", name: "Shepherd", role: "Smallholder shepherd, trade track south" },
      { id: "cookhouse-boy", name: "Boy (name unknown)", role: "Sweeping the cookhouse" },
      { id: "veth", name: "Veth (Stillwater) Ondra", role: "Former warden, traveling companion" },
      { id: "sorel", name: "Sorel", role: "Spice-broker, Edge District contact" },
    ];
    const idx369 = W.knownIndex({ npcs: npcs369 });
    const has = (n) => idx369.some(e => e.name === n && e.kind === "npc");
    check("369: a person you have MET is linkable from the registry, with no codex page required", has("Cassiel Ord") && has("Sorel"));
    // ⛔ A NAME THAT MERELY RESTATES WHAT THEY DO IS NOT A NAME. The guard is deliberately narrow: only a
    // ONE-WORD name that appears inside its own role can put a who-is button on ordinary prose.
    check("369: a one-word placeholder named for its own role is NOT linked — no button on ordinary prose", !has("Shepherd"));
    check("369: …and a parenthetical that SAYS the name is unknown is not linked either", !has("Boy (name unknown)"));
    // ⚠️ AND THE GUARD MUST NOT EAT A REAL PERSON. My first cut rejected every parenthetical and dropped
    // "Veth (Stillwater) Ondra" — an aka — alongside the placeholder.
    check("369: …but a real person with an aka survives the parenthetical rule", has("Veth (Stillwater) Ondra"));
    // ⚠️ ONE ENTRY PER NAME, RICHEST SOURCE FIRST. The same person legitimately appears in two sources, and
    // two entries made the linker's earliest-then-longest tie-break arbitrary.
    const dupe = W.knownIndex({ roster: [{ id: "fig", name: "Sorel" }], npcs: npcs369 });
    check("369: a name in two sources yields ONE entry, and the richer source wins",
      dupe.filter(e => e.name === "Sorel").length === 1 && dupe.find(e => e.name === "Sorel").kind === "figure");
    const card = W.whoIs("cassiel-ord", "npc", { ws: {}, content: {}, character: { npcRegistry: Object.fromEntries(npcs369.map(n => [n.id, n])) }, roster: [] });
    check("369: whoIs answers for someone you have met — role and description, not 'the world knows nothing'",
      card && card.kind === "npc" && card.lines.length >= 2 && /Keeper of the warden post/.test(card.lines[0]));
    // ⚠️ NEVER SILENT FOR SOMEONE STANDING IN THE ROOM: a registered person with nothing authored still
    // gets an honest line, because the card exists to say you know them.
    const bare = W.whoIs("x", "npc", { ws: {}, content: {}, character: { npcRegistry: { x: { id: "x", name: "Teva" } } }, roster: [] });
    check("369: …and a registered person with NOTHING recorded still gets a card, not a null",
      bare && bare.kind === "npc" && bare.lines.length === 1);
    check("369: the card carries what a PORTRAIT needs — the npc branch of showWhoIs was built and unreached",
      "appearance" in card && "gender" in card && "role" in card);
  }

  // ══ SNG-370 — THE GENDER REPAIR CONTROL REACHES EVERY PERSON. ⛔ It read `.slice(0, 30)` in registry
  // order and Silas knows 34 people, so four could not be reached by the tool that exists to fix them —
  // and they were the most RECENTLY met, i.e. the ones just seen rendered wrong. Measured: 35 of the 110
  // people across the live saves carry neither gender nor pronouns, so their portrait gender is a guess.
  {
    const appG = readFileSync(join(root, "app.js"), "utf8");
    const start = appG.indexOf("Set a person's gender");
    // ⚠️ BOUNDED BY THE BLOCK, NOT BY 2400 CHARACTERS. I wrote this gate with a fixed slice an hour after
    // writing three separate comments about gates that pin a position instead of a truth — the same habit
    // reappearing inside the fix for it. The repair screen is a run of `cs-block` sections, so the block
    // ENDS where the next one begins; adding a paragraph here must not turn this red.
    const end = appG.indexOf(`<div class="cs-block"`, start);
    const block = start < 0 ? "" : appG.slice(start, end > start ? end : undefined);
    check("370: the gender repair list is not capped — a cap on a repair tool is a repair you cannot perform",
      start > 0 && !/npcRegistry\)\.slice\(0,\s*\d+\)/.test(block));
    check("370: …and the people with NO gender are listed first, because they are who the control is for",
      /const unset = all\.filter\(n => !n\.gender && !n\.pronouns\)/.test(block) && /\[\.\.\.unset,/.test(block));
    check("370: …and the screen SAYS how many are unrecorded rather than leaving it to be noticed",
      /have no gender recorded/.test(block));
  }

  // The DOM pass: text nodes only, every match, and never inside an existing control.
  check("272/299: names are linked by walking TEXT NODES, never by rewriting rendered HTML",
    /createTreeWalker\(root, NodeFilter\.SHOW_TEXT/.test(appW2) && /SKIP\.has\(el\.tagName\)/.test(appW2));
  check("272/299: EVERY name in a sentence is linked, not just the first",
    /while \(cursor < text\.length\)/.test(appW2) && /at === best\.at && e\.name\.length > best\.e\.name\.length/.test(appW2));
  check("272/299: the pass runs for every screen, from chrome(), and can never take one down",
    /try \{ linkifyKnown\(app\); \} catch/.test(appW2));
}

// --- SNG-300: who seeks a fight ----------------------------------------------------------------------
{
  const wsrcE = readFileSync(join(root, "engine/worldtick.js"), "utf8");
  const docE = JSON.parse(readFileSync(join(root, "content/packs/core/rules/arc_response.json"), "utf8"));
  const eng = docE.engagement;

  check("272/300: engagement is a property of the FIGURE, not a quota on the side",
    /\(rng\(\) < engageOf\(e\.f\) \? engaged : working\)\.push\(e\)/.test(wsrcE));
  // ⚠️ A GATE MUST NOT ASSERT A TUNING VALUE. This pair used to require `marcher > stillhold * 5` and to name
  // both traditions by hand — so when Erik overturned the design (stillhold 0.15 → 1.1, because reading
  // "peace tradition" as "does not participate" was the moralising bias inverted), a gate went RED FOR THE
  // RIGHT CHANGE. That is close to the worst thing a gate can do: it defends yesterday's numbers against
  // today's decision, and the pressure it creates is to weaken the check rather than to think.
  //
  // The INVARIANT it was really guarding is "the table is DIFFERENTIATED, not flat". That survives any
  // retuning, names no tradition, and still fails on the thing it exists to catch.
  check("272/300: it is keyed on tradition, and the table is authored", (() => {
    const v = Object.values(eng?.byTradition || {}).map(Number);
    return v.length >= 20 && v.every(x => Number.isFinite(x) && x > 0);
  })());
  check("272/300: engagement is DIFFERENTIATED — the table is not flat", (() => {
    const v = Object.values(eng.byTradition).map(Number).filter(Number.isFinite);
    const lo = Math.min(...v), hi = Math.max(...v);
    // ⛔ TWO TESTS, BECAUSE A RATIO ALONE IS NOT ENOUGH. Aevi proposed `hi >= lo * 1.35`, which is right and
    // catches a wholly flat table — but it also PASSES on 27 traditions at 1.0 and one outlier at 1.4, which
    // is flat in every way that matters. The distinct-value count is what actually measures differentiation.
    return hi >= lo * 1.35 && new Set(v).size >= 5;
  })());
  check("272/300: nobody is guaranteed to never fight, and nobody fights every pass",
    /Math\.max\(lo, Math\.min\(hi, engageRate/.test(wsrcE) && eng.min > 0 && eng.max < 1);
  check("272/300: an unlisted tradition is unchanged, not penalised",
    /engageCfg\.byTradition\?\.\[t\] != null\) \? Number\(engageCfg\.byTradition\[t\]\) : 1/.test(wsrcE));
}

// --- SNG-302: the economy, and the consumer priceShift waited for ------------------------------------
{
  const EC = await import("../engine/economy.js");
  const econ = JSON.parse(readFileSync(join(root, "content/packs/core/rules/economy.json"), "utf8"));
  const at = (regionId, item, effects = []) => EC.priceOf(item, regionId, { economy: econ, effects });
  const region = (Array.isArray(econ.regions) ? econ.regions : Object.values(econ.regions))[0];
  const goods = Object.keys(region.goods)[0];

  check("272/302: the economy is registered, loaded AND destructured from the right Promise.all",
    /loadRule\("economy", null\)/.test(readFileSync(join(root, "engine/state.js"), "utf8"))
    && /if \(economyRule\) rules\.economy = economyRule/.test(readFileSync(join(root, "engine/state.js"), "utf8")));

  // ⚠️ ERIK’S CORRECTION IS THE MODEL: need dominates, and `none` is a hard zero.
  check("272/302: `need: none` is a HARD ZERO however scarce the thing is", (() => {
    const rows = Array.isArray(econ.regions) ? econ.regions : Object.values(econ.regions);
    const dead = rows.find(r => Object.values(r.goods || {}).some(g => g[0] === "none"));
    if (!dead) return false;
    const g = Object.entries(dead.goods).find(([, v]) => v[0] === "none")[0];
    const p = at(dead.regionId, { worth: "precious", goods: g });
    return p.price === 0 && p.unwanted === true;
  })());
  check("272/302: scarcity MODULATES an existing need, it never creates one", (() => {
    const rows = Array.isArray(econ.regions) ? econ.regions : Object.values(econ.regions);
    const dead = rows.find(r => Object.values(r.goods || {}).some(g => g[0] === "none" && g[1] !== "abundant"));
    if (!dead) return true;   // no such row authored — nothing to prove against
    const g = Object.entries(dead.goods).find(([, v]) => v[0] === "none")[0];
    return at(dead.regionId, { worth: "irreplaceable" }).refused || at(dead.regionId, { worth: "valuable", goods: g }).price === 0;
  })());

  // ⛔ THE IRREPLACEABLE IS REFUSED, NOT PRICED HIGH.
  check("272/302: an irreplaceable item is REFUSED a price rather than given a big one", (() => {
    const p = at(region.regionId, { worth: "irreplaceable" });
    return p.refused === true && p.price === null;
  })());

  // SNG-273 → SNG-302: the effect kind that had no consumer for weeks.
  check("272/302: a priceShift from an arc stage MOVES the local need", (() => {
    const before = EC.shiftNeed("ordinary", []).need;
    const after = EC.shiftNeed("ordinary", [{ kind: "priceShift", goods: "x", demandDelta: -1, arcName: "The Bleed" }], "x").need;
    return before === "ordinary" && after === "little";
  })());
  check("272/302: …and it cannot push need below none or above high", (() => {
    const floor = EC.shiftNeed("none", [{ kind: "priceShift", demandDelta: -3 }]).need;
    const ceil = EC.shiftNeed("high", [{ kind: "priceShift", demandDelta: 3 }]).need;
    return floor === "none" && ceil === "high";
  })());
  check("272/302: a shift for OTHER goods does not touch this item",
    EC.shiftNeed("ordinary", [{ kind: "priceShift", goods: "luxuries", demandDelta: -1 }], "medicines").need === "ordinary");

  // ⚠️ AND THE GAP IS DECLARED, not silently flat.
  check("272/302: the unreachable second axis is REPORTED rather than passing as a working price", (() => {
    const c = EC.economyCoverage(econ, [{ worth: "useful" }, { worth: "trivial" }]);
    return c.secondAxisLive === false && /no item carries a goods category/.test(c.note);
  })());
}

// --- SNG-302b: the real content loader must actually COMPLETE -----------------------------------------
// ⚠️ I put a diagnostic beside the economy merge that referenced `items` ~65 lines before `const items` is
// initialised. That is a temporal-dead-zone ReferenceError which takes the ENTIRE content load down at
// startup — the app would not boot — and `npm test` stayed GREEN through it, because nothing in the suite ran
// the real loader end to end. Everything downstream is worthless if this throws, so it is checked first now.
{
  let loaded = null, threw = null;
  try { const { loadContentHeadless } = await import("./headless_content.mjs"); loaded = await loadContentHeadless(); }
  catch (e) { threw = e; }
  // The name is a PLAIN LITERAL so the ledger’s drift guard can see it — it extracts double-quoted check
  // names, and a template literal is invisible to it. The error text goes to the log, where detail belongs.
  if (threw) console.log(`      loadContent threw: ${String(threw.message).slice(0, 160)}`);
  check("302b: the REAL loadContent() completes without throwing", !threw && !!loaded);
  check("302b: …and returns a world with content in it (a silent empty load is also a failure)",
    !!loaded && Object.keys(loaded.locations || {}).length > 0 && Object.keys(loaded.items || {}).length > 0
    && !!loaded.rules && Object.keys(loaded.rules).length > 20);
}

// --- SNG-303: the wiring is CHECKABLE, so it does not have to be remembered ---------------------------
// The same six lines of content wiring have failed three distinct ways: not registered (the zero-XP bug),
// registered but never loaded (Aevi's economy, caught by the check in under a minute), and loaded into a name
// belonging to a DIFFERENT `Promise.all` — which no prose check can catch, because positional destructuring
// has no names in it. The array and the name list are paired by COUNTING and nothing in the source says so.
{
  const { shapesOfSource, scanEngine } = await import("./wiring_shape.mjs");

  const shapes = scanEngine();
  const mismatched = shapes.filter(s => s.names !== s.entries);
  for (const m of mismatched) console.log(`      ${m.file}:${m.line} — ${m.names} names / ${m.entries} entries`);
  check("303: every Promise.all destructure pairs 1:1 with its awaited entries", shapes.length > 0 && mismatched.length === 0);

  // ⚠️ FALSIFY THE CHECKER. My own `loadRule("encounters")` once landed in `coliseumGrid`'s slot and pushed
  // the grid off the end of the array — with a fully green suite. This is that bug, planted, in one line.
  const planted = "const [a, b] = await Promise.all([one(), two(), three()]);";
  check("303: the checker goes RED on a planted extra entry (a gate that cannot fail is not a gate)",
    shapesOfSource(planted).some(s => s.names === 2 && s.entries === 3));

  // ⚠️ AND IT MUST NOT FIRE ON CORRECT CODE. My first version regex-matched `for (const [k, l] of …)` thirty
  // lines above the real block and reported 5 names against 22 entries — the CHECKER being wrong, not the
  // code. A measuring tool that cries wolf on good input teaches everyone to ignore it, which is worse than
  // having none. So the exact shape that fooled it is now a permanent check.
  const decoy = "for (const [k, l] of Object.entries(x)) { y(k, l); }\nconst [p, q] = await Promise.all([one(), two()]);";
  const dShapes = shapesOfSource(decoy);
  check("303: a preceding for-of destructure does not fool it into a false alarm",
    dShapes.length === 1 && dShapes[0].names === 2 && dShapes[0].entries === 2);
}

// ---- CCODE-158: a GM-initiated relocation the player never asked for is OFFERED, not imposed ----
// Erik's turn: "Take the opportunity to update Warden Coll on the status of the Water crisis." He was at
// the ridge; the beat put him in Coll's office two regions away. departureGateFor guards the door where
// the PLAYER asks to travel, BEFORE the GM is called. The moveTo applier is the other door and it had no
// gate at all — every guard in it was about WHERE, none about WHETHER.
{
  const { isConsequentialMove, departureGateFor } = await import("../engine/intent.js");
  // ⚠️ `edge` is CONNECTED to the ridge and in ANOTHER region — a road runs there, so only the
  // region-crossing clause can catch it. Without a connected cross-region place the not-connected
  // clause absorbs the case and the crossing test proves nothing (it did, at first).
  const locs424 = {
    ridge: { id: "ridge", name: "Threshold Post", regionId: "foothills", connections: ["mill", "edge"] },
    mill:  { id: "mill",  name: "Mill Gate",      regionId: "foothills", connections: ["ridge"] },
    edge:  { id: "edge",  name: "Edge District",  regionId: "radiant",   connections: ["ridge"] }
  };
  check("CCODE-158: a region crossing is a consequential move EVEN WHEN a road connects the two", isConsequentialMove("ridge", "edge", locs424) === true);
  check("CCODE-158: an adjacent step in the same region is NOT (a departure gate that nags is not a gate)", isConsequentialMove("ridge", "mill", locs424) === false);
  check("CCODE-158: a same-region place you are NOT connected to is a journey, not a step", isConsequentialMove("ridge", "orchard", { ...locs424, orchard: { id: "orchard", regionId: "foothills", connections: [] } }) === true);
  check("CCODE-158: an unresolvable destination FAILS CLOSED (the engine knows least, so it counts as real)", isConsequentialMove("ridge", "nowhere", locs424) === true && isConsequentialMove("ridge", null, locs424) === true);
  check("CCODE-158: standing still is not a move", isConsequentialMove("ridge", "ridge", locs424) === false);

  // the applier's actual decision, composed exactly as app.js composes it
  const unearned = (askedToTravel, dest, subParent = null, wgRoute = null) =>
    !!dest && dest !== "ridge" && !askedToTravel && !subParent && !wgRoute && isConsequentialMove("ridge", dest, locs424);
  check("CCODE-158 THE BUG: no travel intent + a region-crossing moveTo is REFUSED (Erik's exact shape)", unearned(false, "edge") === true);
  check("CCODE-158: the SAME move is allowed when the player actually asked to travel", unearned(true, "edge") === false);
  check("CCODE-158: an ordinary adjacent step is never refused", unearned(false, "mill") === false);
  check("CCODE-158: a sub-place and a waygate transit are never refused (they are not relocations)", unearned(false, "edge", "ridge") === false && unearned(false, "edge", null, { destId: "edge" }) === false);
  // ⚠️ RED BY CONSTRUCTION: before the fix the applier had NO whether-check at all, i.e. its effective
  // predicate was "never refuse". Pin that the gate distinguishes the two — a gate that passes under the
  // old behaviour is not a gate.
  const oldApplierPredicate = () => false; // what app.js effectively asked before CCODE-158
  check("CCODE-158: the gate goes RED under the pre-fix behaviour (no whether-check → never refused)", oldApplierPredicate() !== unearned(false, "edge"));

  // the departure gate still agrees with the shared predicate (one definition, two doors)
  const ch424 = { currentLocationId: "ridge" };
  check("CCODE-158: both doors share ONE definition — the gate fires on the crossing and not on the step",
    !!departureGateFor({ destId: "edge", name: "Edge District" }, ch424, locs424) && departureGateFor({ destId: "mill", name: "Mill Gate" }, ch424, locs424) === null);

  const appSrc424 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE-158: the moveTo applier actually consults it, with all four clauses", /const unearnedMove =[\s\S]{0,320}!askedToTravel[\s\S]{0,200}!subParentId[\s\S]{0,60}!wgRoute[\s\S]{0,80}isConsequentialMove/.test(appSrc424));
  check("CCODE-158: a refused move OFFERS the road (_pendingArrival) instead of stranding the player", /refusedMove = true/.test(appSrc424) && /_pendingArrival = \{ ref: moveRef/.test(appSrc424) && /else if \(!refusedMove\)/.test(appSrc424));
  check("CCODE-158: the refusal is logged as an op outcome, so it is visible and not silent", /logOpOutcome\("moveTo", "refused-unearned"\)/.test(appSrc424));
  check("CCODE-158: the correction aside APPENDS — an aside that can be overwritten vanishes at random", /character\._correctionAside = \[character\._correctionAside, "Set right: "/.test(appSrc424));
  const gmSrc424 = readFileSync(join(root, "engine/gm.js"), "utf8");
  check("CCODE-158: the moveTo contract forbids relocating a character whose action did not move them", /THE FICTION MAY NOT MOVE THEM UNLESS THEIR ACTION DID/.test(gmSrc424) && /that is a MESSAGE, not a journey/.test(gmSrc424));
}

// ---- CCODE-159: reaching someone who is ELSEWHERE is not travel (the third bucket) ----
{
  const { isSpeechAct, isRemoteContact } = await import("../engine/intent.js");
  const ERIK = "Take the opportunity to update Warden Coll on the status of the Water crisis and new warden stations.";
  check("CCODE-159 THE BUG: a light-verb wrapper no longer hides the governing verb", isSpeechAct(ERIK) === true);
  // ⚠️ RED BY CONSTRUCTION — the pre-fix belt, rebuilt here, on the same sentence. It read "Take" as the
  // governing verb and had no remote verbs at all, so it returned false and the turn became travel.
  const OLD_SPEECH = /^\s*(?:i(?:'?ll|'?m|'?d| will| am| would)?\s+(?:want to |going to |plan to |mean to |need to )?|let'?s\s+|we(?:'?ll| will)?\s+)?(announc\w*|tell\w*|say|saying|said|speak\w*|talk\w*|confid\w*|discuss\w*|propos\w*|promis\w*|mention\w*|explain\w*|suggest\w*|reassur\w*|admit\w*|confess\w*|declar\w*|inform\w*|warn\w*|ask|asking|asks|chat\w*|whisper\w*|shar\w*)\b/i;
  check("CCODE-159: the gate goes RED on the pre-fix belt (it read \"Take\" and missed \"update\" entirely)", OLD_SPEECH.test(ERIK.trim()) === false);
  check("CCODE-159: the remote half of the verb list is present", ["write to Coll", "send word to Mara", "brief the council", "report what I found", "relay the news"].every(s => isSpeechAct(s) === true));
  check("CCODE-159: a real departure is STILL a departure (the anchor was right, only blind)", ["head to the edge district", "travel to Millbrook", "walk to the mill and write to Coll"].every(s => isSpeechAct(s) === false));
  check("CCODE-159: the governing verb still wins — going somewhere and talking there is going", isSpeechAct("go to Millbrook and tell Pell the news") === false);
  check("CCODE-159: a named CHANNEL is remote contact", ["write to Coll on my shadow tablet", "send word to Mara by bird", "put it on the shadow-slate", "get word to Fendt via the relay"].every(s => isRemoteContact(s) === true));
  check("CCODE-159: ordinary travel is not remote contact", ["walk to the mill", "head south at dawn", "take the road to Cairnhold"].every(s => isRemoteContact(s) === false));
  const appSrc425 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE-159: travelIntentOf suppresses a travelTo on a remote contact — unless real travel is also named", /isRemoteContact\(contactText\) && !TRAVEL_PHRASE\.test\(contactText\)/.test(appSrc425));
  const gmSrc425 = readFileSync(join(root, "engine/gm.js"), "utf8");
  check("CCODE-159: the intent parser is TOLD the third case exists (a slate is not a road)", /REACHING SOMEONE WHO IS ELSEWHERE IS NOT TRAVEL/.test(gmSrc425) && /shadow-slates/.test(gmSrc425) && /light wrapper in front of the real verb/.test(gmSrc425));
}

// ---- CCODE-160: scene state is authoritative about the SITUATION, never about WHO SOMEONE IS ----
{
  const { reconcileSceneIdentity, sceneIdentityNote, sanitizeScene: sc426 } = await import("../engine/gm.js");
  const ERIK_SETTING = "Warden Coll's office in the Edge District warden post—stone walls, afternoon light through a high window. Coll behind her desk, Silas standing across from her with the shadow-sheet still in hand.";
  const reg426 = { coll: { id: "coll", name: "Warden Coll", gender: "man", pronouns: "he/him" } };
  check("CCODE-160: the defect is real and present in the input (else this gate proves nothing)", /\bher desk\b/.test(ERIK_SETTING) && /across from her\b/.test(ERIK_SETTING));
  const r426 = reconcileSceneIdentity({ setting: ERIK_SETTING, npcsPresent: [{ name: "Warden Coll", state: "seated behind her desk, pen down" }], objects: [], threads: [] }, reg426);
  check("CCODE-160 THE BUG: the possessive is repaired against the record — 'her desk' → 'his desk'", /\bhis desk\b/.test(r426.scene.setting) && !/\bher desk\b/.test(r426.scene.setting));
  check("CCODE-160: the OBJECT form is repaired differently — 'across from her with' → 'from him with'", /across from him with\b/.test(r426.scene.setting));
  check("CCODE-160: the fix reaches every prose field, not just the setting", /\bhis desk\b/.test(r426.scene.npcsPresent[0].state));
  check("CCODE-160: it REPORTS what it repaired (a silent repair is an invisible bug)", r426.repaired.length >= 2 && r426.repaired.every(x => x.name === "Warden Coll"));
  // ⚠️ RED BY CONSTRUCTION: with the identity record absent, there is nothing to reconcile against and
  // the wrong pronoun survives — which is exactly the state the game shipped in.
  check("CCODE-160: the gate goes RED with no record to reconcile against (the pre-fix state)", /\bher desk\b/.test(reconcileSceneIdentity({ setting: ERIK_SETTING, npcsPresent: [], objects: [], threads: [] }, {}).scene.setting));
  check("CCODE-160: an UNKNOWN pronoun is left alone — it repairs against a record, it does not guess", /\bher desk\b/.test(reconcileSceneIdentity({ setting: ERIK_SETTING, npcsPresent: [], objects: [], threads: [] }, { coll: { name: "Warden Coll" } }).scene.setting));
  // conservative by construction: two registered people in one sentence cannot be disambiguated
  const amb = reconcileSceneIdentity({ setting: "Coll behind her desk, Pell at the door with her hand on the frame.", npcsPresent: [], objects: [], threads: [] },
    { coll: { name: "Warden Coll", pronouns: "he/him" }, pell: { name: "Pell Ran Marsh", pronouns: "she/her" } });
  check("CCODE-160: it DECLINES an ambiguous string rather than guessing which 'her' is whose", amb.scene.setting.includes("Coll behind her desk") && amb.repaired.length === 0);
  check("CCODE-160: a they/them person is never rewritten (no mangled verb agreement)", reconcileSceneIdentity({ setting: "Ash behind her desk.", npcsPresent: [], objects: [], threads: [] }, { ash: { name: "Ash", pronouns: "they/them" } }).repaired.length === 0);
  check("CCODE-160: the note carries the record's own pronouns INTO the authoritative block", /Warden Coll is man, he\/him/.test(sceneIdentityNote({ npcsPresent: [{ name: "Warden Coll" }] }, reg426)));
  check("CCODE-160: reconcile survives a sanitizeScene round-trip and garbage input", reconcileSceneIdentity(sc426({ setting: ERIK_SETTING }), reg426).repaired.length >= 1 && reconcileSceneIdentity(null, reg426).scene === null);
  const gmSrc426 = readFileSync(join(root, "engine/gm.js"), "utf8");
  check("CCODE-160: the block no longer claims authority over identity, and says the record wins", /AUTHORITATIVE about the SITUATION/.test(gmSrc426) && /NOT authoritative about WHO ANYONE IS/.test(gmSrc426) && /the record is right and this text is a slip/.test(gmSrc426));
  check("CCODE-160: the render path reconciles before serving (heals a save already wedged)", /reconcileSceneIdentity\(sceneState, character\?\.npcRegistry/.test(gmSrc426));
  const appSrc426 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE-160: and the WRITE path reconciles too, so the save stops carrying the error", /const rec = reconcileSceneIdentity\(sceneClean, character\.npcRegistry/.test(appSrc426));
  const corrSrc426 = readFileSync(join(root, "engine/corrections.js"), "utf8");
  check("CCODE-160: the one authoritative block finally has a repair op", /case "correctSceneState"/.test(corrSrc426));
  const cs = { activeScene: { sceneState: { setting: "Warden Coll's office.", threads: ["x"] } }, corrections: [] };
  const rr = applyStateOps(cs, [{ op: "correctSceneState", setting: "The ridge Threshold Post, afternoon.", why: "he never left the ridge" }], {});
  check("CCODE-160: correctSceneState rewrites the anchor and logs it", rr.applied.length === 1 && cs.activeScene.sceneState.setting === "The ridge Threshold Post, afternoon." && cs.corrections.some(x => x.kind === "sceneState"));
  // ⚠️ the empty-anchor guard must be tested WITH threads present, or the "needs setting and/or threads"
  // guard behind it absorbs the case and the first guard is never actually exercised (it did, at first).
  check("CCODE-160: it refuses an empty anchor and a no-op ask (a scene with no anchor is worse than a wrong one)",
    applyStateOps(cs, [{ op: "correctSceneState", setting: "   ", threads: ["still open"] }], {}).refused.length === 1
    && applyStateOps(cs, [{ op: "correctSceneState", setting: "   " }], {}).refused.length === 1
    && applyStateOps(cs, [{ op: "correctSceneState" }], {}).refused.length === 1);
  check("CCODE-160: it refuses when there is no active scene to repair", applyStateOps({ corrections: [] }, [{ op: "correctSceneState", setting: "somewhere" }], {}).refused.length === 1);
}

// ---- CCODE-161: the Shadow Tablet is a real object, under all the names people say for it ----
// Erik's ruling: the object is the Shadow Tablet; "shadow sheet" and "shadow slate" are alternates for
// the same thing. It was made in play and never emitted, so it lived as prose in two NPC records under
// two different names — and the intent parser, handed the inventory as the character's affordances,
// could not see the one thing that made "write to Coll" possible.
{
  const { reclaimEstablishedItems, resolveInventoryItem, normalizeInventory: norm427, fromCatalog: fc427 } = await import("../engine/inventory.js");
  const pack427 = JSON.parse(readFileSync(join(root, "content/packs/valley/items/shadow_tablet.json"), "utf8"));
  const cat427 = Object.fromEntries(pack427.items.map(i => [i.id, i]));
  const tablet = cat427.shadow_tablet;
  check("CCODE-161: the object is authored, canonically named, and carries Erik's alternates", tablet.name === "Shadow Tablet" && ["Shadow Sheet", "Shadow Slate"].every(a => (tablet.aliases || []).includes(a)));
  check("CCODE-161: it is registered in the pack manifest (an unlisted file is not content)", JSON.parse(readFileSync(join(root, "content/packs/valley/manifest.json"), "utf8")).provides.items.includes("items/shadow_tablet.json"));

  // THE BUG: authored aliases were dropped on the way into inventory — a writer with no reader.
  check("CCODE-161 THE BUG: fromCatalog carries authored aliases through to the instance", (fc427(tablet).aliases || []).includes("Shadow Slate"));
  check("CCODE-161: an item with no aliases gains no empty field (the shape stays clean)", !("aliases" in fc427({ id: "x", name: "Rock", kind: "misc" })));

  // the whole point of the alternates: a later mention under another name must not fork a second item
  const holder = { inventory: [fc427(tablet)] };
  check("CCODE-161: every name Erik allows collapses onto the ONE object", ["shadow sheet", "Shadow Slate", "shadow-sheet", "my shadow tablet"].every(s => resolveInventoryItem(holder, s, cat427)?.id === "shadow_tablet"));
  check("CCODE-161: a save holding an ALTERNATE as a bare string re-links to the real item", (() => { const d = { inventory: ["Shadow Slate"] }; norm427(d, cat427); return d.inventory[0].id === "shadow_tablet" && d.inventory[0].kind === "focus"; })());

  // the reclaim — trace-gated, and proved against Silas's ACTUAL save, not a fixture.
  //
  // ⛔ SNG-435 SESSION: THE LIVE DEFECT IS GONE, BECAUSE THE FIX WORKED. Silas now holds the tablet, so
  // the premise gate ("the defect is real in the live save") went red on a save that had been REPAIRED — a
  // gate reporting success as failure. That is the right thing for a premise check to do when its premise
  // expires; what is wrong is to delete it, because the repair then loses its only real-data test.
  //
  // ⚠️ SO THE DEFECT IS RECONSTRUCTED FROM HIS OWN SAVE rather than kept as a copy of it: the same
  // record with the tablet taken back out and the reclaim flag cleared, which is exactly the state it was in
  // when Erik reported it. The npcRegistry trace — the evidence the repair reads — is still his and still
  // real, so this stays a test against live data and not a fixture I wrote to pass.
  const silasNow = JSON.parse(readFileSync(join(root, "characters/player-s9z9u1/char-mrhs8286.json"), "utf8"));
  const silas = { ...silasNow, inventory: (silasNow.inventory || []).filter(i => !/shadow/i.test(i.name || "") && i.id !== "shadow_tablet") };
  delete silas.itemReclaimVersion;
  check("CCODE-161: the defect shape is reconstructed from the live save, and the trace it repairs from is real",
    !(silas.inventory || []).some(i => /shadow/i.test(i.name || ""))
    && JSON.stringify(silas.npcRegistry).toLowerCase().includes("shadow-slate")
    && (silasNow.inventory || []).length > (silas.inventory || []).length,
    "if the live save no longer carries the trace, this repair has no evidence to work from and the gate is void");
  const got = reclaimEstablishedItems(silas, cat427);
  check("CCODE-161 THE FIX: the trace in his own record gives the tablet back", got.length === 1 && got[0].id === "shadow_tablet" && !!got[0].trace);
  const held = (silas.inventory || []).find(i => i.id === "shadow_tablet");
  check("CCODE-161: and it arrives WHOLE — catalog kind, description and aliases, not a hollow stub", held && held.kind === "focus" && !!held.description && (held.aliases || []).includes("Shadow Sheet"));
  check("CCODE-161: idempotent — a second pass grants nothing", reclaimEstablishedItems(silas, cat427).length === 0);
  // ⚠️ the already-held check ALSO makes a second pass empty, so it masks the version flag entirely. The
  // case only the flag can answer: the player DROPS the thing. Without the flag it comes back on every
  // load — an item you threw away returning forever, which is the engine overruling the player.
  check("CCODE-161: an item the player DROPPED stays dropped (only the version flag can hold this)", (() => {
    const dropped = { ...silas, inventory: (silas.inventory || []).filter(i => i.id !== "shadow_tablet") };
    return reclaimEstablishedItems(dropped, cat427).length === 0;
  })());
  // ⚠️ REPAIR, NOT WISH: no trace in the record, no item. This is the line that keeps the pass honest.
  check("CCODE-161: a character whose story never had one gets NOTHING", reclaimEstablishedItems({ inventory: [], chronicle: ["walked to the mill"], npcRegistry: {} }, cat427).length === 0);
  check("CCODE-161: an item with no establishedBy block is never reclaimed by this pass", reclaimEstablishedItems({ inventory: [], chronicle: ["I carry a marcher blade everywhere"], npcRegistry: {} }, { marcher_blade: { id: "marcher_blade", name: "Marcher's Blade" } }).length === 0);
  // ⚠️ it must NOT ride the XP backfill's version — that would re-credit experience to every character
  const invSrc427 = readFileSync(join(root, "engine/inventory.js"), "utf8");
  // the invariant is about the XP backfill's version, not about the word appearing in a comment —
  // my first assertion failed on my own explanatory note, which is a checker being wrong, not the code.
  const bfSrc427 = readFileSync(join(root, "engine/backfill.js"), "utf8");
  check("CCODE-161: the reclaim has its OWN version flag, and the XP backfill's is untouched (a repair must not ride a wish's version number)",
    /ITEM_RECLAIM_VERSION/.test(invSrc427) && /itemReclaimVersion/.test(invSrc427)
    && /export const BACKFILL_VERSION = 1;/.test(bfSrc427) && !/reclaimEstablishedItems/.test(bfSrc427));
  const appSrc427 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE-161: it runs on load and SAYS SO (a silent grant is indistinguishable from a bug)", /reclaimEstablishedItems\(c, CONTENT\.items\)/.test(appSrc427) && /the story gave you this and the ledger missed it/.test(appSrc427));
  const intentSrc427 = readFileSync(join(root, "engine/intent.js"), "utf8");
  check("CCODE-161: all three names are recognised as a remote channel (CCODE-159 agrees with the ruling)", /shadow\[-\\s\]\?\(\?:slate\|sheet\|tablet\)/.test(intentSrc427));
}

// ---- SNG-401: draw an NPC's picture again, WITHOUT destroying the one they have ----
// Aevi's spec, and §3 is the load-bearing rule: "a regenerate that silently replaces a face the player
// had grown used to is worse than no button. The player asked for another try, not for the old one to
// be deleted."
{
  const { regenerateImage, acceptImage, isGeneratedImage, setArtMode, addGalleryImage: addG401 } = await import("../engine/art.js");
  const artWas = localStorage.getItem("singularity.artMode");
  setArtMode("generate");
  const pell = () => ({ id: "pell", name: "Pell Ran Marsh", description: "a village blacksmith, file in hand", image: "ORIGINAL", relationship: 10 });

  // §3 — THE RULE. The record must be untouched by a draw.
  const p1 = pell();
  const drawn = regenerateImage(p1, "npc", { ratingLevel: 2, attempt: 1 });
  check("401 §3 THE RULE: a draw does NOT touch the record (the old face survives)", p1.image === "ORIGINAL" && !p1.imagePinned && !p1.imageSeedKey);
  check("401: …and it returns a real, different picture to look at beside it", !!drawn?.url && drawn.url !== "ORIGINAL" && /image\.pollinations/.test(drawn.url));

  // §2 — a re-roll is the SAME prompt with a NEW seed. Same seed would redraw the same face.
  const d2 = regenerateImage(pell(), "npc", { ratingLevel: 2, attempt: 2 });
  check("401 §2: same prompt, DIFFERENT seed — two attempts are two pictures", drawn.prompt === d2.prompt && drawn.url !== d2.url && drawn.seedKey !== d2.seedKey);
  check("401: attempt keys do not compound across re-rolls (r1 → r2, never r1#r2)", /#r2$/.test(d2.seedKey) && !/#r\d+#r/.test(regenerateImage({ ...pell(), imageSeedKey: drawn.seedKey }, "npc", { attempt: 3 }).seedKey));

  // §4 — THE FLOORS. A re-roll is not a way around the content ceiling, and minor-safety is absolute.
  const kid = { id: "wren", name: "Wren", description: "a child of the mill", isMinor: true };
  const kidDraw = regenerateImage(kid, "npc", { ratingLevel: 4, attempt: 1 });
  check("401 §4: minor-safety runs on a re-roll exactly as on a first mint", /child-safe|wholesome|no sexual/i.test(decodeURIComponent(kidDraw.url)));
  const gLow = regenerateImage(pell(), "npc", { ratingLevel: 0, attempt: 1 });
  const gHigh = regenerateImage(pell(), "npc", { ratingLevel: 4, attempt: 1 });
  check("401 §4: the viewer's ceiling still shapes the prompt (a re-roll cannot climb it)", decodeURIComponent(gLow.url).includes("family-friendly") && !decodeURIComponent(gHigh.url).includes("family-friendly"));

  // §3 "on accept" — NOW it lands, and the seed is remembered so the face stays stable.
  const p3 = pell();
  const ok = acceptImage(p3, { url: drawn.url, seedKey: drawn.seedKey });
  check("401 §3 on accept: the chosen picture becomes theirs and its seed is kept", ok && p3.image === drawn.url && p3.imageSeedKey === drawn.seedKey);
  check("401: accepting PINS — a chosen face is not re-drawn behind the player's back", p3.imagePinned === true);
  check("401: accept refuses an empty pick rather than blanking the record", acceptImage(p3, {}) === false && p3.image === drawn.url);

  // the pin has to be READ, or it is decoration. This is the bond-milestone pass's own guard.
  const appSrc401 = readFileSync(join(root, "app.js"), "utf8");
  check("401: the bond-portrait pass HONOURS the pin (else keeping buys you one milestone)", /if \(n\.imagePinned\) \{ n\._portraitTier = tier; continue; \}/.test(appSrc401));

  // §1 — provenance. Without it a button "can only re-fetch the same URL".
  const c401 = { gallery: [] };
  addG401(c401, { kind: "portrait", url: "u1", caption: "Pell Ran Marsh — devoted", subjectKind: "npc", subjectId: "pell" });
  addG401(c401, { kind: "moment", url: "u2", caption: "a moment" });
  const tileOf = u => c401.gallery.find(g => g.url === u);
  check("401 §1: a gallery tile now records WHOSE face it is", tileOf("u1").subjectId === "pell" && tileOf("u1").subjectKind === "npc");
  check("401 §1: a tile with no subject gains no empty fields (additive — old entries still work)", !("subjectId" in tileOf("u2")) && !("subjectKind" in tileOf("u2")));
  check("401 §1: the prompt is NOT stuffed into a DOM attribute (Aevi: they are long and spoiler-bearing)", !/data-regen-prompt/.test(appSrc401));
  check("401 §1: the lightbox carries provenance per item and the gallery path supplies it", /regen: galleryRegenFor\(g\)/.test(appSrc401) && /function galleryRegenFor/.test(appSrc401));
  // ⚠️ CORRECTED BY CCODE-166. I gated "EXACT, never fuzzy" — and exact was WRONG: it failed on "Cevaine of
  // the Seventh Measure" against a registry that says "Cevaine", so a real portrait of a known person had
  // no controls. What this gate was actually protecting is that a near-miss must never redraw the wrong
  // person, and that survives `namesMatch`, which needs a substantial whole-word hit. Aimed at the
  // property now instead of at one implementation of it.
  check("401/166: the caption fallback is CONSERVATIVE — a fuller name resolves, a vague description does not",
    /namesMatch\(n\.name, nm\)/.test(appSrc401));

  // §1 ACROSS THE WHOLE SURFACE — Aevi counted eight call sites, "all pass the same two fields".
  for (const [site, re] of [
    ["location banner", /data-lightbox="location" data-regen-kind="location" data-regen-subject=/],
    ["craft art", /data-lightbox="\$\{esc\(selImg\)\}" data-regen-kind="ability" data-regen-subject=/],
    ["item examine", /data-lightbox="item" data-regen-kind="item" data-regen-subject=/],
    ["moment art", /data-lightbox="moment" data-regen-kind="moment"/],
    ["character portrait", /data-lightbox="portrait" data-regen-kind="character"/]
  ]) check(`401 §1: the ${site} carries its provenance`, re.test(appSrc401));
  // ⛔ THE BRAID MOMENT IS CHECKED SEPARATELY NOW, BECAUSE IT SHARES ONE CARD BUILDER WITH EVERY OTHER
  // CELEBRATION. DESIGN_celebrations §1 (Erik): the `.braid-moment` surface "should be the format for things
  // like the news of milestones for holdings", and it had already generalised itself twice off one
  // implementation — so `momentCard` was extracted rather than copied, and ✦ A PLACE IS YOURS ✦ uses it.
  //
  // ⚠️ THE LITERAL `data-regen-kind="ability"` NO LONGER SITS BESIDE `braid-moment-art`: the attribute is
  // emitted from a variable in the shared card, and the VALUE is supplied at the braid call site.
  // ⛔ SO THIS IS AIMED AT THE PROPERTY RATHER THAN AT ONE IMPLEMENTATION OF IT — the same move the caption
  // gate above made, and for the same reason. It now proves BOTH halves of the wiring, which the single
  // adjacency regex never did: a card that emits the pair, and a braid path that fills it in.
  check("401 §1: the braid moment carries its provenance",
    /class="braid-moment-art"/.test(appSrc401) &&
    /data-regen-kind="\$\{esc\(regenKind\)\}" *. *: *""/.test(appSrc401) &&
    /regenKind: "ability", regenSubject: def\.id/.test(appSrc401));
  // ⚠️ AND THE SHARED CARD KEEPS THE PARTS §2 CALLS LOAD-BEARING — the kicker, the provenance line, and the
  // naming invitation. ⛔ A celebration that cannot be named is an award, not an achievement.
  check("401 §1: …and the shared celebration card keeps the kicker, provenance and naming invitation",
    /braid-moment-kicker/.test(appSrc401) && /braid-moment-parents/.test(appSrc401) &&
    /id="braid-rename-in"/.test(appSrc401) && /function momentCard\(/.test(appSrc401));
  check("401 §1: …and the holding acceptance uses that same card, not a second copy of it",
    /function showPlaceMoment\(/.test(appSrc401) &&
    /IS YOURS/.test(appSrc401) && /placeName\.length <= 28/.test(appSrc401) &&
    (appSrc401.match(/class="help-card braid-moment"/g) || []).length === 1);
  check("401 §1: the delegated handler reads the provenance off the img (no eight signatures changed)", /img\.dataset\.regenKind/.test(appSrc401) && /img\.dataset\.regenSubject/.test(appSrc401));
  check("401 §1: the FEED image is deliberately NOT regenerable — it is someone else's moment", /data-lightbox="feed"(?![^>]*data-regen-kind)/.test(appSrc401));

  // §2 THE SECOND BUTTON. Aevi: a re-roll on a wrong COMPOSITION returns the same wrong composition.
  // ⛔ ERIK: the celebration "names the place in its kicker", and carries a GENERATED image so the whole
  // re-roll / rebuild / ★ keep apparatus works on it. ⚠️ An img with provenance into an UNREGISTERED kind
  // is the fourth door on the very surface built to show the image work off — so the registry is asserted.
  check("401 §1: the holding celebration mints a regenerable image through a REGISTERED kind",
    /function ensureHoldingImage\(/.test(appSrc401) && /regenKind: "holding"/.test(appSrc401) &&
    /^\s*holding: \{/m.test(appSrc401));
  check("401 §2: there is a REBUILD as well as a re-roll, and it takes new words", /data-lbrebuild/.test(appSrc401) && /Describe .* differently/.test(appSrc401) && /regenLightboxItem\(it, \+\+attempts, said\.trim\(\)\)/.test(appSrc401));
  check("401 §2: rebuild is hidden on an AUTHORED image (re-describing would discard the authoring)", /const canRebuild = canRegen && isGeneratedImage\(it\.url\)/.test(appSrc401));
  check("401 §2: an authored path is told from a generated one by where it came from", isGeneratedImage("https://image.pollinations.ai/prompt/x") && !isGeneratedImage("content/packs/valley/assets/thornmother.png") && !isGeneratedImage(""));
  const rebuilt = regenerateImage(pell(), "npc", { ratingLevel: 2, attempt: 1, promptOverride: "a grey-haired smith at an anvil, soot on her forearms" });
  check("401 §2: a rebuild draws from the NEW words, not the record's own description", decodeURIComponent(rebuilt.url).includes("soot on her forearms") && !decodeURIComponent(rebuilt.url).includes("file in hand"));
  check("401 §2: …and the floors still run on the player's own words", decodeURIComponent(regenerateImage(pell(), "npc", { ratingLevel: 0, attempt: 1, promptOverride: "an erotic nude portrait" }).url).match(/erotic|nude/) === null);
  check("401 §2: a rebuild with no record at all still draws (a moment has no record, only words)", !!regenerateImage(null, "moment", { promptOverride: "the seam sealed at dawn" })?.url);
  check("401: nothing to draw from is refused rather than guessed", regenerateImage(null, "moment", {}) === null);

  // the kind table — one place that knows where each subject is read from and kept
  check("401: every regenerable kind declares BOTH how to find it and where a kept image lands", /const REGEN_KINDS = \{/.test(appSrc401)
    && ["npc", "character", "location", "item", "ability", "moment", "beast"].every(k => new RegExp(`\\b${k}: \\{`).test(appSrc401.slice(appSrc401.indexOf("const REGEN_KINDS")))) );
  check("401: an UNKNOWN kind yields no button rather than a guess", /const spec = REGEN_KINDS\[regen\.kind\];\s*\n\s*if \(!spec\) return null;/.test(appSrc401));
  check("401: a record-less kind is legitimate, not an error (the gallery tile IS its record)", /A null record is legitimate/.test(appSrc401));

  // §3 in the UI — append, never replace. This is the line that would undo the whole spec.
  // ⚠️ RE-AIMED (CCODE-172). It pinned `list.push`, and a draw is now INSERTED beside its source instead of
  // at the end — a better answer to the same requirement. The property is unchanged and is what it asserts:
  // the old picture is never overwritten, only added to.
  check("401 §3/172: a new draw is ADDED to the list, never written over the current item",
    /list\.splice\(i \+ 1, 0, drawn\);/.test(appSrc401) && !/list\[i\] = drawn/.test(appSrc401));
  check("401 §3: Keep shows only on a draw the player made, not on the picture they already had", /const isNewDraw = !!it\.regen && !!it\.isDraw;/.test(appSrc401));
  check("401 §4: the button is disabled in flight, shows work, and NAMES a failure", /regenBtn\.disabled = true; regenBtn\.textContent = "…drawing"/.test(appSrc401) && /couldn't draw/.test(appSrc401) && /didn't come through/.test(appSrc401));
  check("401 §5: there is a direct way in from the people list, only when a picture exists", /data-repic=/.test(appSrc401) && /\?\.\[p\.id\]\?\.image \?/.test(appSrc401));
  check("401: art OFF means no draw at all (generation is the on-switch, honoured here too)", (() => { setArtMode("off"); const r = regenerateImage(pell(), "npc", {}); setArtMode("generate"); return r === null; })());

  // ⛔ FOUND WHILE MUTATING SNG-401 — A PRE-EXISTING HOLE, NOT A NEW ONE. Deleting the FLOORS call from
  // `ensureImage` — the path every FIRST image in the game takes — left all ~3400 checks green. The rating
  // ceiling and minor-protection on the primary image path were entirely ungated; only the re-roll I had
  // just written was covered. A safety floor nobody tests is a safety floor that can be removed by accident.
  {
    const kidRec = { id: "wren2", name: "Wren", role: "a child of the mill", isMinor: true };
    ensureImage(kidRec, "npc", { ratingLevel: 4 });
    check("035/401: ensureImage runs the FLOORS — minor-protection on a first mint", /child-safe|wholesome/i.test(decodeURIComponent(kidRec.image || "")));
    const adultG = { id: "a1", name: "Roth", role: "a soldier, blood on his hands" };
    ensureImage(adultG, "npc", { ratingLevel: 0 });
    check("035/401: ensureImage runs the FLOORS — the viewer's ceiling on a first mint", (() => { const u = decodeURIComponent(adultG.image || ""); return u.includes("family-friendly") && !/\bblood\b/.test(u); })());
    const tail = { id: "t1", name: "Anyone", role: "a traveller" };
    ensureImage(tail, "npc", { ratingLevel: 2 });
    check("035/401/176/182: …and the ceiling rides every first mint that HAS one", /mild peril, no gore/.test(decodeURIComponent(tail.image || "")));
  }
  check("401: the prompt lookup is keyed off the DOM, not stored in it", /const _regenPrompts = new Map\(\)/.test(appSrc401) && /notePromptFor\(url, moment\.prompt\)/.test(appSrc401));
  if (artWas) localStorage.setItem("singularity.artMode", artWas);
}

// ---- SNG-400/400b: the death news carries its facts, and the battle image is BUILT ----
{
  const { buildBattlePrompt, battleKey, figureLook, powerPhrase } = await import("../engine/battleprompt.js");
  const { stampNews, clashNewsItem, applyEpicClashOutcome: applyClash400 } = await import("../engine/worldtick.js");

  // §1 THE BLOCKER. Aevi: "No victimId. No killerId. No locationId. A sentence, and a tier."
  const flat = stampNews("Word reaches you: Veln Ashpause was killed.", { worldDay: 32 });
  check("400 §1: an ordinary line is unchanged (additive — every existing caller untouched)", flat.text.length > 0 && !("victimId" in flat) && !("kind" in flat));
  const rich = stampNews({ text: "A legend has fallen.", kind: "death", victimId: "neth_the_stayed", killerId: "morvane_the_harvest", arcId: "arc_what_wakes_beneath" }, { worldDay: 32 });
  check("400 §1 THE FIX: the facts survive the news builder that used to drop them", rich.kind === "death" && rich.victimId === "neth_the_stayed" && rich.killerId === "morvane_the_harvest" && rich.arcId === "arc_what_wakes_beneath" && rich.worldDay === 32);
  check("400 §1: clashNewsItem carries a string line AND an object line (an object wrapped as {text} becomes '[object Object]')",
    clashNewsItem("X bested Y", { worldDay: 3 }).text === "X bested Y"
    && clashNewsItem({ text: "fell", kind: "death", victimId: "v" }, { worldDay: 3, arcId: "a1" }).victimId === "v"
    && !/\[object Object\]/.test(String(clashNewsItem({ text: "fell", victimId: "v" }, {}).text)));
  const wtSrc400 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
  // ⛔ SNG-433 — THIS WAS A SOURCE REGEX PINNED TO `text: event.text`, AND IT WENT RED THE MOMENT THE NEWS
  // LINE CAME FROM AEVI'S TEMPLATES INSTEAD OF THE ENGINE'S OWN SENTENCE. The claim was never about which
  // words the item carries; it is that a DEATH NEWS ITEM CARRIES ITS IDS, so the player can click it back
  // into the fight. Asserted behaviourally now — the prose is free to change and the contract is not.
  {
    const kNews = (applyClash400({}, { id: "w400", name: "W" }, { id: "l400", name: "L" }, "killed", 40).news || [])
      .find(n => n.kind === "death");
    check("400 §1: the death is emitted WITH its ids at the source, not just in the propagated event",
      !!kNews && kNews.victimId === "l400" && kNews.killerId === "w400" && !!String(kNews.text || "").trim(),
      JSON.stringify(kNews || null));
  }
  // ⛔ SNG-431 §3 — THE NUMBER IN THIS GATE ENCODED THE BUG. It asserted exactly 3 while its own sentence
  // says EVERY site, and there are FOUR places that resolve a clash: the arc fight, the strike, the
  // challenge, and the narrated stir. The fourth wrapped `{ text: line }` around the object — which is the
  // "[object Object]" failure `clashNewsItem`'s own header warns about, latent there for every death.
  // ⚠️ So it is a CENSUS now: as many shapings as there are outcomes to shape. A count that has to be
  // hand-updated when a site is added is a count that will be left behind by the next one.
  {
    // …minus the declaration itself, which matches the same call shape.
    const applies = (wtSrc400.match(/(?<!export function )applyEpicClashOutcome\(ws,/g) || []).length;
    const shapings = (wtSrc400.match(/news\.push\(clashNewsItem\(line,/g) || []).length;
    check("400 §1: every clash site emits through the one shaping",
      applies === 4 && shapings === applies, `${applies} clash sites, ${shapings} shaped emissions`);
  }
  check("400: a CHALLENGE carries no arcId — it is deliberately not part of an arc", /a challenge is NOT part of an arc[\s\S]{0,400}clashNewsItem\(line, \{ worldDay: currentWorldDay \}\)/.test(wtSrc400));

  // §3 THE BUILD — real figures from the shipped roster, not fixtures
  const epics400 = JSON.parse(readFileSync(join(root, "content/packs/valley/tradition_epics.json"), "utf8")).epics;
  const neth = epics400.find(f => f.id === "neth_the_stayed");
  const morvane = epics400.find(f => f.id === "morvane_the_harvest");
  check("400b: the roster carries the builder's INPUTS on all 66 (appearance + fightingStyle)", epics400.length === 66 && epics400.every(f => f.appearance && f.fightingStyle));
  check("400b: …and they had no reader before this (the writer-with-no-reader Aevi flagged)", !!neth && !!morvane);
  const built = buildBattlePrompt({ victim: morvane, killer: neth, place: "the braided confluence", depth: 0 });

  // ⛔ THE POINT OF THE WHOLE TICKET: a list with a conjunction in it is not a picture.
  check("400b §1 THE FAILURE IT REPLACES: the output is NOT the two presences joined by 'AGAINST'", !/\bAGAINST\b/i.test(built.prompt));
  check("400b §3: the POWER leads — it is the subject of the image, not decoration", built.prompt.toLowerCase().indexOf(String(neth.fightingStyle).slice(0, 12).toLowerCase()) === 0);
  check("400b: both figures are IN it, and in one relation rather than two descriptions", /standing over/.test(built.prompt) && /falling/.test(built.prompt) && built.prompt.includes("braided confluence"));
  check("400b §3: SHORT is the requirement — a long prompt averages into a generic picture", built.prompt.length <= 340);
  check("400b: it is a battle, sized as one", built.kind === "battle");

  // ⛔ §2a — THE FAILURE THAT KEEPS COMING BACK, AND THE CENSUS THAT CATCHES IT. Aevi's first version made
  // "the two people most likely to kill each other render as one person fighting a mirror." My first
  // version did it again by stripping the role, and my second still mirrored 2 of 5 rival pairs. This is a
  // census, not a sentence: every killer distinct, and EVERY authored rival pair distinct in both directions.
  const shots = epics400.map(f => buildBattlePrompt({ victim: morvane, killer: f, place: "x" }).prompt);
  check("400b §2a: all 66 killers give 66 different pictures", new Set(shots).size === 66);
  const rivalPairs = epics400.filter(f => (f.rivals || []).length)
    .map(f => [f, epics400.find(x => x.id === f.rivals[0])]).filter(([, r]) => r);
  const mirrored = rivalPairs.filter(([a, b]) => buildBattlePrompt({ victim: b, killer: a }).prompt === buildBattlePrompt({ victim: a, killer: b }).prompt);
  check(`400b §2a: not one of ${rivalPairs.length} authored rival pairs renders as a mirror`, rivalPairs.length >= 50 && mirrored.length === 0);
  check("400b §2a: it individuates from the ONE field that is 66/66 distinct (Aevi's own answer)", (() => {
    const stripped = epics400.map(f => buildBattlePrompt({ victim: morvane, killer: { ...f, offscreenVerbs: [], personalVerbs: [] }, place: "x" }).prompt);
    return new Set(stripped).size < 66;   // remove it and the collisions come straight back
  })());
  check("400b: a prompt never ends on a dangling fragment (a truncated clause is drawn as detail)", shots.every(s => !s.includes("…")) && Math.max(...shots.map(s => s.length)) <= 400);
  check("400b: the ABILITY, when there is one, outranks the fighting style — the power actually used",
    powerPhrase({ name: "The Cut Thread", shape: "a single severing motion", effectTags: ["sever"], description: "ends without wounding" }, neth).startsWith("The Cut Thread"));
  check("400b: with no ability it falls back to the killer's authored style, never to nothing", powerPhrase(null, neth).length > 5 && powerPhrase(null, {}) === "a killing blow");
  check("400b: a figure reduces to a LOOK and a MOTION, not a biography", (() => { const l = figureLook(neth); return l.look.length <= 160 && l.motion.length <= 70 && l.name === neth.name; })());
  // ⚠️ ITS OWN GATE, because it is no longer load-bearing for DISTINCTNESS and would otherwise be
  // droppable in silence. Once the per-person verb landed, removing the role stopped collapsing anything
  // — but "master ashwarden" vs "reaper ashwarden" is real information about what the picture shows, and
  // a thing that is only valuable and not load-bearing is exactly the thing a refactor deletes.
  check("400b: the role + tradition survive the trim (a master and a reaper are different pictures)", (() => {
    const a = figureLook(neth).look, b = figureLook(morvane).look;
    return /master/.test(a) && /ashwarden/.test(a) && /reaper/.test(b) && a !== b;
  })());
  check("400b: figureLook survives a null figure rather than throwing mid-build", (() => { try { return figureLook(null).name === "someone"; } catch { return false; } })());

  // §4 THE FALLBACK — "there is no illness in this game"; the real fallback is a death with no named killer
  const lone = buildBattlePrompt({ victim: neth, killer: null, place: "the ridge", depth: 2 });
  check("400b §4: no killer → ONE figure, and it prefers the authored deathImagePrompt", lone.kind === "death" && lone.prompt.includes(String(neth.deathImagePrompt).slice(0, 25)));
  check("400b §4: …and it invents no opponent", !/standing over|falling/.test(lone.prompt));
  check("400b: how deep the ending ran changes the picture", buildBattlePrompt({ victim: morvane, killer: neth, depth: 0 }).prompt !== buildBattlePrompt({ victim: morvane, killer: neth, depth: 2 }).prompt);

  // §3 CACHING — "a re-rolling battle quietly says it was a different fight"
  const k1 = battleKey({ victimId: "a", killerId: "b", abilityId: null, worldDay: 32 });
  check("400b §3: the cache key is victim|killer|ability|worldDay", k1 === "a|b|-|32" && battleKey({}) === "?|-|-|?");
  check("400b: the same fight keys the same forever; a different day is a different fight", k1 === battleKey({ victimId: "a", killerId: "b", worldDay: 32 }) && k1 !== battleKey({ victimId: "a", killerId: "b", worldDay: 33 }));

  // the reader — Aevi: "without ids there is nothing to click"
  const appSrc400 = readFileSync(join(root, "app.js"), "utf8");
  check("400 §3.2: a death news item is CLICKABLE and opens the battle", /data-battlenews=/.test(appSrc400) && /function battleImageFor/.test(appSrc400));
  // ⚠️ SNG-431 §3 widened this to every clash, so the shape it asserts moved. The CLAIM is unchanged and is
  // the load-bearing half: a control is offered only when the figures are on the roster and art is on —
  // "a control that opens nothing is worse than a line of prose".
  check("400 §3.2: …only when it is genuinely openable (a control that opens nothing is worse than prose)",
    /const known = \(id\) => !!id && roster188\.some\(f => f\.id === id\);/.test(appSrc400)
    && /const roster188 = worldRoster\(character\.worldState \|\| \{\}, CONTENT\) \|\| \[\];/.test(appSrc400)
    && /const canSee = \(n\) => imagesEnabled\(\) && \(/.test(appSrc400)
    && /\(n\?\.kind === "death" && known\(n\.victimId\)\)/.test(appSrc400));
  // ⛔ SNG-431 §3: and the other three outcomes are the ones Erik actually sees.
  check("431/3: a wounded, checked or stalemated fight is clickable too — not only a death",
    /\(n\?\.kind === "clash" && known\(n\.winnerId\) && known\(n\.loserId\)\)\);/.test(appSrc400)
    && /if \(!isDeath && !\(item\.kind === "clash" && outcome\)\) return null;/.test(appSrc400));
  // ⚠️ THE OUTCOME IS IN THE CACHE KEY, or two fights between the same pair share one picture.
  // ⛔ CCODE-188 (Erik): "there's no link to click on the 'bested' to see the scene where those two
  // fought." The lines already in his log predate the ids and would never carry them, so a fix that only
  // helps future fights leaves every fight he can currently see dead on the page. Recovered from the
  // ENGINE'S OWN four templates — exact splits, whole-name `===` against the roster, null on any miss.
  // ⚠️ AND IT ASSERTS THE USE, NOT THE PRESENCE. Written as "the CLASH_SHAPES constant exists" it stayed
  // GREEN with the loop mutated to iterate an empty array — the table was still there and reached nothing.
  // That is the same shape as a registered-but-unloaded content file, one layer down, and it is the fifth
  // time this session a gate of mine has checked that something EXISTS rather than that it RUNS.
  check("CCODE-188: a fight recorded before the ids existed is still openable",
    /for \(const \[re, outcome\] of CLASH_SHAPES\) \{/.test(appSrc400)
    && /const n = raw\?\.kind \? raw : \(recovered\(raw\) \|\| raw\);/.test(appSrc400)
    && /const byName = \(nm\) => roster188\.find\(f => f\?\.name === nm\) \|\| null;/.test(appSrc400)
    && /if \(!w \|\| !l\) return null;/.test(appSrc400));
  // ⚠️ AND THE PATTERNS ARE THE ENGINE'S. A recovery regex that drifts from the template it parses is a
  // silent no-op, so it is checked against what `applyEpicClashOutcome` actually writes, not against itself.
  check("CCODE-188: …and the patterns still match what the engine writes, for all four outcomes", (() => {
    const A = { id: "w", name: "The Unbound", tier: "heroic", homeLocation: "a" };
    const B = { id: "l", name: "The Ender Who Forgot Why", tier: "heroic", homeLocation: "b" };
    const SHAPES = [
      [/^(.+?) bested (.+?) — .+ withdraws to lick their wounds\.$/, "wounded"],
      [/^(.+?) checked (.+?) — for now, .+ designs are held\.$/, "stopped"],
      [/^(.+?) and (.+?) met — and neither could break the other\.$/, "stalemate"],
      [/^A legend has fallen: (.+?) has killed (.+?)\. The world is one great figure lighter/, "killed"],
    ];
    return ["wounded", "stopped", "stalemate", "killed"].every(k => {
      const t = applyEpicClashOutcome({}, A, B, k, 10, {}).news[0].text;
      return SHAPES.some(([re, o]) => { const m = re.exec(t); return m && o === k && m[1] === A.name && m[2] === B.name; });
    });
  })());
  // ⛔ CCODE-188 (Erik, on the whois card for The Unbound): "this popup screen doesn't have a discard
  // button." A world figure's portrait is minted from a seed and never enters the gallery, so it had
  // neither a `meta` nor a second picture — the two things the old rule required.
  check("CCODE-188: the ONLY picture of a subject can be discarded — the card re-mints from the seed",
    /\|\| \(isGeneratedImage\(it\.url\) && !!it\.regen\?\.subjectId && !!spec\?\.keep\);/.test(appSrc400));

  check("431/3: the same pair meeting twice gets two pictures — the outcome is part of the key",
    /const key = battleKey\(\{ victimId: loserId, killerId: winnerId, abilityId: item\.abilityId, worldDay: item\.worldDay, outcome \}\);/.test(appSrc400));
  // …and the picture is not a killing when nobody died.
  check("431/3: the prompt frames what actually happened — a stalemate is not drawn as a death", (() => {
    const bp = { name: "A", appearance: "lean", fightingStyle: "fast" }, cp = { name: "B", appearance: "vast", fightingStyle: "slow" };
    const k = buildBattlePrompt({ victim: bp, killer: cp, place: "here", outcome: "killed" }).prompt;
    const st = buildBattlePrompt({ victim: bp, killer: cp, place: "here", outcome: "stalemate" }).prompt;
    return /standing over/.test(k) && /falling/.test(k) && /the moment of the ending/.test(k)
      && /locked against/.test(st) && !/falling/.test(st) && !/the moment of the ending/.test(st)
      && buildBattlePrompt({ victim: bp, killer: cp, outcome: "stalemate" }).kind === "battle";
  })());
  check("400b: the cache key IS the image seed, so stability is a property of the build", /imageURLFor\(built\.kind, safe, key\)/.test(appSrc400));
  // ⚠️ CCODE-190 moved what the floors are applied TO — the COMPOSED line, not the builder's raw list.
  // The claim is unchanged and is the load-bearing half: the floors run on whatever reaches the model.
  check("400b: the mint runs the FLOORS like every other image", /sanitizeImagePrompt\(composedOut\.prompt, \{ ratingLevel: viewerRatingLevel\(\), isMinor: isMinorSubject\(victim\) \}\)/.test(appSrc400));
  check("400b: an unknown figure yields no picture rather than a guessed one", /if \(!victim\) return null;/.test(appSrc400));
  // ⚠️ WINDOW WIDENED FOR CCODE-186, which gave `battle` a `current` and a fallback store — the entry grew
  // past 200 characters and this went red on a change that made it MORE capable, not less. A byte-window
  // around a code shape is a gate that fails on its own subject growing; the assertion is what it stores.
  check("400b × 401: the battle is re-rollable AND re-describable — the first real builder behind Rebuild",
    /battle: \{[\s\S]{0,700}character\.battleImages\[key\]\.url = url/.test(appSrc400));
  const artSrc400 = readFileSync(join(root, "engine/art.js"), "utf8");
  // ---- CCODE-189: author-directed text was reaching the image model ------------------------------------
  // ⛔ Measured on a live world: 35 of 385 abilities and 8 of 70 appearances carry ⛔/⚠️ markers or SHOUTING,
  // and all of it went into the picture. A real prompt opened "The Borne Bargain — reposition, ⚠️ ABYSSAL
  // ---- CCODE-190: code selects the parts, a model composes the line -----------------------------------
  // ⛔ Erik, on the measured numbers: "wire it. Do this for every image because i think it will be hugely
  // valuable." Across 269 real fights the deterministic builder produced a median of 14 comma clauses,
  // 268 of 269 with eight or more, and 248 repeating a word — "a list with a conjunction in it", the exact
  // failure battleprompt.js exists to replace, after two rounds of tuning its clamps.
  // ⚠️ EVERY CHECK HERE INJECTS ITS OWN `call`. No test spends Erik's API key.
  {
    const IP = await import("../engine/imageprompt.js");
    const LIST = "The Borne Bargain — reposition, sovereign abyssal, horned, dressed better than anyone "
      + "expects, closes a bargain that hollows someone, sovereign, bargain-marks lighting as they take, "
      + "locked against, investigator verist, nothing concealed, says the true thing no one wanted said, "
      + "neither of them breaking, at The Unblinking Stone";
    const ONE_LINE = "a horned figure in fine dress closing a bargain, bargain-marks lighting as they take, "
      + "locked against a plain-faced investigator, neither breaking, at the Unblinking Stone";

    let calls = 0;
    const call = async () => { calls++; return ONE_LINE; };
    const cache = {};
    const first = await IP.composeImagePrompt(LIST, { cache, kind: "battle", call });
    check("CCODE-190: a list of parts comes back as one line",
      first.composed && first.prompt === ONE_LINE && calls === 1, JSON.stringify(first));

    // ⛔ AEVI'S STABILITY RULE IS THE LOAD-BEARING ONE: "same fight, same picture, forever. A re-rolling
    // battle quietly says it was a different fight." Determinism is a property of the CACHE, so the model
    // is asked once, ever — non-determinism never reaches the player.
    const second = await IP.composeImagePrompt(LIST, { cache, kind: "battle", call: async () => { calls++; return "SOMETHING ELSE ENTIRELY"; } });
    check("CCODE-190: the same subject is composed ONCE, ever — the cache is what makes it stable",
      second.prompt === ONE_LINE && second.composed && calls === 1, `calls=${calls} prompt=${second.prompt}`);

    // ⛔ AND IT NEVER BLOCKS A PICTURE. No key, offline, refused, rate-limited — the deterministic prompt
    // is what comes back, unchanged. This is the project's own law applied to a call in front of an image.
    // ⚠️ WRAPPED, BECAUSE A GATE THAT CRASHES IS NOT A GATE THAT FAILS. With the fallback mutated out,
    // `composeImagePrompt` rejects, the rejection escapes this block, and the whole SUITE dies mid-file —
    // taking the twelve checks below it with it. The run then looks like a crash rather than a red line,
    // and a harness reading stdout's tail reports it as a pass. Turn the throw into the failure it is.
    let boom;
    try { boom = await IP.composeImagePrompt(LIST, { cache: {}, kind: "battle", call: async () => { throw new Error("NO_API_KEY"); } }); }
    catch (e) { boom = { prompt: `THREW: ${e?.message}`, composed: null }; }
    check("CCODE-190: a failed or keyless compose returns the builder's own prompt, unchanged",
      boom.prompt === LIST && boom.composed === false, boom.prompt.slice(0, 60));

    // ⚠️ A REFUSAL IS NOT A PROMPT — returning one puts "I can't help with that" into an image generator.
    for (const bad of ["I can't help with that.", "Sorry, I cannot create that image.", "", "```", "  "]) {
      const r = await IP.composeImagePrompt(LIST, { cache: {}, kind: "battle", call: async () => bad });
      check(`CCODE-190: a refusal or empty reply is refused, not drawn — ${JSON.stringify(bad.slice(0, 22))}`,
        r.prompt === LIST && r.composed === false, r.prompt.slice(0, 60));
    }
    // …and the wrapper a model adds anyway is stripped rather than trusted.
    const wrapped = await IP.composeImagePrompt(LIST, { cache: {}, kind: "battle", call: async () => `Here's the prompt:\n"${ONE_LINE}"` });
    check("CCODE-190: 'Here's the prompt:' and its quotes are stripped rather than drawn",
      wrapped.composed && wrapped.prompt === ONE_LINE, wrapped.prompt);

    // ⚠️ ASSERTED BEHAVIOURALLY, not against an imported constant — an exported constant that is only ever
    // READ is indistinguishable from a dead export to the importedNeverCalled ratchet. 240 is the module's cap.
    const longOut = (await IP.composeImagePrompt(LIST, { cache: {}, kind: "b", call: async () => "x, ".repeat(400) })).prompt;
    check("CCODE-190: a composed line respects the cap the builders could not hold",
      longOut.length <= 240 && longOut.length > 0, `${longOut.length} chars`);

    // ⛔ A SHORT PROMPT IS NOT WORTH A CALL. Composing one adds drift and spends a request for nothing.
    let cheap = 0;
    const short = await IP.composeImagePrompt("a lean scarred woman on a wet stone bridge at dusk",
      { cache: {}, kind: "npc", call: async () => { cheap++; return ONE_LINE; } });
    check("CCODE-190: an already-short prompt is left alone — no call, no drift",
      cheap === 0 && short.composed === false);

    // ---- CCODE-191: both fights came back as ONE person -------------------------------------------------
    // ⛔ Erik, on the first real results: "seems like you'll really need to start with the two figures if you
    // want to get them both in." The pictures proved it — Neth's grey wool robes wearing the Choirmaster's
    // mid-blow palm, in one body. The composer was told it was compressing "a list of visual details" and had
    // no idea two people were in the list, so it fused them: `buildBattlePrompt`'s own design ("two figures in
    // ONE relation") undone by the thing meant to serve it.
    {
      const twoSys = [];
      const spy = async (msgs, o) => { twoSys.push(o.system); return "figure in grey wool robes, palm raised mid-blow, kneeling"; };
      const r2 = await IP.composeImagePrompt(LIST, { cache: {}, kind: "battle", subjects: 2, call: spy });
      // ⚠️ SUBJECT COUNT IS THE FRAME, NOT A DETAIL. An image model decides how many bodies to draw in the
      // first few words — a count that arrives as a subordinate clause a third of the way in gets ignored.
      check("CCODE-191: a two-figure fight is composed as two figures, and the count LEADS",
        /^two figures\b/i.test(r2.prompt), r2.prompt);
      check("CCODE-191: …and the composer is told there are two, rather than left to guess from a comma list",
        /TWO FIGHTING FIGURES/.test(twoSys[0] || "") && /FIRST WORDS/.test(twoSys[0] || ""));
      // ⛔ ENFORCED, NOT MERELY ASKED FOR — the model mostly complies; when it does not, code puts the frame
      // back rather than shipping a two-person fight as one body.
      check("CCODE-191: a reply that forgets the count has it restored, not shipped as one body",
        IP.cleanComposed("figure in grey wool robes, kneeling, palm raised", true).startsWith("Two figures"));
      check("CCODE-191: …and a reply that already leads with it is not doubled",
        (IP.cleanComposed("Two figures — a spectre and a kneeling woman", true).match(/two figures/gi) || []).length === 1);
      check("CCODE-191: a single-subject picture is never given a second body",
        !/two figures/i.test(IP.cleanComposed("a lean scarred woman on a wet bridge at dusk", false)));
      // ⛔ AND THE COUNT IS IN THE CACHE KEY, or the one-figure picture Erik already has would be served
      // back forever and never re-composed.
      // ⚠️ ASSERTED THROUGH `composeImagePrompt`, NOT `composeKey`. Written against the helper it stayed GREEN
      // with the count removed from the call site — the key function still distinguished "1" from "2" while
      // nothing passed either. Testing the helper is not testing the wiring.
      {
        const shared = {};
        await IP.composeImagePrompt(LIST, { cache: shared, kind: "battle", subjects: 1, call: async () => "one lone figure kneeling in mist, palm raised" });
        const asTwo = await IP.composeImagePrompt(LIST, { cache: shared, kind: "battle", subjects: 2, call: async () => "Two figures locked, one striking, one giving no ground" });
        check("CCODE-191: the subject count is part of the cache key — an old one-figure compose is not reused",
          /^two figures/i.test(asTwo.prompt), asTwo.prompt);
      }
      // The builder is the only thing that knows there are two; it now says so.
      const bp191 = await import("../engine/battleprompt.js");
      const two191 = bp191.buildBattlePrompt({ victim: { name: "A", appearance: "grey wool" }, killer: { name: "B", appearance: "half-transparent" }, place: "x", outcome: "wounded" });
      const one191 = bp191.buildBattlePrompt({ victim: { name: "A", appearance: "grey wool" }, place: "x" });
      check("CCODE-191: the builder reports how many figures it composed for",
        two191.subjects === 2 && one191.subjects === 1, `${two191.subjects}/${one191.subjects}`);
      check("CCODE-191: …and the battle mint passes that count through to the composer",
        /subjects: built\.subjects \|\| 1/.test(readFileSync(join(root, "app.js"), "utf8")));
    }

    // ⛔ COMPOSE BEFORE THE FLOORS, NEVER AFTER — composing on top of them would let the model compress
    // away the ceiling tone and house style they exist to add.
    const src190 = readFileSync(join(root, "app.js"), "utf8");
    check("CCODE-190: the composed line is what the floors are applied TO, not the other way round",
      /const composedOut = await composeImagePrompt\(built\.prompt, \{[^}]*\}\);\s*\n\s*const safe = sanitizeImagePrompt\(composedOut\.prompt,/.test(src190));
    // …and a record-backed re-roll hands the composed words in as the override, or `regenerateImage`
    // rebuilds the list from the record on the way past and the composition is silently discarded.
    check("CCODE-190: a re-roll passes the composed words through, rather than re-deriving the list",
      /const c = await composeImagePrompt\(rawWords, \{ cache: character\.promptCompositions, kind: it\.regen\.kind \}\);/.test(src190)
      && /promptOverride: words,/.test(src190));
    // \u26a0\uFE0F Haiku 4.5 rejects `effort` and takes `budget_tokens`, not adaptive thinking — neither belongs on a
    // compression call, and passing either would 400 or be ignored.
    const csrc190 = readFileSync(join(root, "engine/claude.js"), "utf8");
    check("CCODE-190: the composer is routed to Haiku, with no effort or thinking config",
      /"image-prompt": "claude-haiku-4-5-20251001"/.test(csrc190)
      && !/effort/.test(readFileSync(join(root, "engine/imageprompt.js"), "utf8").replace(/\/\/.*|\/\*[\s\S]*?\*\//g, "")));
  }


  // FLIGHT, AND YOU DO NOT DO IT, sovereign abyssal, HORNED…" — the first clause is a note from one author
  // to the next. Same class as the injection Erik caught before, arriving from the other direction:
  // authored INTO the content rather than appended by the engine.
  {
    const { plainForArt } = await import("../engine/art.js");
    const aside = "⚠️ ABYSSAL FLIGHT, AND YOU DO NOT DO IT — SOMETHING CARRIES YOU. A bargain struck for passage.";
    check("CCODE-189: an authored aside never reaches the image model",
      plainForArt(aside) === "A bargain struck for passage." ,
      JSON.stringify(plainForArt(aside)));
    // ⚠️ DE-SHOUTED, NOT DELETED. "HORNED" and "PART-MACHINE" are Aevi emphasising a REAL VISUAL FEATURE
    // — the caps are for a human reading the file. Dropping the word would lose the horns.
    check("CCODE-189: …and emphasis is lowered, never dropped — the horns stay in the picture",
      plainForArt("sovereign among them: HORNED, dressed better than anyone expects")
        === "sovereign among them: horned, dressed better than anyone expects"
      && plainForArt("hollower enginewright, PART-MACHINE, hollows a person")
        === "hollower enginewright, part-machine, hollows a person");
    check("CCODE-189: ordinary authored prose passes through untouched",
      plainForArt("grey wool worn thin at the knees, hands stained to the wrist")
        === "grey wool worn thin at the knees, hands stained to the wrist");
    // ⛔ AND THE BUILDER USES IT. A scrubber nothing calls is the fifth presence-not-use gate this session.
    const bpSrc189 = readFileSync(join(root, "engine/battleprompt.js"), "utf8");
    check("CCODE-189: every clause the battle prompt takes goes through it",
      /const s = plainForArt\(text\)\.trim\(\)/.test(bpSrc189)
      && /import \{ plainForArt \} from "\.\/art\.js";/.test(bpSrc189));
    // ⛔ SHORT IS THE REQUIREMENT (Aevi). The description is reader-prose and was appended on top of the
    // visual `shape`, pushing 269 real prompts to a 362-char average against a 400 cap.
    check("CCODE-189: the power phrase leads with what it LOOKS like, not the paragraph explaining it",
      /const visual = \[shape, tags\]\.filter\(Boolean\)\.join\(", "\);/.test(bpSrc189)
      && /const named = visual \|\| clause\(ability\.description/.test(bpSrc189));
    check("CCODE-189: …and a craft with no shape still says something",
      /Old Hunger — a slow taking/.test(powerPhrase({ name: "Old Hunger", description: "a slow taking that leaves the shape behind" }, {})),
      powerPhrase({ name: "Old Hunger", description: "a slow taking that leaves the shape behind" }, {}));
  }
  check("400b: a battle has its own wide frame (a portrait crop of a fight shows one shoulder)", /battle:\s+\{ width: 1024, height: 512 \}/.test(artSrc400) && /death:\s+\{ width: 768, height: 512 \}/.test(artSrc400));
}

// ---- CCODE-180: the caption was running under the buttons ----
// Erik sent a screenshot: "…e waystation fire—shelter-keeper, traveler · version 2 of 2 · 19/29 in the
// gallery · a new draw" with the head cut off by one button and the tail colliding with another.
// ⛔ CAUSE: each action was ABSOLUTELY POSITIONED at its own offset into the band the caption occupies, so
// a long caption slid beneath them, and a button that did not render left a hole instead of letting its
// neighbours close up. Four independent anchors is how it got there; pixel-nudging them is how it stays.
{
  const css180 = readFileSync(join(root, "style.css"), "utf8");
  const app180 = readFileSync(join(root, "app.js"), "utf8");
  const ACTIONS = ["lightbox-regen", "lightbox-rebuild", "lightbox-discard", "lightbox-keep"];

  check("CCODE180: the four actions live in ONE row", /<div class="lightbox-actions">/.test(app180)
    && /\.lightbox-actions \{[^}]*display: flex[^}]*flex-wrap: wrap/.test(css180));
  // ⛔ THE REGRESSION THAT ALMOST SHIPPED: a stale absolute rule sat LATER in the file than the new row and
  // won the cascade, so the button would have re-absoluted itself while the row looked correct in source.
  check("CCODE180: not one action is absolutely positioned any more", ACTIONS.every(cls => {
    const rules = [...css180.matchAll(new RegExp(`\\.${cls}[^{]*\\{([^}]*)\\}`, "g"))].map(m => m[1]);
    return rules.length > 0 && rules.every(body => !/position:\s*absolute/.test(body));
  }), () => ACTIONS.filter(cls => [...css180.matchAll(new RegExp(`\\.${cls}[^{]*\\{([^}]*)\\}`, "g"))].some(m => /position:\s*absolute/.test(m[1]))).join(", "));
  check("CCODE180: and none of them carries a hand-tuned left/right offset", ACTIONS.every(cls =>
    [...css180.matchAll(new RegExp(`\\.${cls}[^{]*\\{([^}]*)\\}`, "g"))].every(m => !/(^|;)\s*(left|right):/.test(m[1]))));
  // ⚠️ COUNT THE STRUCTURAL RULE, NOT EVERY MENTION. My first version counted `.lightbox-actions {` and
  // caught the responsive `gap` override inside the media query — a legitimate second mention, not a
  // second definition. What must be unique is the rule that decides the LAYOUT.
  check("CCODE180: the row's layout is defined ONCE, so a later rule cannot quietly re-break it",
    (css180.match(/\.lightbox-actions \{[^}]*display:/g) || []).length === 1);
  check("CCODE180: the caption is free to wrap rather than slide under anything", /\.lightbox-cap \{ max-width: 92vw; \}/.test(css180));
  // the image must yield room, or the row clips off the bottom and looks like it does not exist
  check("CCODE180: the picture leaves room for the caption and the row on a short screen", (() => {
    const m = css180.match(/\.lightbox-inner img \{[^}]*max-height:\s*(\d+)vh/);
    return m && Number(m[1]) <= 80;
  })());
  check("CCODE180: close/save/details stay pinned at the top, away from the caption band",
    /\.lightbox-close \{[^}]*position: absolute[^}]*top:/.test(css180) && /\.lightbox-meta-btn \{[^}]*position: absolute[^}]*top:/.test(css180));
}

// ---- CCODE-185: an index into a mutable list is not a handle ----
// Erik: "after keeping some photos the gallery doesn't refresh, so when I click on something it opens up
// something else." ⛔ The tile carried `data-lbindex` — a POSITION captured when the grid rendered. Keeping
// an image unshifts a new entry at index 0, so every index the DOM was holding shifted by one and every
// tile opened its neighbour. The bug is not "the gallery is stale"; it is that a position was ever used as
// a name for a thing.
{
  const src185 = readFileSync(join(root, "app.js"), "utf8");
  // the class of bug, demonstrated rather than described
  check("CCODE185 THE BUG: an index handle points at the wrong picture once the list grows at the front", (() => {
    const g = [{ url: "a" }, { url: "b" }, { url: "c" }];
    const idxAtRender = 1;
    g.unshift({ url: "NEW" });                    // exactly what addGalleryImage does on a Keep
    return g[idxAtRender].url !== "b";
  })());
  check("CCODE185 THE FIX: a URL handle survives it", (() => {
    const g = [{ url: "a" }, { url: "b" }, { url: "c" }];
    g.unshift({ url: "NEW" });
    return g[g.findIndex(x => x.url === "b")].url === "b";
  })());
  // ⚠️ STRIP COMMENTS BEFORE A NEGATIVE. The note above explaining this bug contains `data-lbindex`, so the
  // assertion failed on its own explanation — the fifth time this session a checker has matched the prose
  // about a thing rather than the thing. A negative claim about CODE has to be made against code.
  const markup185 = src185.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
  check("CCODE185: the tile carries its url and no index at all",
    /data-lburl="\$\{esc\(g\.url\)\}"/.test(markup185) && !/data-lbindex/.test(markup185));
  check("CCODE185: …and the position is resolved against the CURRENT gallery at click time",
    /const at = Math\.max\(0, items\.findIndex\(x => x\.url === want\)\);/.test(src185));
  check("CCODE185: a url that has since been discarded still opens something rather than nothing", /Math\.max\(0, /.test(src185));
  // and the grid catches up with whatever happened inside the box
  check("CCODE185: the lightbox tells its caller when it closes", /function openLightbox\(items, start = 0, \{ onClose = null \} = \{\}\)/.test(src185)
    && /try \{ onClose\?\.\(\); \} catch/.test(src185));
  check("CCODE185: the gallery re-renders on close, so counts and defaults are current",
    /onClose: \(\) => \{ if \(document\.querySelector\("\.gallery-grid"\)\) renderGallery\(\); \}/.test(src185));
  check("CCODE185: …and a failing redraw never eats the close", /catch \{ \/\* a redraw is never worth eating the close \*\/ \}/.test(src185));
}

// ---- CCODE-184: "I want to be able to set the default picture please." ----
// ⛔ KEEP WAS DOING TWO JOBS. It cast the likeness vote AND silently became the shown picture — so keeping a
// fifth image because you liked one detail of it replaced the face you had already chosen, and there was no
// way to say which one represents someone. Two sentences, two buttons:
//   ☆ Keep this look  — this is what they LOOK like   (a vote, many, accumulates, steers future renders)
//   ★ Set as default  — this is the picture to SHOW   (exactly one, and it pins against the re-mint)
{
  const src184 = readFileSync(join(root, "app.js"), "utf8");
  // ⚠️ THE MARKUP **AND** THE HANDLER. Checking the bare attribute passed while half the feature was gone —
  // the mutation removed the button and the querySelector still matched.
  check("CCODE184: there is a button that sets the default picture, and something listening to it",
    /<button class="lightbox-default" data-lbdefault/.test(src184) && /★ Set as default/.test(src184)
    && /el\.querySelector\("\[data-lbdefault\]"\)/.test(src184));
  check("CCODE184: it is offered only when this is NOT already the default", /const canSetDefault = !!it\.regen\?\.subjectId && !!spec\?\.keep && !isCurrent;/.test(src184));
  // ⛔ THE SPLIT ITSELF: keeping must no longer change what is shown
  check("CCODE184: KEEP no longer sets the shown picture — it is a vote and only a vote",
    !/if \(!spec\.keep\(it\.regen\.subjectId, it\.url, it\.seedKey\)\) return false;/.test(src184));
  // ⚠️ CCODE-193: loosened from the exact argument list, which broke the day the URL started being
  // resolved through the composed-re-mint table. The claim is WHICH function the button calls and with
  // whose id — not the spelling of its second argument.
  check("CCODE184: …and the default button is what calls the kind's keep",
    /const ok = sub\.spec\.keep\(it\.regen\.subjectId, [^;]*it\.seedKey\);/.test(src184));
  // ⚠️ CCODE-186 SUPERSEDED THE CLAIM THIS ONE USED TO MAKE. It read "a subject-less picture offers
  // neither (nothing to represent, nothing to vote on)" — true when written, and Erik has since ruled the
  // other way: *"make sure all images have this."* There are no subject-less pictures now; `keepableRegen`
  // gives a one-off its own url as a subject. The LINE is still the right guard (a kind with no `keep`
  // still offers nothing), so the check stays and its sentence is corrected rather than left lying.
  check("CCODE184: the offer is keyed on a subject and a kind that can store one",
    /const canKeep = !!it\.regen\?\.subjectId && !!spec\?\.keep;/.test(src184));
  // the two must remain independent, which is the whole point
  const { toggleKeep: tk184, acceptImage: ai184 } = await import("../engine/art.js");
  const store184 = {}, rec184 = { id: "pell", name: "Pell", image: "chosen" };
  tk184(store184, "npc:pell", { url: "other", note: "dark hair", prompt: "dark hair, strong build" });
  check("CCODE184: keeping a DIFFERENT picture does not move the default", rec184.image === "chosen" && store184["npc:pell"].keeps.length === 1);
  ai184(rec184, { url: "other", seedKey: "s" });
  check("CCODE184: …and setting the default does not add a vote", rec184.image === "other" && store184["npc:pell"].keeps.length === 1);
  check("CCODE184: setting a default still PINS, so the milestone re-mint cannot overrule the choice", rec184.imagePinned === true);
  // and the gallery stack shows whatever the default is
  check("CCODE184: the stack's representative follows the default", /const rep = st\.members\.find\(m => m\.url === chosen\) \|\| st\.members\[0\];/.test(src184));
}

// ---- CCODE-183: the gallery stacks by subject ----
// Erik: "I have created several images of Pell now that I like and have kept. They don't need to appear
// separate in the gallery — they should show up as the one I choose to represent her, and when clicked I
// can see all the other kept images in a rotating stack… This can apply to all versions of images rendered.
// If I like a battle scene I want to be able to render a few more images of it to keep."
// ⚠️ THE GRID AND THE LIGHTBOX ALREADY DISAGREED: the lightbox has grouped versions by subject since
// CCODE-172, and the grid never did — so one person held four tiles and the count said 76 for far fewer
// actual subjects. This is that same grouping applied one layer up.
{
  const src183 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE183: the grid groups into stacks before it renders", /const stacks = galleryStacks\(shown\);/.test(src183) && /function galleryStacks\(entries\)/.test(src183));
  check("CCODE183: a stack shows the picture the player CHOSE, not merely the newest",
    /const chosen = spec\?\.current \? spec\.current\(st\.regen\.subjectId\) : null;/.test(src183)
    && /const rep = st\.members\.find\(m => m\.url === chosen\) \|\| st\.members\[0\];/.test(src183));
  check("CCODE183: …and it says how many are behind it", /gal-stack-badge/.test(src183) && /\$\{n\} pictures of this/.test(src183));
  check("CCODE183: a picture with NO subject stays its own tile (a moment is not part of anything)", /`solo:\$\{g\.url\}`/.test(src183));
  // ⚠️ CORRECTED BY CCODE-185: the tile carries its URL, not a position — an index captured at render time
  // pointed at the wrong picture the moment a Keep unshifted a new entry. The property is unchanged: the
  // stack opens on its own representative, and the lightbox's per-subject ring takes it from there.
  check("CCODE183/185: opening a stack opens the REPRESENTATIVE, resolved at click time",
    /data-lburl="\$\{esc\(g\.url\)\}"/.test(src183)
    && /const at = Math\.max\(0, items\.findIndex\(x => x\.url === want\)\);/.test(src183));

  // ⚠️ THE SHAPE keepLightboxItem ACTUALLY WRITES — his four Pell tiles, plus a legacy one with no
  // provenance that must still join them, plus two of one battle, plus a one-off that must not.
  const tiles183 = [
    { kind: "npc", caption: "Pell", url: "p1", subjectKind: "npc", subjectId: "pell" },
    { kind: "npc", caption: "Pell", url: "p2", subjectKind: "npc", subjectId: "pell" },
    { kind: "npc", caption: "Pell", url: "p3", subjectKind: "npc", subjectId: "pell" },
    { kind: "npc", caption: "Pell — devoted", url: "p0" },
    { kind: "battle", caption: "A — killed by B", url: "b1", subjectKind: "battle", subjectId: "a|b|-|44" },
    { kind: "battle", caption: "A — killed by B", url: "b2", subjectKind: "battle", subjectId: "a|b|-|44" },
    { kind: "moment", caption: "a chase", url: "m1" }
  ];
  const { namesMatch: nm183 } = await import("../engine/namematch.js");
  const reg183 = [{ id: "pell", name: "Pell" }];
  const keyOf = (t) => {
    if (t.subjectKind && t.subjectId) return `${t.subjectKind}:${t.subjectId}`;
    const nm = String(t.caption || "").split("—")[0].trim();
    if (t.kind === "portrait" || t.kind === "npc") { const h = reg183.find(n => nm183(n.name, nm)); if (h) return `npc:${h.id}`; }
    return `solo:${t.url}`;
  };
  const grouped = tiles183.reduce((m, t) => { const k = keyOf(t); (m[k] = m[k] || []).push(t); return m; }, {});
  check("CCODE183: four kept Pell pictures become ONE tile", (grouped["npc:pell"] || []).length === 4);
  check("CCODE183: …including one minted before provenance existed, joined by name", (grouped["npc:pell"] || []).some(t => t.url === "p0"));
  check("CCODE183: two pictures of the SAME battle stack too — 'if I like a battle scene I want to render a few more'", (grouped["battle:a|b|-|44"] || []).length === 2);
  check("CCODE183: a one-off moment is left alone", (grouped["solo:m1"] || []).length === 1 && Object.keys(grouped).length === 3);
  // a battle is keepable, or "render a few more of it to keep" is not a thing you can do
  check("CCODE183: a battle CAN be kept (it carries a subject, so the Keep button is real)",
    /battle: \{[\s\S]{0,400}character\.battleImages\[key\]\.url = url/.test(src183));
}

// ---- CCODE-179: the house style follows the PEOPLE ----
// Erik: "I like to keep the house style but make sure that house style is variable based on the tradition
// they're from." The old constant locked a PALETTE — "muted earth tones with teal and gold accents" — onto
// every image in the game, competing with 26 authored tradition palettes for the same slot. An Umbral
// rendered in teal and gold is not an Umbral. The tradition file's own usage note asks for exactly this.
{
  const A179 = await import("../engine/art.js");
  const tr179 = JSON.parse(readFileSync(join(root, "content/packs/core/rules/tradition_visual_aesthetics.json"), "utf8")).traditions;
  const ids = Object.keys(tr179);
  const styles = ids.map(t => A179.houseStyleFor(tr179[t]));

  check(`CCODE179: all ${ids.length} traditions give ${ids.length} distinct style wrappers`, ids.length >= 26 && new Set(styles).size === ids.length);
  // ⚠️ THE MEDIUM NEVER MOVES — that is what keeps it one game rather than 26 unrelated galleries.
  check("CCODE179: every one keeps the constant medium", styles.every(v => v.startsWith(A179.IMAGE_STYLE_MEDIUM)));
  check("CCODE179: …and the house palette is GONE from a tradition wrapper (it was the thing competing)",
    styles.every(v => !v.includes(A179.IMAGE_STYLE_HOUSE)));
  check("CCODE179: a subject with no tradition still gets the house look",
    A179.houseStyleFor(null) === `${A179.IMAGE_STYLE_MEDIUM}, ${A179.IMAGE_STYLE_HOUSE}` && A179.houseStyleFor({}) === A179.houseStyleFor(null));
  check("CCODE179: the wrapper carries palette, light and mood — the three that make a people look like themselves", (() => {
    const w = A179.houseStyleFor(tr179.umbral);
    return /near-black, cold indigo/.test(w) && /no light source/.test(w) && /soft-footed/.test(w);
  })());
  check("CCODE179: each borrowed clause is clamped — an aesthetic is prose, the wrapper is a wrapper", styles.every(v => v.length < 260));
  // ⛔ CCODE-193: THIS WAS A SOURCE REGEX COUNTING A LITERAL, and it went red the moment both mints
  // started routing through one helper — the shape moved, the claim did not. What it means is that a
  // picture drawn for a people carries that people's palette, from EITHER path. Asserted on the URLs.
  check("CCODE179: the URL builder takes the aesthetic and BOTH mint paths hand it over", (() => {
    const aes = { palette: "near-black, cold indigo", light: "no light source", mood: "soft-footed" };
    const rec = { id: "a179", name: "Someone", appearance: "a plain coat, worn at the cuff" };
    const plain = A179.ensureImage({ ...rec }, "npc", { ratingLevel: 2 });
    const styled = A179.ensureImage({ ...rec }, "npc", { ratingLevel: 2, promptOpts: { aesthetic: aes } });
    const redrawn = A179.regenerateImage({ ...rec }, "npc", { ratingLevel: 2, promptOpts: { aesthetic: aes } });
    const carries = (u) => !!u && u.includes(encodeURIComponent("near-black, cold indigo"));
    return !carries(plain) && carries(styled) && carries(redrawn?.url);
  })());
  check("CCODE179: two traditions genuinely produce different URLs for the same prompt", (() => {
    const was = localStorage.getItem("singularity.artMode"); A179.setArtMode("generate");
    const a = A179.imageURLFor("npc", "a person", "seed", { aesthetic: tr179.umbral });
    const b = A179.imageURLFor("npc", "a person", "seed", { aesthetic: tr179.blazeborn });
    if (was) localStorage.setItem("singularity.artMode", was);
    return a !== b && decodeURIComponent(a).includes("cold indigo") && decodeURIComponent(b).includes("white-gold");
  })());
  const src179 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE179: a re-roll keeps the people's look (the regen path resolves the aesthetic too)",
    /promptOpts: rec => \(\{ aesthetic: npcAesthetic\(rec\) \}\)/.test(src179));
}

// ---- CCODE-175/176/177: Erik's rulings on what gets injected, and where a look actually comes from ----
{
  const A176 = await import("../engine/art.js");
  const was176 = localStorage.getItem("singularity.artMode"); A176.setArtMode("generate");
  const d176 = "scorched leather apron, forearms scarred";

  // ⛔ CCODE-175 — WHERE A LOOK COMES FROM. Erik: "I have Cevaine's image with white hair that I love… but
  // no re-render is giving her white hair anymore." MEASURED: nothing in her record mentions hair at all.
  // Her beloved picture was minted from "a person, character portrait, named Cevaine, Woman, …" — the
  // pre-SNG-367 generic lead — so the white hair was the model's invention from one seed. Keeping that
  // image taught the likeness nothing, because the words were never there to count. A keep can carry the
  // player's OWN words now, and they outrank clauses the engine merely assembled.
  const st175 = {};
  A176.toggleKeep(st175, "npc:cevaine", { url: "u1", note: "white hair, translucent skin",
    prompt: A176.sanitizeImagePrompt("white hair, translucent skin, Tall, angular, character portrait, named Cevaine, Woman", { ratingLevel: 2 }) });
  const lk175 = A176.likenessClause(st175["npc:cevaine"].keeps);
  check("CCODE-175 CEVAINE: the words the player typed LEAD the likeness", lk175.startsWith("white hair, translucent skin"), lk175);
  // ⚠️ A CASE WHERE THE WEIGHT ALONE DECIDES. My first version put the note first in BOTH weightings, because
  // a note also sorts earliest on ties — so it proved order, not weight. Here one note (seen once) must beat
  // an assembled clause that TWO keeps agree on; that only holds if a typed word counts double.
  check("CCODE-175: …and a word the player typed ONCE outranks a clause two prompts merely share", (() => {
    const s3 = {};
    // the note must NOT also sit in the prompt, or it wins on ordinary count and the weight proves nothing
    A176.toggleKeep(s3, "w", { url: "a", note: "white hair", prompt: "grey cloak" });
    A176.toggleKeep(s3, "w", { url: "b", prompt: "grey cloak" });
    return A176.likenessClause(s3.w.keeps).startsWith("white hair");
  })(), () => { const s3 = {}; A176.toggleKeep(s3, "w", { url: "a", note: "white hair", prompt: "grey cloak" }); A176.toggleKeep(s3, "w", { url: "b", prompt: "grey cloak" }); return A176.likenessClause(s3.w.keeps); });
  check("CCODE-175: the engine's own framing never gets a vote (it is on every portrait, so agreement would elect it)",
    !/character portrait|named cevaine|a person/i.test(lk175), lk175);
  check("CCODE-175: a keep with no note still votes on its description", (() => {
    const s2 = {}; A176.toggleKeep(s2, "k", { url: "a", prompt: "grey wool cloak, a scar" });
    return A176.likenessClause(s2.k.keeps).includes("grey wool cloak");
  })());

  // ⛔ CCODE-176 — ERIK'S RULING ON THE INJECTIONS
  check("CCODE-176: the blanket safety tail is GONE from every prompt", !/no signature|no copyrighted characters/.test(A176.sanitizeImagePrompt(d176, { ratingLevel: 4, kind: "npc" })));
  check("CCODE-176: the tone now shifts by KIND, so a battle and a portrait stop looking the same", (() => {
    const b = A176.sanitizeImagePrompt(d176, { ratingLevel: 4, kind: "battle" });
    const n = A176.sanitizeImagePrompt(d176, { ratingLevel: 4, kind: "npc" });
    return /action, epic fantasy/.test(b) && !/action, epic fantasy/.test(n) && b !== n;
  })());
  check("CCODE-176: every scene kind gets its own register", ["battle", "death", "beast", "location", "moment", "item"]
    .map(k => A176.sanitizeImagePrompt(d176, { ratingLevel: 3, kind: k })).every((v, _, all) => all.filter(x => x === v).length === 1));
  check("CCODE-176: the rating still governs on top of the kind", /no gore/.test(A176.sanitizeImagePrompt(d176, { ratingLevel: 1, kind: "battle" })) && !/no gore/.test(A176.sanitizeImagePrompt(d176, { ratingLevel: 4, kind: "battle" })));
  // the scrub leaves a hole and the hole is visible — "a sensual, erotic encounter" became "a , encounter",
  // an empty clause the generator reads as detail. Same junk class as the "no ," in the old safety tail.
  check("CCODE-178: a scrubbed word leaves no orphaned comma behind", (() => {
    const out = A176.sanitizeImagePrompt("a sensual, erotic encounter between two lovers", { ratingLevel: 0, kind: "moment" });
    return !/\s,|,\s*,|^\s*,|,\s*$/.test(out) && !/\ba\s*,/.test(out);
  })(), () => A176.sanitizeImagePrompt("a sensual, erotic encounter between two lovers", { ratingLevel: 0, kind: "moment" }));
  check("CCODE-176: the boilerplate is a fraction of what it was", (A176.sanitizeImagePrompt(d176, { ratingLevel: 4, kind: "npc" }).length - d176.length) < 60);
  // ⛔ AND THE ONE THING THAT DID NOT MOVE
  check("CCODE-176/178: a MINOR's clause rides ALONGSIDE the scene, and the ceiling is still clamped to PG", (() => {
    const m = A176.sanitizeImagePrompt(d176, { ratingLevel: 4, isMinor: true, kind: "battle" });
    return /a child, fully clothed, non-sexual/.test(m) && /epic fantasy/.test(m) && !/mature dramatic tone/.test(m) && /adventurous, mild, no gore/.test(m);
  })());
  check("CCODE-176: and the sexual scrub is still absolute for a minor at any ceiling",
    !/sensual|erotic/i.test(A176.sanitizeImagePrompt("a sensual erotic study", { ratingLevel: 4, isMinor: true })));

  // ⛔ CCODE-181/182: three things that had no gate at all, found by mutating rather than by review.
  check("CCODE-182: a KIND tone round-trips — it is strippable, so re-sanitising stays idempotent", (() => {
    const wk = A176.sanitizeImagePrompt("a fight at the gate", { ratingLevel: 2, kind: "battle" });
    return A176.bareImagePrompt(wk) === "a fight at the gate" && A176.sanitizeImagePrompt(wk, { ratingLevel: 2, kind: "battle" }) === wk;
  })());
  const srcA181 = readFileSync(join(root, "app.js"), "utf8");
  // Erik on Dawn Surgery: a Radiant craft came back in muted earth tones because the RE-ROLL carried no
  // tradition — the first mint passed one, this entry had no promptOpts at all.
  // ⚠️ SNG-435 §C3 REWROTE THIS. It was a source regex pinned to `CONTENT.traditionVisualAesthetics[...]`
  // and went red the moment six hand-rolled lookups became one resolver — the spelling moved, the claim did
  // not. The claim is that a re-roll of a craft still comes back in that craft's own colours, and it is
  // stronger now: it keeps its people where there is one, and its PHYSICS where there is not.
  check("CCODE-182: a CRAFT keeps its people on a re-roll (its own colours drive prompt and style alike)", (() => {
    // ⛔ PINNED TO SPELLING TWICE NOW. The comment above records this gate going red when six hand-rolled
    // lookups became one resolver — "the spelling moved, the claim did not" — and it was then re-pinned to
    // the NEW spelling, including a `|| rec.tradition` fallback that is PROVABLY DEAD: `traditionOf` reads
    // `ability.tradition` FIRST, so the right-hand side can never be reached.
    //
    // ⚠️ CCODE-337 removed that dead fallback and this went red again — for the second time, on a change
    // that made the code more correct. ⛔ A SOURCE GATE MUST ASSERT THE CLAIM, NOT THE CHARACTERS.
    //
    // The claim: a re-roll of a craft passes an aesthetic derived through the RESOLVER, and hands the
    // PHYSICS along too so §C3 can answer where there is no people. Both halves, neither spelling.
    // ⚠️ `.find` TOOK THE FIRST OF THREE. There are three `promptOpts: rec =>` lines — two for NPCs and one
    // for crafts — so the first match was the NPC one and none of the craft conditions could ever hold, which
    // read as "the wiring is gone" when the wiring was three lines further down.
    // ⛔ THE SAME SHAPE AS `rules[0]` AND `loadRule("ties")`: a lookup that finds A match, not THE match.
    const promptLines = srcA181.split("\n").filter(l => /promptOpts:\s*rec\s*=>/.test(l));
    const wired = promptLines.some(l => /aestheticFor\(/.test(l)
      && /abilityTradition\(rec\)/.test(l)
      && /powerSystem:\s*rec\.powerSystem/.test(l));
    const house = A176.houseStyleFor(null);
    const rootkin = A176.houseStyleFor({ palette: "deep green, bark-brown, sap-amber" });
    return wired && rootkin !== house && /deep green/.test(rootkin);
  })());
  // "no ability to keep this image" — on the warpling. A creature recurs and has an authored look; it was
  // prompt-only purely because nothing ever gave its tile a subject.
  check("CCODE-181: a BEAST tile resolves to its creature, so its look can be kept",
    /if \(g\.kind === "beast"\) \{/.test(srcA181) && /namesMatch\(c\.name, nm\)/.test(srcA181) && /subjectKind: "beast", subjectId: creature\.id/.test(srcA181));

  // ⛔ CCODE-186 (Erik): "the keep button isn't showing up on every image type. I generated a new one I
  // liked and neither the initial nor the regen had a keep button. Make sure all images have this."
  // ⚠️ AND THE INTENT WAS ALREADY IN A COMMENT AND NEVER BUILT — `likenessKey` says a tile with no record
  // "keys on its own url", and returned null. A comment describing behaviour that does not exist.
  {
    const s186 = srcA181;
    // The rule lands at the ONE place all eleven surfaces pass through. Per-surface fixes are how this got here.
    check("CCODE-186: every picture the lightbox opens is given a subject, whatever surface it came from",
      /function keepableRegen\(it\)/.test(s186) && /for \(const it of list\) it\.regen = keepableRegen\(it\);/.test(s186));
    // ⛔ CCODE-187 (Erik): "my new versions of Resonant Sight have split from the default view… leave the
    // more generic subject as the stack title." Resonant Sight is a `discovery` out of emergence_recipes
    // — not on the sheet, not in customAbilities, not in the catalog — so the name lookup finds nothing and
    // every picture of it keyed on its own URL: a stack of one, per draw. The CAPTION is the subject when
    // nothing else is, and it is identical across every draw of the same thing.
    check("CCODE-187: a tile with no record stacks on its CAPTION, so every draw of one thing is one stack",
      /if \(cap\) return `solo:cap:\$\{cap\.slice\(0, 90\)\}`;/.test(s186)
      && /const solo = soloSubjectId\(\{ caption: it\.caption \|\| it\.meta\?\.caption, seedKey: it\.seedKey, url: it\.url \}\);/.test(s186));
    check("CCODE-187: …and a tile with NO caption still falls back to its url — a stack of one is honest there",
      /return g\?\.seedKey \? `solo:\$\{g\.seedKey\}` : \(g\?\.url \? `solo:\$\{g\.url\}` : null\);/.test(s186));
    // ⚠️ A stack holds pictures made on DIFFERENT days, so one day stamped on the stack is wrong the moment
    // there are two. The details panel already carries it per image.
    check("CCODE-187: the stack title is the subject — world-day is a fact about one picture, not the stack",
      /\$\{n > 1 \? ` <span class="hint">· \$\{n\} pictures<\/span>` : g\.worldDay \?/.test(s186)
      && /\["world-day", m\.worldDay\]/.test(s186));
    // ⛔ A KIND THAT NEEDS A RECORD AND HAS NONE MUST NOT BE HANDED A SYNTHETIC ID — its `keep` would look
    // up "solo:https://…" in the registry, find nothing, and return false on click. That is the exact
    // "✕ couldn't keep" Erik hit at CCODE-166, and giving every item a subject is a fresh way to cause it.
    check("CCODE-186: …and a record-backed kind with no record falls to `moment`, never to a synthetic id",
      /return spec\.needsId \? \{ \.\.\.it\.regen, kind: "moment", label: it\.regen\.label \|\| "this moment", subjectId: solo \}/.test(s186));
    // Every kind in the table can store a keep — the census, not a spot check on the three I touched.
    const table186 = s186.slice(s186.indexOf("const REGEN_KINDS = {"), s186.indexOf("const _regenPrompts"));
    const kinds186 = [...table186.matchAll(/^  (\w+): \{/gm)].map(m => m[1]);
    // ⚠️ SLICED TO THE BLOCK'S END, not to a guessed 900 characters. SNG-435 lengthened one entry's
    // `promptOpts` line and this reported `ability` as having no keep — the census was measuring line
    // length, not capability, and it would have failed for a comment just as easily.
    const noKeep186 = kinds186.filter(k => {
      const start = table186.indexOf(`  ${k}: {`);
      const end = table186.indexOf("\n  },", start);
      return !/\bkeep: /.test(table186.slice(start, end > -1 ? end : undefined));
    });
    check("CCODE-186: every image kind can be kept — the census, not the three I happened to touch",
      kinds186.length >= 9 && noKeep186.length === 0, `${kinds186.length} kinds; without keep: ${noKeep186.join(", ")}`);
    // ⚠️ AND OFFERING A DRAW WITH NOTHING TO DRAW FROM IS "some images say they fail to redraw" reborn.
    check("CCODE-186: Draw again is offered only when there IS a record or a stored prompt behind it",
      /const hasSource = !!\(it\.regen && \(REGEN_KINDS\[it\.regen\.kind\]\?\.find\?\.\(it\.regen\.subjectId\)/.test(s186)
      && /const canRegen = !!\(it\.regen && it\.regen\.kind && hasSource && imagesEnabled\(\)\);/.test(s186));
    // Erik: "I don't need the 'chosen' tag on the display."
    check("CCODE-186: the gallery no longer tags the stack's own top picture as 'chosen'",
      !/st\.chosen \? ` <span class="rep-band trusted">chosen<\/span>`/.test(s186)
      && /class="gal-stack-badge"/.test(s186));
  }

  // CCODE-177 — discarding
  const src177 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE-177: a picture can be discarded", /data-lbdiscard/.test(src177));
  // ⚠️ CCODE-188 widened this — a subject's ONLY picture is discardable now too, because a figure portrait
  // is minted from a seed and re-mints on the next open. The claim here is unchanged: a KEPT picture is
  // discardable, not only an unsaved draw.
  check("CCODE-177: …a KEPT picture too, not only an unsaved draw",
    /const canDiscard = isDraw172 \|\| \(!!it\.meta && list\.length > 1\)/.test(src177));
  check("CCODE-177: an UNKEPT draw is simply dropped from the run — it was never written anywhere", /if \(isDraw172 && !keepsFor\(it\.regen\)\.some\(k => k\.url === it\.url\)\)/.test(src177));
  check("CCODE-177: a KEPT one is confirmed, and leaves the gallery", /deleteGalleryImage\(character, it\.url\)/.test(src177) && /Delete this picture\?/.test(src177));
  check("CCODE-177: ⛔ and its VOTE is withdrawn with it — a deleted picture must stop steering what they look like",
    /if \(at >= 0\) ks\.splice\(at, 1\);/.test(src177));
  check("CCODE-177: discarding the last one closes the box rather than showing nothing", (src177.match(/if \(!list\.length\) \{ close\(\); return; \}/g) || []).length >= 2);
  if (was176) localStorage.setItem("singularity.artMode", was176);
}

// ---- CCODE-174: the floors were corrupting their own safety tail ----
// Erik, reading a prompt in the details panel: "What's all this stuff getting injected into my image
// prompt?" — the ceiling tone and safety tail appended TWICE, and the first copy mangled:
//   "…tasteful, non-explicit, no , original character not a real person… no signature,
//     dark, intense, cinematic, mature dramatic tone, tasteful, non-explicit, no nudity…"
// ⛔ THE WORD "nudity" WAS EATEN OUT OF THE SAFETY TAIL BY THE SAFETY SCRUB. A stored prompt is an
// ALREADY-SANITISED prompt, so re-running the floors ran SEXUAL_MARKERS across the tail this function had
// itself written. The guard degraded itself a little more every time a picture was redrawn.
{
  const { sanitizeImagePrompt: san174, bareImagePrompt: bare174, likenessClause: lc174, IMAGE_STYLE: STY174, setArtMode: sam174 } = await import("../engine/art.js");
  const was174 = localStorage.getItem("singularity.artMode"); sam174("generate");
  const raw174 = "someone tending the waystation fire—shelter-keeper, traveler";
  const once = san174(raw174, { ratingLevel: 2, kind: "npc" });   // CCODE-182: R+ contributes no tone at all now, so idempotency is proved at a ceiling that does

  check("CCODE-174 THE RULE: the floors are IDEMPOTENT — twice is the same as once", san174(once, { ratingLevel: 2, kind: "npc" }) === once);
  check("CCODE-174: …and so is three times, four times, forever", san174(san174(san174(once, { ratingLevel: 2, kind: "npc" }), { ratingLevel: 2, kind: "npc" }), { ratingLevel: 2, kind: "npc" }) === once);
  // the ORIGINAL bug was the tail eating its own word; the tail is gone (CCODE-176) so the property is now
  // simply that nothing repeats and nothing arrives mangled.
  check("CCODE-174/176/182: nothing is appended twice and nothing arrives mangled", !/no ,/.test(once) && (once.match(/mild peril, no gore/g) || []).length === 1 && !/no signature/.test(once));
  check("CCODE-174/182: the ceiling tone appears exactly once", (once.match(/mild peril, no gore/g) || []).length === 1);
  // ⛔ CCODE-182 REGRESSION GUARD: setting a ceiling tone to "" put an EMPTY ALTERNATIVE into the strip
  // regex, so `(?:a|b|)` matched at every position and bareImagePrompt deleted every space in the prompt —
  // "Surgery using Light as a scalpel" came out "SurgeryusingLightasascalpel". Caught only because the
  // verification PRINTED real output instead of asserting a boolean about it.
  check("CCODE-182: an empty ceiling tone does not turn the strip into a space-eater",
    bare174("Surgery using Light as a scalpel. Bright lights to see every detail.") === "Surgery using Light as a scalpel. Bright lights to see every detail.",
    () => bare174("Surgery using Light as a scalpel. Bright lights to see every detail."));
  check("CCODE-182: …and a real prompt survives a full round-trip with its spaces",
    /Bright lights to see/.test(san174("Bright lights to see and work", { ratingLevel: 4, kind: "ability" })));
  check("CCODE-182: the upper ceilings impose no MOOD (a rating is a limit, not a look)",
    san174("a bright clean workshop", { ratingLevel: 4, kind: "ability" }) === "a bright clean workshop"
    && !/dark, intense/.test(san174("a bright clean workshop", { ratingLevel: 3, kind: "ability" })));
  check("CCODE-182: …while the LOW ceilings still say what they exclude",
    /no gore/.test(san174("x", { ratingLevel: 0 })) && /no gore/.test(san174("x", { ratingLevel: 2 })));

  // ⚠️ ERIK'S ACTUAL CORRUPTED STRING, recovered — an already-damaged prompt must heal, not stay damaged
  const broken174 = "someone tending the waystation fire—shelter-keeper, traveler, dark, intense, cinematic, mature dramatic tone, tasteful, non-explicit, no , original character not a real person, no copyrighted characters, no text, no watermark, no signature, dark, intense, cinematic, mature dramatic tone, tasteful, non-explicit, no nudity, original character not a real person, no copyrighted characters, no text, no watermark, no signature";
  check("CCODE-174: the string Erik pasted strips back to its description", bare174(broken174) === raw174, () => bare174(broken174));
  check("CCODE-174: …and re-sanitising it gives a clean single pass", san174(broken174, { ratingLevel: 2, kind: "npc" }) === once);

  // the floors still DO their job — idempotency must not have softened them
  check("CCODE-174/178: the floors still scrub BELOW the ceiling that allows it", !/erotic|nude study/.test(san174("an erotic nude study of a woman", { ratingLevel: 2 })));
  check("CCODE-174/176: minor-protection still absolute at any ceiling", /a child, fully clothed, non-sexual/.test(san174("a person", { ratingLevel: 4, isMinor: true })));
  check("CCODE-174: the ceiling still shapes the tone", /family-friendly/.test(san174("a person", { ratingLevel: 0 })) && !/family-friendly/.test(san174("a person", { ratingLevel: 4 })));

  // ⛔ AND THE LIKENESS VOTE WAS COUNTING THE BOILERPLATE. Every kept prompt ends with the same tail, and
  // the vote ranks by AGREEMENT — so the unanimous winners would have been "tasteful", "non-explicit",
  // "no nudity", and the actual face would have been pushed out by the floors.
  const keeps174 = [{ url: "a", prompt: san174("silver hair, sharp cheekbones, grey wool cloak", { ratingLevel: 2 }) },
                    { url: "b", prompt: san174("pale eyes, silver hair, grey wool cloak", { ratingLevel: 2 }) }];
  const clause174 = lc174(keeps174);
  check("CCODE-174: the likeness vote counts the DESCRIPTION, never the safety boilerplate",
    clause174.startsWith("silver hair, grey wool cloak") && !/tasteful|non-explicit|no nudity|no gore/.test(clause174), clause174);

  // the panel showed a prompt that was not the whole prompt
  const src174 = readFileSync(join(root, "app.js"), "utf8");
  // ⚠️ UPDATED BY CCODE-179: the style is no longer one constant, so the panel shows the one THIS picture
  // used. The property — the appended style is visible rather than hidden — is unchanged and stronger.
  check("CCODE-174/179: the details panel shows the style wrapper this picture actually used",
    /…and the style wrapper/.test(src174) && /esc\(houseStyleFor\(aes\)\)/.test(src174));
  check("CCODE-174/179: the style is a named export rather than a hidden constant", typeof STY174 === "string" && STY174.length > 20);
  if (was174) localStorage.setItem("singularity.artMode", was174);
}

// ---- CCODE-173: a portrait is drawn from what someone LOOKS LIKE ----
// Erik: "I can't make the re-gen image look like the same person… it's almost like we're missing a field
// that describes the person's appearance?" The field exists — it was not being read, and the two paths were
// not even reading the same one. Measured on Cinder Vael: the card drew from `imagePrompt` (a SCENE — "a
// wright's workshop crowded with half-finished machines…") while the re-roll drew from `appearance` (the
// LOOK — "scorched leather apron, forearms scarred…"). Two sentences about two different things, so Draw
// again was never redrawing the same description.
// ⚠️ AEVI SAID THIS IN SNG-400b §2 AND MY SIDE NEVER DID ITS HALF: "`imagePrompt` is a SCENE and cannot be
// reused as 'what this person looks like' in a different scene."
{
  const { figureArtRecord: far173 } = await import("../engine/whois.js");
  const { assembleImagePrompt: asm173, setArtMode: sam173 } = await import("../engine/art.js");
  const was173 = localStorage.getItem("singularity.artMode"); sam173("generate");
  const epics173 = JSON.parse(readFileSync(join(root, "content/packs/valley/tradition_epics.json"), "utf8")).epics;

  // ⛔ THE PROPERTY ERIK ASKED FOR, AS A CENSUS: the card and the re-roll must describe the same person.
  const mismatched = epics173.filter(f => {
    const rec = far173(f);
    return asm173("npc", { ...rec, id: `whois-${f.id}` }, {}) !== asm173("npc", rec, {});
  });
  check(`CCODE-173: all ${epics173.length} figures build ONE prompt for the card and the re-roll`,
    epics173.length === 66 && mismatched.length === 0, () => mismatched.slice(0, 3).map(f => f.name).join("; "));

  const cinder = epics173.find(f => /Cinder Vael/.test(f.name));
  check("CCODE-173: the LOOK leads, not the scene", far173(cinder).appearance === cinder.appearance && far173(cinder).appearance !== cinder.imagePrompt);
  check("CCODE-173: …and a figure with no authored look still gets a picture from the scene rather than nothing",
    far173({ id: "x", name: "X", imagePrompt: "a scene" }).appearance === "a scene" && far173({ id: "y", name: "Y" }).appearance === "");
  check("CCODE-173: the DEAD are drawn from their authored death, which IS a scene on purpose (SNG-399b)",
    far173(cinder, { dead: true }).appearance === cinder.deathImagePrompt);
  check("CCODE-173: gender and role ride, so the portrait is not a coin toss", far173(cinder).gender === "she" && far173(cinder).role === "Maker");
  check("CCODE-173: nothing in, nothing out", far173(null) === null);

  // ⚠️ THE SCENE WAS BEING CUT ANYWAY — the prompt seed clamps its lead, so the workshop sentence arrived as
  // a fragment ("on a bench she has ,") which a generator draws as detail. The look fits; check it survives.
  const built173 = asm173("npc", far173(cinder), {});
  check("CCODE-173: the description reaches the prompt whole, not severed mid-sentence",
    built173.includes("unslept, mid-task even now") && !built173.includes("…"));

  const whoSrc173 = readFileSync(join(root, "engine/whois.js"), "utf8");
  check("CCODE-173: whoIs hands the card the look first", /appearance: fig\.appearance \|\| fig\.imagePrompt \|\| fig\.form \|\| null,/.test(whoSrc173));
  const appSrc173 = readFileSync(join(root, "app.js"), "utf8");
  // ⚠️ ASSERT THE USE. My first version checked the record was BUILT — so putting the old hand-rolled object
  // back into the ensureImage call left the gate green with the bug fully restored. Fourth time today.
  check("CCODE-173: the card and the regen path ask the SAME builder (two records was the bug)",
    /const artRec = figureArtRecord\(rosterFig, \{ dead: !!known\.dead \}\)/.test(appSrc173)
    && /ensureImage\(\{ \.\.\.artRec, id: artSeed \}/.test(appSrc173)
    && /find: id => figureArtRecord\(rosterFigureOf\(id\), \{ dead: \/\^whois-death-\/\.test\(String\(id\)\) \}\)/.test(appSrc173));
  if (was173) localStorage.setItem("singularity.artMode", was173);
}

// ---- CCODE-172: the lightbox tells you what you are looking at, and the arrows stay on it ----
// Erik, on a 70-tile gallery: "can you make it so i can see all the fields — also, I'd like to be able to
// see the prompt that generated the image. And when I click an image that has re-generated more versions…
// I'd like to only go through the versions of the subject image; right now it runs through all images."
{
  const src172 = readFileSync(join(root, "app.js"), "utf8");

  // ⛔ THE NAVIGATION BUG WAS MINE. SNG-401 §3 said to append a draw to "the list the arrows already walk",
  // and I did — which is right for a one-image lightbox and wrong for a gallery, where the new version
  // landed at index 70 and comparing it against the original meant arrowing past sixty-eight other
  // pictures. Comparing the two IS the point of not destroying the old one.
  const rootOf = (x) => x?.versionOf || x?.url;
  const runOf = (list, i) => {
    const c = list[i]; if (!c) return null;
    const r = rootOf(c), sub = c.regen?.subjectId || null;
    const run = list.map((x, n) => (rootOf(x) === r || (sub && x?.regen?.subjectId === sub)) ? n : -1).filter(n => n >= 0);
    return run.length > 1 ? run : null;
  };
  // Erik's exact shape: a beast at tile 20 of 70, then two draws from it
  const g172 = Array.from({ length: 70 }, (_, n) => ({ url: `u${n}`, regen: { kind: "moment", subjectId: null } }));
  g172[19] = { url: "warpling", caption: "warpling", regen: { kind: "beast", subjectId: null } };
  check("CCODE-172: one picture with no versions still browses the whole gallery", runOf(g172, 19) === null);
  g172.splice(20, 0, { url: "w2", versionOf: "warpling", regen: g172[19].regen });
  g172.splice(21, 0, { url: "w3", versionOf: "warpling", regen: g172[19].regen });
  const ring = runOf(g172, 19);
  check("CCODE-172 THE FIX: once drawn, the run is just those versions", JSON.stringify(ring) === JSON.stringify([19, 20, 21]));
  check("CCODE-172: stepping wraps WITHIN the run and never escapes into the gallery", (() => {
    let i = 20; const stp = d => { const at = ring.indexOf(i); i = ring[(at + d + ring.length) % ring.length]; };
    stp(1); const a = g172[i].url; stp(1); const b = g172[i].url; stp(-1); const c = g172[i].url;
    return a === "w3" && b === "warpling" && c === "w3";
  })());
  // ⚠️ grouping on subjectId ALONE would have missed his own case — a beast has no subject record
  check("CCODE-172: a SUBJECT-less picture still groups its versions (the warpling has no subject at all)",
    runOf(g172, 20) !== null && g172[20].regen.subjectId === null);
  // …and two gallery tiles of the same PERSON group even without a shared origin
  const people = [{ url: "p1", regen: { kind: "npc", subjectId: "cevaine" } }, { url: "x", regen: { kind: "moment", subjectId: null } },
                  { url: "p2", regen: { kind: "npc", subjectId: "cevaine" } }];
  check("CCODE-172: two separate portraits of one person are one run", JSON.stringify(runOf(people, 0)) === JSON.stringify([0, 2]));

  check("CCODE-172: the app groups by origin AND subject", /const rootOf = \(x\) => x\?\.versionOf \|\| x\?\.url;/.test(src172)
    && /rootOf\(x\) === root \|\| \(sub && x\?\.regen\?\.subjectId === sub\)/.test(src172));
  check("CCODE-172: a draw records what it was drawn FROM", /versionOf: it\.versionOf \|\| it\.url/.test(src172));
  check("CCODE-172: a draw is inserted BESIDE its source, not at the end of the gallery",
    /list\.splice\(i \+ 1, 0, drawn\);/.test(src172) && !/list\.push\(drawn\)/.test(src172));
  check("CCODE-172: both the keys and the arrow buttons use ONE stepper (they cannot disagree)",
    (src172.match(/step\(-1\)/g) || []).length >= 2 && (src172.match(/step\(1\)/g) || []).length >= 2);
  check("CCODE-172: the caption says which ring the arrows are on", /version \$\{run\.indexOf\(i\) \+ 1\} of \$\{run\.length\}/.test(src172) && /in the gallery/.test(src172));

  // the fields + the prompt
  check("CCODE-172: every field the entry carries is shown", /class="lb-fields"/.test(src172)
    && ["caption", "kind", "subject", "world-day", "recorded", "seed", "kept looks", "source", "url"].every(k => src172.includes(`"${k}"`)));
  check("CCODE-172: the PROMPT is shown, and selectable so it can be taken", /class="lb-prompt"/.test(src172) && /user-select: text/.test(readFileSync(join(root, "style.css"), "utf8")));
  check("CCODE-172: …and it says so plainly when an older picture has no prompt on record", /not recorded for this image/.test(src172));
  check("CCODE-172: revealed on demand, not always-on (Aevi: prompts are long and some are spoiler-bearing)",
    /showMeta \? `<div class="lightbox-meta">/.test(src172) && /let showMeta = false;/.test(src172));
  check("CCODE-172: the gallery hands the whole entry through, so there ARE fields to show", /regen: galleryRegenFor\(g\), meta: g/.test(src172));
}

// ---- CCODE-171: one person, one identity, one face ----
// Erik: "there are still too many duplicate NPCs and People and Scenes… how can we make sure that the NPC
// image and name actually point to the same name and image set? Cevaine AND Cevaine of the 7th Order."
// ⛔ MEASURED FIRST: registry duplicates are RARE (one across every save). The duplication he sees is a
// person recorded in THREE id namespaces — registry id, codex topic id, authored content id — with the
// image seed taken from whichever surface he opened. Mara Wells is `mara-wells` to the portrait and
// `water-keeper` to the card: one woman, two faces, two sets of kept looks.
{
  const { canonicalPersonId, bareName, personArtSeed } = await import("../engine/npcs.js");

  // THE NAME INSIDE A LABEL — a codex label is a name plus what they are
  const bares = { "Leth — Edge District Archivist": "Leth", "Dara Holt, the Ditch-Mother": "Dara Holt",
    "Overseer Grael": "Grael", "Cevaine of the Seventh Measure": "Cevaine",
    "Neth, Who Has Buried More Than She Has Known": "Neth" };
  for (const [label, want] of Object.entries(bares))
    check(`CCODE-171: "${label}" is ${want}`, bareName(label) === want, bareName(label));

  // ⛔ AND THE GUARD THAT MAKES IT SAFE. A POSSESSIVE is a relation, never an epithet — `namesMatch` would
  // fold these together, which is why this deliberately is not namesMatch. Erik has just been bitten by a
  // wrong merge; over-folding a person costs far more than leaving two apart.
  check("CCODE-171: a possessive is a DIFFERENT person — Grael's Runner is not Grael", bareName("Grael's Runner — File Removal Witness") === "Grael's Runner");
  check("CCODE-171: …nor is Mara's errand-runner Mara", bareName("Pip Cotter, Mara's Errand-Runner") === "Pip Cotter");
  // ⚠️ THE GUARD, TESTED ON WHAT IT ACTUALLY PROTECTS. My first version mutated it away and nothing went
  // red, because the cases I had chosen carried a possessive OR an "of the", never both. A real alias from
  // Splarf's save carries both — and it names a THING Cevaine did, not Cevaine.
  check("CCODE-171: a possessive survives the epithet strip — \"Cevaine's Reading of the Veil-Breach\" is not a person's by-name",
    bareName("Cevaine's Reading of the Veil-Breach") === "Cevaine's Reading of the Veil-Breach", bareName("Cevaine's Reading of the Veil-Breach"));

  const reg171 = { npcRegistry: {
    cevaine: { id: "cevaine", name: "Cevaine" },
    grael: { id: "grael", name: "Grael" },
    leth: { id: "leth", name: "Leth", aliases: [] }
  } };
  check("CCODE-171 ERIK'S CASE: 'Cevaine of the Seventh Measure' resolves to Cevaine", canonicalPersonId(reg171, { label: "Cevaine of the Seventh Measure" }) === "cevaine");
  check("CCODE-171: a title does not make a second person", canonicalPersonId(reg171, { label: "Overseer Grael" }) === "grael");
  check("CCODE-171: a role-suffix does not either", canonicalPersonId(reg171, { label: "Leth — Edge District Archivist" }) === "leth");
  check("CCODE-171 THE REFUSAL: Grael's Runner stays their own person", canonicalPersonId(reg171, { label: "Grael's Runner — File Removal Witness" }) === null);
  check("CCODE-171: someone the registry has never heard of stays separate", canonicalPersonId(reg171, { label: "A Passing Stranger" }) === null);
  check("CCODE-171: an explicit link beats any name reasoning", canonicalPersonId(reg171, { npcId: "grael", label: "Cevaine" }) === "grael");
  check("CCODE-171: and a seed exists even for someone unknown (never a crash, never a shared 'undefined' face)",
    personArtSeed(reg171, { label: "A Passing Stranger" }).startsWith("whois-") && personArtSeed(reg171, { label: "Cevaine of the Seventh Measure" }) === "whois-cevaine");

  // ⚠️ THE REAL SAVES ARE THE FIXTURE — the report, asserted against what he actually plays
  for (const f of ["char-mrhs8286", "char-msgpisca"]) {
    const c = JSON.parse(readFileSync(join(root, `characters/player-s9z9u1/${f}.json`), "utf8"));
    const people = Object.values(c.codex?.topics || {}).filter(t => t.kind === "person");
    const split = people.filter(t => { const id = canonicalPersonId(c, { entityId: t.entityId || t.id, label: t.label }); return id && `whois-${t.entityId || t.id}` !== `whois-${id}`; });
    check(`CCODE-171: ${c.name}'s card and portrait now agree on every linked person`, people.length > 0 && split.every(t => !!canonicalPersonId(c, { entityId: t.entityId || t.id, label: t.label })),
      () => split.map(t => t.label).join("; "));
  }
  const src171 = readFileSync(join(root, "app.js"), "utf8");
  // ⚠️ ASSERT THE USE, NOT THE PRESENCE. My first version checked that the resolver was CALLED — so cutting
  // its result out of the seed left the gate green while the bug came straight back.
  check("CCODE-171: the whois card seeds on the canonical identity, not the topic id",
    /const canonId = canonicalPersonId\(character, \{ entityId: known\.codexId \|\| known\.id, label: known\.label \}\);/.test(src171)
    && /const seedKey171 = canonId \|\| seed;/.test(src171)
    && /`whois-death-\$\{seedKey171\}` : `whois-\$\{seedKey171\}`/.test(src171));
  check("CCODE-171: and the codex page asks the same question, through the same helper",
    /personArtSeed\(character, \{ entityId: open\.entityId \|\| open\.id, topicId: open\.id, label: open\.label \}\)/.test(src171)
    && /export function personArtSeed/.test(readFileSync(join(root, "engine/npcs.js"), "utf8")));
}

// ---- CCODE-169: EVERY PICTURE THE PLAYER SEES CAN BE OPENED ----
// ⛔ ERIK ASKED THE RIGHT QUESTION: "have you run the audits lately and would they catch these?" The answer
// to the second half is NO, and the reason is worth writing down. The audits verify that MODULES talk to
// each other — exports, imports, call sites. All three bugs he found were INSIDE a module:
//   · the codex portrait had no `data-lightbox`      → an HTML attribute; no audit reads DOM
//   · the merge-undo button never rendered            → `undoLastMerge` WAS imported and called, so every
//                                                       wiring check reads it as fully wired
//   · the item-kind whitelist                         → a data literal, not an export
// Module granularity cannot see a conditional, an attribute, or a table key. That is the gap, and this is
// the first check aimed at it: a CENSUS of image surfaces, because "I count the writers and never count
// the readers" is exactly how the ninth surface stayed shut.
{
  const appSrc169 = readFileSync(join(root, "app.js"), "utf8");
  // ⚠️ STRIP COMMENTS FIRST. My own note above — "found by counting <img> tags" — was picked up as a bare
  // image surface with no lightbox and failed the gate. That is the FOURTH time this session a checker has
  // matched the prose EXPLAINING the thing rather than the thing (wiring_audit documents the same trap and
  // I walked into it anyway). A census of markup must read markup.
  const markup169 = appSrc169.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
  const tags = [...markup169.matchAll(/<img\s[^>]*>/g)].map(m => m[0]);
  // the lightbox's OWN img is the one that must not be openable — it is already open.
  const surfaces = tags.filter(t => !/data-lbimg/.test(t));
  const shut = surfaces.filter(t => !/data-lightbox/.test(t));
  check(`CCODE-169: all ${surfaces.length} image surfaces open (a picture you cannot look at is a picture you cannot fix)`,
    surfaces.length >= 10 && shut.length === 0,
    () => shut.map(t => t.replace(/\s+/g, " ").slice(0, 90)).join(" || "));

  // ⚠️ AND A FACE MUST BE REDRAWABLE, not merely viewable. A quest illustration or a scene banner has no
  // subject record to redraw against, so view-only is the honest answer there; a PERSON is different.
  const faces = surfaces.filter(t => /class="(?:whois-portrait|comp-portrait|cs-portrait|codex-top-art)"/.test(t));
  const faceless = faces.filter(t => !/data-regen-kind/.test(t));
  check(`CCODE-169: all ${faces.length} PORTRAIT surfaces carry regen provenance (a face you cannot redraw is the whole complaint)`,
    faces.length >= 4 && faceless.length === 0,
    () => faceless.map(t => t.replace(/\s+/g, " ").slice(0, 90)).join(" || "));

  // the tenth surface, found by counting rather than by Erik hitting it
  check("CCODE-169: the COMPANION portrait — found by census, not by report", /class="comp-portrait"[^>]*data-regen-kind="figure"/.test(appSrc169));
  // the companion's panel re-mints on every open, so a kept look has to outrank the mint there too
  const compBlock = appSrc169.slice(appSrc169.indexOf("const artSeed = `companion-"), appSrc169.indexOf("const artSeed = `companion-") + 700);
  check("CCODE-169: a companion's kept look survives the re-mint, like every other person's",
    /const chosen = character\?\.figureImages/.test(compBlock) && /const url = chosen \|\| ensureImage/.test(compBlock));
}

// ---- CCODE-168: an item in a kind nobody listed is counted and never shown ----
// Erik: "I don't see my shadow tablet in my inventory" — with the header reading 27 and twenty-six tiles on
// screen. The bag rendered from a hard-coded five-kind whitelist while content ships SEVEN, so every
// `focus`, `relic` and `armor` item in the game was invisible. My tablet was the one that made it visible.
{
  const { ITEM_KINDS, itemKindsIn, itemKindLabel, addItem: addI168 } = await import("../engine/inventory.js");

  // ⛔ THE CLASS, NOT THE INSTANCE: every shipped item must fall in a kind the bag can render.
  const shipped = [];
  const walk168 = (d) => { for (const f of readdirSync(d, { withFileTypes: true })) {
    const pth = join(d, f.name);
    if (f.isDirectory()) walk168(pth);
    else if (f.name.endsWith(".json")) { try { const j = JSON.parse(readFileSync(pth, "utf8"));
      const arr = Array.isArray(j) ? j : (j.items || []);
      if (Array.isArray(arr)) for (const a of arr) if (a && a.name && a.kind && (a.worth || a.bonusTags || a.consumable !== undefined)) shipped.push(a);
    } catch { /* not an item pack */ } } } };
  walk168(join(root, "content/packs"));
  const orphan = shipped.filter(i => !ITEM_KINDS.includes(i.kind));
  check(`CCODE-168: all ${shipped.length} shipped items fall in a kind the bag can render`, shipped.length > 20 && orphan.length === 0,
    () => [...new Set(orphan.map(i => `${i.kind} (${i.name})`))].join("; "));
  check("CCODE-168: the kinds that were invisible are in the vocabulary", ["focus", "relic", "armor"].every(k => ITEM_KINDS.includes(k)));

  // ⛔ A CENSUS, NOT A WHITELIST — a kind nobody thought of is still the player's item
  const bag = [{ name: "a", kind: "weapon" }, { name: "b", kind: "focus" }, { name: "c", kind: "wholly-new-kind" }];
  const ks = itemKindsIn(bag);
  check("CCODE-168: an UNKNOWN kind still gets a section rather than vanishing", ks.includes("wholly-new-kind"));
  check("CCODE-168: …and the known kinds keep their display order in front of it", ks.indexOf("weapon") < ks.indexOf("focus") && ks.indexOf("focus") < ks.indexOf("wholly-new-kind"));
  check("CCODE-168: EVERY item in a bag is accounted for by some section (the header count and the tiles agree)", (() => {
    const shown = itemKindsIn(bag).reduce((n, k) => n + bag.filter(i => i.kind === k).length, 0);
    return shown === bag.length;
  })());
  check("CCODE-168: headings are words — not 'focuss' or 'armors'", itemKindLabel("focus") === "focus items" && itemKindLabel("armor") === "armour" && itemKindLabel("weapon") === "weapons");

  // the OTHER copy of the same whitelist: a GM-conferred focus was silently flattened to misc
  const ch168 = { inventory: [] };
  addI168(ch168, { name: "A Prism Lens", kind: "focus", description: "a lens" }, {});
  check("CCODE-168: a GM-conferred item KEEPS its kind (the second copy of the whitelist flattened it to misc)",
    ch168.inventory[0].kind === "focus");
  addI168(ch168, { name: "A Nonsense", kind: "not-a-kind" }, {});
  check("CCODE-168: …while a genuinely bogus kind still clamps to misc", ch168.inventory.find(i => i.name === "A Nonsense").kind === "misc");

  const src168 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE-168: the bag renders from the census and there is no second whitelist left", /const kinds = itemKindsIn\(character\.inventory \|\| \[\]\);/.test(src168)
    && !/\["weapon", "tool", "consumable", "quest", "misc"\]/.test(src168));
  check("CCODE-168: an item with NO kind at all is still shown", /const kindless = inv\.filter\(i => !i\?\.kind\);/.test(src168) && /\$\{grid\}\$\{extra\}/.test(src168));

  // Erik's own bag, with the reclaim applied — the report, asserted
  const silas168 = JSON.parse(readFileSync(join(root, "characters/player-s9z9u1/char-mrhs8286.json"), "utf8"));
  const withTablet = [...(silas168.inventory || []), { id: "shadow_tablet", name: "Shadow Tablet", kind: "focus" }];
  const rendered = itemKindsIn(withTablet).reduce((n, k) => n + withTablet.filter(i => i.kind === k).length, 0);
  check("CCODE-168: Silas's bag WITH the tablet renders every item it counts", rendered === withTablet.length, `${rendered}/${withTablet.length}`);
}

// ---- CCODE-167: a merge the player made by hand had no way back, and the dialog SAID so ----
// Erik: "I accidentally merged Cevaine the person with Cevaine Lore in the codex... :(" — and he was right
// to think it was gone, because the confirm box told him "This can't be undone." ⛔ IT WAS NEVER TRUE.
// mergeInto has written an undo receipt since SNG-153 (its own line: "the player's own merge is undoable
// too") — but the undo button rendered only beside the AUTO-merge digest, so a hand-made merge recorded a
// receipt nobody could reach. A capability, a UI that hid it, and copy that denied it.
{
  const { mergeInto: mi167, undoLastMerge: undo167, ensureCodex: ec167 } = await import("../engine/codex.js");
  const mk167 = () => { const c = { codex: { topics: {
    person: { id: "person", label: "Cevaine of the Seventh Measure", kind: "person", facts: ["[d3] she held the veil"], links: ["thinning"], aliases: ["Cevaine"], entityId: "cevaine" },
    lore: { id: "lore", label: "Cevaine", kind: "lore", facts: ["[d4] the practice as witness"], links: [], aliases: [] },
    thinning: { id: "thinning", label: "The Thinning", kind: "place", facts: [], links: ["person"], aliases: [] }
  } } }; ec167(c); return c; };

  const c167 = mk167();
  mi167(c167, "person", "lore");
  check("CCODE-167: a hand-made merge WRITES a receipt (it always did)", (c167.codex.mergeUndo || []).length === 1);
  check("CCODE-167: …and the merge really happened", !c167.codex.topics.person && c167.codex.topics.lore.facts.length === 2);
  const r167 = undo167(c167);
  check("CCODE-167 THE FIX: Erik's exact merge comes back", r167?.restored === "Cevaine of the Seventh Measure" && !!c167.codex.topics.person);
  check("CCODE-167: the person returns WHOLE — facts, links, aliases, entityId", (() => {
    const p = c167.codex.topics.person;
    return p.facts[0] === "[d3] she held the veil" && p.links[0] === "thinning" && p.aliases[0] === "Cevaine" && p.entityId === "cevaine";
  })());
  check("CCODE-167: and the entry it was folded into is rewound, not left holding both", (() => {
    const l = c167.codex.topics.lore;
    return l.facts.length === 1 && l.aliases.length === 0;
  })());
  check("CCODE-167: a third topic's link back to it is repaired too (an un-merge that strands links is half an un-merge)",
    c167.codex.topics.thinning.links[0] === "person");
  check("CCODE-167: undoing consumes its receipt — a second press cannot double-restore", (c167.codex.mergeUndo || []).length === 0 && undo167(c167) === null);

  // BY INDEX — an accidental merge is not always the last thing you did
  const c2 = mk167();
  c2.codex.topics.other = { id: "other", label: "A Road", kind: "place", facts: [], links: [], aliases: [] };
  mi167(c2, "person", "lore");
  mi167(c2, "other", "thinning");
  check("CCODE-167: an OLDER merge is still reachable by index", undo167(c2, 0)?.restored === "Cevaine of the Seventh Measure" && !!c2.codex.topics.person && !c2.codex.topics.other);

  const src167 = readFileSync(join(root, "app.js"), "utf8");
  // ⚠️ SCOPED TO THE MERGE DIALOG. My first version asserted the phrase was absent from the WHOLE FILE and
  // failed on two innocent hits: the character-DELETE confirm, where "this can't be undone" is true and
  // must stay, and my own comment quoting the old copy. A checker satisfied — or broken — by the note
  // explaining a bug is import_integrity's documented blind spot, arriving yet again.
  const mergeConfirm167 = (src167.match(/if \(!confirm\(`Fold [^`]*`\)\) return;/) || [""])[0];
  check("CCODE-167: the MERGE dialog no longer claims the merge is permanent",
    !!mergeConfirm167 && !/can't be undone/.test(mergeConfirm167) && /You can undo this/.test(mergeConfirm167), mergeConfirm167.slice(0, 120));
  check("CCODE-167: …while the character-DELETE dialog still says so, because there it is TRUE",
    /Delete <strong>\$\{esc\(c\?\.name \|\| "this character"\)\}<\/strong>\? This can't be undone/.test(src167));
  check("CCODE-167: the undo is offered whenever there is something to undo, not only after an auto-merge",
    /\(character\.codex\?\.mergeUndo \|\| \[\]\)\.length \|\| character\._codexDigest/.test(src167));
  check("CCODE-167: a hand-made merge leaves a receipt saying what it did", /character\._codexDigest = `Folded "\$\{foldedLabel\}" into/.test(src167));
  check("CCODE-167: the button carries an INDEX, so it can reach past the newest merge", /data-codexundo="/.test(src167) && /undoLastMerge\(character, Number\(b\.dataset\.codexundo\)\)/.test(src167));
}

// ---- CCODE-166: the tiles with no buttons at all ----
// Erik: "new buttons are now missing from #11/22 and 19/22 in Splarf's gallery." Two causes, both mine.
{
  const { namesMatch: nm166 } = await import("../engine/namematch.js");
  const src166 = readFileSync(join(root, "app.js"), "utf8");

  // ⛔ (a) I HAND-ROLLED AN EXACT COMPARISON WHERE THE PROJECT ALREADY HAD THE RIGHT ONE. Splarf's gallery
  // captions a tile "Cevaine of the Seventh Measure" while his registry says "Cevaine" — SNG-111's case,
  // and precisely what `namesMatch` exists for. Lowercase equality failed it, so a real portrait of a known
  // person offered no controls at all.
  check("CCODE-166: a fuller caption resolves to the known person (Cevaine of the Seventh Measure → Cevaine)",
    nm166("Cevaine", "Cevaine of the Seventh Measure") === true);
  check("CCODE-166: …and it stays conservative — a DESCRIPTION still matches nobody",
    nm166("The Waystation Caretaker", "someone tending the waystation fire") === false && nm166("Cevaine", "someone tending the waystation fire") === false);
  check("CCODE-166: the resolver uses that helper rather than a fresh one", /namesMatch\(n\.name, nm\)/.test(src166) && /namesMatch\(character\.name, nm\)/.test(src166));

  // (b) an UNNAMED person's picture is still a picture — drawable, just not a subject to vote on
  check("CCODE-166: an unnamed subject's tile still draws instead of going dead", /return g\.prompt \? mk\("moment", null\) : null;/.test(src166));

  // ⛔ AND A VOTE NEEDS SOMETHING TO VOTE ON. Keep on a prompt-only tile has a null likeness key, so it
  // would have reported success and recorded nothing.
  check("CCODE-166: Keep requires a subject — a vote that attaches to nothing is a lie that looks like a feature",
    /const canKeep = !!it\.regen\?\.subjectId && !!spec\?\.keep;/.test(src166));

  // crafts and places have names too — most of a gallery was drawable but not keepable
  check("CCODE-166: a craft tile resolves by its own name, so its look can be kept", /if \(g\.kind === "ability" \|\| g\.kind === "discovery"\) \{/.test(src166) && /namesMatch\(cat\[k\]\.name, nm\)/.test(src166));
  check("CCODE-166: a place tile does too", /if \(g\.kind === "location"\) \{/.test(src166) && /namesMatch\(CONTENT\.locations\[k\]\.name, nm\)/.test(src166));

  // ⚠️ THE REAL SAVE IS THE FIXTURE. Every tile with a url must offer SOMETHING; this is the report Erik
  // filed, asserted against the gallery he filed it about.
  const splarf = JSON.parse(readFileSync(join(root, "characters/player-s9z9u1/char-msgpisca.json"), "utf8"));
  const tiles = (splarf.gallery || []).filter(g => g && g.url);
  const dead = tiles.filter(g => !g.prompt && !(g.subjectKind && g.subjectId));
  check(`CCODE-166: every one of Splarf's ${tiles.length} tiles has something to draw from`, tiles.length > 0 && dead.length === 0,
    () => dead.map(g => `${g.kind}: ${g.caption}`).join("; "));
  const named = tiles.filter(g => g.kind === "npc" || g.kind === "portrait");
  const resolved = named.filter(g => {
    const n = String(g.caption || "").split("—")[0].trim();
    return nm166(splarf.name, n) || Object.values(splarf.npcRegistry || {}).some(x => x?.name && nm166(x.name, n));
  });
  check("CCODE-166: the people-tiles that name a known person now resolve to them", named.length > 0 && resolved.length >= named.length - 1,
    () => `${resolved.length}/${named.length} resolved`);
}

// ---- CCODE-164/165: Keep is a VOTE on the likeness, and the codex leads with its subject's face ----
// Erik, redefining the feature after playing: "the keep button should be a highly weighted vote — I like
// the way one image came out so I want to keep that look as the person in any future renderings. If I like
// two images I should be able to keep both, or as many as I want."
{
  const { likenessClause, withLikeness, toggleKeep, likenessSeed, setArtMode: setArt164,
          regenerateImage: regen164, ensureImage: ensure164 } = await import("../engine/art.js");
  const was164 = localStorage.getItem("singularity.artMode");
  setArt164("generate");
  const keeps = [
    { url: "a", prompt: "silver hair, sharp cheekbones, grey wool cloak, a scar at the jaw" },
    { url: "b", prompt: "pale eyes, silver hair, grey wool cloak, lantern light" }
  ];
  const clause = likenessClause(keeps);
  check("CCODE-164 THE VOTE: what two kept pictures AGREE on leads the likeness", /^silver hair, grey wool cloak/.test(clause), clause);
  check("CCODE-164: …and what only one of them says still rides, behind the agreement", /sharp cheekbones/.test(clause) && /pale eyes/.test(clause), clause);
  check("CCODE-164: one keep is a whole vote, in its own order", likenessClause([keeps[0]]).startsWith("silver hair, sharp cheekbones"));
  // ⚠️ THE CASE HAS TO DISCRIMINATE. My first version asserted a thrice-repeated term still led — which it
  // does whether or not repetition is deduped, so the check proved nothing and the mutation stayed green.
  // Now: a term repeated three times in ONE keep must LOSE to a term two SEPARATE keeps agree on.
  check("CCODE-164: a prompt repeating itself is still ONE vote — genuine agreement outranks ballot-stuffing",
    likenessClause([{ url: "x", prompt: "red hat, red hat, red hat, blue coat" }, { url: "y", prompt: "blue coat, green boots" }]).startsWith("blue coat"));
  check("CCODE-164: nothing kept = nothing added (the prompt is untouched)", likenessClause([]) === "" && withLikeness("a smith at her anvil", []) === "a smith at her anvil");
  check("CCODE-164: the likeness LEADS the prompt (a diffusion prompt weights its opening most)", withLikeness("a smith at her anvil", keeps).startsWith("silver hair"));
  check("CCODE-164: the clause is bounded — a preference, never an average of everything",
    likenessClause(Array.from({ length: 8 }, (_, i) => ({ url: `u${i}`, prompt: `trait${i} aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa, common thing` }))).length <= 240);

  const store = {};
  toggleKeep(store, "npc:pell", { url: "u1", prompt: "silver hair", seedKey: "s1" });
  toggleKeep(store, "npc:pell", { url: "u2", prompt: "grey wool", seedKey: "s2" });
  check("CCODE-164: keeps ACCUMULATE — two liked pictures both guide the face", store["npc:pell"].keeps.length === 2);
  const off = toggleKeep(store, "npc:pell", { url: "u1", prompt: "silver hair" });
  check("CCODE-164: the same button withdraws a vote (a vote you cannot take back is a trap)", off.kept === false && store["npc:pell"].keeps.length === 1);
  check("CCODE-164: re-keeping restores it", toggleKeep(store, "npc:pell", { url: "u1", prompt: "silver hair" }).kept === true);
  check("CCODE-164: keeps are capped — past a handful it stops being a preference and becomes an average",
    (() => { const s2 = {}; for (let i = 0; i < 20; i++) toggleKeep(s2, "k", { url: `u${i}`, prompt: `p${i}` }); return s2.k.keeps.length <= 8; })());
  check("CCODE-164: a kept SEED anchors a fresh mint (the strongest consistency lever a diffusion model has)",
    likenessSeed(store["npc:pell"].keeps) !== null && likenessSeed([]) === null);

  const pell164 = { id: "pell164", name: "Pell", description: "a village blacksmith" };
  ensure164(pell164, "npc", { ratingLevel: 2, promptOpts: { keeps } });
  check("CCODE-164: a FIRST mint of a liked subject is drawn toward the kept look", decodeURIComponent(pell164.image).includes("silver hair"));
  const rr = regen164({ id: "p2", name: "Pell", description: "a village blacksmith" }, "npc", { ratingLevel: 2, attempt: 1, promptOpts: { keeps } });
  check("CCODE-164: a RE-ROLL keeps the face and changes only the draw", decodeURIComponent(rr.url).includes("silver hair"));
  const rb = regen164({ id: "p3", name: "Pell" }, "npc", { ratingLevel: 2, attempt: 1, promptOpts: { keeps }, promptOverride: "a bald man in red armour" });
  check("CCODE-164: a REBUILD is NOT overridden by old votes — describing it differently must mean something",
    decodeURIComponent(rb.url).includes("bald man in red armour") && !decodeURIComponent(rb.url).includes("silver hair"));
  check("CCODE-164: the FLOORS still run after the likeness (a liked look cannot smuggle past the ceiling)",
    decodeURIComponent(regen164({ id: "p4", name: "X" }, "npc", { ratingLevel: 0, attempt: 1, promptOpts: { keeps: [{ url: "z", prompt: "an erotic nude study" }] } }).url).match(/erotic|nude/) === null);

  const src165 = readFileSync(join(root, "app.js"), "utf8");
  const codexFn = src165.slice(src165.indexOf("function codexTopImage"));
  check("CCODE-165: the codex topic page renders its subject at the top", /\$\{codexTopImage\(open\)\}/.test(src165));
  // ⚠️ RE-AIMED (CCODE-171): both surfaces now build the seed through ONE helper rather than each spelling
  // `whois-${seed}` for itself — which is a stronger form of the same property, so the gate asserts THAT.
  check("CCODE-165: it uses the SAME seed builder as the popup, so it is the same person and not a second one",
    /personArtSeed\(character, \{ entityId: open\.entityId \|\| open\.id, topicId: open\.id, label: open\.label \}\)/.test(codexFn));
  check("CCODE-165: it opens into the lightbox with the same controls", /class="codex-top-art"[^`]*data-lightbox="figure"[^`]*data-regen-kind="figure"/.test(src165));
  check("CCODE-165: only entries that HAVE a subject get a face (an event or a mystery is not a person)", /CODEX_PICTURABLE = new Set\(\["person", "place"\]\)/.test(src165));
  check("CCODE-165: a kept look wins on the codex page too", /const chosen = character\?\.figureImages\?\.\[artSeed\] \|\| null;/.test(codexFn) && /const url = chosen \|\|/.test(codexFn));
  check("CCODE-164: the votes reach the paths that draw people (bond portraits and figure cards)", (src165.match(/keeps: keepsForSubject\(/g) || []).length >= 2);
  if (was164) localStorage.setItem("singularity.artMode", was164);
}

// ---- CCODE-163: the two gaps Erik found by testing SNG-401 ----
// (1) "I don't see where I can select a portrait as Canon."  (2) "the popups that read the codex entry
// don't have an image popup at all."  Both were mine: I gated Keep too narrowly, and I counted eight
// lightbox call sites when there are nine.
{
  const src163 = readFileSync(join(root, "app.js"), "utf8");

  // (2) THE NINTH SURFACE — the whois/codex card's portrait could not even be opened.
  check("CCODE-163: the codex/whois portrait opens the lightbox and carries its provenance",
    /class="whois-portrait"[^`]*data-lightbox="figure"[^`]*data-regen-kind="figure"[^`]*data-regen-subject=/.test(src163));
  check("CCODE-163: `figure` is a real regen kind — found, current, and keepable", (() => {
    // ⚠️ SLICE TO THE NEXT ENTRY, NOT N CHARACTERS. These read a fixed 600/700-char window from the entry
    // start, so adding a comment inside an entry pushed its own properties out of view and failed a gate
    // about the properties. A window measured in bytes is a window that closes when you explain something.
    const tbl = src163.slice(src163.indexOf("const REGEN_KINDS = {"), src163.indexOf("// SNG-401 §1, Aevi's constraint"));
    const NEXT_ENTRY = new RegExp("\\n  \\w+: \\{");
    const entryOf = (k) => { const i = tbl.indexOf(`${k}: {`); if (i < 0) return ""; const nxt = tbl.slice(i + 1).search(NEXT_ENTRY); return nxt < 0 ? tbl.slice(i) : tbl.slice(i, i + 1 + nxt); };
    const blk = entryOf("figure");
    // ⚠️ CCODE-181 widened `find` to fall back to the registry — the epic roster holds 66 legends while the
    // card opens for anyone the player knows, so every ordinary NPC resolved to nothing. Both halves gated.
    return /find: id => figureArtRecord\(rosterFigureOf\(id\)/.test(blk) && /character\?\.npcRegistry\?\.\[String\(id\)\.replace/.test(blk)
      && /current: id => character\?\.figureImages/.test(blk) && /keep: \(id, url\) =>/.test(blk);
  })());
  check("CCODE-163: a figure's seed maps back to the person, alive or dead", /replace\(\/\^whois-\(\?:death-\)\?\/, ""\)/.test(src163));
  // ⛔ the card re-mints from a stable seed on every open, so a chosen picture MUST outrank the mint
  check("CCODE-163: a picture the player chose beats the re-mint (else Keep is undone on the next open)",
    /const chosen = character\?\.figureImages\?\.\[artSeed\] \|\| null;/.test(src163) && /const url = chosen \|\| ensureImage\(/.test(src163));

  // (1) SELECT AN EXISTING PICTURE AS THE ONE — Keep was reachable only from a fresh draw
  // ⚠️ SUPERSEDED BY CCODE-164 AND THE CHANGE IS THE POINT. When Keep meant "make this the portrait", it
  // was correct to hide it on the picture already in use — a no-op button. Now it means "this is what they
  // look like", which is a DIFFERENT statement from "this is the one shown", and is perfectly sensible to
  // cast on the current picture. What must still never appear is a Keep with nothing to attach to.
  check("CCODE-163/164/166: Keep is offered on any picture WITH A SUBJECT, new draw or not", /const canKeep = !!it\.regen\?\.subjectId && !!spec\?\.keep;/.test(src163));
  check("CCODE-163/164: …and never where there is no subject to attach a look to (the '✕ couldn't keep' Erik hit)",
    /needsId: true/.test(src163) && /REGEN_KINDS\[k\] && !REGEN_KINDS\[k\]\.needsId \? k : "moment"/.test(src163));
  check("CCODE-163/172: the caption says WHICH picture is the one in use, so 'use this one' has a reference point",
    /isCurrent && "the one in use"/.test(src163));
  check("CCODE-163: every regenerable kind can say what its current picture is", (() => {
    const tbl = src163.slice(src163.indexOf("const REGEN_KINDS = {"), src163.indexOf("// SNG-401 §1, Aevi's constraint"));
    // the record-backed kinds must all answer `current`; the prompt-only ones (moment/beast/battle/death) need not
    const NEXT_ENTRY = new RegExp("\\n  \\w+: \\{");
    const entryOf = (k) => { const i = tbl.indexOf(`${k}: {`); if (i < 0) return ""; const nxt = tbl.slice(i + 1).search(NEXT_ENTRY); return nxt < 0 ? tbl.slice(i) : tbl.slice(i, i + 1 + nxt); };
    return ["npc", "character", "figure", "location", "item", "ability", "beast"].every(k => /current:/.test(entryOf(k)));
  })());
  // the lightbox must sit ABOVE the card it was opened from, or the picture opens invisibly
  const css163 = readFileSync(join(root, "style.css"), "utf8");
  check("CCODE-163: the lightbox outranks the whois overlay it opens from", (() => {
    const z = (re) => Number((css163.match(re) || [])[1] || 0);
    return z(/\.lightbox \{[^}]*z-index:\s*(\d+)/) > z(/\.help-overlay \{[^}]*z-index:\s*(\d+)/);
  })());
}

// ---- CCODE-162: ONE COMMUNITY, ONE SPELLING (within a region) ----
// ⛔ FOUND BY AN INTERMITTENT GATE, WHICH IS THE WORST WAY TO FIND ANYTHING. "…and the first hop is
// somewhere in its OWN region" failed roughly two runs in three, and only after teaching `check` to print
// the detail its call site had always passed did the cause show: the deed hopped to `echo_vale.millbrook`
// while it started from `valley.millbrook`. ONE community, two spellings — the tail of SNG-427, where the
// regionId was repointed to `valley` and the communityId kept the old prefix.
//
// ⚠️ THE RULE IS NARROW ON PURPOSE. `center.gate` (The Axis Gate) and `abyssal.gate` (The Bargain Gate) are
// genuinely two places that share a leaf name in different regions — that is prefixes doing their job, and
// a cruder "no leaf twice" rule would fail on correct data. The real invariant: WITHIN ONE REGION, a
// community leaf resolves to exactly one full id.
{
  const dir162 = join(root, "content/packs/valley/locations");
  const groups = new Map();
  for (const f of readdirSync(dir162).filter(x => x.endsWith(".json"))) {
    const l = JSON.parse(readFileSync(join(dir162, f), "utf8"));
    if (!l.communityId) continue;
    const key = `${l.regionId || l.region || "?"}::${String(l.communityId).split(".").pop()}`;
    (groups.get(key) || groups.set(key, new Set()).get(key)).add(l.communityId);
  }
  const split = [...groups.entries()].filter(([, s]) => s.size > 1);
  check("CCODE-162: no community is spelled two ways inside one region (it splits the place in half)",
    split.length === 0, () => split.map(([k, s]) => `${k} → ${[...s].join(" | ")}`).join("; "));
  // the fix itself, pinned: the Crossing follows the region it was moved to
  const xing = JSON.parse(readFileSync(join(dir162, "echo_river_crossing.json"), "utf8"));
  check("CCODE-162: the Crossing's community follows its region (Aevi moved it to valley; the id now agrees)",
    xing.regionId === "valley" && xing.communityId === "valley.millbrook",
    `regionId=${xing.regionId} communityId=${xing.communityId}`);
  // ⚠️ and the harness change that made this findable at all
  const smokeSrc162 = readFileSync(join(root, "tests/smoke.mjs"), "utf8");
  check("CCODE-162: check() renders the failure detail its call sites pass (a written diagnostic with no reader)",
    /function check\(name, cond, detail = null\)/.test(smokeSrc162) && /if \(detail\) console\.log/.test(smokeSrc162));
}

// ⚠️ ANYTHING APPENDED BELOW `process.exit` NEVER RUNS. This bit me: eight minting checks were added to
// the end of this file, the suite went green, and not one of them had executed. A test that cannot fail is
// worse than no test — it is a green light with nothing behind it. This guard makes the trap visible.
// ---- CCODE-191: no source file may carry a control character ----------------------------------------
// ⛔ FOUND BY ACCIDENT, AND IT WAS ALREADY SHIPPED. Three regexes in app.js carry a literal BACKSPACE
// (U+0008) where \\b was intended — `teaching`, `finished` and `splitWords`, the guards for "someone is
// teaching me this", "this is finished", and "split the spear". `/\b(taught|teaches|…)\b/` can only match
// text that literally contains a backspace, so ALL THREE HAVE NEVER FIRED in play.
//
// ⚠️ THE CAUSE IS MY OWN TOOLING, four times in one session: a shell heredoc hands python "\\b", python
// reads it as the backspace escape, and the file gets a control character that greps clean, renders
// invisibly, and silently turns a word-boundary guard into a dead one. Reviewing the diff does not catch
// it — the character has no width. A machine has to look.
{
  // ⚠️ WRITTEN AS \uXXXX ESCAPES, DELIBERATELY. Spelled with raw bytes — which is how it arrived the
  // first time — the gate's own pattern would carry the very characters it exists to forbid, and fail on
  // itself. A checker that cannot survive its own rule is not a checker.
  const CONTROL = new RegExp("[\u0000-\u0008\u000b\u000c\u000e-\u001f]");
  const scanned = [], dirty = [];
  const roots = ["app.js", "engine", "tests", "scripts"];
  const walk = (rel) => {
    const abs = join(root, rel);
    let st; try { st = statSync(abs); } catch { return; }
    if (st.isDirectory()) { for (const f of readdirSync(abs)) walk(rel + "/" + f); return; }
    if (!/\.(js|mjs)$/.test(rel)) return;
    scanned.push(rel);
    const txt = readFileSync(abs, "utf8");
    const m = txt.match(CONTROL);
    if (m) {
      const at = txt.indexOf(m[0]);
      dirty.push(`${rel}:${txt.slice(0, at).split("\n").length} (U+${m[0].charCodeAt(0).toString(16).padStart(4, "0")})`);
    }
  };
  for (const r of roots) walk(r);
  check(`CCODE-191: no source file carries a control character (${scanned.length} files scanned)`,
    dirty.length === 0, `a \b written as a literal backspace is an invisible dead regex: ${dirty.slice(0, 5).join(" · ")}`);
}

// ---- SNG-433: the clash news, in the authored voice ------------------------------------------------
// ⛔ ERIK'S THREE QUESTIONS OF THE NEWS — "coherent? interesting? obvious why it's news?" — answered no,
// no and no, because the four sentences were written by an engine and one of them printed a full name
// twice. Aevi re-authored them; these gates are that the words a PLAYER READS come from her file.
{
  const NV = await import("../engine/newsvoice.js");
  const { applyEpicClashOutcome: applyClash433, advanceGeneratedOffscreen: tick433, initWorldState: initWs433 } =
    await import("../engine/worldtick.js");
  const { loadContentHeadless: lch433 } = await import("./headless_content.mjs");
  const C433 = await lch433();
  const T433 = C433.rules?.newsTemplates;

  // 1 · REGISTERED **AND** LOADED. Authored at b197b719, in no manifest, read by nothing — the same
  // invisible-one-step-earlier failure as the name pools, on the very next file Aevi shipped.
  check("433: news_templates is registered AND loaded onto rules.newsTemplates (not merely on disk)",
    !!T433?.templates && !!T433?.fragments,
    `rules.newsTemplates = ${JSON.stringify(Object.keys(T433 || {}))}`);

  // 2 · ⛔ THE ENGINE SAYS "stopped"; THE AUTHOR WROTE "checked". An unmapped outcome returns undefined and
  // falls silently back to the hardcoded line — the exact way a wired file stays unwired.
  {
    const missing = Object.entries(NV.OUTCOME_TEMPLATE_KEY).filter(([, k]) => !T433?.templates?.[k]);
    const thin = Object.entries(T433?.templates || {}).filter(([, b]) => !b.rival || !b.mutual || !b.stranger);
    check("433: every outcome the engine can produce names a template block that exists, with all three relationships",
      missing.length === 0 && thin.length === 0 && Object.keys(NV.OUTCOME_TEMPLATE_KEY).length === 4,
      `unmapped=${missing.map(m => m[0])} thin=${thin.map(t => t[0])}`);
  }

  // 3 · THE TEXT COMES FROM THE FILE. Not "the function exists" — the sentence a player reads is hers.
  {
    const A433 = { id: "a433", name: "The Hollow King of the Wild Half", rivals: ["b433"] };
    const B433 = { id: "b433", name: "Neth, Who Has Buried More Than She Has Known", rivals: ["a433"] };
    const out = applyClash433({}, A433, B433, "stopped", 12, { content: C433 });
    const text = out.news[0]?.text || "";
    // ⚠️ THE LITERAL IS LIFTED FROM THE FILE, NOT RETYPED HERE. A gate carrying its own copy of Aevi's prose
    // goes green while she rewords it, and then guards nothing — the longest run of words BETWEEN the
    // placeholders is whatever she wrote today.
    const authored = T433.templates.checked.mutual.split(/\{[a-zA-Z]+\}/)
      .map(s => s.trim()).sort((a, b) => b.length - a.length)[0];
    check("433: a 'stopped' clash is reported in the AUTHORED words (the 'checked' block), not the engine's own line",
      text.includes(authored) && !/checked .*for now/.test(text), `${text.slice(0, 120)} ⟵ wanted "${authored}"`);
    // 4 · SHORT FORM ON SECOND MENTION — the stutter Erik saw, measured rather than eyeballed.
    check("433: the full name appears ONCE and the second mention is short",
      text.split(B433.name).length === 2 && text.includes("Neth") && text.lastIndexOf("Neth") > text.indexOf(B433.name),
      text);
  }

  // 5 · THE SHORT-NAME RULE, RE-VERIFIED ON THE REAL CORPUS. Aevi's first rule produced "Morvane of the";
  // her claim about the second is "0 cut on a stopword across all 66". Claim, therefore gate.
  {
    const names = (C433.legends?.roster || []).map(f => f?.name).filter(Boolean);
    const bad = names.filter(n => /\b(of|who|that|the|a|an|and|or|with|in|at|on|to|for|by|from)$/i.test(NV.shortName(n).trim()));
    const shortened = names.filter(n => NV.shortName(n) !== n);
    check(`433: no authored name shortens onto a preposition or article (${names.length} names, ${shortened.length} shorten)`,
      names.length > 60 && bad.length === 0 && shortened.length > 20, bad.slice(0, 4).join(" · "));
  }

  // 6 · THE RELATIONSHIP IS WHY IT IS NEWS. Three different sentences for the same two people, chosen by
  // `rivals` — a field authored on 58 of 66 figures and read by nothing since SNG-208.
  {
    const line = (ar, br) => NV.clashLine({ templates: T433.templates, outcome: "killed",
      winner: { id: "x", name: "Winner Name Here", rivals: ar ? ["y"] : [] },
      loser: { id: "y", name: "Loser Name Here", rivals: br ? ["x"] : [] }, place: "The Maw" });
    const mutual = line(true, true), rival = line(true, false), stranger = line(false, false);
    check("433: mutual, rival and stranger are three DIFFERENT sentences for the same two figures",
      mutual !== rival && rival !== stranger && mutual !== stranger && [mutual, rival, stranger].every(s => s && s.includes("The Maw")),
      `${mutual}\n      ${rival}\n      ${stranger}`);
  }

  // 7 · ⛔ NO PLACE → DROP THE PHRASE, NEVER "at null".
  {
    const noPlace = NV.clashLine({ templates: T433.templates, outcome: "killed",
      winner: { id: "x", name: "A Winner" }, loser: { id: "y", name: "A Loser" }, place: null });
    // ⚠️ AND A DANGLING " at ." IS THE SAME BUG WEARING BETTER MANNERS. Emptying the slot instead of
    // dropping the phrase leaves "killed them at ." — which no assertion about the word "null" can see.
    check("433: a clash with no place drops ' at {place}' rather than printing 'at null' or a dangling 'at'",
      !!noPlace && !/\bat (null|undefined|\{place\})/.test(noPlace) && !/\bat\s*([.,;—]|$)/.test(noPlace)
      && !/\s{2,}/.test(noPlace), noPlace);
  }

  // 8 · ⛔ A DISPLAY NAME, NEVER AN ID — "the the_ceaseless" is this fault and it has shipped before.
  {
    const locId = Object.keys(C433.locations || {}).find(id => C433.locations[id]?.name && id.includes("_"));
    const rendered = applyClash433({}, { id: "p1", name: "One Name" }, { id: "p2", name: "Two Name" },
      "wounded", 5, { content: C433, locationId: locId }).news[0]?.text || "";
    check("433: the place in a clash line is the location's DISPLAY NAME, and the id never reaches the player",
      rendered.includes(C433.locations[locId].name) && !rendered.includes(locId), `${locId} → ${rendered.slice(0, 110)}`);
  }

  // 9 · …AND THE SECOND DEFENCE, which fails differently: a caller that skipped the lookup and handed the
  // renderer an id gets the phrase dropped rather than the id printed.
  check("433: an id-shaped place handed straight to the renderer is refused, not printed",
    NV.isIdShaped("the_ceaseless") && !NV.isIdShaped("The Ceaseless")
    && !/the_ceaseless/.test(NV.fillTemplate("{W} killed {L} at {place}.", { W: "A", L: "B", place: "the_ceaseless" })));

  // 10 · THE POWER IS A DETAIL THE TELLER KNEW, NOT A STAT LINE — "roughly one in three", and the SAME
  // fight must say the same words every time, or a news item cannot be trusted to reopen the same battle.
  {
    const draw = (i) => NV.clashLine({ templates: T433.templates, outcome: "wounded",
      winner: { id: `w${i}`, name: "Winner Name" }, loser: { id: `l${i}`, name: "Loser Name" },
      place: "The Maw", power: "The Spent Hour" });
    // ⛔ DETERMINISM OVER 300 FIGHTS, NOT ONE — and the difference is the whole gate. `draw(7) === draw(7)`
    // was my first version, and mutation says it is worth nothing: with a 1-in-3 roll two draws of the SAME
    // fight still agree 5 times in 9 (both roll the power, or both roll a variant — and the variant is fixed
    // by the relationship). A gate that goes red 45% of the time is worse than no gate, because it will be
    // seen green and believed. Two full passes must agree line for line.
    const n = 300;
    const pass = () => Array.from({ length: n }, (_, i) => draw(i));
    const first = pass(), second = pass();
    const withPower = first.filter(s => s.includes("The Spent Hour")).length;
    check(`433: the power names the fight roughly one time in three (${withPower}/${n}) and never re-rolls`,
      withPower > n * 0.2 && withPower < n * 0.47 && first.every((s, i) => s === second[i]));
  }

  // 11 · ⛔ "Overseer Grael of the Edge District a daughter who thinks he is a clerk" IS NOT A SENTENCE.
  // Two grammatical shapes, two templates, chosen by the shape — and Aevi's FIELD hint is backwards for the
  // shipped content, which is why only the shape decides: `personalVerbs` is 219 fragments and 0 verbs.
  {
    const F = T433.fragments;
    const verb = NV.fragmentLine({ templates: F, name: "The Hollow King", frag: "sells a secret that wasn't his" });
    const noun = NV.fragmentLine({ templates: F, name: "Overseer Grael", frag: "a daughter who thinks he is a clerk" });
    check("433: a verb fragment and a noun fragment take DIFFERENT templates, and neither is a bare join",
      NV.fragmentForm("sells a secret that wasn't his") === "verbForm"
      && NV.fragmentForm("a daughter who thinks he is a clerk") === "nounForm"
      && NV.fragmentForm("learning a faster road") === "nounForm"
      && verb !== noun && !noun.startsWith("Overseer Grael a "), `${verb}\n      ${noun}`);
    const pv = (C433.legends?.roster || []).flatMap(f => f.personalVerbs || []);
    check(`433: every fragment this news site can draw is a noun phrase (${pv.length} personalVerbs, 0 verbs) — the shape decides, not the field`,
      pv.length > 100 && pv.every(v => NV.fragmentForm(v) === "nounForm"),
      pv.filter(v => NV.fragmentForm(v) !== "nounForm").slice(0, 3).join(" · "));
  }

  // 12 · AEVI'S OWN ASKED-FOR GATE, verbatim: *"no string under `templates` or `fragments` may contain ⛔ or
  // ⚠️."* She caught one leaking into a stalemate line — an editorial marker inside prose a player reads.
  {
    const leaks = [];
    const walk = (o, path) => {
      if (typeof o === "string") { if (/[⛔⚠]/.test(o) && !path.split(".").pop().startsWith("_")) leaks.push(path); return; }
      if (o && typeof o === "object") for (const [k, v] of Object.entries(o)) walk(v, `${path}.${k}`);
    };
    walk(T433.templates, "templates"); walk(T433.fragments, "fragments");
    check("433: no editorial marker leaks into a string a player reads", leaks.length === 0, leaks.join(" · "));
  }

  // 13 · THE WIRING ITSELF, as a census rather than a number — four sites resolve a clash and all four must
  // hand it the content, or three of them quietly keep the engine's own sentences.
  {
    const wt433 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
    const applies = (wt433.match(/(?<!export function )applyEpicClashOutcome\(ws,/g) || []).length;
    const fed = (wt433.match(/abilitiesByTradition[^}]*, content \}/g) || []).length;
    check("433: every clash site hands the tick's content to the reporter", applies === 4 && fed === applies,
      `${applies} clash sites, ${fed} carrying content`);
  }

  // 14 · AND END TO END: a world that actually runs, and the murmurs it produces are sentences.
  {
    let seed433 = 12345;
    const rng433 = () => ((seed433 = (seed433 * 1664525 + 1013904223) >>> 0) / 4294967296);
    const ch433 = { name: "P", level: 6, worldState: initWs433(1) };
    // 900 days, because the personal-beat path does not fire in the first 400: measured 0 murmurs at
    // day 400 and 19 by day 600. A gate over an empty list is green and proves nothing.
    for (let d = 1; d <= 900; d++) {
      await tick433({ character: ch433, content: C433, evolveFn: async () => ({}), rng: rng433, now: Date.UTC(2025, 0, 1) + d * 86400000 });
    }
    const items = ch433.worldState.news || [];
    const murmurs = items.filter(n => n.tier === "murmur" && !n.kind);
    const templated = murmurs.filter(n => /is spoken of:|Word from/.test(n.text));
    const rawIds = items.filter(n => /\b[a-z0-9]+_[a-z0-9_]+\b/.test(String(n.text)));
    check(`433 END TO END: a live world's personal beats are sentences (${templated.length}/${murmurs.length} through a template) and no id reaches the page`,
      murmurs.length > 0 && templated.length > 0 && rawIds.length === 0,
      rawIds.slice(0, 2).map(n => n.text).join(" · "));
  }
}

// ---- CCODE-193: the composer reaches EVERY picture, one beat late ---------------------------------
// ⛔ ERIK'S ASK WAS "EVERY IMAGE" AND CCODE-190 REACHED TWO PATHS. The other twelve mint inside a
// synchronous template literal, where there is nowhere to put an `await`. His ruling: "I'm ok with an
// uncomposed followed by a composed." So the mint announces itself and the composition follows.
{
  const A193 = await import("../engine/art.js");
  const { setArtMode: setArt193 } = A193;
  setArt193("generate");
  const fired = [];
  A193.onImageMinted(j => fired.push(j));
  const npc193 = { id: "n193", name: "Pell Ran Marsh",
    appearance: "grey wool worn thin at the knees, hands stained to the wrist, a look that does not move" };
  const url193 = A193.ensureImage(npc193, "npc", { ratingLevel: 2 });
  const first = fired[0];
  // 1 · IT FIRES ON A REAL MINT — and NOT on a cached one, or a saved character would re-compose every
  // picture it owns on every open, which is a bill for nothing.
  A193.ensureImage(npc193, "npc", { ratingLevel: 2 });
  check("CCODE-193: a fresh mint announces itself and a persist-once cache hit does NOT (no re-compose on every open)",
    !!url193 && fired.length === 1 && first?.url === url193 && first?.record === npc193 && first?.field === "image",
    `fired ${fired.length}×`);
  // 2 · ⛔ COMPOSE BEFORE THE FLOORS, NEVER AFTER. The hook must carry the line the floors have NOT yet
  // been applied to — composing on top of them lets the model compress away the ceiling tone it just added.
  {
    const floored = A193.sanitizeImagePrompt(first.raw, { ratingLevel: first.ratingLevel, isMinor: first.isMinor, kind: first.kind });
    check("CCODE-193: the hook carries the PRE-FLOOR line, and the floors are what the picture was actually minted from",
      floored !== first.raw && floored.startsWith(first.raw) && url193.includes(encodeURIComponent(floored)),
      `raw=${first.raw.slice(-40)} | floored=${floored.slice(-40)}`);
  }
  // 3 · A SWAP IS NOT ONE ASSIGNMENT. The caller stores the URL wherever it likes; every copy is the same
  // picture, so every copy moves.
  {
    const OLD = "https://image.pollinations.ai/prompt/one?seed=1", NEW = "https://image.pollinations.ai/prompt/two?seed=1";
    const save = { portrait: OLD, keep: OLD + "x", locationImages: { maw: OLD }, npcRegistry: { p: { image: OLD, name: "P" } },
                   gallery: [{ url: OLD, caption: "c" }, { url: "other" }], nested: { deep: { arr: [OLD, "no"] } } };
    const n = A193.swapImageUrl(save, OLD, NEW);
    check("CCODE-193: a re-mint rewrites EVERY stored copy of the old URL and nothing that merely resembles it",
      n === 5 && save.portrait === NEW && save.locationImages.maw === NEW && save.npcRegistry.p.image === NEW
      && save.gallery[0].url === NEW && save.nested.deep.arr[0] === NEW
      && save.keep === OLD + "x" && save.gallery[1].url === "other" && save.npcRegistry.p.name === "P", `changed ${n}`);
  }
  // 4 · ⚠️ A SAVE HOLDS CYCLES. `seen` is not an optimisation — without it this hangs on a real character
  // rather than on a fixture, which is the kind of bug that only ever appears in play.
  {
    const a = { image: "OLD" }; a.self = a; a.kid = { parent: a, image: "OLD" };
    // ⚠️ CAUGHT, NOT LEFT TO CRASH. Without the guard this overflows the stack, and a suite that dies
    // reports nothing at all — a mutation has to produce a RED, not a corpse.
    let n = -1; try { n = A193.swapImageUrl(a, "OLD", "NEW"); } catch (e) { n = `threw: ${e?.message}`; }
    check("CCODE-193: the rewrite terminates on a save that points back at itself", n === 2 && a.image === "NEW" && a.kid.image === "NEW", String(n));
  }
  // 5 · ONE COMPOSITION PER SUBJECT, EVER — the cache is what keeps this from being a per-render bill, and
  // it is also Aevi's stability rule: same subject, same picture, forever.
  {
    const { composeImagePrompt } = await import("../engine/imageprompt.js");
    const long = Array.from({ length: 14 }, (_, i) => `clause number ${i} with some visual detail in it`).join(", ");
    let calls = 0;
    const stub = async () => { calls++; return "a composed line about a person in grey wool, hands stained, standing still"; };
    const cache = {};
    const a1 = await composeImagePrompt(long, { cache, kind: "npc", call: stub });
    const a2 = await composeImagePrompt(long, { cache, kind: "npc", call: stub });
    check("CCODE-193: a subject is composed ONCE — the second mint of the same line reads the cache and spends nothing",
      calls === 1 && a1.composed && a2.composed && a1.prompt === a2.prompt, `${calls} call(s)`);
  }
  // 5b · ⛔ A DERIVE-AT-RENDER PATH HAS NOWHERE TO PUT THE ANSWER. The scene banner and the item study
  // rebuild their URL every render and store nothing, so without a memory of what a composition replaced,
  // the banner would show the composed picture once and the raw one forever after — a flicker on every
  // render instead of one. The mint asks first, and a known answer is returned WITHOUT announcing again.
  {
    const asked = [];
    const fired2 = [];
    A193.onImageMinted(j => fired2.push(j));
    const scene = { name: "The Maw" }, st = { setting: "a low hall of wet stone, one lamp guttering" };
    const first2 = A193.sceneImage(scene, st, { ratingLevel: 2 });
    A193.onComposedLookup(u => { asked.push(u); return u === first2 ? "COMPOSED-URL" : null; });
    const second2 = A193.sceneImage(scene, st, { ratingLevel: 2 });
    A193.onComposedLookup(null);
    check("CCODE-193: a derive-at-render picture remembers the composed re-mint, and does not re-announce it",
      !!first2 && fired2.length === 1 && second2 === "COMPOSED-URL" && asked.includes(first2) && fired2.length === 1,
      `fired ${fired2.length}×, asked ${asked.length}×, got ${String(second2).slice(0, 40)}`);
    A193.onImageMinted(null);
  }
  // 5c · ⚠️ AND THE PLAYER VOTES ON WHAT THEY CAN SEE. A lightbox item is built before the composition
  // lands, so "Keep this look" and "Set as default" would otherwise commit the address of a picture that
  // has already been replaced on screen — the vote would be cast on a picture nobody is looking at.
  {
    const app5c = readFileSync(join(root, "app.js"), "utf8");
    // ⛔ BOTH HALVES OF THE TABLE, because mutation showed one of them was untested: 5b exercises
    // art.js's lookup with a stub, which stays green with the app-side WRITE deleted. Testing the
    // mechanism is not testing the wiring — the same lesson CCODE-191's cache-key gate learned.
    // ⚠️ CCODE-198 CHANGED THE TABLE'S WRITER, NOT ITS PURPOSE. It used to record the composed re-mint;
    // now the only thing that replaces a minted URL is the SNG-435 heal (a proven-empty address swapped for a
    // busted one that has bytes). The table and both readers stay, because the reason they exist is unchanged:
    // a lightbox item is built before the swap, so committing `it.url` would commit an address nothing serves.
    check("CCODE-193/198: a replaced URL is recorded against the one it replaces, and read back wherever one is committed",
      /\(character\.composedImages \|\|= \{\}\)\[job\.url\] = good;/.test(app5c)
      && /onComposedLookup\(\(url\) => shownUrl\(url\)/.test(app5c)
      && /it = \{ \.\.\.it, url: shownUrl\(it\.url\) \}/.test(app5c)
      && /sub\.spec\.keep\(it\.regen\.subjectId, shownUrl\(it\.url\)/.test(app5c)
      && /function shownUrl\(u\) \{ return \(u && character\?\.composedImages\?\.\[u\]\) \|\| u; \}/.test(app5c));
  }
  // 6 · THE WIRING, AS A CENSUS. The hook fires inside the ONE mint, so a picture added tomorrow is composed
  // without anyone remembering to wire it — and the twelve call sites stay untouched.
  {
    const app193 = readFileSync(join(root, "app.js"), "utf8");
    const art193 = readFileSync(join(root, "engine/art.js"), "utf8");
    // ⛔ THE STRONGEST FORM OF "EVERY IMAGE": nothing in art.js builds a URL except `mintURL`. A gate
    // that counted call sites would pass the day someone adds a thirteenth that mints around it — which
    // is exactly how the scene banner and the item study missed §1.
    const mintBody = art193.slice(art193.indexOf("function mintURL("), art193.indexOf("export function onImageMinted"));
    // ⚠️ TWO OCCURRENCES ONLY: the declaration, and the single use inside `mintURL`. Anything else is a
    // mint that skips the announcement, which is how the scene banner and the item study missed §1.
    const mintStart = art193.indexOf("function mintURL("), mintEnd = art193.indexOf("export function onImageMinted");
    const strays = [...art193.matchAll(/imageURLFor\(/g)]
      .filter(m => !art193.startsWith("export function imageURLFor(", m.index - 16))
      .filter(m => m.index < mintStart || m.index > mintEnd);
    const sites = (app193.match(/ensureImage\(/g) || []).length;
    const installs = (app193.match(/onImageMinted\(/g) || []).length;
    check(`CCODE-193: every URL in art.js is minted through the ONE announcing helper (${sites} app call sites, ${installs} listener)`,
      sites >= 10 && installs === 1 && /_onMinted\(\{/.test(mintBody) && strays.length === 0,
      `${strays.length} mint(s) bypass mintURL`);
    // ⛔ AND NO CALL SITE COMPOSES FOR ITSELF. Two paths to one answer is how the sentence and the picture
    // came to disagree in SNG-431; the battle mint is the one deliberate exception, because it composes
    // BEFORE minting (it knows there are two figures) rather than after.
    const composeCalls = (app193.match(/composeImagePrompt\(/g) || []).length;
    // ⛔ CCODE-198: TWO, NOT THREE. The automatic post-mint compose is gone at Erik's word, so what is
    // left is the battle mint (which composes BEFORE minting, because it knows there are two figures) and the
    // lightbox re-roll (which composes because he asked for it). Both are places a player is waiting on a
    // picture they requested; neither replaces one they already have.
    check("CCODE-193/198: composition happens only where it was ASKED for — the battle mint and Draw again",
      composeCalls === 2, `${composeCalls} direct composeImagePrompt call(s)`);
    // ⛔ NO KEY, NO CALL. The picture is already drawn; queueing without a key spends a failure per image.
    // ⛔ SNG-435 INVERTED THIS ONE, and the inversion is the finding. CCODE-193 kept the key check on
    // the LISTENER, which was right when the queue only composed — and became wrong the moment the queue also
    // VERIFIED. A player with no API key queued nothing, so they verified nothing, and would have collected
    // burned URLs invisibly forever. Composition costs money and is optional; proving the picture exists is
    // neither. The claim now is that the key gates the CALL and not the queue.
    // ⛔ CCODE-198 SETTLED THIS ONE BY REMOVING THE QUESTION. The queue does not compose at all now, so
    // there is no API key decision left in it — it verifies, and verification is free and not optional. What
    // must stay true is that a player with no key still has every picture checked.
    check("CCODE-193/198: the mint queue verifies and does NOTHING else — no key decision, no second draw",
      /if \(!job\?\.url \|\| !imagesEnabled\(\)\) return;/.test(app193)
      // ⚠️ THE DECLARATION, not the word. The note recording why it was deleted quotes its name, and a
      // scan for the bare string would read that documentation as the offence — the same trap the shared-
      // calendar gate fell into this morning. Asserting the declaration is gone is narrower and exactly the claim.
      && !/async function recomposeMinted/.test(app193)
      && !/getApiKey\(\)/.test(app193.slice(app193.indexOf("async function drainCompositions"), app193.indexOf("onComposedLookup("))));
  }
  A193.onImageMinted(null);
}

// ---- CCODE-195: the season turns ------------------------------------------------------------------
// ⛔ ERIK, FROM PLAY: "It never ceases to be early-spring... even after over 1000 world ticks." A season
// was 45 character-days = 1080 character-hours against a beat worth 1–2, so ONE season cost ~600 turns and a
// year ~4,800 — and what that hid was not a word in a header but seven of the eight authored SEASON_PRESSURE
// entries, each with a condition line the GM narrates from and the arc-kinds it tilts toward.
{
  const WT = await import("../engine/worldtime.js");
  const LA = await import("../engine/latentarcs.js");
  const { loadContentHeadless: lch195 } = await import("./headless_content.mjs");
  const C195 = await lch195();
  const cal195 = WT.seasonCalendar();
  // 1 · AUTHORED AND IN FORCE. Two engine constants meant the world's calendar could not be turned by the
  // people who own the world; a dial nothing loads is the same thing wearing a JSON file.
  check("CCODE-195: the season calendar is AUTHORED and in force (not the engine fallback)",
    !!C195.worldClock?.calendar?.daysPerSeason
    && cal195.daysPerSeason === C195.worldClock.calendar.daysPerSeason
    && cal195.seasons.length === C195.worldClock.calendar.seasons.length,
    `in force ${cal195.seasons.length}×${cal195.daysPerSeason}, authored ${C195.worldClock?.calendar?.seasons?.length}×${C195.worldClock?.calendar?.daysPerSeason}`);
  // 2 · ⛔ AND IT IS REACHABLE, MEASURED RATHER THAN ASSERTED. A beat moves the clock ~1h and a scene end 2h;
  // the claim is that a season turns inside a campaign, not inside a lifetime. 600 turns was the old answer.
  {
    const turnsPerSeason = Math.round(cal195.daysPerSeason * 24 / WT.ADVANCE.beat);
    const turnsPerYear = turnsPerSeason * cal195.seasons.length;
    console.log(`      season economy: ~${turnsPerSeason} turns per season, ~${turnsPerYear} per year (was 1080 / 8640)`);
    check(`CCODE-195: a season is reachable in play (~${turnsPerSeason} turns, was ~1080)`,
      turnsPerSeason > 40 && turnsPerSeason <= 400,
      "under 40 and the season is weather; over 400 and no one arrives at the second one");
  }
  // 3 · ⛔ EVERY SEASON THE CLOCK CAN PRODUCE MUST HAVE A PRESSURE. The names live in two places now — the
  // authored calendar and latentarcs' SEASON_PRESSURE — and a season with no condition line reaches the GM as
  // silence. The whole point of making the calendar turnable is that someone WILL turn it.
  {
    const dumb = cal195.seasons.filter(s => !LA.seasonalPressure(s));
    check(`CCODE-195: every season on the calendar has an authored pressure (${cal195.seasons.length} seasons)`,
      dumb.length === 0, `no condition line for: ${dumb.join(", ")}`);
  }
  // 4 · IT ACTUALLY TURNS, and wraps rather than running off the end of the list.
  {
    const at = (d) => WT.readClock({ day: d, hour: 12 }).season;
    const d = cal195.daysPerSeason;
    check("CCODE-195: the season turns on the boundary and the year wraps",
      at(1) === cal195.seasons[0] && at(d) === cal195.seasons[0] && at(d + 1) === cal195.seasons[1]
      && at(d * cal195.seasons.length + 1) === cal195.seasons[0],
      `${at(1)} → ${at(d + 1)} → ${at(d * cal195.seasons.length + 1)}`);
  }
  // 5 · ⚠️ A MALFORMED CALENDAR IS REFUSED, NOT HALF-APPLIED. No seasons is a division by nothing and a
  // header that reads `undefined`; a pack should degrade to the engine's own calendar, never to garbage.
  {
    const before = WT.seasonCalendar();
    const bad = [null, {}, { seasons: [], daysPerSeason: 5 }, { seasons: ["x"], daysPerSeason: 0 }, { seasons: "spring", daysPerSeason: 5 }];
    const held = bad.every(b => { const c = WT.setSeasonCalendar(b); return c.seasons.length === before.seasons.length && c.daysPerSeason === before.daysPerSeason; });
    check("CCODE-195: a malformed authored calendar is refused and the one in force is kept", held
      && !!WT.readClock({ day: 3, hour: 12 }).season);
  }
  // 6 · ⛔ AND NOTHING PUSHES AN INVENTED CALENDAR INTO SHARED STATE. The world tick wrote a hardcoded
  // `season: "late-spring", year: 15` into the file every other player reads — one writer, ZERO readers, and
  // `remote?.calendar ||` then preserved the first invention forever. A fabricated fact in shared state is
  // worse than a missing one: a missing field is obviously absent, and that one looked authored.
  {
    // ⚠️ COMMENTS STRIPPED FIRST, and this went red before they were: the note explaining what was
    // removed QUOTES the removed code, so the gate read its own documentation as the offence. The wiring
    // audit records the mirror of this — a check silenced by describing it — and both come from scanning prose
    // as if it were code.
    const wt195 = readFileSync(join(root, "engine/worldtick.js"), "utf8")
      .replace(/\/\*[\s\S]*?\*\//g, "").replace(/(^|[^:"'`\\])\/\/[^\r\n]*/g, "$1");
    check("CCODE-195: no invented season or year is written into the shared region file",
      !/season: "late-spring"/.test(wt195) && !/year: 15/.test(wt195) && !/calendar: remote/.test(wt195));
  }
}

// ---- CCODE-194: the lean has a reader ------------------------------------------------------------
// ⛔ `profileInsight` WAS NOT NEVER-WIRED, IT WAS DE-WIRED. SNG-118 replaced the profile prose wall with
// tappable chips and this went with the wall — imported by app.js, called by nothing, for eleven tickets.
// Erik: "You're right about the feature. It sounds like it could live on the character screen."
{
  const PP = await import("../engine/playerprofile.js");
  const APT194 = [
    { id: "open_handed", tendency: "generous", threshold: 5, description: "you give before you are asked", mods: {} },
    { id: "shadow", tendency: "stealth", threshold: 5, description: "rooms forget you were in them", mods: {} },
  ];
  const say194 = (prof) => PP.profileInsight(prof, APT194, {});
  // 1 · ⛔ THE HALF WITH NO READER IS `tendencies`. A chip appears when a threshold is CROSSED; nothing has
  // ever shown the player the drift that gets them there, so "who are you becoming?" was answerable only in
  // hindsight. Below the threshold, the lean is the whole of what can honestly be said.
  check("CCODE-194: a character with drift and no marks is told which way they lean",
    /you lean generous/.test(say194({ tendencies: { generous: 3, ruthless: 1 } })), say194({ tendencies: { generous: 3, ruthless: 1 } }));
  check("CCODE-194: a character with no drift at all is told exactly that, and nothing is invented",
    say194({}) === "The world is still learning who you are." && say194({ tendencies: { generous: 0 } }) === "The world is still learning who you are.");
  // 2 · ⚠️ IT MAY NOT SAY WHAT THE CHIPS SAY. The chips carry every earned aptitude WITH its description,
  // its mods and its standing. Restoring the old body would have put a prose list directly above the chips
  // that replaced it — undoing SNG-118 rather than surfacing a feature.
  {
    const marked = say194({ tendencies: { generous: 7 }, aptitudes: ["open_handed"] });
    check("CCODE-194: it does NOT re-list what the chips already show (no aptitude descriptions in the line)",
      !marked.includes("you give before you are asked") && !/open.handed/i.test(marked) && marked.length < 120, marked);
    check("CCODE-194: a crossed threshold reads differently from a drift — the mark is acknowledged, not repeated",
      /has marked you/.test(marked) && !/A pattern is forming/.test(marked), marked);
  }
  // 3 · A SECOND LEAN ONLY WHEN IT IS ACTUALLY CLOSE — naming the runner-up regardless would make every
  // character read as torn between two things, which is a claim about them that is usually false.
  check("CCODE-194: a close second lean is named and a distant one is not",
    /stealth close behind/.test(say194({ tendencies: { generous: 4, stealth: 3.2 } }))
    && !/close behind/.test(say194({ tendencies: { generous: 9, stealth: 1 } })));
  // 4 · SNG-113'S RULE, KEPT: loss is legible, never silent — and said in words here, because a mark you are
  // about to lose is the one part of this a player may need to act on today.
  {
    const slip = say194({ tendencies: { generous: 7, stealth: 5.2 }, aptitudes: ["open_handed", "shadow"] });
    check("CCODE-194: an aptitude about to be lost is said in words, and capitalised as its own sentence",
      /Shadow is slipping\./.test(slip), slip);
  }
  // 5 · AND IT IS ON THE SCREEN ERIK NAMED, above the chips, in the one block about who this character is.
  {
    const app194 = readFileSync(join(root, "app.js"), "utf8");
    const css194 = readFileSync(join(root, "style.css"), "utf8");
    const block194 = app194.slice(app194.indexOf("Play-style (${esc(character.name)}'s own)"),
                                 app194.indexOf("Active quests", app194.indexOf("Play-style (${esc(character.name)}'s own)")));
    check("CCODE-194: the character screen renders it, ABOVE the chips (the drift comes before the threshold it crosses)",
      /profileInsight\(character, CONTENT\.rules\.playerAptitudes/.test(block194)
      && block194.indexOf("profileInsight") < block194.indexOf("aptitudeChips")
      && /\.cs-lean \{/.test(css194), block194.replace(/\s+/g, " ").slice(0, 130));
  }
}

// ---- CCODE-196: a filtered-out craft is GONE, not faint ------------------------------------------
// ⛔ ERIK: "if i filter out skills have them disappear completely, not just dim... dimmed they still
// interfere with selection." A dimmed node kept its 13px hit circle — absent to the eye, present to the
// mouse — so a click meant for a craft that PASSED the filter could land on one it rejected.
{
  const { wheelRejects } = await import("../engine/wheelgeom.js");
  const heal = { id: "h", families: ["mend"], reachable: true };
  const harm = { id: "x", families: ["break"], reachable: true };
  const sugg = { id: "s", families: ["break"], recommended: true, reachable: true };
  const ownedSugg = { id: "o", families: ["break"], recommended: true, owned: true };
  // 1 · ⚠️ A TRADITION CLICK ALONE REJECTS NOTHING. SNG-202B's related/adjacent/dim rings are how the
  // wheel shows its shape — hiding the far side would tell the player the circle is smaller than it is.
  check("CCODE-196/197: a held tradition HIDES the rest (Erik: \"a bare tradition click should hide things too\")",
    wheelRejects({ cls: "life" }, { selTrads: new Set(["death"]) })
    && !wheelRejects({ cls: "death" }, { selTrads: new Set(["death"]) }));
  // 2 · each real filter rejects what it is for
  check("CCODE-196: the function filter rejects a craft with none of the chosen families",
    wheelRejects(harm, { fnFilter: new Set(["mend"]) }) && !wheelRejects(heal, { fnFilter: new Set(["mend"]) }));
  check("CCODE-196: ✨ Suggested rejects the unsuggested — and the already-owned, which is not a suggestion",
    wheelRejects(harm, { suggestOnly: true }) && !wheelRejects(sugg, { suggestOnly: true })
    && wheelRejects(ownedSugg, { suggestOnly: true }));
  check("CCODE-196: Attainable rejects what the points do not reach",
    wheelRejects({ families: ["break"] }, { buyableOnly: true }) && !wheelRejects(harm, { buyableOnly: true }));
  // 3 · ⛔ AND THEY COMPOSE, which is what Erik asked for at SNG-218: "the death ones" + "which of those
  // heal" + "which are suggested" must resolve to ONE visible set, not three overlapping paint jobs.
  check("CCODE-196: the filters INTERSECT — failing any one of them removes the craft",
    wheelRejects({ ...heal, cls: "life" }, { fnFilter: new Set(["mend"]), selTrads: new Set(["death"]) })
    && !wheelRejects({ ...heal, cls: "death" }, { fnFilter: new Set(["mend"]), selTrads: new Set(["death"]) }));
  // 4 · and the render DROPS it rather than fading it — the hit circle is the bug, so it must not be built.
  {
    const app196 = readFileSync(join(root, "app.js"), "utf8");
    const map196 = app196.slice(app196.indexOf("return m.nodes.map(nd => {"), app196.indexOf("}).join(\"\");", app196.indexOf("return m.nodes.map(nd => {")));
    check("CCODE-196: a rejected node returns EMPTY before the hit circle is ever emitted",
      /if \(rejectsNode\(nd\)\) return "";/.test(map196)
      && map196.indexOf("rejectsNode(nd)) return") < map196.indexOf('class="hit"'),
      "dimming it leaves a 13px invisible target on top of the wheel");
    check("CCODE-196: a hidden craft reserves no label slot either (visible labels must not be shoved by invisible nodes)",
      /m\.nodes\.filter\(nd => nd\.name && !rejectsNode\(nd\) &&/.test(app196));
  }
}

// ---- CCODE-199: a craft that rides the bond, and the numbers behind the map ----------------------
// ⛔ AEVI AUTHORED `progression: "stage"` AND NOTHING READ IT. `Attended End` is Marrow's craft, lent to
// the player, and its ranks open as the bird's bond deepens. She diagnosed a stage-3 ceiling in `bondOf`;
// measured, that ceiling does not exist. ⚠️ AND THE ROOT CAUSE WAS ONE STEP EARLIER AGAIN:
// `abilities/companion_taught.json` was not in the manifest, so the craft did not exist at all. Third time
// this class has appeared — after minted_names.json and news_templates.json.
{
  const CO = await import("../engine/companions.js");
  const CM = await import("../engine/craftmechanics.js");
  const { loadContentHeadless: lch199 } = await import("./headless_content.mjs");
  const C199 = await lch199();
  const ae = C199.abilities?.the_attended_end;
  // 1 · registered and loaded — the step before the field
  check("CCODE-199: the companion-taught craft is REGISTERED and loads (it was on disk and in no manifest)",
    !!ae && ae.progression === "stage", `the_attended_end ${ae ? "loads" : "MISSING"}`);
  // 2 · the teacher resolves from prose, which is a weak link and is gated as one
  check("CCODE-199: the teacher resolves from `taughtBy` when no companionId is authored",
    CO.stageTaughtBy(ae) === "marrow"
    && CO.stageTaughtBy({ progression: "stage", companionId: "hush" }) === "hush"
    && CO.stageTaughtBy({ taughtBy: "Marrow (companion bond)" }) === null,   // not a stage craft: no teacher
    String(CO.stageTaughtBy(ae)));
  // 3 · ⛔ THE RANK RIDES THE BOND, BOTH WAYS. A lent craft is lent — freezing the high-water mark would
  // make the lending one-directional and silently unlike every other bond consequence.
  {
    const at = (bond) => { const ch = { abilities: [{ abilityId: "the_attended_end", level: 1 }], companionBonds: { marrow: bond } };
      CO.syncStageTaughtRanks(ch, C199.abilities, C199.companions, C199.rules); return ch.abilities[0].level; };
    console.log(`      stage craft: bond 0->r${at(0)} 2->r${at(2)} 3->r${at(3)} 9->r${at(9)} 10->r${at(10)}`);
    check("CCODE-199: a stage craft's rank follows the bond up",
      at(0) === 1 && at(2) === 1 && at(3) === 2 && at(10) === 3);
    const cooled = { abilities: [{ abilityId: "the_attended_end", level: 3 }], companionBonds: { marrow: 0 } };
    CO.syncStageTaughtRanks(cooled, C199.abilities, C199.companions, C199.rules);
    check("CCODE-199: …and DOWN when the bond cools (a lent craft is lent)", cooled.abilities[0].level === 1);
  }
  // 4 · ⛔ AND IT CANNOT BE BOUGHT. A point spent here would be a point burned in silence.
  {
    const PR = await import("../engine/progression.js");
    const ch = { level: 20, skillPoints: 99, abilities: [{ abilityId: "the_attended_end", level: 1 }], companionBonds: { marrow: 10 } };
    const r = PR.rankUpAbility(ch, "the_attended_end", C199.rules, { catalog: C199.abilities });
    check("CCODE-199: a stage craft refuses a skill point, and says why",
      r.ok === false && /bond/.test(r.why || ""), JSON.stringify(r));
  }
  // 5 · ⛔ ANTISOAK, ON ERIK'S OWN THREE EXAMPLES. The middle one is the definition: antisoak AMPLIFIES
  // a wound and does not create one, so a blow that never landed cannot be made worse.
  check("CCODE-199: antisoak matches Erik's three worked examples exactly (10/8/6=8 · 6/8/6=0 · 2/0/6=8)",
    CM.antisoakLanded(10, 8, 6) === 8 && CM.antisoakLanded(6, 8, 6) === 0 && CM.antisoakLanded(2, 0, 6) === 8,
    `${CM.antisoakLanded(10, 8, 6)} / ${CM.antisoakLanded(6, 8, 6)} / ${CM.antisoakLanded(2, 0, 6)}`);
  // 5b · ⛔ CCODE-207 / SNG-500 §1 — HEALING HAS A READER. 25 crafts carried authored dice and nothing read
  // them: `mechanicFor` had three call sites and healing reached none, so `physicians_tome`'s 2d4 was prose
  // with a number attached. The asymmetries are gated here rather than suppressed on the damage path,
  // because a suppression is a thing a later edit undoes quietly and a gate is not.
  {
    const cfg207 = C199.craftMechanics || {};
    const tome = C199.abilities?.physicians_tome;
    const fixed = () => 0.5;                       // a fixed rng, so every number below is the SAME roll
    const heal = (opts = {}) => CM.resolveHeal(tome, { cfg: cfg207, rng: fixed, rank: 2, ...opts });

    check("CCODE-207: a healing craft resolves at all — the largest inert block in the game has a reader",
      !!tome && heal().ok === true && heal().healed > 0, JSON.stringify(heal()));

    // ⚠️ RANK IS A QUANTITY, NOT A DURATION. Erik: "HEALED IS HEALED."
    const r1 = heal({ rank: 1 }).healed, r2 = heal({ rank: 2 }).healed, r3 = heal({ rank: 3 }).healed;
    check("CCODE-207: rank buys a bigger heal, never a longer one — healed is healed",
      r1 < r2 && r2 < r3, `r1=${r1} r2=${r2} r3=${r3}`);

    // ⛔ NO CRIT. Hand the craft a crit dial and a rng that would crit on the damage path; nothing changes.
    const withCrit = { ...tome, mechanic: { ...tome.mechanic, crit: { success: { text: "x", chance: 95 } } } };
    check("CCODE-207: a heal cannot crit into overhealing — the crit dial is never consulted",
      CM.resolveHeal(withCrit, { cfg: cfg207, rng: fixed, rank: 2 }).healed === heal().healed);

    // ⛔ NO EVASION. A subject's evasion is not a thing that exists on this path; proving it means the
    // field can be set to anything and the answer does not move.
    const withEvade = { ...tome, mechanic: { ...tome.mechanic, evasion: 99, evasionRank: 3 } };
    check("CCODE-207: a heal cannot be evaded — you do not dodge being mended",
      CM.resolveHeal(withEvade, { cfg: cfg207, rng: fixed, rank: 2 }).healed === heal().healed);

    // ⛔ ARMOUR DOES NOT SOAK A HEAL. Only ACTIVE ONGOING HARM does.
    const withSoak = { ...tome, mechanic: { ...tome.mechanic, soak: 99, soakRank: 3 } };
    check("CCODE-207: armour does not soak a heal — plate does not stop mending",
      CM.resolveHeal(withSoak, { cfg: cfg207, rng: fixed, rank: 2 }).healed === heal().healed);

    const bleeding = heal({ ongoingHarm: [{ id: "bleed", magnitude: 3 }] });
    check("CCODE-207: ACTIVE ONGOING HARM soaks a heal — the wound is still opening while you close it",
      bleeding.soaked === 3 && bleeding.healed === heal().healed - 3,
      `soaked=${bleeding.soaked} healed=${bleeding.healed} vs clean ${heal().healed}`);

    // ⚠️ THE COUNTER-COUNTER. `Physician's Tome r1` — "the bleeding stopped" — is written for this.
    const staunched = heal({ ongoingHarm: [{ id: "bleed", magnitude: 3 }], staunch: true });
    check("CCODE-207: a heal may spend its value ENDING the harm instead of mending",
      staunched.ended.includes("bleed") && staunched.staunched === 3 && staunched.soaked === 0);

    // ⛔ AND IT MUST BE ABLE TO FAIL. A roll that cannot afford the harm ends nothing — otherwise
    // staunching is free and the crafts that impose bleeding never matter.
    const tooBig = heal({ ongoingHarm: [{ id: "grey", magnitude: 99 }], staunch: true });
    check("CCODE-207: a heal that cannot afford the harm ends nothing and mends nothing",
      tooBig.ended.length === 0 && tooBig.healed === 0, JSON.stringify(tooBig));

    // partial: two conditions, only the cheaper affordable — and what is still running keeps soaking
    const partial = heal({ ongoingHarm: [{ id: "nick", magnitude: 2 }, { id: "grey", magnitude: 99 }], staunch: true });
    check("CCODE-207: staunching some is not staunching all — what still runs still soaks",
      partial.ended.length === 1 && partial.ended[0] === "nick" && partial.healed === 0, JSON.stringify(partial));

    // ⚠️ THE TAPER, AND ITS FLOOR. Aevi's bound; Erik's numbers.
    const t0 = heal({ priorHeals: 0 }).healed, t1 = heal({ priorHeals: 1 }).healed, t9 = heal({ priorHeals: 9 }).healed;
    check("CCODE-207: repeat healing of one subject returns less each time, and never nothing",
      t1 < t0 && t9 > 0 && t9 >= Math.round(t0 * (cfg207.healing?.taperFloor ?? 0.25)),
      `t0=${t0} t1=${t1} t9=${t9}`);

    // ⛔ THE DIAL IS AUTHORED, NOT HARDCODED. A balance number that can only be changed by editing engine
    // source is a number nobody turns — the arc-response lesson.
    check("CCODE-207: the taper dial is authored in craft_mechanics.json and reaches the engine",
      Number.isFinite(cfg207.healing?.taperPer) && Number.isFinite(cfg207.healing?.taperFloor),
      JSON.stringify(cfg207.healing ?? null));

    check("CCODE-207: a craft that is not a heal is REFUSED, not resolved as one",
      CM.resolveHeal(C199.abilities?.sustained_regard, { cfg: cfg207, rng: fixed }).ok === false);

    // ⛔ COVERAGE, WHICH IS THE WHOLE POINT. Every authored healing craft must actually resolve — a
    // reader that works on the one craft it was written against is not a reader.
    const healers = Object.values(C199.abilities || {}).filter(a => a.shape === "healing" && a.mechanic?.dice);
    const dead = healers.filter(a => { const r = CM.resolveHeal(a, { cfg: cfg207, rng: fixed, rank: 1 }); return !r.ok || r.healed <= 0; });
    check(`CCODE-207: all ${healers.length} authored healing crafts resolve to a real number`,
      healers.length >= 20 && dead.length === 0, dead.slice(0, 6).map(a => a.id).join(", "));

    // ⛔ AND IT IS CALLED. A resolver with no call site is the exact bug this whole week has been about —
    // `resolveHeal` passing its own unit tests while healing stayed inert would be `narrationHints` again,
    // 376 written and 0 read. This runs a REAL round through `battleRound` and reads the result.
    //
    // ⚠️ HEALING WAS NEVER GUARDED OUT OF THE DAMAGE BLOCK — IT WAS NEVER LET IN. That branch is gated on
    // `harmFunctions`, and `heal`/`mend`/`restore` are not harm verbs, so a healing craft could WIN A ROUND
    // and produce nothing at all. The verb set is authored at `engine.damage.healFunctions`, beside the
    // harm one, because a set of verbs the engine treats specially is content.
    {
      const SB207 = await import("../engine/skill_battle.js");
      const rules207 = C199.rules || {};
      const sb207 = rules207.skillBattle || C199.skillBattle || {};
      const steps207 = C199.resolutionSteps || rules207.resolution || {};
      const decl = { ...tome, function: "heal", tier: 2, attribute: "mental", intensity: "standard",
                     name: "Physician's Tome", rank: 2 };
      const oppDecl = { function: "strike", tier: 1, attribute: "physical", intensity: "standard", name: "jab" };
      const hurt = { attributes: { mental: 6, physical: 4, social: 3, practical: 5 }, level: 8,
                     health: 20, maxHealth: 40, ongoingHarm: [{ id: "bleed", magnitude: 2 }] };
      const weak = { attributes: { mental: 1, physical: 2, social: 1, practical: 1 }, level: 1,
                     health: 20, maxHealth: 20, soak: 0 };
      const round = SB207.battleRound({ playerDecl: decl, oppDecl, playerSheet: hurt, oppSheet: weak,
        state: { momentum: 0, round: 1, playerEnergy: 100, opponentEnergy: 50, effects: [], pressure: { player: 0, opponent: 0 } },
        rules: rules207, sb: sb207, steps: steps207, rng: () => 0.5 });

      check("CCODE-207: a heal that WINS A ROUND produces a heal — the resolver is actually called",
        round.roundWinner === "player" && round.healing?.side === "player" && round.healing.amount > 0,
        JSON.stringify(round.healing ?? null));
      // ⛔ AND IT IS NOT A BLOW. A round won by mending must not also deal damage.
      check("CCODE-207: winning a round by mending deals no damage — a heal is not a negative hit",
        round.damage === null, JSON.stringify(round.damage));
      // the subject's ongoing harm reaches the resolver through the round, not just the unit test
      check("CCODE-207: the SUBJECT's ongoing harm reaches the round — a bleeding healer heals less",
        round.healing?.soaked === 2 && round.healing.amount === round.healing.rolled - 2,
        JSON.stringify(round.healing ?? null));
      // the verb set is authored, not hardcoded in the branch
      check("CCODE-207: the healing verbs are authored beside the harm verbs, not baked into the engine",
        Array.isArray((sb207.engine?.damage || sb207.damage || {}).healFunctions),
        JSON.stringify((sb207.engine?.damage || sb207.damage || {}).healFunctions ?? null));
    }
  }
  // 5c · ⛔ CCODE-208 / SNG-500 §2 — A CRAFT IMPOSES A CONDITION, AND A DENIED SIDE DOES NOT ACT.
  // `Keening` is authored and does nothing at any rank. Aevi's correction was the design: it does not need
  // a new state — `incapacitation.js` already owns what happens once you are down — it needs an ENTRANCE.
  {
    const cfg208 = C199.craftMechanics || {};
    const keening = { id: "keening", name: "Keening", function: "strike", tier: 3, attribute: "social",
      rank: 2, mechanic: { imposes: { condition: "unconscious", resist: "physical", degradesTo: "action_loss", targets: 3 } } };
    const imp = (o = {}) => CM.resolveImposition(keening, { cfg: cfg208, rank: 2, ...o });

    check("CCODE-208: a craft with no `imposes` imposes nothing — silence, not a default",
      CM.resolveImposition({ id: "x" }, { cfg: cfg208 }).ok === false);

    // ⛔ THE ONE THAT MATTERS MOST. Erik's §40: the ENGINE may impose death when the situation calls for it.
    // A craft is not a situation. Refused LOUDLY — a clamp would let `"slain"` sit in the catalogue looking
    // like it worked.
    const killer = { mechanic: { imposes: { condition: "slain" } } };
    check("CCODE-208: a craft can NEVER impose death — `slain` is refused, not clamped",
      CM.resolveImposition(killer, { cfg: cfg208, margin: 999 }).ok === false
      && /not a condition a craft may impose/.test(CM.resolveImposition(killer, { cfg: cfg208, margin: 999 }).why || ""));
    check("CCODE-208: nor by the back door — a `degradesTo` of `slain` is refused too",
      CM.resolveImposition({ mechanic: { imposes: { condition: "unconscious", degradesTo: "slain" } } },
        { cfg: cfg208, margin: 0, targetResist: 99 }).ok === false);

    check("CCODE-208: a decisive exchange puts them under",
      imp({ margin: 40, targetResist: 2 }).condition === "unconscious");

    // ⚠️ THE RESIST CHANGES WHAT LANDS, NEVER WHETHER ANYTHING DOES.
    const resisted = imp({ margin: 1, targetResist: 9 });
    check("CCODE-208: a resisted imposition DEGRADES to action-loss — it never evaporates",
      resisted.ok === true && resisted.condition === "action_loss"
      && resisted.resisted === true && resisted.degradedTo === "unconscious", JSON.stringify(resisted));

    check("CCODE-208: rank makes it HARDER TO SHRUG OFF, not a bigger number",
      imp({ rank: 3, margin: 0, targetResist: 4 }).threshold < imp({ rank: 1, margin: 0, targetResist: 4 }).threshold);
    check("CCODE-208: what the subject brings raises the bar",
      imp({ targetResist: 8 }).threshold > imp({ targetResist: 1 }).threshold);
    check("CCODE-208: the craft's own `targets` caps how many it can reach",
      imp({ margin: 40, targets: 99 }).targets === 3);
    // ⛔ ESCALATE — AEVI'S §4 SHAPE, THE ONE SHE EXPECTED TO BE UNSUPPORTED. "A weakening becomes an
    // incapacitation· an action-loss becomes unconsciousness." It is supported the moment a craft can
    // impose at all, because escalation is a different argument to the same call rather than a new system.
    {
      const grey = { mechanic: { imposes: { condition: "staggered", onCrit: "incapacitated", degradesTo: "action_loss" } } };
      check("CCODE-208 ESCALATE: a crit makes the effect a DIFFERENT, better effect, not a bigger number",
        CM.resolveImposition(grey, { cfg: cfg208, margin: 40 }).condition === "staggered"
        && CM.resolveImposition(grey, { cfg: cfg208, margin: 40, degree: "crit_success" }).condition === "incapacitated");
      check("CCODE-208 ESCALATE: a craft with no onCrit crits exactly as before — opt-in, not imposed",
        CM.resolveImposition(keening, { cfg: cfg208, margin: 40, degree: "crit_success" }).condition === "unconscious");
      // ⛔ AND THE DEATH GUARD HOLDS THROUGH THE ESCALATION PATH, which is the door it would have come in by.
      check("CCODE-208 ESCALATE: a crit cannot escalate into death either",
        CM.resolveImposition({ mechanic: { imposes: { condition: "staggered", onCrit: "slain" } } },
          { cfg: cfg208, margin: 40, degree: "crit_success" }).ok === false);
    }
    check("CCODE-208: the imposition dial is authored in craft_mechanics.json, not hardcoded",
      Number.isFinite(cfg208.imposition?.base) && Number.isFinite(cfg208.imposition?.perRank),
      JSON.stringify(cfg208.imposition ?? null));

    // ---- and it is CALLED, through a real round ----
    {
      const SB208 = await import("../engine/skill_battle.js");
      const EN208 = await import("../engine/encounters.js");
      const rules208 = C199.rules || {};
      const sb208 = rules208.skillBattle || C199.skillBattle || {};
      const steps208 = C199.resolutionSteps || rules208.resolution || {};
      const strong = { attributes: { social: 7, physical: 5, mental: 4, practical: 4 }, level: 9, health: 40, maxHealth: 40 };
      const frail = { attributes: { social: 1, physical: 1, mental: 1, practical: 1 }, level: 1, health: 20, maxHealth: 20, soak: 0 };
      const jab = { function: "strike", tier: 1, attribute: "physical", intensity: "standard", name: "jab" };
      const run = (extra = {}) => SB208.battleRound({ playerDecl: keening, oppDecl: jab, playerSheet: strong, oppSheet: frail,
        state: { momentum: 0, round: 1, playerEnergy: 100, opponentEnergy: 50, effects: [], pressure: { player: 0, opponent: 0 }, ...extra },
        rules: rules208, sb: sb208, steps: steps208, rng: () => 0.5 });

      const round = run();
      check("CCODE-208: a winning craft's imposition reaches the round — the resolver is actually called",
        round.imposed?.side === "opponent" && ["unconscious", "action_loss"].includes(round.imposed.condition),
        JSON.stringify(round.imposed ?? null));

      // ⛔ ACTION LOSS. `deniesPhase` rode onto live effects since CCODE-41 and NOTHING asked about the
      // action phase — only "sense", in app.js. A side that gets no turn must not merely roll worse.
      const denied = run({ effects: [{ kind: "hold", label: "held", side: "player", roundsLeft: 2, deniesPhase: "action", value: 0 }] });
      check("CCODE-208: a side denied the ACTION phase loses the exchange without rolling for it",
        denied.roundWinner === "opponent" && denied.deniedAct?.player === true, JSON.stringify(denied.deniedAct));
      const bothDenied = run({ effects: [
        { kind: "hold", label: "held", side: "player", roundsLeft: 2, deniesPhase: "action", value: 0 },
        { kind: "hold", label: "held", side: "opponent", roundsLeft: 2, deniesPhase: "action", value: 0 }] });
      check("CCODE-208: both sides denied is a wasted round for both, not a win for either",
        bothDenied.roundWinner === null);

      // ---- and the state is CONSULTED, not merely set ----
      check("CCODE-208: an imposed unconscious puts someone down — checkIncapacitation reads it",
        EN208.checkIncapacitation({ health: 30, condition: "unconscious" }) === "incapacitated");
      check("CCODE-208: health still does it on its own, and an ordinary character is still standing",
        EN208.checkIncapacitation({ health: 0 }) === "incapacitated"
        && EN208.checkIncapacitation({ health: 30 }) === null);
      // ⛔ AND `slain` IS NOT A CONDITION THAT PUTS YOU THERE. Death is the incapacitation table's outcome,
      // reached after you are down — never a string a craft or a caller can set to skip the weighing.
      check("CCODE-208: `slain` as a condition does not short-circuit the incapacitation table",
        EN208.checkIncapacitation({ health: 30, condition: "slain" }) === null);
    }
  }
  // 5d · ⛔ CCODE-209 / SNG-511 §2 — `world/` IS A SECOND DOOR, AND A SECOND DOOR NEEDS ITS OWN LOCK.
  // Aevi asked whether `content/packs/core/world/` is deliberately outside the manifest or "the same
  // invisibility one directory over." She read it right: it is a different loading mechanism — nine of its
  // ten files are reached by DIRECT PATH from app.js, scripts/world/* and content_ci, and the manifest has
  // no `world` key at all. Registering them would have invented a defect.
  //
  // ⚠️ BUT THE MANIFEST CANNOT PROTECT WHAT IT CANNOT SEE. The failure class still exists here, wearing a
  // different face: not "a file with no manifest entry" but "a file with no READER". `scale.json` is
  // exactly that, and her instinct to separate "the loader cannot see it" from "nobody has wired it yet"
  // is the whole point — they are different problems with different fixes. So: a ratchet.
  {
    const worldDir = join(root, "content/packs/core/world");
    const scanned = ["app.js", "engine", "scripts", "tests"]
      .flatMap(rel => {
        const abs = join(root, rel);
        if (!existsSync(abs)) return [];
        if (rel.endsWith(".js")) return [readFileSync(abs, "utf8")];
        const walk = (d) => readdirSync(d, { withFileTypes: true }).flatMap(e =>
          e.isDirectory() ? walk(join(d, e.name))
            // ⛔ AND THE SCANNER MUST NOT READ ITSELF. This gate first came up GREEN at 10/10 because the
            // only occurrence of `scale.json` anywhere was the comment above explaining that it has no
            // reader. A gate satisfied by its own documentation is the same bug as one tripped by it.
            : /\.(js|mjs)$/.test(e.name) && e.name !== "smoke.mjs" ? [readFileSync(join(d, e.name), "utf8")] : []);
        return walk(abs);
      }).join("\n");
    const worldFiles = readdirSync(worldDir).filter(f => f.endsWith(".json"));
    const unread = worldFiles.filter(f => !scanned.includes(f));
    check(`CCODE-209: ${worldFiles.length - unread.length}/${worldFiles.length} world/ files have a reader — may only IMPROVE`,
      unread.length <= 1, `unread: ${unread.join(", ")}`);
    // ⛔ AND THE DIRECTORY STAYS OUT OF THE MANIFEST ON PURPOSE. If someone "fixes" that later, this says
    // why not — the loader has no `world` key, so a manifest entry there would be a path nothing reads.
    const coreManifest = JSON.parse(readFileSync(join(root, "content/packs/core/manifest.json"), "utf8"));
    check("CCODE-209: world/ is deliberately outside the manifest — a second door, documented in §42.1",
      !Object.keys(coreManifest.provides || {}).includes("world"),
      "a `world` key was added to provides; the loader has none, so those paths would be read by nothing");
  }
  // 5e · ⛔ CCODE-210: ANTISOAK IS CALLED. It was built against Erik's three examples, gated, and had NO
  // CALL SITE for a week - my own reader-with-no-writer, and Aevi's dungeon spec found it by asking which
  // of Level 3's mechanics were real. A gate on the arithmetic is not a gate on the wiring.
  {
    const SB210 = await import("../engine/skill_battle.js");
    const rules210 = C199.rules || {}, sb210 = rules210.skillBattle || C199.skillBattle || {};
    const steps210 = C199.resolutionSteps || rules210.resolution || {};
    const hitter = { attributes: { physical: 8, mental: 4, social: 4, practical: 5 }, level: 9, health: 40, maxHealth: 40 };
    const decl = { function: "strike", tier: 4, attribute: "physical", intensity: "standard", name: "a hard blow" };
    const jab = { function: "shield", tier: 1, attribute: "physical", intensity: "conserve", name: "guard" };
    const target = (extra) => ({ attributes: { physical: 1, mental: 1, social: 1, practical: 1 }, level: 1,
      health: 40, maxHealth: 40, soak: 2, ...extra });
    const run = (t) => SB210.battleRound({ playerDecl: decl, oppDecl: jab, playerSheet: hitter, oppSheet: t,
      state: { momentum: 0, round: 1, playerEnergy: 100, opponentEnergy: 50, effects: [], pressure: { player: 0, opponent: 0 } },
      rules: rules210, sb: sb210, steps: steps210, rng: () => 0.5 });
    const plain = run(target({})), vuln = run(target({ antisoak: 6 }));
    check("CCODE-210: an ANTISOAKED target takes more from the same blow — the arithmetic is wired, not just gated",
      vuln.damage?.amount === plain.damage?.amount + 6,
      );
  }
  // 5f · ⛔ CCODE-211 / SNG-500 §4 — THE CONTESTED SENSE SLOT. Obscure was something you HAD, read off the
  // sheet whether or not you lifted a finger. Now it is something you DO, and it costs the same thing a
  // guard costs: you did not look.
  {
    const SB211 = await import("../engine/skill_battle.js");
    const rules211 = C199.rules || {}, sb211 = rules211.skillBattle || C199.skillBattle || {};
    const steps211 = C199.resolutionSteps || rules211.resolution || {};

    // ⚠️ THE TAG, NEVER THE VERB. Inferring obscure from `conceal`/`deceive` would enrol every craft
    // carrying those verbs into a role its author never gave it — 15 crafts are tagged, and more than 15
    // carry the verbs.
    check("CCODE-211: obscure is read from the TAG, not from the verb",
      SB211.isObscureDecl({ obscure: true, function: "strike" }) === true
      && SB211.isObscureDecl({ function: "conceal" }) === false
      && SB211.isObscureDecl({ function: "deceive" }) === false);
    check("CCODE-211: and the sense tag is its own flag, not a guess from the verb",
      SB211.isSenseDecl({ sense: true }) === true && SB211.isSenseDecl({ function: "reveal" }) === false);

    // ⛔ THE TIE RULE, AT ITS BOUNDARY. Aevi named this as the rule most likely to be softened in
    // implementation because it looks unfair in a unit test. It is gated at the exact boundary so
    // softening it cannot pass quietly.
    check("CCODE-211: THE OBSCURER WINS TIES — a gap of exactly 0 is the hider's, 1 is the reader's",
      SB211.obscurerWinsTie(0) === true && SB211.obscurerWinsTie(1) === false && SB211.obscurerWinsTie(-1) === true);

    const reader = { sense: true, function: "reveal", tier: 2, attribute: "mental", intensity: "standard", name: "Read" };
    const hider = { obscure: true, function: "conceal", tier: 5, attribute: "social", intensity: "press", name: "False Stance" };
    const guard = { function: "shield", tier: 1, attribute: "physical", intensity: "conserve", name: "a raised guard" };
    const weak = { attributes: { mental: 3, physical: 3, social: 3, practical: 3 }, level: 3, health: 30, maxHealth: 30 };
    const strong = { attributes: { mental: 8, physical: 8, social: 8, practical: 8 }, level: 12, health: 30, maxHealth: 30 };
    const sense = (pd, od, ps = weak, os = strong) => SB211.battleRound({ playerDecl: pd, oppDecl: od,
      playerSheet: ps, oppSheet: os,
      state: { momentum: 0, round: 1, playerEnergy: 100, opponentEnergy: 100, effects: [], pressure: { player: 0, opponent: 0 } },
      rules: rules211, sb: sb211, steps: steps211, rng: () => 0.5, phase: "sense" });

    // ⛔ DECLARING OBSCURE COSTS YOU THE READ. The same trade the guard already made — it is a choice only
    // if it is a trade.
    const asHider = sense(hider, guard, strong, weak);
    check("CCODE-211: declaring obscure earns NO sense tier — you did not look",
      asHider.senseTier === 0 && !!asHider.obscuredInsteadOfReading, JSON.stringify(asHider.obscuredInsteadOfReading));
    check("CCODE-211: and it earns no setup bonus either — the guard's rule, one craft further",
      asHider.setupBonus === 0);

    // an ACTIVE obscure opposes the read with the roll they actually made
    const vsHider = sense(reader, hider);
    check("CCODE-211: a DECLARED obscure raises the bar above passive guardedness",
      vsHider.obscuredBy && vsHider.obscuredBy.resist > vsHider.obscuredBy.was,
      JSON.stringify(vsHider.obscuredBy ?? null));
    // ⛔ AND NEVER LOWERS IT. Working at being unfound cannot leave you easier to read than standing there.
    const lazyHider = { ...hider, tier: 1, intensity: "conserve" };
    const vsLazy = sense(reader, lazyHider);
    check("CCODE-211: a badly-rolled obscure never leaves them EASIER to read than standing there",
      !vsLazy.obscuredBy || vsLazy.obscuredBy.resist >= vsLazy.obscuredBy.was,
      JSON.stringify(vsLazy.obscuredBy ?? null));
    // an undeclared opponent gets the passive path and no tie
    const vsGuard = sense(reader, guard);
    check("CCODE-211: an opponent who did NOT declare obscure gets the passive path and no tie",
      !vsGuard.obscuredBy);
  }
  // 5g · ⛔ CCODE-212 / SNG-517 — A SUCCESSFUL OBSCURE EARNS THE BONUS ACTION. Erik's ruling, and it
  // partially reverses a warning of mine that is on the record: the sense step was built consequence-free
  // so that READING is not a way to win.
  //
  // ⚠️ IT HOLDS BECAUSE IT IS ASYMMETRIC, AND THAT ASYMMETRY IS THE FIRST GATE HERE. The reader still banks
  // nothing. What the change adds is that BEATING a reader is a way to win — a different claim from the one
  // the guard was protecting, and the one Erik actually ruled on.
  {
    const SB212 = await import("../engine/skill_battle.js");
    const sb212 = (C199.rules?.skillBattle || C199.skillBattle || {});
    const ss = sb212.engine?.senseStep || sb212.senseStep || {};
    const cfg212 = { senseStep: ss };
    const bonus = (o) => SB212.senseBonusFor({ sb: cfg212, ...o });

    // ⛔ THE GUARD'S PROTECTION, RESTATED AS A GATE. If this ever returns anything for a reader, the thing
    // CCode warned about has happened and nobody noticed.
    check("CCODE-212: the READER can never earn a bonus from the sense step — reading is still not a way to win",
      bonus({ obscured: false, opponentSensed: true, gap: -999 }) === null
      && bonus({ obscured: false, opponentSensed: false, gap: 999 }) === null);

    check("CCODE-212: hiding from nobody is not a win — a passive opponent earns the obscurer nothing",
      bonus({ obscured: true, opponentSensed: false, gap: -999 }) === null);

    // ⛔ CCODE-213 / ERIK'S SECOND RULING: AN UNCONTESTED OBSCURE PAYS. "Let obscure grant a free action
    // in the case the opponent does nothing in the sense round as well." ⚠️ This REVERSES Aevi's specced
    // "hiding from nobody is not a win" for the IDLE case only — she still governs the case where they
    // acted and simply did not look.
    {
      check("CCODE-213: an obscure nobody contested earns the bonus — they spent nothing, you spent your slot",
        bonus({ obscured: true, opponentIdle: true, gap: 0 }) === "obscurer");
      // ⛔ AND THE ASYMMETRY SURVIVES THE NEW BRANCH. This is the gate that matters: a new early return is
      // exactly how "the reader banks nothing" would quietly stop being true.
      check("CCODE-213: the reader STILL banks nothing, even against an opponent who did nothing",
        SB212.senseBonusFor({ sb: cfg212, obscured: false, opponentIdle: true, gap: -999 }) === null);
      // ⚠️ NOTHING MEANS NOTHING. A guard is an ACT — they spent the slot, just not on looking — and
      // Aevi's rule still governs it. Widening this to "did not read" is a different ruling.
      check("CCODE-213: a guard is an ACT, not nothing — it still earns the obscurer nothing",
        SB212.declaredNothing({ function: "shield" }) === false
        && bonus({ obscured: true, opponentSensed: false, opponentIdle: false, gap: -999 }) === null);
      check("CCODE-213: 'nothing' is no declaration at all — absent, functionless, or explicitly idle",
        SB212.declaredNothing(null) === true && SB212.declaredNothing({}) === true
        && SB212.declaredNothing({ function: "strike", noAct: true }) === true);
      // the band is about a coin-flip, and there was no flip
      check("CCODE-213: the null band does NOT apply to an uncontested obscure — there was no roll to tie",
        bonus({ obscured: true, opponentIdle: true, gap: 0 }) === "obscurer"
        && bonus({ obscured: true, opponentSensed: true, gap: 0 }) === null);
    }

    // ⛔ OBSCURE vs OBSCURE EARNS NOBODY ANYTHING - BOTH WASTED THE SLOT. Aevi specced this condition
    // explicitly and it was passing only as a CONSEQUENCE of  rejecting a conceal craft.
    // ⚠️ That is true today and would stop being true the moment anyone widened , at
    // which point BOTH sides would start banking a bonus for hiding from each other and nothing would say
    // so. A specced condition that holds by accident is not held.
    {
      const hid = { obscure: true, function: "conceal", name: "False Stance" };
      check("CCODE-212: obscure vs obscure earns nobody anything — both wasted the slot",
        SB212.declaredSense(hid, cfg212) === false
        && bonus({ obscured: true, opponentSensed: SB212.declaredSense(hid, cfg212), gap: -999 }) === null);
    }

    // ⛔ THE NULL BAND IS A SEPARATE AXIS FROM THE TIE RULE, AND AEVI SAID NOT TO MERGE THEM.
    // At gap 0: the obscurer WINS THE READ (obscurerWinsTie) and EARNS NO BONUS (the band). Both, together,
    // is the whole point — they broke even.
    // ⚠️ AND IT MUST TEST INSIDE THE BAND, NOT AT ZERO. The first version of this gate checked gap 0 -
    // which returns null from the SIGN check whether or not a band exists, so deleting the band left it
    // green. Green for the wrong reason at the exact boundary it claimed to test. A gap of -1 is inside
    // the band and on the OBSCURER's side, so only the band can be what withholds the bonus.
    check("CCODE-212: at gap 0 the obscurer denies the read AND earns no bonus — two axes, not one",
      SB212.obscurerWinsTie(0) === true
      && bonus({ obscured: true, opponentSensed: true, gap: 0 }) === null
      && bonus({ obscured: true, opponentSensed: true, gap: -1 }) === null);

    const band = Math.max(0, Number(ss.bonusNullBand ?? 2));
    check(`CCODE-212: the null band is ±${band} and its edge is inclusive — the band is a dial, not a literal`,
      bonus({ obscured: true, opponentSensed: true, gap: -band }) === null
      && bonus({ obscured: true, opponentSensed: true, gap: -(band + 1) }) === "obscurer"
      && Number.isFinite(Number(ss.bonusNullBand)), `authored band: ${ss.bonusNullBand}`);

    check("CCODE-212: an obscure that was READ ANYWAY earns nothing — the gambit can lose",
      bonus({ obscured: true, opponentSensed: true, gap: band + 99 }) === null);

    // ⚠️ SENSE IS AN ACT, NOT A ROLE — deliberately looser than isObscureDecl, and for a measured reason:
    // opponentPolicy builds declarations with no tags at all, so a tag-only rule could never fire in play.
    check("CCODE-212: 'did they read' accepts the authored senseFunctions as well as the tag",
      SB212.declaredSense({ function: "reveal" }, cfg212) === true
      && SB212.declaredSense({ sense: true, function: "strike" }, cfg212) === true
      && SB212.declaredSense({ function: "strike" }, cfg212) === false);

    // ---- and end to end, with the sign in the right direction ----
    {
      const rules212 = C199.rules || {}, steps212 = C199.resolutionSteps || rules212.resolution || {};
      const hider = { obscure: true, function: "conceal", tier: 5, attribute: "social", intensity: "press", name: "False Stance" };
      const looker = { function: "reveal", tier: 1, attribute: "mental", intensity: "conserve", name: "a glance" };
      const guard = { function: "shield", tier: 1, attribute: "physical", intensity: "conserve", name: "a raised guard" };
      const strong = { attributes: { mental: 8, physical: 8, social: 8, practical: 8 }, level: 12, health: 30, maxHealth: 30 };
      const weak = { attributes: { mental: 2, physical: 2, social: 2, practical: 2 }, level: 2, health: 30, maxHealth: 30 };
      const run = (pd, od) => SB212.battleRound({ playerDecl: pd, oppDecl: od, playerSheet: strong, oppSheet: weak,
        state: { momentum: 0, round: 1, playerEnergy: 100, opponentEnergy: 100, effects: [], pressure: { player: 0, opponent: 0 } },
        rules: rules212, sb: sb212, steps: steps212, rng: () => 0.5, phase: "sense" });

      const beat = run(hider, looker);
      check("CCODE-212: a strong obscure against someone who LOOKED earns the bonus action, end to end",
        beat.bonusEarned?.player === true && beat.senseBonus?.winner === "obscurer",
        JSON.stringify(beat.senseBonus ?? null));
      // ⛔ THE SIGN. `readerGap` is the PLAYER's read; for a player who HID, the reader is the opponent and
      // the gap must run the other way. Paying the bonus off the hider's own read is a sign error that
      // reads as balance — so it is gated by the case that would expose it.
      const vsGuard = run(hider, guard);
      check("CCODE-212: the same strong obscure against a guard earns NOTHING — no watcher, no win",
        vsGuard.bonusEarned?.player !== true && vsGuard.senseBonus?.opponentSensed === false,
        JSON.stringify(vsGuard.senseBonus ?? null));
    }

    // ⚠️ THE RECEIPT IS AUTHORED, and all five variants share the first clause on purpose: "You did not
    // look" is THE COST, and the player reads it every time regardless of outcome.
    const rc = ss.obscureReceipt || {};
    const variants = ["base", "wonBonus", "nullBand", "failed", "noWatcher"];
    check("CCODE-212: the obscure receipt is authored in content, all five variants, none invented in code",
      variants.every(k => rc[k]?.head && rc[k]?.body), variants.filter(k => !rc[k]?.head).join(", "));
    check("CCODE-212: every variant opens with the COST — 'You did not look' is read every time",
      variants.every(k => /^You did not look/.test(rc[k]?.head || "")),
      variants.filter(k => !/^You did not look/.test(rc[k]?.head || "")).join(", "));
  }
  // 5h · ⛔ CCODE-214 — AN AUTHORED BLOCK LIVES ON THE RANK. Found by PLAYING the Sunk Assay, not by any
  // gate: 19 `imposes` blocks and 8 `ongoingHarm` blocks are authored on `tree[]`, and both readers looked
  // at `ability.mechanic`. None of it fired, and every gate passed — because my fixtures put the block
  // where my reader looked. A gate written by the same hand as the reader tests the assumption.
  {
    const withImposes = Object.values(C199.abilities || {})
      .filter(a => (a.tree || []).some(r => r.imposes || r.mechanic?.imposes));
    check(`CCODE-214: all ${withImposes.length} rank-authored imposes blocks RESOLVE — they live on the tree, not the ability`,
      withImposes.length >= 10 && withImposes.every(a => {
        const r = (a.tree || []).find(x => x.imposes || x.mechanic?.imposes);
        return CM.resolveImposition(a, { cfg: C199.craftMechanics || {}, rank: r.rank, margin: 99 }).ok;
      }), withImposes.filter(a => {
        const r = (a.tree || []).find(x => x.imposes || x.mechanic?.imposes);
        return !CM.resolveImposition(a, { cfg: C199.craftMechanics || {}, rank: r.rank, margin: 99 }).ok;
      }).map(a => a.id).join(", "));

    // ⛔ AND IT WALKS DOWN. A craft whose r1 staggers must still stagger at r3 — an exact-rank lookup made
    // the capability DISAPPEAR ON RANK-UP, which is worse than never working and which no gate would show
    // because a gate picks the rank it tests.
    const ki = C199.abilities?.ki_wield;
    check("CCODE-214: an r1 block still holds at r3 — a capability must not vanish when its wielder improves",
      !!ki && CM.resolveImposition(ki, { cfg: C199.craftMechanics || {}, rank: 3, margin: 99 }).ok === true);

    // ⚠️ THE AMOUNT IS DERIVED. Aevi authored `{ "type": "decay" }` — the KIND, no number. Making her author
    // a second one would be asking content to repeat what `magnitude`/`dice` already say.
    const harms = Object.values(C199.abilities || {})
      .filter(a => (a.tree || []).some(r => r.ongoingHarm || r.mechanic?.ongoingHarm));
    const zero = harms.filter(a => {
      const r = (a.tree || []).find(x => x.ongoingHarm || x.mechanic?.ongoingHarm);
      const oh = CM.ongoingHarmOf(a, r.rank);
      return !oh || oh.magnitude <= 0 || !oh.type;
    });
    check(`CCODE-214: all ${harms.length} ongoingHarm blocks derive a TYPE and a real amount`,
      harms.length >= 6 && zero.length === 0, zero.map(a => a.id).join(", "));

    // ⛔ AND THE GUARD MOVED WITH THE READER. `resolveImposition` learned to read the tree; the `if (spec)`
    // in skill_battle did not, so it kept deciding there was nothing to resolve. A reader fixed in one
    // place and gated in another is still a reader nobody reaches.
    {
      const rules214 = C199.rules || {}, sb214 = rules214.skillBattle || C199.skillBattle || {};
      const steps214 = C199.resolutionSteps || rules214.resolution || {};
      const SB214 = await import("../engine/skill_battle.js");
      const kiDecl = { ...(ki || {}), function: "strike", tier: 4, attribute: "physical", intensity: "standard", rank: 2, name: "Ki Wield" };
      const frail = { attributes: { physical: 1, mental: 1, social: 1, practical: 1 }, level: 1, health: 40, maxHealth: 40, soak: 0 };
      const strong = { attributes: { physical: 8, mental: 6, social: 4, practical: 6 }, level: 10, health: 40, maxHealth: 40 };
      const r = SB214.battleRound({ playerDecl: kiDecl, oppDecl: { function: "shield", tier: 1, attribute: "physical", intensity: "conserve", name: "guard" },
        playerSheet: strong, oppSheet: frail,
        state: { momentum: 0, round: 1, playerEnergy: 100, opponentEnergy: 50, effects: [], pressure: { player: 0, opponent: 0 } },
        rules: rules214, sb: sb214, steps: steps214, rng: () => 0.5 });
      check("CCODE-214: a rank-authored imposition reaches a real round — the guard reads the tree too",
        r.imposed?.side === "opponent" && !!r.imposed.condition, JSON.stringify(r.imposed ?? null));
    }
  }
  // 5i · ⛔ CCODE-215 / SNG-522 §1 — A PROJECT IS A THING YOU COME BACK TO. The only item on either
  // queue that blocked something already built: Sunk Assay L4 could not be started, and Aevi deliberately
  // did not stub it, because a project level that resolves in a scene is the feature's opposite.
  {
    const PJ = await import("../engine/projects.js");
    const pcfg = (C199.craftMechanics || {}).projects || {};
    const bs = C199.abilities?.built_system;

    check("CCODE-215: a project craft is one that declares BOTH downtime and projectTicks",
      PJ.isProjectCraft(bs) === true
      && PJ.isProjectCraft({ downtime: true }) === false
      && PJ.isProjectCraft(C199.abilities?.ki_wield) === false);

    // ⛔ A THRESHOLD, NEVER A DATE. Nothing in the record is a day you wait for.
    const ch = { name: "gate" };
    const opened = PJ.openProject(ch, bs, { day: 3, cfg: pcfg });
    check("CCODE-215: opening banks nothing and sets a THRESHOLD, not a completion date",
      opened.ok && opened.project.banked === 0 && opened.project.threshold > 0
      && opened.project.completesOn === undefined, JSON.stringify(PJ.projectProgress(opened.project)));
    check("CCODE-215: the same craft cannot be opened twice — two of one working is a bookkeeping bug",
      PJ.openProject(ch, bs, { day: 4, cfg: pcfg }).ok === false);

    // ⚠️ MORE HANDS HELP, SUBLINEARLY. A village must not finish a year's assay in an afternoon.
    const alone = { banked: 0, threshold: 999, lastTickDay: 0, history: [], name: "a" };
    const crowd = { banked: 0, threshold: 999, lastTickDay: 0, history: [], name: "b" };
    PJ.tickProject(alone, { days: 10, hands: 1, cfg: pcfg });
    PJ.tickProject(crowd, { days: 10, hands: 9, cfg: pcfg });
    check("CCODE-215: more hands bank faster, but never nine times faster for nine hands",
      crowd.banked > alone.banked && crowd.banked < alone.banked * 9,
      `1 hand ${alone.banked} · 9 hands ${crowd.banked}`);

    // ⛔ INTERRUPTION KEEPS THE WORK; SABOTAGE TAKES IT. Conflating them would make walking away from a
    // project the same as having it wrecked.
    const p2 = PJ.openProject({ name: "x" }, bs, { day: 0, cfg: pcfg }).project;
    PJ.tickProject(p2, { days: 5, cfg: pcfg });
    const bankedBefore = p2.banked;
    PJ.interruptProject(p2, "the water rose");
    const whileOut = PJ.tickProject(p2, { days: 99, cfg: pcfg });
    check("CCODE-215: interrupted work banks nothing and LOSES nothing",
      whileOut.ok === false && p2.banked === bankedBefore);
    PJ.resumeProject(p2);
    PJ.sabotageProject(p2, 999, "the Grave-Callers");
    check("CCODE-215: sabotage takes banked work and never drives it below zero",
      p2.banked === 0);

    // ⚠️ AND IT OUTLIVES ITS OPENER — which is what lets L4 be inherited rather than restarted.
    PJ.inheritProject(p2, "Teva");
    check("CCODE-215: a project can be handed on — the owner moves, the opener is history and does not",
      p2.owner === "Teva" && p2.opener === "x");

    const fin = PJ.tickProject(p2, { days: 9999, cfg: pcfg });
    check("CCODE-215: it completes by reaching the threshold, and completing is a one-way door",
      fin.done === true && PJ.tickProject(p2, { days: 1, cfg: pcfg }).ok === false);

    check("CCODE-215: the project dials are authored in craft_mechanics.json, not hardcoded",
      Number.isFinite(Number(pcfg.ticksPerMagnitude)) && Number.isFinite(Number(pcfg.perExtraHand)),
      JSON.stringify(pcfg));
  }
  // 5j · ⛔ CCODE-216 / SNG-522 §3 — PERSIST-UNTIL-HEALED IS A DIFFERENT CLOCK, and `antisoakImposed`
  // finally has a reader. Erik's antisoak ruling left one question open — does a craft's number mean "this
  // blow benefits" or "this blow LEAVES them open"? ⚠️ AEVI ANSWERED IT BY AUTHORING: `antisoakImposed`
  // 3/5/8 across Grief Strike's ranks, the imposing reading, read by nothing.
  {
    const CD = await import("../engine/conditions.js");
    const SB216 = await import("../engine/skill_battle.js");
    const rules216 = C199.rules || {}, sb216 = rules216.skillBattle || C199.skillBattle || {};
    const steps216 = C199.resolutionSteps || rules216.resolution || {};
    const gs = C199.abilities?.grief_strike;
    const strong = { attributes: { social: 8, physical: 6, mental: 5, practical: 5 }, level: 10, health: 40, maxHealth: 40 };
    const frail = { attributes: { social: 1, physical: 1, mental: 1, practical: 1 }, level: 1, health: 40, maxHealth: 40, soak: 0 };
    const swing = (rank) => SB216.battleRound({
      playerDecl: { ...gs, function: (gs?.functions || [])[0], tier: 4, attribute: "social", intensity: "standard", rank, name: "Grief Strike" },
      oppDecl: { function: "shield", tier: 1, attribute: "physical", intensity: "conserve", name: "guard" },
      playerSheet: strong, oppSheet: frail,
      state: { momentum: 0, round: 1, playerEnergy: 100, opponentEnergy: 50, effects: [], pressure: { player: 0, opponent: 0 } },
      rules: rules216, sb: sb216, steps: steps216, rng: () => 0.5 });

    const r1 = swing(1), r3 = swing(3);
    check("CCODE-216: `antisoakImposed` reaches a real round, and it SCALES with rank (3 → 8)",
      r1.opened?.magnitude === 3 && r3.opened?.magnitude === 8,
      `r1 ${JSON.stringify(r1.opened ?? null)} · r3 ${JSON.stringify(r3.opened ?? null)}`);
    // ⛔ ON THE LOSER. Reading it off the striker as a self-buff is the other half of the ambiguity, and
    // this is the gate that says which one shipped.
    check("CCODE-216: the vulnerability lands on the one who was HIT, not the one who swung",
      r3.opened?.side === "opponent");

    // ---- the condition lifecycle ----
    const them = { name: "them" };
    CD.applyCondition(them, { id: "grief_open", ...r3.opened }, { day: 1 });
    check("CCODE-216: a carried antisoak sums to what antisoakLanded reads off the sheet",
      CD.antisoakOn(them) === 8);
    CD.applyCondition(them, { id: "grief_open", kind: "antisoak", magnitude: 2 }, { day: 2 });
    check("CCODE-216: a condition is a STATE, not a stack — being greyed twice is being greyed",
      them.conditions.length === 1 && CD.antisoakOn(them) === 8);

    // ⛔ THE RULE, IN ONE LINE: rest clears what rest can clear.
    const patient = { name: "patient", conditions: [] };
    CD.applyCondition(patient, { id: "winded", kind: "ongoingHarm", magnitude: 2 });
    CD.applyCondition(patient, { id: "grey", kind: "ongoingHarm", magnitude: 4, persistUntilHealed: true });
    const night = CD.clearOnRest(patient, { kind: "sleep" });
    check("CCODE-216: a night clears an ordinary condition",
      night.cleared.some(c => c.id === "winded"));
    // ⛔ AND THIS IS THE WHOLE FEATURE. Erik on Grey Hand: "it doesn't come back immediately upon stopping —
    // it would have to be healed/restored." No number of nights fixes a hand that has stopped working.
    check("CCODE-216: NO amount of rest clears a persist-until-healed condition — that is the different clock",
      night.persisted.some(c => c.id === "grey")
      && CD.clearOnRest(patient, { kind: "sleep" }).persisted.some(c => c.id === "grey")
      && patient.conditions.some(c => c.id === "grey"));
    check("CCODE-216: and the caller is TOLD what persisted — a rule, not a mystery",
      night.persisted.length > 0 && night.persisted.every(c => c.id));

    // ⚠️ A BREATHER IS NOT A NIGHT, or "take a breather" becomes a universal cure with a smaller number.
    const tired = { name: "tired", conditions: [] };
    CD.applyCondition(tired, { id: "winded", kind: "ongoingHarm", magnitude: 2 });
    check("CCODE-216: an hour off your feet does not clear what a night would",
      CD.clearOnRest(tired, { kind: "breather" }).cleared.length === 0 && tired.conditions.length === 1);

    // and the OTHER half of the clock
    const mended = CD.clearOnHeal(patient, ["grey"]);
    check("CCODE-216: a heal clears what rest could not — by id, because a mend answers one wrong",
      mended.cleared.some(c => c.id === "grey") && !patient.conditions.some(c => c.id === "grey"));

    // ⚠️ PERSISTENCE IS CONTAGIOUS. A lighter second application must not make a mending-only condition
    // sleep-offable again — that would be a cure by reapplying the injury.
    const twice = { name: "twice", conditions: [] };
    CD.applyCondition(twice, { id: "grey", kind: "ongoingHarm", magnitude: 4, persistUntilHealed: true });
    CD.applyCondition(twice, { id: "grey", kind: "ongoingHarm", magnitude: 1 });
    check("CCODE-216: re-applying a lighter version does not make a mending-only condition sleep-offable",
      CD.clearOnRest(twice, { kind: "sleep" }).persisted.some(c => c.id === "grey"));

    check("CCODE-216: the persist flag is read rank-first and walks down (the CCODE-214 rule)",
      CD.persistsUntilHealed({ tree: [{ rank: 1, persistUntilHealed: true }] }, 3) === true
      && CD.persistsUntilHealed({ tree: [{ rank: 1 }] }, 3) === false);
  }
  // 5k · ⛔ CCODE-218 — TWO MORE READERS AEVI'S AUTHORING NEEDED. Both were fields she added that nothing
  // consulted, and both were found by measuring after her commit rather than by any gate.
  {
    const CD218 = await import("../engine/conditions.js");
    // ⚠️ its own import - `AR` belongs to the §C3 block further down and is not in scope here. The suite
    // exits on a throw, so a stray reference does not fail ONE gate, it silently deletes every gate after
    // it: 3,974 passes became 3,923 with zero failures reported.
    const AR218 = await import("../engine/art.js");
    const doc218 = C199.visualAesthetics || {};
    const A218 = Object.values(C199.abilities || {});

    // ⛔ A BODY IS NOT A PEOPLE AND NOT A POWER SOURCE. She opened a third namespace for form kits and she
    // is right that it is a third thing — an Ent's branch-club looks like an ENT, which is neither the
    // tradition that taught it nor the physics it runs on.
    const formed = A218.filter(a => a.aestheticKey);
    check(`CCODE-218: the form kit's look reaches its grants (${formed.length} craft(s) carry an aestheticKey)`,
      formed.length >= 5 && formed.every(a => !!AR218.aestheticFor(a, doc218)),
      formed.filter(a => !AR218.aestheticFor(a, doc218)).map(a => a.id).join(", "));
    // ⚠️ AND IT WINS, because what a thing is MADE OF is a more specific claim than who taught it.
    check("CCODE-218: a form look beats a tradition look — the most specific claim wins",
      AR218.aestheticFor({ aestheticKey: "form_ent", tradition: "rootkin" }, doc218) === doc218.forms?.form_ent);

    // ⛔ HER SHAPE NAMES WHAT PERSISTS, AND IT IS BETTER THAN THE BOOLEAN I ASKED FOR.
    const persists = A218.filter(a => CD218.persistsUntilHealed(a, 3));
    check(`CCODE-218: persistUntilHealed reaches ${persists.length} crafts — Grey Hand's design is true in play`,
      persists.length >= 4 && persists.some(a => a.id === "grey_hand"),
      persists.map(a => a.id).join(", "));
    check("CCODE-218: and the condition's NAME comes with it — a receipt can say what will not close",
      CD218.persistedConditionName(C199.abilities?.grey_hand, 1) === "enfeeblement"
      && CD218.persistedConditionName(C199.abilities?.hastened_grey, 1) === "decay");
    // both shapes accepted; the bare flag still works
    check("CCODE-218: a bare `true` is still accepted — her richer shape did not break the simpler one",
      CD218.persistsUntilHealed({ tree: [{ rank: 1, persistUntilHealed: true }] }, 1) === true
      && CD218.persistedConditionName({ tree: [{ rank: 1, persistUntilHealed: true }] }, 1) === null);
  }
  // 5l · ⛔ CCODE-220 / WORK ORDER §5 — THE DRIVEN-NPC DIRECTIVE FIRES, AND HERE IS THE TRANSCRIPT.
  // Aevi asked for evidence rather than a claim: "a driven NPC visibly acts on its directive in a harness
  // run, and the 890 characters demonstrably reach the model."
  //
  // ⚠️ AND THE ANSWER IS NOT WHAT EITHER OF US ASSUMED. The trigger was never missing — `npcRegistryForGM`
  // appends the directive whenever a driven NPC is in the block. What gates it is POPULATION (7 of 111
  // have interiority) and MEETING them, which are content and play, not wiring.
  {
    const NP = await import("../engine/npcs.js");
    const inter = C199.npcInteriority || {};
    const drivenIds = Object.keys(inter.npcs || {});
    check(`CCODE-220: ${drivenIds.length} NPCs carry authored interiority`, drivenIds.length >= 5, drivenIds.join(", "));

    const who = drivenIds[0];
    const met = { name: "the player", npcRegistry: { [who]: { id: who, name: "Pell", relationship: 4, status: "active", history: ["met"], knownFacts: [], skillsObserved: [] } } };
    const block = String(NP.npcRegistryForGM(met, { locationId: null, sceneNpcNames: [], interiority: inter, rules: C199.rules }) || "");
    const head = String(inter.drivenNpcDirective || "").slice(0, 40);
    check("CCODE-220: a met driven NPC puts the DIRECTIVE in front of the model — the wire is live",
      !!head && block.includes(head) && /DRIVEN:/.test(block),
      `block ${block.length} chars`);

    // ⛔ AND AN ID-LESS ENTRY NO LONGER LOSES ITS DRIVES SILENTLY. `driveOf` reads `n.id`; the registry is
    // KEYED by id, so an entry without one produced no directive and said nothing about it. CCODE-20
    // already had to backfill missing ids, which is the evidence that they happen.
    const idless = { name: "the player", npcRegistry: { [who]: { name: "Pell", relationship: 4, status: "active", history: ["met"], knownFacts: [], skillsObserved: [] } } };
    const blockNoId = String(NP.npcRegistryForGM(idless, { locationId: null, sceneNpcNames: [], interiority: inter, rules: C199.rules }) || "");
    check("CCODE-220: an id-less registry entry still gets its drives — the key IS the id",
      blockNoId.includes(head) && /DRIVEN:/.test(blockNoId), `block ${blockNoId.length} chars`);

    // ⚠️ AND AN UNDRIVEN NPC MUST NOT DRAG THE DIRECTIVE IN. It is 890 characters of instruction; sending
    // it for a cast with no driven member is prompt budget spent on nothing.
    const plain = { name: "the player", npcRegistry: { someone: { id: "someone", name: "Someone", relationship: 1, status: "active", history: ["met"], knownFacts: [], skillsObserved: [] } } };
    const blockPlain = String(NP.npcRegistryForGM(plain, { locationId: null, sceneNpcNames: [], interiority: inter, rules: C199.rules }) || "");
    check("CCODE-220: a cast with no driven member does NOT carry the directive — 890 chars are not free",
      !blockPlain.includes(head));
  }
  // 5m · ⛔ CCODE-221 — THE GROUND CARD ANSWERS FOR 351 OF 373 CRAFTS, AND NONE OF THAT WAS GATED.
  // Reverting the pure-school fallthrough left the whole suite green, exactly as reverting the CCODE-217
  // flip did a week ago. ⚠️ Twice now the fix has been the argument and the check has been an afterthought.
  {
    const SU = await import("../engine/substrate.js");
    const ps221 = JSON.parse(readFileSync(join(root, "content/packs/core/rules/power_sources.json"), "utf8"));
    const fh221 = JSON.parse(readFileSync(join(root, "content/packs/core/rules/foothills.json"), "utf8"));
    const noSchool = { name: "a practitioner who has chosen nothing", domains: {} };
    // ⚠️ A FIXTURE THAT THE CORPUS CAN RETIRE. `valley_craft` was retired into its parents on
    // 2026-08-31, so `find(a => a.tradition === "valley_craft")` returns undefined and every check below
    // graded `craftSource(undefined)`. The claim — a FOOTHILL computes its source from its parents
    // instead of storing one — is unchanged and still worth proving; it just needs a foothill that has
    // crafts. ⛔ THE MERGER WILL RETIRE MORE OF THESE, so the gate asks rather than assumes.
    const craftIn = (t) => Object.values(C199.abilities || {}).find(a => a.tradition === t);
    // ⛔ R33 (SNG-443) RETIRED ALL OF THESE FIXTURES BY RULING, not by merger: a foothill is a place of access,
    // and since the 2026-09-02 lineage assignment NO craft carries one as its `tradition`. The computation is
    // still real — `foothills.json` authors the parents — so “live” now means AUTHORED, and the craft that
    // reaches the branch is synthetic. The corpus-level fact R33 makes true is asserted below instead.
    const liveFoothill = ["valley_craft", "harmonic", "radiant_folk"].find(t => fh221.foothills?.[t]?.parents);
    // ⛔ SPEC_body_source.md §0 — THE CRAFT'S OWN `powerSystem` NOW WINS, and every real craft has one, so a
    // real craft never reaches the tradition/foothill branches this block exists to prove. Strip the
    // declaration: the claim under test is what the TRADITION machinery answers, not what the craft declares.
    const undeclared = (a) => a && { ...a, powerSystem: undefined };
    const srcOf = (t) => SU.craftSource(undeclared(craftIn(t)) || { id: "syn_" + t, tradition: t }, noSchool, C199.schools, ps221, fh221);

    // ⛔ A PURE SCHOOL KEEPS ITS TRADITION'S SOURCE — the comment in substrate.js said so and the code
    // returned `source: school.extension` (null) and stopped. `schoolForTradition` DEFAULTS to the pure
    // school, so every practitioner who had not chosen one graded against nothing while reporting
    // `via: "school"` as though it had answered.
    check("CCODE-221: a practitioner with no chosen school still resolves their tradition's source",
      srcOf("ashwarden")?.source === "metaphysical", JSON.stringify(srcOf("ashwarden")));

    // ⛔ A FOOTHILL IS COMPUTED FROM ITS PARENTS, NEVER STORED. And harmonic is the proof: its parents
    // resolve 50/50 between the two nanite states — a tie — which resolves to `combination`, exactly what
    // its 15 crafts already carry. A computation that reproduces a value nobody derived it from.
    // ⚠️ THE TIE IS GONE AND THE GATE MUST NOT PIN IT. Aevi re-derived harmonic's blend from the craft data on
    // 2026-09-02 (mason .4 / lattice .3 / threnodist .3 — ordered .7, wild .3), so it no longer ties. Asserting
    // `combination` would assert the old numbers; asserting the value the AUTHORED WEIGHTS imply asserts the rule.
    const implied = (t) => {
      const w = {};
      for (const [p, v] of Object.entries(fh221.foothills?.[t]?.parents || {})) { const pr = ps221.byTradition?.[p]?.primary; if (pr) w[pr] = (w[pr] || 0) + Number(v); }
      const r = Object.entries(w).sort((a, b) => b[1] - a[1]);
      const alias = { ordered_nanite: "nanite", wild_nanite: "wild" };
      return r.length > 1 && r[0][1] === r[1][1] ? "combination" : (alias[r[0]?.[0]] || r[0]?.[0]);
    };
    check("CCODE-221: a foothill computes its source from its parents — the value its authored weights imply",
      !!srcOf("harmonic") && srcOf("harmonic").source === implied("harmonic") && srcOf("harmonic").via === "foothill",
      `${srcOf("harmonic")?.source} vs implied ${implied("harmonic")}`);
    // ⚠️ THE CLAIM IS `via: "foothill"` WITH A COMPUTED SOURCE — not any particular source. My first
    // repair asserted `=== "metaphysical"`, which was valley_craft's OWN answer (its parents are stillhold
    // 0.4 metaphysical, wright 0.3 precursor, rootkin 0.3 wild_nanite, so metaphysical carried the weight).
    // ⛔ HARMONIC COMPUTES `combination` AND RADIANT_FOLK COMPUTES `precursor`, and both are CORRECT.
    // Hardcoding one foothill's result is the same fixture-coupling the derivation above was meant to end —
    // I fixed the fixture and left the expected VALUE pinned to the fixture I removed.
    const fhSrc = liveFoothill ? srcOf(liveFoothill) : null;
    check(`CCODE-221: a FOOTHILL (${liveFoothill || "none live"}) resolves its ground from PARENTS rather than a stored row`,
      !!fhSrc && fhSrc.via === "foothill" && !!fhSrc.source,
      JSON.stringify(fhSrc));
    // ⛔ AND IT IS A REAL COMPUTATION, not a constant: two foothills must not be forced to agree.
    const fhAll = ["valley_craft", "harmonic", "radiant_folk"].map(t => craftIn(t) && srcOf(t)).filter(Boolean);
    check("CCODE-221: …and different foothills reach different grounds — parents actually decide it",
      new Set(fhAll.map(r => r.source)).size >= 2 || fhAll.length < 2,
      fhAll.map(r => r.source).join(", "));
    // ⛔ NON-VACUITY: if every foothill is retired this must fail rather than pass by finding nothing.
    // ⛔ NON-VACUITY, RE-AIMED: the old guard demanded a craft CARRY a foothill, which R33 forbids. What must
    // hold now is the ruling itself — no craft's lineage is a place, and the place's crafts still exist as ACCESS.
    check("CCODE-221: …R33 — no craft carries a foothill as its lineage, and the foothill's crafts carry it as `learnedAt`",
      !!liveFoothill && !Object.values(C199.abilities).some(a => fh221.foothills?.[a.tradition])
      && Object.values(C199.abilities).some(a => fh221.foothills?.[a.learnedAt]),   // valley_craft was retired into parents; harmonic and radiant_folk crafts are learnedAt
      `${Object.values(C199.abilities).filter(a => fh221.foothills?.[a.tradition]).length} carry a place as lineage`);

    // ⛔ DEFERRED IS NOT STALE. Erik deferred abyssal to its own audit; the row carries `primary: null` and
    // the card must DECLINE rather than answer from parents that are not its parents.
    check("CCODE-221: a deferred tradition declines, and says it is deferred rather than absent",
      // ⚠️ abyssal was the live case until Erik settled it (2026-09-03, primary veil); the RULE is what must hold
      (() => { const d = SU.craftSource({ id: "syn_deferred", tradition: "held_back", powerSystem: "veil" }, noSchool, C199.schools, { byTradition: { held_back: { primary: null } } }, fh221); return d?.via === "deferred" && d?.source === null; })(),
      "a synthetic `primary: null` row, with the craft declaring veil");

    // ⚠️ §2b — AN UNAUTHORED MIX IS DISTINGUISHABLE FROM A PURE ONE. Aevi's own precedent quoted back:
    // "an absent value doing double duty was the actual trap."
    check("CCODE-221: `mixAuthored` separates an unauthored mix from a pure mean",
      srcOf("ashwarden")?.mixAuthored === true && srcOf("rootkin")?.mixAuthored === false,
      `ashwarden ${srcOf("ashwarden")?.mixAuthored} · rootkin ${srcOf("rootkin")?.mixAuthored}`);

    // and the coverage the whole ticket was for
    const withTrad = Object.values(C199.abilities || {}).filter(a => a.tradition);
    const answered = withTrad.filter(a => SU.craftSource(a, noSchool, C199.schools, ps221, fh221)?.source);
    check(`CCODE-221: ${answered.length}/${withTrad.length} crafts resolve a source — may only IMPROVE`,
      answered.length >= 351, `${withTrad.length - answered.length} still unanswered`);
  }
  // 5n · ⛔ CCODE-222 — A REASON FOR THE ENGINE TO BRING SOMEONE TO YOU. CCODE-220 proved the driven-NPC
  // directive fires for a person already in the scene; nothing put them there. This is that half.
  {
    const SK = await import("../engine/seeking.js");
    const inter222 = C199.npcInteriority || {};
    const cfg222 = inter222.seeking || {};
    const driven = Object.keys(inter222.npcs || {})[0];

    // ⛔ THE GUARD THAT STOPS 111 PEOPLE KNOCKING. No authored want, no seeking — however strongly they
    // feel. Without this the seven authored people are lost in a stream of acquaintances.
    const noWant = { npcRegistry: { stranger: { id: "stranger", name: "Stranger", relationship: 9, status: "active", lastSeen: { day: 0 } } } };
    check("CCODE-222: an NPC with no authored want NEVER comes looking, whatever the relationship",
      SK.seekersAmong(noWant, { interiority: inter222, currentDay: 999, cfg: cfg222 }).length === 0);

    // ⛔ PATIENCE KEYS ON THE MAGNITUDE, NOT THE SIGN. Someone who loves you and someone who cannot stand
    // you are both impatient; a rival who wants something is the more interesting scene. Keying on the
    // signed value would make hostility a reason to stay away, which is a different game.
    check("CCODE-222: an enemy is exactly as impatient as a friend — the rate reads |relationship|",
      SK.patienceOf(-7, cfg222) === SK.patienceOf(7, cfg222)
      && SK.patienceOf(7, cfg222) < SK.patienceOf(0, cfg222));
    check("CCODE-222: nobody arrives the morning after, however strongly they feel",
      SK.patienceOf(99, cfg222) >= (cfg222.patienceFloor ?? 3));

    // ⚠️ A CLOCK, NOT A QUEUE: pressure builds while APART and empties when you meet.
    const reg = () => ({ npcRegistry: { [driven]: { id: driven, name: "Driven", relationship: 6, status: "active", lastSeen: { day: 1, locationId: "x" } } } });
    const waited = reg();
    check("CCODE-222: pressure builds while you are apart — they come looking on their own schedule",
      SK.seekersAmong(waited, { interiority: inter222, currentDay: 60, cfg: cfg222 }).length === 1);
    SK.noteSeen(waited, driven, 60);
    check("CCODE-222: and MEETING them empties the clock — that is what makes it a clock",
      SK.seekersAmong(waited, { interiority: inter222, currentDay: 60, cfg: cfg222 }).length === 0);

    // ⛔ BOUNDED. "A world where four people find you the moment you rest is not a world with
    // relationships in it, it is a notification tray."
    const crowd = { npcRegistry: {} };
    for (const id of Object.keys(inter222.npcs || {})) crowd.npcRegistry[id] = { id, name: id, relationship: 8, status: "active", lastSeen: { day: 0 } };
    check(`CCODE-222: at most ${cfg222.maxSeekers ?? 1} seeker at a time, out of ${Object.keys(crowd.npcRegistry).length} who all qualify`,
      SK.seekersAmong(crowd, { interiority: inter222, currentDay: 999, cfg: cfg222 }).length <= Math.max(1, cfg222.maxSeekers ?? 1));

    // the dead and the departed do not come looking
    const gone = { npcRegistry: { [driven]: { id: driven, name: "Gone", relationship: 8, status: "dead", lastSeen: { day: 0 } } } };
    check("CCODE-222: someone whose status is not active does not come looking",
      SK.seekersAmong(gone, { interiority: inter222, currentDay: 999, cfg: cfg222 }).length === 0);

    // ⚠️ BEING SOUGHT IS NOT BEING MET. `advanceSeeking` must not mark anyone seen, or the arrival is
    // spent without the scene ever happening.
    const untouched = reg();
    const before = JSON.stringify(untouched.npcRegistry);
    SK.advanceSeeking(untouched, { interiority: inter222, currentDay: 99, cfg: cfg222 });
    check("CCODE-222: the tick READS the registry and never marks anyone seen — being sought is not being met",
      JSON.stringify(untouched.npcRegistry) === before);

    check("CCODE-222: the seeking dials are authored in content, not hardcoded",
      Number.isFinite(Number(cfg222.patienceDays)) && Number.isFinite(Number(cfg222.patiencePerPoint)),
      JSON.stringify(cfg222).slice(0, 120));

    // ---- and it reaches the world tick's news, end to end ----
    {
      const WT = await import("../engine/worldtick.js");
      const ch222 = { name: "the player", clock: { day: 60, hour: 8 }, currentLocationId: "millbrook",
        npcRegistry: { [driven]: { id: driven, name: "Driven", relationship: -7, status: "active", lastSeen: { day: 1, locationId: "millbrook" } } } };
      ch222.worldState = WT.initWorldState(1);
      const out = await WT.runWorldTick({ character: ch222, content: C199, currentDay: 60 });
      const lines = (out.news || []).map(n => (typeof n === "string" ? n : (n.text || n.line || "")));
      check("CCODE-222: a seeker reaches the world tick's NEWS — the player is told somebody came",
        lines.some(l => /Driven/.test(l)), lines.join(" | ").slice(0, 160));
    }
  }
  // 5o · ⛔ SYSTEM_SPEC §45.1 — RANK-FIRST AUTHORING, CHECKED BOTH WAYS. The spec's table claims these
  // fields are authored on tree[] and NEVER on the ability. That claim is what makes `authoredBlock`
  // necessary; if it ever stops being true, a reader pointed at the ability starts looking correct.
  {
    const CM45 = await import("../engine/craftmechanics.js");
    const A45 = Object.values(C199.abilities || {});
    for (const [key, wantTree] of [["imposes", 14], ["ongoingHarm", 7], ["persistUntilHealed", 4]]) {
      let onTree = 0, onAbility = 0;
      for (const a of A45) {
        if (a?.mechanic?.[key] != null || a?.[key] != null) onAbility++;
        if ((a.tree || []).some(r => r?.[key] != null || r?.mechanic?.[key] != null)) onTree++;
      }
      // ⛔ THE SPEC'S NUMBER IS A FLOOR, NOT A SPELLING — authoring more is fine, losing it is not.
      check(`CCODE-223: §45.1 — \`${key}\` is authored on tree[] (${onTree}, spec floor ${wantTree})`,
        onTree >= wantTree, `tree ${onTree} / ability ${onAbility}`);
      // ⚠️ AND THE COLUMN THAT READS ZERO IS THE ONE THAT MATTERS. Non-zero here means somebody authored
      // against `authoredBlock`'s FALLBACK, and every rank-aware reader silently stops being rank-aware.
      check(`CCODE-223: §45.1 — and NOTHING authors \`${key}\` at the ability level, where a reader would find it by accident`,
        onAbility === 0, `ability-level count ${onAbility}`);
    }

    // the reader itself: a rank-authored value must beat the ability-level fallback, and must respect rank
    const probe = { mechanic: { imposes: "ability_level" },
      tree: [{ rank: 1, imposes: "r1" }, { rank: 3, imposes: "r3" }] };
    check("CCODE-223: §45.1 — authoredBlock prefers the RANK's value over the ability's",
      CM45.authoredBlock(probe, "imposes", 1) === "r1");
    check("CCODE-223: §45.1 — and takes the highest rank AT OR BELOW the character's, not the highest authored",
      CM45.authoredBlock(probe, "imposes", 2) === "r1" && CM45.authoredBlock(probe, "imposes", 3) === "r3");
    check("CCODE-223: §45.1 — falling back to the ability only when NO rank authors it",
      CM45.authoredBlock({ mechanic: { imposes: "ability_level" }, tree: [{ rank: 1 }] }, "imposes", 3) === "ability_level");

    // ⚠️ §45.6 — healing keys off the VERB, not off a field. I measured this the wrong way while writing
    // the spec and nearly recorded "no content uses healing" as fact.
    const healFns45 = new Set((C199.skillBattleSystem?.engine?.damage?.healFunctions) || ["heal", "mend", "restore"]);
    const menders = A45.filter(a => (a.functions || []).some(f => healFns45.has(String(f).toLowerCase()))).length;
    check(`CCODE-223: §45.6 — healing is authored as a VERB and ${menders} crafts carry one (a \`heal\` FIELD would find zero)`,
      menders > 0, `${menders} crafts`);
  }

  // 5p · ⛔ CCODE-224 (Erik's backlog 1) — THE CREATE SCREEN DRAWS THE REAL WHEEL, and the rule deciding
  // what a player may pick is one function shared by the wheel and the list under it.
  {
    const WG = await import("../engine/wheelgeom.js");
    const TR = await import("../engine/traditions.js");
    const cat224 = C199.abilities || {};
    const idx224 = C199.traditionIndex;
    const dom224 = { primary: (idx224?.stations || [])[0]?.traditionId || "death", secondary: null, tertiary: null };
    const opts224 = { domains: dom224, traditionIndex: idx224, domainAccess: TR.domainAccess };
    const pool = WG.creationPool(cat224, opts224);

    check(`CCODE-224: creation offers a non-empty pool from one shared rule (${pool.length} crafts for ${dom224.primary})`,
      pool.length > 0, `${pool.length}`);

    // ⛔ DEPTH IS EARNED IN PLAY, NEVER BOUGHT AT CREATION. The wheel DRAWS rank 2+ (that is the point —
    // the spoke running out to its capstone), so the rule is the only thing stopping them being clickable.
    check("CCODE-224: nothing above rank 1 is pickable at creation, however the wheel paints it",
      pool.every(a => (a.levelReq || 1) === 1), pool.filter(a => (a.levelReq || 1) > 1).map(a => a.id).slice(0, 3).join(","));

    // ⚠️ A PICK SPENT ON A CRAFT YOU ALREADY GET FREE IS A WASTED PICK (SNG-192 §1).
    const someId = pool[0]?.id;
    check("CCODE-224: a granted craft is removed from the pool, so no pick is ever wasted on one",
      someId ? !WG.creationPool(cat224, { ...opts224, grantIds: [someId] }).some(a => a.id === someId) : false);
    check("CCODE-224: …and the grant list is accepted as a Set as well as an array (app.js passes a Set)",
      someId ? !WG.creationPool(cat224, { ...opts224, grantIds: new Set([someId]) }).some(a => a.id === someId) : false);

    // ⛔ THE POOL IS THE DOMAIN'S, NOT A CONSTANT. Different people, different wheel.
    const other = (idx224?.stations || []).map(s => s.traditionId).find(t => t !== dom224.primary);
    const poolB = WG.creationPool(cat224, { ...opts224, domains: { primary: other } });
    // ⛔ CCODE-339b CHANGED WHAT THIS CAN CLAIM. Erik opened the antipode’s L1 crafts at creation, so the
    // rank-1 POOL is now identical whoever you are — nothing is refused. ⚠️ THAT IS A REAL CONSEQUENCE AND
    // IT IS REPORTED RATHER THAN HIDDEN: your people no longer decides WHICH first crafts you may take.
    //
    // ✅ WHAT IT STILL DECIDES IS THE BAND — cost, and whether you can cast the thing at all. So the claim
    // moves from "a different pool" to "a different READING of the same pool", which is what the wheel paints.
    const bandsA = pool.map(a => TR.domainAccess(a, 1, dom224, idx224).band).join(",");
    const bandsB = poolB.map(a => TR.domainAccess(a, 1, { primary: other }, idx224).band).join(",");
    check(`CCODE-224: a different primary reads the same pool DIFFERENTLY (${dom224.primary} vs ${other})`,
      bandsA !== bandsB, "bands identical — the domain choice would mean nothing at creation");

    // ⚠️ EVERY CRAFT OFFERED IS ACTUALLY ALLOWED BY THE BAND RULE — the rule must not have drifted into
    // "level 1 and not granted", which would offer the whole rank-1 corpus regardless of who you are.
    check("CCODE-224: every craft offered passes domainAccess for those domains — the band rule is really applied",
      pool.every(a => TR.domainAccess(a, 1, dom224, idx224).allowed === true));
    // ⚠️ 2026-09-05 — THE ENGINE'S OWN READER, ON BOTH SIDES. This counted `levelReq === 1` while the pool
    // bounds by `abilityTier` (`tier ?? levelReq`). The two readings coincide only while every record agrees
    // with itself, so the day three crafts landed carrying a `tier` that differs from their `levelReq`, this
    // check fired at the POOL for a disagreement in the CONTENT. A guard that asserts an identity between two
    // readings of one fact is measuring the corpus's self-consistency and calling it an engine defect.
    const { abilityTier: tier224 } = await import("../engine/skilltree.js");
    const rank1All = Object.values(cat224).filter(a => tier224(a) === 1).length;
    // ⛔ THE POOL STOPPED BEING A FILTER, DELIBERATELY. This asserted `pool.length < rank1All` — that
    // creation refuses something. Under CCODE-339b it refuses NOTHING at rank 1, and asserting otherwise
    // would re-impose the wall Erik just removed.
    // ⚠️ THE GUARD THAT REPLACES IT: the pool must still be BOUNDED BY RANK, or "offer everything" would
    // quietly start offering capstones at creation.
    check(`CCODE-224: every rank-1 craft is offered (${pool.length} of ${rank1All}) — the antipode included`,
      pool.length === rank1All, `${pool.length}/${rank1All}`);
    check("CCODE-224: …and NOTHING above rank 1 is, whatever the domains say",
      pool.every(a => tier224(a) === 1));
    // ⛔ AND THE QUESTION THE OLD CHECK WAS ACCIDENTALLY ASKING, ASKED ON PURPOSE. `tier` and `levelReq` carry
    // ONE fact — how deep a craft is — and a record that answers it twice can answer it two ways. Three do,
    // all landed 2026-09-05 with the bond grants. ⚠️ WHICH NUMBER IS RIGHT IS AUTHORING, NOT ENGINEERING:
    // `scholars_margin` and `the_taking_root` read levelReq 1 / tier 2, `the_old_procedure` levelReq 2 / tier 3.
    // The engine believes `tier`, so today those three are one rung deeper than their own levelReq claims.
    // ⚑ A RATCHET, NOT A WALL — it may only go DOWN, so the three are visible until they are reconciled and
    // a fourth cannot arrive unnoticed.
    const TIER_LEVELREQ_SPLIT = 3;   // 2026-09-05: scholars_margin · the_taking_root · the_old_procedure
    const split224 = Object.values(cat224).filter(a => a.tier != null && a.levelReq != null && Number(a.tier) !== Number(a.levelReq));
    check(`CCODE-224: ⚠️ ratchet — crafts whose \`tier\` and \`levelReq\` disagree = ${split224.length} (baseline ${TIER_LEVELREQ_SPLIT}) — may only go DOWN`,
      split224.length <= TIER_LEVELREQ_SPLIT,
      split224.map(a => `${a.id} tier=${a.tier}/levelReq=${a.levelReq}`).join(" · "));

    // ⛔ AND THE TWO SURFACES ARE HELD TO IT BY SOURCE: app.js must not grow a second copy of the rule.
    const appSrc224 = readFileSync(join(root, "app.js"), "utf8");
    check("CCODE-224: app.js's creation pool DELEGATES to wheelgeom rather than re-implementing the filter",
      /function creationChoosable[\s\S]{0,600}?creationPool\(/.test(appSrc224));
    check("CCODE-224: the wheel and the list both pick through ONE toggle, so max-picks cannot be enforced on only one",
      /const togglePick = \(id\)[\s\S]{0,400}?data-ab[\s\S]{0,200}?togglePick\(b\.dataset\.ab\)[\s\S]{0,200}?togglePick\(g\.dataset\.cwnode\)/.test(appSrc224));
    check("CCODE-224: the create wheel emits NO hit target for a craft it will not accept (CCODE-196: absent-looking must be absent)",
      /const hit = open \? `<circle class="hit"/.test(appSrc224));
    check("CCODE-224: …and a GRANTED craft gets no hit target either — it reads as clickable and has no handler (CCODE-196 inverted)",
      /const hit = open \?/.test(appSrc224) && !/\(open \|\| granted\) \? `<circle class="hit"/.test(appSrc224));
    // ⛔ THE MEASUREMENT THAT CHANGED THE DESIGN. 150 of 155 rank-1 crafts are offered to ANY people —
    // only the antipode is refused — so a binary open/shut wheel is 150 identical bright dots and the
    // primary spoke means nothing. The wheel paints the BAND instead, and the create copy had to be
    // corrected: it enumerated "primary, kin, secondary, tertiary, folk" as the whole pool, and 101 far-band
    // crafts were being offered outside that list.
    {
      const closed224 = Object.values(cat224).filter(a => (a.levelReq || 1) === 1
        && TR.domainAccess(a, 1, dom224, idx224).band === "antipode");   // ⚠️ CCODE-339 renamed the band: it is no longer CLOSED, it is uncastable
      // ⛔ THIS GATE'S ORIGINAL WARNING CAME TRUE, AND IT WAS RIGHT TO WORRY. It read: "the thing that
      // makes that safe is that they cannot be CAST — if this ever passes with `castable !== false`, a
      // character can begin able to use both ends of their axis and the wheel stops meaning anything."
      //
      // ⚠️ R16 MADE THEM CASTABLE. And the warning was live: `lean` is a RATIO, so a level-1 character
      // holding one home craft and one antipode craft measured as PERFECTLY BALANCED — lean 0, the
      // primary's own ceiling in their far pole, at character creation.
      //
      // ✅ THE SAFETY IS NOW `minAxisWeight`, NOT UNCASTABILITY. Below an authored floor of total axis
      // weight the character is a novice there and the far pole stays far. THAT is what this gate must
      // defend now — the property, not the mechanism that used to provide it.
      check(`CCODE-224: the antipode’s rank-1 crafts ARE offered (${closed224.length}) — and are castable under R16`,
        closed224.length > 0
        && closed224.every(a => pool.some(x => x.id === a.id))
        && closed224.every(a => TR.domainAccess(a, 1, dom224, idx224).castable !== false),
        `${closed224.length} antipode crafts`);
      const far224 = pool.filter(a => TR.domainAccess(a, 1, dom224, idx224).band === "far").length;
      check(`CCODE-224: …and ${far224} FAR-band crafts ARE offered, so the wheel must paint the band or say nothing`,
        far224 > 0 && far224 > pool.length / 3, `${far224} far of ${pool.length}`);
      check("CCODE-224: the create copy no longer enumerates a whitelist the rule does not enforce",
        !/The far pole of what you are isn't here/.test(appSrc224) && /antipode<\/strong> isn't here/.test(appSrc224));
      check("CCODE-224: the wheel classes a far craft as pickable-but-far, never as barred",
        /near \? "open near" : "open far"/.test(appSrc224));
    }

    // ⚠️ FOUND BY WALKING THE SCREEN, NOT BY READING IT: the domain step's button said "Next: your
    // companion" and its handler calls renderAbilityStep. Two steps early, and no gate could see it because
    // both halves were individually correct.
    check("CCODE-224: the domain step's button names the step it actually opens (it promised the companion and opened the crafts)",
      /id="dom-done"[\s\S]{0,200}?Next: what have you learned/.test(appSrc224)
      && /dom-done"\)\.onclick[\s\S]{0,200}?renderAbilityStep\(\)/.test(appSrc224));

    check("CCODE-224: the create screen and the level-up screen share ONE wheel model (buildWheelModel takes the sheet)",
      /function buildWheelModel\(sheet = character\)/.test(appSrc224) && /buildWheelModel\(creationSheet\(state\)\)/.test(appSrc224));
  }

  // 5q · ⛔ CCODE-227 (Erik backlog 7, step 1) — conditions.js CAN NOW FIRE IN PLAY. It shipped green with
  // six exports reachable only from this file: a rest cleared nothing, because the module that decides what
  // a rest clears was imported by nothing. ⚠️ EVERY GATE IT ALREADY HAD STILL PASSED — they tested the
  // function, and nothing tested that anything calls it. That is the whole shape of Erik's backlog item 7.
  {
    const appSrc227 = readFileSync(join(root, "app.js"), "utf8");
    check("CCODE-227: app.js IMPORTS conditions.js — the module is no longer reachable only from a test",
      /import \{[^}]*clearOnRest[^}]*\} from "\.\/engine\/conditions\.js"/.test(appSrc227));
    check("CCODE-227: …and `rest()` actually CALLS it, on both the night and the breather",
      (appSrc227.match(/clearOnRest\(character, \{ kind: "(sleep|breather)" \}\)/g) || []).length === 2,
      (appSrc227.match(/clearOnRest\(character, \{ kind: "\w+" \}\)/g) || []).join(" | "));
    // ⛔ AND THE PLAYER IS TOLD. `persisted` exists so waking up still broken is a rule and not a mystery;
    // wiring the call without surfacing the answer would be wiring half of it.
    check("CCODE-227: what a rest could NOT lift reaches the player, and the GM is told to narrate it",
      /conditionAside\(rested/.test(appSrc227) && /persistNote/.test(appSrc227)
      && /will not lift until it is healed/.test(appSrc227));

    // the behaviour itself, through the real module
    const CD = await import("../engine/conditions.js");
    const mk = () => ({ conditions: [
      { id: "winded", name: "Winded", kind: "momentary" },
      { id: "gash", name: "Gash", persistUntilHealed: true },
      { id: "shaken", name: "Shaken" } ] });
    const night = mk(); const rn = CD.clearOnRest(night, { kind: "sleep" });
    // ⛔ AND THE PLAYER CAN SEE WHAT THEY CARRY. A condition on the sheet that never reaches the screen
    // is the same failure as one that never lands — and I shipped exactly that for one commit, importing
    // `activeConditions` and calling it nowhere, inside a change about stranded code.
    check("CCODE-227b: the character screen SHOWS standing conditions, and marks the ones a night will not lift",
      /activeConditions\(character\)/.test(appSrc227) && /What you are carrying/.test(appSrc227)
      && /will not lift with rest/.test(appSrc227));

    check("CCODE-227: a night lifts what a night can and leaves persist-until-healed standing",
      rn.cleared.length === 2 && rn.persisted.length === 1 && rn.persisted[0].id === "gash");
    const breather = mk(); const rb = CD.clearOnRest(breather, { kind: "breather" });
    check("CCODE-227: an hour off your feet lifts ONLY the momentary — a breather is not a night",
      rb.cleared.length === 1 && rb.cleared[0].id === "winded" && rb.persisted.length === 2);
  }

  // 5r · ⛔ CCODE-228 — THE SEAM THAT HAS EATEN EIGHT VALUES, GATED BY DERIVATION.
  //
  // `encounters.js::skillBattleRound` hand-builds its return from `battleRound`'s. Its own comment records
  // that it silently dropped `effects`, `pressure`, `phase` and `health` — four separate bugs, four separate
  // fixes, each one adding a key to the list. `imposed`, `inflicted`, `opened` and `deniedAct` were the next
  // four, and the last of those meant NOTHING in the game ever wrote `character.conditions`.
  //
  // ⚠️ ADDING FOUR MORE NAMES TO THE LIST WOULD BE THE FIFTH FIX OF THE SAME SHAPE. This gate DERIVES the
  // expectation from what `battleRound` actually returns on a live round, so key nine cannot ship green.
  {
    const SB228 = await import("../engine/skill_battle.js");
    const sheet228 = (name) => ({ name, level: 5, health: 20, maxHealth: 20, energy: 40, maxEnergy: 40,
      attributes: { physical: 5, mental: 4, social: 3, practical: 3 }, subAttributes: {}, alignment: {}, skills: [] });
    const decl228 = { name: "Strike", function: "strike", intensity: "standard", tier: 1 };

    // ⚠️ DERIVED FROM MANY ROUNDS, AND THE DERIVATION ITSELF IS GATED. Two earlier versions of this check
    // were wrong in opposite directions and I am leaving both on the record: reading keys off ONE live round
    // missed conditional ones (dropping `senseTier` did not go red), and parsing the source literal for
    // depth-1 names found ZERO keys and passed vacuously — "none dropped" out of nothing at all.
    // ⛔ SO THE FLOOR BELOW IS THE POINT: a derived gate that can find nothing must fail, not pass. Every
    // derived check in this file should carry one.
    const roundKeys = new Set(); const thrown228 = [];
    for (const phase of ["action", "sense"]) {
      for (const fn of ["strike", "obscure", "sense", "mend"]) {
        try {
          const r228 = SB228.battleRound({
            playerDecl: { ...decl228, function: fn }, oppDecl: { ...decl228, name: "Swing" },
            playerSheet: sheet228("you"), oppSheet: sheet228("them"), phase,
            state: { momentum: 0, round: 1, playerEnergy: 40, opponentEnergy: 40, opponentHealth: 20, effects: [], pressure: { player: 0, opponent: 0 } },
            rules: C199.rules, sb: C199.skillBattle?.engine || C199.skillBattle, rng: () => 0.5, kind: "fight"
          });
          for (const k of Object.keys(r228)) roundKeys.add(k);
        } catch (e) { thrown228.push(`${phase}/${fn}: ${e.message.slice(0, 60)}`); }
      }
    }
    const OWNED = new Set(["state", "delta", "resolved", "opponentHealth", "player", "opponent", "landed", "degraded"]);
    const wanted = [...roundKeys].filter(k => !OWNED.has(k));
    check(`CCODE-228: the seam gate is not vacuous — ${wanted.length} forwardable keys observed across 8 round shapes`,
      wanted.length >= 12, `only ${wanted.length} — the derivation broke; fix it rather than lowering the floor${thrown228.length ? " · threw: " + thrown228[0] : ""}`);
    const wrapSrc = readFileSync(join(root, "engine/encounters.js"), "utf8");
    const retLine = wrapSrc.slice(wrapSrc.indexOf("return { state: s, player: r.player"));
    const forwarded = new Set([...retLine.slice(0, retLine.indexOf("};")).matchAll(/(\w+):\s*r\.(\w+)/g)].map(m => m[2]));
    const dropped = wanted.filter(k => !forwarded.has(k));
    check(`CCODE-228: skillBattleRound forwards EVERY key battleRound produces — ${wanted.length} keys, none dropped`,
      dropped.length === 0, dropped.length ? `DROPPED: ${dropped.join(", ")} — add them to the wrapper's return` : "");

    // and the four that were actually missing, by name, so the regression is legible
    for (const k of ["imposed", "inflicted", "opened", "deniedAct"]) {
      check(`CCODE-228: \`${k}\` survives the wrapper (it did not, and that is why nothing imposed anything)`,
        forwarded.has(k));
    }

    // ⛔ AND THE OTHER HALF: something has to APPLY it. Forwarding a value nobody consumes is the same bug
    // one step later — which is exactly how conditions.js shipped green with six dead exports.
    const appSrc228 = readFileSync(join(root, "app.js"), "utf8") + "\n" + readFileSync(join(root, "engine/battle_turn.js"), "utf8");   // §71
    check("CCODE-228: sbDeclare CONSUMES rr.imposed and writes a condition to the sheet",
      /if \(rr\.imposed && !rr\.imposed\.refused\)/.test(appSrc228) && /applyCondition\(character, cond\)/.test(appSrc228));
    check("CCODE-228: a PLAYER-side imposition goes on the SHEET (it outlives the fight); an OPPONENT-side one rides the encounter",
      /side === "player"\) applyCondition\(character/.test(appSrc228) && /rr\.state\.opponentConditions/.test(appSrc228));
    check("CCODE-228: a REFUSED imposition writes nothing — `refused` is a reason, not an effect",
      /!rr\.imposed\.refused/.test(appSrc228));
  }

  // 5s · ⛔ CCODE-229 (Aevi's §3) — THE FILES AND THE GAME MUST BE RECONCILED BY THE LOADER'S OWN MERGE.
  {
    const ST = await import("../engine/state.js");
    const fgtDoc = JSON.parse(readFileSync(join(root, "content/packs/core/rules/first_gift_template.json"), "utf8"));
    const cohort = fgtDoc.cohort || [];
    check(`CCODE-229: the loader's template merge is EXPORTED, not copied (${cohort.length}-craft cohort)`,
      typeof ST.applyFirstGiftTemplate === "function" && cohort.length > 0);

    // ⛔ THE PHANTOM, REPRODUCED: on disk these crafts have no mechanic; in the game they do.
    const raw = {};
    for (const f of readdirSync(join(root, "content/packs/core/abilities")).filter(x => x.endsWith(".json")))
      for (const a of (JSON.parse(readFileSync(join(root, "content/packs/core/abilities", f), "utf8")).abilities || []))
        raw[a.id] = { ...a };
    const bareOnDisk = cohort.filter(id => raw[id] && !(raw[id].mechanic && Object.keys(raw[id].mechanic).length));
    check(`CCODE-229: ${bareOnDisk.length} cohort crafts carry NO mechanic on disk — a file-walking gate calls these unauthored`,
      bareOnDisk.length > 0, bareOnDisk.slice(0, 4).join(", "));
    check("CCODE-229: …and after the loader's merge every one of them is authored — the defect was the reader",
      (() => { ST.applyFirstGiftTemplate(raw, fgtDoc);
        return bareOnDisk.every(id => raw[id].mechanic && Object.keys(raw[id].mechanic).length); })());

    // ⚠️ AND THE MERGE FILLS GAPS WITHOUT EATING AUTHORED CONTENT — the rule that makes it safe to apply
    // everywhere. An authored magnitude must survive a templated duration (shallow merge, entry wins).
    const probe = { x: { id: "x", mechanic: { magnitude: 9 } } };
    ST.applyFirstGiftTemplate(probe, { cohort: ["x"], template: { mechanic: { magnitude: 3, duration: 1 }, shape: "setup" } });
    check("CCODE-229: the template FILLS gaps and never overwrites — authored magnitude 9 survives, duration is filled",
      probe.x.mechanic.magnitude === 9 && probe.x.mechanic.duration === 1 && probe.x.shape === "setup");

    // and the gate that was reading a regression now reconciles
    const ciSrc = readFileSync(join(root, "tests/content_ci.mjs"), "utf8");
    check("CCODE-229: content_ci imports the loader's merge rather than reimplementing it (there were already two copies)",
      /import \{ applyFirstGiftTemplate \} from "\.\.\/engine\/state\.js"/.test(ciSrc)
      && /applyFirstGiftTemplate\(byId,/.test(ciSrc));
  }

  // 5t · ⛔ CCODE-230 (Aevi's §1) — GATE THE FACT, REPORT THE GUESS, AND NEVER THE REVERSE.
  {
    let undeclared230 = 0, r2plus230 = 0;
    for (const a of Object.values(C199.abilities || {}))
      for (const r of (a.tree || [])) {
        if (Number(r.rank) < 2) continue;
        r2plus230++;
        if (!((r.gainAxes || []).length)) undeclared230++;
      }
    // ⚠️ THE UNIT IS IN THE GATE'S OWN NAME. Ranks, not crafts; rank ≥ 2; the LOADED catalogue, not the
    // files — on disk this reads 227, because `first_gift_template` supplies `gainAxes` to its cohort at
    // load. Aevi measured 227 and I measured 177 and neither of us was wrong; nobody had said which.
    const AXIS_BASELINE = 177;
    check(`CCODE-230: ranks (r≥2, LOADED catalogue) declaring no gain axis = ${undeclared230} of ${r2plus230} (baseline ${AXIS_BASELINE}) — may only go DOWN`,
      undeclared230 <= AXIS_BASELINE,
      "a rank lost its gain axis, or a new rank shipped without one — the worklist may only shrink");

    // ⛔ AND THE NON-VACUITY FLOOR, the lesson from CCODE-228: a derived count that can silently become
    // zero passes forever. If this catalogue ever has no r2+ ranks at all, something is very wrong.
    check(`CCODE-230: …and the measurement is not vacuous — ${r2plus230} ranks at r≥2 were examined`,
      r2plus230 > 300, `only ${r2plus230}`);

    // ⚠️ THE PROSE CHECK IS A REPORT AND THE BUILD MUST NOT BE ABLE TO TURN IT INTO A GATE. Aevi: "a regex
    // gate teaches the author to satisfy the regex… and the PROSE may be the thing that is wrong."
    const wlSrc = readFileSync(join(root, "scripts/axis_worklist.mjs"), "utf8");
    check("CCODE-230: the prose-vs-declaration finding is REPORT ONLY — it writes a file and asserts nothing",
      /REPORT ONLY\. THIS IS NOT A GATE/.test(wlSrc) && !/\bcheck\(|\bassert\(|process\.exit\(1\)/.test(wlSrc));
    check("CCODE-230: the worklist declares its UNIT in the header (ranks · r≥2 · loaded, not files)",
      /UNIT: RANKS \(not crafts\), at rank ≥ 2, over the LOADED CATALOGUE/.test(wlSrc));
    check("CCODE-230: …and flags `rankDeltas` so the mechanical/judgement split falls out rather than being guessed",
      /hasDeltas/.test(wlSrc) && /near-mechanical/i.test(wlSrc));
  }

  // 5u · ⛔ CCODE-233 (Aevi's §2 #4) — foothills WAS REGISTERED, WIRED, AND NEVER LOADED.
  //
  // `craftSource` has had a foothill branch since the source reconciliation, and it reads
  // `foothills?.foothills?.[tid]`. Nothing loaded the file and `groundRow` never passed it, so the
  // argument was null on every call IN PLAY. The branch ran only in tests, which hand the data in
  // directly — a live rule with a dead caller, passing its own gates the whole time.
  //
  // ⚠️ SO THE GATE HAS TO CHECK THE CALLER, not the rule. Testing `craftSource(…, foothills)` proves
  // nothing about a game that never passes one — which is exactly how this survived.
  {
    const SUB233 = await import("../engine/substrate.js");
    check(`CCODE-233: the loader exposes CONTENT.foothills (${Object.keys(C199.foothills?.foothills || {}).length} foothill traditions)`,
      Object.keys(C199.foothills?.foothills || {}).length > 0);
    const appSrc233 = readFileSync(join(root, "app.js"), "utf8");
    check("CCODE-233: …and the ground card PASSES it — the rule had a live gate and a dead caller",
      /foothills: CONTENT\.foothills/.test(appSrc233));

    // what it is worth, measured both ways so the claim is a number and not an adjective
    const ch233 = { domains: { primary: "harmonic" }, abilities: [], attributes: {} };
    // ⚠️ R33 + SPEC_body_source §0: no real craft carries a foothill as its tradition, and every real craft
    // answers via its own `powerSystem` before any tradition branch — so the gap is measured on one
    // declaration-less craft per AUTHORED foothill, which is the only shape that can still reach the branch.
    const footCrafts = Object.keys(C199.foothills?.foothills || {}).map(t => ({ id: "syn_" + t, tradition: t }));
    const resolves = (foot) => footCrafts.filter(a =>
      SUB233.craftSource(a, ch233, C199.schools, C199.powerSources, foot)?.source).length;
    const without = resolves(null), withF = resolves(C199.foothills);
    check(`CCODE-233: passing the foothills answers ${withF - without} more crafts (${without} → ${withF}) — that gap was the bug`,
      without === 0 && withF > without, `${without} → ${withF} of ${footCrafts.length} authored foothills`);

    // ⛔ AND THE HARMONIC TIE, which is the rule's whole reason for existing: two parents at 50/50 resolve
    // to `combination` rather than picking a winner. It has never once run in play until now.
    const harmonicCraft = footCrafts.find(a =>
      SUB233.craftSource(a, ch233, C199.schools, C199.powerSources, C199.foothills)?.via === "foothill");
    check("CCODE-233: a foothill craft now answers VIA the foothill rule in the same call the game makes",
      !!harmonicCraft, harmonicCraft ? harmonicCraft.id : "none resolved via foothill");
  }

  // 5v · ⛔ CCODE-234 / §3 — THE PURSE. Six acceptance criteria, and five of them exist because a purse of
  // five integers would be WRONG: it loses scrip's Reach key, marks' indivisibility and paper's drift.
  {
    const PU = await import("../engine/purse.js");
    const ec234 = C199.rules?.economy;
    check(`CCODE-234: the economy is loaded and authors its currencies (${(ec234?.currencies || []).length})`,
      (ec234?.currencies || []).length === 5);

    // 1 · hold, gain and spend each of the five
    const ch = { name: "t" };
    const gained = ["crystal", "coin", "paper", "marks"].map(c => PU.credit(ch, c, 10, { origin: "found" }).ok);
    gained.push(PU.credit(ch, "scrip", 10, { origin: "traded", regionId: "ashlands" }).ok);
    check("CCODE-234 §1: a character holds, gains and spends each of the five", gained.every(Boolean)
      && PU.debit(ch, "crystal", 4).ok && PU.held(ch.purse, "crystal") === 6);

    // 2 · ⛔ SCRIP DOES NOT TRAVEL, AND THE REFUSAL IS LEGIBLE — not a silent zero
    const wrong = PU.canSpendHere(ch.purse, "scrip", "the_fen");
    check("CCODE-234 §2: scrip earned in one Reach cannot be spent in another",
      wrong.ok === false && wrong.wrongReach === true);
    check("CCODE-234 §2: …and the refusal NAMES where it is good — a silent zero is not a refusal",
      /ashlands/.test(wrong.why) && /the_fen/.test(wrong.why), wrong.why);
    // ⚠️ "how much scrip do you have" has no answer without a Reach. Returning 0 would be a lie.
    check("CCODE-234 §2: asking for scrip with no Reach returns null, not zero",
      PU.held(ch.purse, "scrip") === null && PU.held(ch.purse, "scrip", "ashlands") === 10);

    // 3 · ⛔ NO OPERATION PRODUCES A FRACTIONAL MARK
    const frac = [PU.credit(ch, "marks", 2.5, { origin: "paid" }), PU.debit(ch, "marks", 0.5)];
    check("CCODE-234 §3: no operation produces a fractional mark", frac.every(r => !r.ok && r.indivisible));
    const conv = PU.convert(1, "crystal", "marks", { economy: ec234 });
    check("CCODE-234 §3: …and the rule survives CONVERSION — a fraction of a mark is nothing, never 0.5",
      !conv.ok || Number.isInteger(conv.amountOut));

    // 4 · ⚠️ PAPER CARRIES ISSUER RISK: the same notes are worth less after the world moves
    const pc = { name: "p" }; PU.credit(pc, "paper", 20, { origin: "traded" });
    const w0 = PU.worthOf(pc.purse, ec234, {});
    const w1 = PU.worthOf(pc.purse, ec234, { worldState: { economy: { paperValue: 1.5 } } });
    check(`CCODE-234 §4: paper held across an issuer move reflects the NEW value (${w0.totalInCrystal} → ${w1.totalInCrystal} crystal, same 20 notes)`,
      w1.totalInCrystal < w0.totalInCrystal);
    // ⛔ WHICH ONLY WORKS BECAUSE THE PURSE STORES NOTES AND NOT WORTH. A cached worth would freeze paper
    // at the rate it was earned and defeat the one currency whose character is that it can betray you.
    check("CCODE-234 §4: …because the purse stores COUNTS — worth is computed, never stored",
      typeof pc.purse.paper === "number" && !("worth" in pc.purse) && !("value" in pc.purse));

    // 5 · ⛔ NO PATH MINTS A COIN
    const mints = ["minted", "created", null, "spawned"].map(o => PU.credit({ name: "m" }, "coin", 1, { origin: o }));
    check("CCODE-234 §5: no path mints a coin — a credit with no honest provenance is refused",
      mints.every(r => !r.ok && r.unmintable));
    check("CCODE-234 §5: …but coin can still be FOUND or taken in trade — fixed supply, not frozen",
      PU.credit({ name: "f" }, "coin", 1, { origin: "found" }).ok
      && PU.credit({ name: "f2" }, "coin", 1, { origin: "traded" }).ok);
    // ⚠️ and the rule is scoped: crystal is not fixed-supply and must not inherit the refusal
    check("CCODE-234 §5: …and the rule is COIN's alone — crystal takes any honest origin",
      PU.credit({ name: "c" }, "crystal", 1, { origin: "reward" }).ok);

    // 6 · conversion math is inspectable, and reproduces the AUTHORED worked example
    const wx = PU.convert(20, "coin", "crystal", { economy: ec234 });
    check(`CCODE-234 §6: conversion reproduces economy.json's own worked example — 20 coin → 10 shards (got ${wx.amountOut})`,
      wx.ok && wx.amountOut === 10, wx.math);
    check("CCODE-234 §6: …and every term is returned, so a player can see the bite rather than be told it",
      wx.baseValueIn === 6 && wx.baseValueOut === 10 && wx.spread === 0.15 && /20 × \(6\/10\)/.test(wx.math));
  }

  // 5w · ⛔ CCODE-235 / §4 — THE EXCHANGE, WHICH IS NOT A SHOP. `economy.json`: "There is no shop screen
  // and there should not be one… the price model exists so the GM has a number to be honest about, not so
  // a UI can render a catalogue." So this gates a TRANSACTION PRIMITIVE, and one of the gates is that no
  // screen, catalogue or open-trade state came with it.
  {
    const PU = await import("../engine/purse.js");
    const EC = await import("../engine/economy.js");
    const ec235 = C199.rules?.economy;
    const item235 = Object.values(C199.items)[0];
    const line = EC.priceLine(item235, "the_crossing", { economy: ec235 });

    const ch = { name: "t", inventory: [] };
    PU.credit(ch, "crystal", 50, { origin: "found" });
    const before = PU.held(ch.purse, "crystal");
    const r = PU.settleExchange(ch, { price: line.price, economy: ec235, regionId: "the_crossing", take: [item235] });
    check(`CCODE-235 §4: goods move and the purse moves BY THE SAME NUMBER priceLine showed (${line.price})`,
      r.ok && r.paid === line.price && before - PU.held(ch.purse, "crystal") === line.price
      && ch.inventory.length === 1, JSON.stringify({ paid: r.paid, quoted: line.price }));

    // ⛔ ERIK'S RULING: the deal RESOLVES AND CLOSES. "the price is paid and the goods exchanged, even if
    // those goods are a month's worth of work" — so a month's labour is GIVEN at the deal, not tracked.
    check("CCODE-235 §4: the transaction leaves NO open state behind it — nothing escrowed, nothing owed",
      r.open === false && !Object.keys(ch).some(k => /trade|escrow|owed|pending|contract/i.test(k)));
    // ⚠️ STRIPPED OF COMMENTS FIRST. My first version of this matched its own explanatory comment — the
    // file says "nothing is escrowed" and "there is deliberately no `openTrades`", so the gate reported the
    // words it was looking for and went red on a correct file. A scanner reading its own prose is a failure
    // I catalogued twice this month and then committed a third time, here.
    const purseCode = readFileSync(join(root, "engine/purse.js"), "utf8")
      .replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
    check("CCODE-235 §4: …and the engine has no place to PUT an open trade — the absence is structural",
      !/openTrades|escrow|pendingTrade|owedBy/i.test(purseCode));

    // ⚠️ A FAILED TRADE MUST NOT HALF-SETTLE. Checked before anything moves, which is the only way "no
    // open state" can actually be guaranteed rather than asserted.
    const poor = { name: "p", inventory: [] };
    PU.credit(poor, "crystal", 1, { origin: "found" });
    const fail = PU.settleExchange(poor, { price: 999, economy: ec235, regionId: "the_crossing", take: [item235] });
    check("CCODE-235 §4: a trade that cannot be paid changes NOTHING — no goods, no coin, no half-state",
      !fail.ok && PU.held(poor.purse, "crystal") === 1 && poor.inventory.length === 0, fail.why);

    // ⚠️ AND THE INDIVISIBILITY COST IS STATED RATHER THAN SWALLOWED: paying in marks rounds UP to a whole
    // mark, and `overpay` says how much that cost you.
    const mk = { name: "m", inventory: [] };
    PU.credit(mk, "marks", 20, { origin: "paid" });
    const inMarks = PU.canSettle(mk, 9, { currency: "marks", economy: ec235 });
    check("CCODE-235 §4: paying in an indivisible currency rounds UP and SAYS what that cost",
      inMarks.ok && Number.isInteger(inMarks.due) && inMarks.overpay > 0, inMarks.math);
  }

  // 5x · ⛔ CCODE-236 / §5–§6 — bargain, provoke, soothe. ⚠️ REGISTERING A VERB IS NOT MECHANISING IT.
  // `SNG-263 §1` only checks that a verb appears in a family or an override, so adding three lines to
  // `craft_mechanics.json` would have turned it green while building nothing — laundering a gate. Every
  // check below tests the CONSUMER; the registration is checked last and only as a consequence.
  {
    const EC = await import("../engine/economy.js");
    const CM = await import("../engine/craftmechanics.js");
    const ec236 = C199.rules?.economy;

    // ⛔ THE LOAD-BEARING RULE: RANK SCALES THE STAKE, NOT THE DISCOUNT.
    const small1 = EC.bargainOutcome({ price: 8, rank: 1, margin: 20, economy: ec236 });
    const small5 = EC.bargainOutcome({ price: 8, rank: 5, margin: 20, economy: ec236 });
    check("CCODE-236 §5: rank does NOT deepen the cut — r1 and r5 save the same on a sack of grain",
      small1.ok && small5.ok && small1.newPrice === small5.newPrice,
      `r1 ${small1.newPrice} vs r5 ${small5.newPrice}`);
    const big1 = EC.bargainOutcome({ price: 200, rank: 1, margin: 20, economy: ec236 });
    const big5 = EC.bargainOutcome({ price: 200, rank: 5, margin: 20, economy: ec236 });
    check("CCODE-236 §5: rank changes what SIZE of deal it reaches — r1 cannot move a caravan contract, r5 can",
      big1.ok === false && big1.outOfReach === true && big5.ok === true);
    // ⚠️ AND OUT-OF-REACH IS A REFUSAL, NOT A SMALLER EFFECT. A rank-1 haggler at a caravan contract is out
    // of their depth, not slightly less persuasive — scaling it down would rebuild the discount ladder.
    check("CCODE-236 §5: a deal beyond reach moves the price NOT AT ALL — refusal, never a smaller effect",
      big1.newPrice === 200 && /too big to move/.test(big1.why));
    check("CCODE-236 §5: a bargain measurably moves the SETTLED price, and says by what",
      small1.newPrice < 8 && /margin 20/.test(small1.math), small1.math);
    // ⚠️ §31.5 — both sides give something
    // ⚠️ AND THE MAGNITUDE ITSELF IS GUARDED, which the rank gates above do NOT do. I mutated the saving to
    // double and nothing went red: "r1 and r5 save the same" stays true when both are wrong together. The
    // cap is the only thing standing between a bargain and a free item, so it is gated directly.
    const capped = EC.bargainOutcome({ price: 100, rank: 5, margin: 9999, economy: ec236 });
    const authoredCap = Number.isFinite(Number(ec236?.bargain?.savingCap)) ? Number(ec236.bargain.savingCap) : 0.3;
    check(`CCODE-236 §5: the saving is CAPPED at ${(authoredCap * 100).toFixed(0)}% however good the roll — a bargain is never a gift`,
      capped.ok && capped.fraction <= authoredCap + 1e-9 && capped.newPrice >= 100 * (1 - authoredCap) - 1e-9,
      `${(capped.fraction * 100).toFixed(0)}% off`);

    check("CCODE-236 §5: a won bargain owes a concession — the only social verb with a price on both sides",
      small1.concessionOwed === true);
    check("CCODE-236 §5: no ground given → no saving", EC.bargainOutcome({ price: 8, rank: 3, margin: 0, economy: ec236 }).ok === false);

    // ⛔ PROVOKE takes the opponent's chosen line — and nothing when there is no line to take
    check("CCODE-236 §6: provoke CLEARS state.tactic — the chosen action, gone, back to default",
      CM.resolveProvoke({ tactic: "press-in" }, { margin: 12 }).ok === true
      && CM.resolveProvoke({ tactic: "press-in" }, { margin: 12 }).tactic === null);
    // ⛔ SUPERSEDED BY CCODE-256, AND THE OLD RULE WAS DELIBERATE SO IT IS RECORDED RATHER THAN DELETED.
    // This asserted that provoke does NOTHING to a foe committed to nothing — "a refusal, not a hollow win."
    // ⚠️ THE REASONING WAS SOUND AND THE CONSEQUENCE WAS NOT: `state.tactic` is set ONLY by the narrator, so
    // provoke's entire value hung on the GM having chosen to give this foe a line — invisible to the player
    // and impossible to play around. Erik: "Seems like you should be able to provoke even those without a
    // 'line'." ⛔ THE ANSWER ONLY EXISTED AFTER CCODE-250: now that a foe CHOOSES whom to hit, goading
    // something with no line means MAKING YOURSELF THE THING IT WANTS. Still not a hollow win — a different
    // one, and the tool a protector was missing.
    check("CCODE-256 §6: provoking a foe with NO line taunts it instead — you become what it wants",
      CM.resolveProvoke({ tactic: null }, { margin: 12, taunter: "veth" }).ok === true
      && CM.resolveProvoke({ tactic: null }, { margin: 12, taunter: "veth" }).taunted?.targetId === "veth");
    // ⚠️ AND IT IS NOT PERMANENT. A taunt that held for the whole fight would let one character lock a foe
    // onto themselves forever, which removes the decision instead of creating one.
    check("CCODE-256 §6: …for a couple of rounds, not for the fight — it has to be re-earned",
      CM.resolveProvoke({ tactic: null }, { margin: 12 }).taunted?.rounds >= 1
      && CM.resolveProvoke({ tactic: null }, { margin: 12 }).taunted?.rounds <= 3);
    // ⛔ AND A FAILED PROVOKE STILL DOES NOTHING — the refusal that survives is the one that was always right.
    check("CCODE-256 §6: a provoke they do not rise to takes nothing and taunts nobody",
      CM.resolveProvoke({ tactic: null }, { margin: 0 }).ok === false
      && !CM.resolveProvoke({ tactic: null }, { margin: 0 }).taunted);

    // ⚠️ SOOTHE removes heat, never reasons
    const cool = CM.resolveSoothe({ momentum: 6 }, { margin: 20 });
    const losing = CM.resolveSoothe({ momentum: -6 }, { margin: 20 });
    check("CCODE-236 §6: soothe pulls momentum TOWARD zero from either side",
      cool.momentum.after === 3 && losing.momentum.after === -3);
    // ⛔ NEVER PAST ZERO: cooling a fight the other side is winning must not hand you the advantage.
    const huge = CM.resolveSoothe({ momentum: 2 }, { margin: 200 });
    check("CCODE-236 §6: …and never past zero — a soothe that overshot would be an attack",
      huge.momentum.after === 0);
    check("CCODE-236 §6: soothe never touches a damage track — it removes heat, not reasons (§31.5)",
      cool.touchedDamage === false && !("health" in cool) && !("damage" in cool));

    // …and ONLY NOW, the registration — as a consequence of the above, never as a substitute for it
    const cmCfg = C199.craftMechanics || {};
    for (const v of ["bargain", "provoke", "soothe"]) {
      const sh = CM.shapeOfVerb(v, cmCfg);
      check(`CCODE-236: \`${v}\` resolves to an effect-shape (${sh?.shape || "none"}) — SNG-263 §1 drops it`, !!sh?.shape);
    }
    check("CCODE-236 §5: bargain's operative is `scope`, because the rank axis IS the stake",
      CM.shapeOfVerb("bargain", cmCfg)?.operative === "scope");
  }

  // 5y · ⛔ CCODE-237 (Aevi's §0) — A HEAL REACHES A SHEET. Her one non-negotiable was "`mechanic.dice` ON A
  // HEALING SHAPE MUST BE READ", and `mechanic_effects.json` said `HEAL — wired: false`.
  //
  // ⚠️ MEASURED, THE FILE WAS STALE AND THE REAL GAP WAS ONE STEP LATER: the dice ARE read (dawn_surgery
  // rolls its 3d4 and the round reports 12), the wrapper forwards `healing` — and NOTHING CONSUMED IT.
  // `deltas.health` started at 0 and the heal never entered it, so 57 healing crafts mended nobody. Same
  // shape as `imposed`, one file over. ⛔ SO THE GATES BELOW TEST THE SHEET, not the roll.
  {
    const EN237 = await import("../engine/encounters.js");
    const heal237 = Object.values(C199.abilities).find(a => a.id === "dawn_surgery")
      || Object.values(C199.abilities).find(a => a.mechanic?.dice && (a.functions || []).includes("heal"));
    const sheet237 = (name, hp) => ({ name, level: 5, health: hp, maxHealth: 20, energy: 40, maxEnergy: 40,
      attributes: { physical: 5, mental: 4, social: 3, practical: 3 }, subAttributes: {}, alignment: {},
      skills: [], abilities: [], tacticTags: [] });
    const runHeal = () => {
      const ch = sheet237("you", 8);
      const def = { id: "d", type: "duel", name: "t", opponent: { name: "Foe", health: 20, threat: 20, tacticTags: [] }, skillBattle: true };
      const st = { mode: "skill_battle", momentum: 0, round: 1, opponentEnergy: 40, opponentHealth: 20,
        effects: [], pressure: { player: 0, opponent: 0 }, status: "active", opponentSheet: sheet237("Foe", 20) };
      const decl = { ...heal237, name: heal237.name, function: "heal", intensity: "standard", tier: heal237.levelReq || 1, rank: 1 };
      return EN237.skillBattleRound(st, def, decl, { character: ch, rules: C199.rules, sb: C199.skillBattle?.engine || C199.skillBattle, rng: () => 0.5 });
    };
    const rr = runHeal();
    check(`CCODE-237: the authored dice reach the round — ${heal237?.id} ${JSON.stringify(heal237?.mechanic?.dice)} → ${rr.healing?.amount}`,
      !!rr.healing && rr.healing.amount > 0);
    // ⛔ THE GATE THAT WOULD HAVE CAUGHT THIS: not "does it roll" but "does the sheet move".
    check(`CCODE-237: …and it REACHES THE SHEET — deltas.health ${rr.deltas.health} (it was 0 for every heal ever cast)`,
      rr.deltas.health === rr.healing.amount);
    // ⚠️ THE SIGN. A heal on the player must RAISE health. Backwards, every mending craft is a weapon —
    // the one failure a healing branch must not have, and a plausible one to write.
    check("CCODE-237: a heal on the player RAISES health — a mending craft is never a weapon",
      rr.deltas.health > 0);
    check("CCODE-237: …and the player is told it landed",
      (rr.events || []).some(e => /MENDS/.test(e)), (rr.events || []).join(" | ").slice(0, 90));

    // the dice are the craft's own: two different crafts with different dice heal differently
    const healers = Object.values(C199.abilities)
      .filter(a => a.mechanic?.dice && (a.functions || []).some(f => ["heal", "mend", "restore"].includes(f)));
    check(`CCODE-237: ${healers.length} healing crafts carry authored dice — the field Aevi asked to be read`,
      healers.length > 20, `${healers.length}`);
    const CM237 = await import("../engine/craftmechanics.js");
    const amounts = healers.slice(0, 8).map(a => CM237.resolveHeal(a, { rank: 1, cfg: C199.craftMechanics, rng: () => 0.5 }).healed);
    check("CCODE-237: …and the dice are the CRAFT'S OWN — different dice heal different amounts, not one flat number",
      new Set(amounts).size > 1, amounts.join(","));
  }

  // 5z · ⛔ CCODE-238 — AN ANTISOAK CARRIED AS A CONDITION REACHES THE ROUND.
  //
  // CCODE-216 built antisoak as a CONDITION; CCODE-228 wired an imposition to write one onto the sheet.
  // `skill_battle` read `targetSheet.antisoak` — a flat number nothing populated from them. ⚠️ MEASURED:
  // a flat `antisoak: 5` took a 20 to 25, and the identical antisoak carried as a condition changed
  // NOTHING. The chain was imposed → condition → [nothing] → antisoakLanded.
  //
  // ⛔ FOUND BY THE EFFECT AUDIT MISFIRING, WHICH IS WORTH RECORDING: my probe put antisoak in
  // `conditions`, got no movement, and the harness was about to report ANTISOAK as inert. The mechanic was
  // fine; my probe was wrong; and chasing why it was wrong found a real gap one layer down.
  {
    const SBz = await import("../engine/skill_battle.js");
    const abz = Object.values(C199.abilities).find(a => a.mechanic?.dice && (a.functions || []).includes("strike"));
    const shz = (x) => Object.assign({ name: "them", level: 5, health: 20, maxHealth: 20, energy: 40, maxEnergy: 40,
      attributes: { physical: 5, mental: 4, social: 3, practical: 3 }, subAttributes: {}, alignment: {}, skills: [], soak: 4 }, x || {});
    const dz = Object.assign({}, abz, { name: abz.name, function: "strike", intensity: "standard", tier: 1, rank: 1,
      mechanic: Object.assign({}, abz.mechanic, { dice: { n: 6, d: 6 } }) });
    const hit = (opp) => SBz.battleRound({ playerDecl: dz, oppDecl: { name: "S", function: "strike", intensity: "standard", tier: 1 },
      playerSheet: shz({ name: "you" }), oppSheet: opp,
      state: { momentum: 0, round: 1, playerEnergy: 40, opponentEnergy: 40, opponentHealth: 20, effects: [], pressure: { player: 0, opponent: 0 } },
      rules: C199.rules, sb: C199.skillBattle?.engine || C199.skillBattle, rng: () => 0.5, kind: "fight" }).damage?.amount ?? null;

    const none = hit(shz({}));
    const flat = hit(shz({ antisoak: 5 }));
    const cond = hit(shz({ conditions: [{ id: "opened", kind: "antisoak", magnitude: 5 }] }));
    const both = hit(shz({ antisoak: 5, conditions: [{ id: "opened", kind: "antisoak", magnitude: 5 }] }));

    check(`CCODE-238: a flat sheet antisoak still lands (${none} → ${flat})`, flat > none);
    check(`CCODE-238: …and an antisoak carried as a CONDITION lands too (${none} → ${cond}) — it did nothing before`,
      cond > none, `${none} vs ${cond}`);
    // ⛔ §41: SUMMED, not max'd — two crafts each opening a different weakness is worse than one.
    check(`CCODE-238: two sources SUM rather than compete (${both}) — §41's rule, not a max`,
      both > flat && both - none === (flat - none) + (cond - none), `${both}`);
    // ⚠️ and a condition of a DIFFERENT kind must not be read as antisoak
    check("CCODE-238: only conditions of kind `antisoak` count — a stagger is not a weakness",
      hit(shz({ conditions: [{ id: "staggered", kind: "action_loss", magnitude: 5 }] })) === none);
  }

  // 5aa · ⛔ CCODE-239 — PROJECTS ADVANCE WITH THE DAYS. `projects.js` shipped green with every export
  // reachable only from smoke.mjs: work could be banked and nothing ever advanced it, which makes a
  // threshold a duration that never elapses. It was the ONE inert verdict in the effect audit.
  {
    const appSrc239 = readFileSync(join(root, "app.js"), "utf8");
    check("CCODE-239: app.js imports projects.js — the module can fire in play",
      /import \{[^}]*tickAllProjects[^}]*\} from "\.\/engine\/projects\.js"/.test(appSrc239));
    check("CCODE-239: …and `maybeTick` — the one choke point the clock passes through — calls it",
      /async function maybeTick\(\)[\s\S]{0,900}?tickAllProjects\(character/.test(appSrc239));
    // ⚠️ BY THE DELTA, NOT BY THE CALL. maybeTick fires on re-entry as well as on a clock jump, so ticking
    // one day per call would pay a project for opening the app.
    check("CCODE-239: it pays the DAY DELTA, not one day per call — reopening the app must not advance work",
      /const days = Math\.max\(0, currentDay - last\)/.test(appSrc239)
      && /character\._lastProjectDay = currentDay/.test(appSrc239));
    check("CCODE-239: a project that COMPLETES reaches the news — silent completion reads as never having run",
      /_projectNews/.test(appSrc239) && /unseenNews/.test(appSrc239));

    // the rule itself, through the real module and REAL project crafts. ⚠️ My first version fabricated an
    // ability `{id, threshold}` — `isProjectCraft` requires `projectTicks && downtime`, so openProject
    // returned a REFUSAL, `projectProgress(refusal)` threw, and the suite died reporting zero failures:
    // 4,104 passes became 4,057. Third time this session, same tell.
    const PR239 = await import("../engine/projects.js");
    const pcraft = Object.values(C199.abilities).filter(a => PR239.isProjectCraft(a));
    check(`CCODE-239: the corpus authors real project crafts (${pcraft.length}) — the rule has content to act on`,
      pcraft.length > 0, pcraft.map(a => a.id).join(", "));
    if (pcraft.length) {
      // ⚠️ `.project` — openProject returns `{ok, project}`, not the project. Using the wrapper made
      // `history` undefined and killed the suite a SECOND time on the same block. Two different
      // mistakes, one gate, and both were me not reading the return shape before calling it.
      const mk = () => PR239.openProject({ projects: [], name: "t" }, pcraft[0], { day: 0 }).project;
      const p1 = mk();
      const before = PR239.projectProgress(p1).fraction;
      PR239.tickProject(p1, { days: 3, hands: 1 });
      check(`CCODE-239: days of work move a project toward its threshold (${before}% → ${PR239.projectProgress(p1).fraction}%)`,
        PR239.projectProgress(p1).fraction > before);
      // ⛔ THE THRESHOLD IS WORK, NOT A DATE — the rule the whole module exists for.
      const p2 = mk(); PR239.tickProject(p2, { days: 99, hands: 0 });
      const p3 = mk(); PR239.tickProject(p3, { days: 1, hands: 4 });
      check("CCODE-239: hands do the work, not the calendar — 99 days with no hands is not 1 day with four",
        PR239.projectProgress(p2).fraction !== PR239.projectProgress(p3).fraction,
        `${PR239.projectProgress(p2).fraction}% vs ${PR239.projectProgress(p3).fraction}%`);
    }
  }



// ⛔ CCODE-242 — EVERY OP THE GM IS TOLD TO EMIT MUST HAVE A CONSUMER.
//
// This is Erik's backlog 7 ("can the GM generate every kind of content?") made answerable instead of
// guessable. ⚠️ I GOT THAT ANSWER WRONG THREE TIMES — "5 of 11 kinds", then "7", then a list of nine
// unapplied op groups — every time by measuring ONE mechanism (`GEN_TYPES`) and inferring the whole
// surface. The GM creates content through at least four different routes:
//
//   · `generate()` / GEN_TYPES        — npc, location, arc, creature, item
//   · turn op groups                  — questUpdates, placeUpdates, npcUpdates, itemUpdates, …
//   · singular creators               — newEncounter, newAbility
//   · in-play minting                 — braids, from the player's own pairings
//
// ⛔ SO COUNTING ONE ROUTE ANSWERS NOTHING. What is checkable is the contract: the GM's prompt is a promise
// about what the engine will honour, and an advertised op with no consumer is a promise the game breaks
// silently — the model emits it, the turn succeeds, and the effect vanishes.
{
  const gmSrc = readFileSync(join(root, "engine/gm.js"), "utf8");
  const appSrc242 = readFileSync(join(root, "app.js"), "utf8")
    // ⛔ COMMENTS STRIPPED. A scanner reading its own prose has bitten this project five times now.
    .replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
  // ⛔ gm.js IS EXCLUDED FROM ITS OWN CONSUMER CORPUS. My first version included it, so every
  // advertised op "consumed" itself and the check passed for every possible input — proved by
  // advertising a `weatherOps` nothing implements and watching the gate stay green. The ADVERTISER
  // can never count as the CONSUMER; that is the whole claim.
  const engineSrc242 = readdirSync(join(root, "engine")).filter(f => (f.endsWith(".js") || f.endsWith(".mjs")) && f !== "gm.js")
    .map(f => readFileSync(join(root, "engine", f), "utf8")).join("\n")
    .replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");

  // the op names the prompt's JSON schema advertises, taken from the schema block only
  // ⚠️ THE WHOLE FILE, NOT A WINDOW. My first version sliced ±4000 chars around `"questUpdates"` and
  // found 9 of the ~18 ops — and the CONSUMER check below then passed cleanly on that half-list. The
  // non-vacuity floor is the only reason I noticed; without it this section would have reported a green
  // contract over half a vocabulary.
  const advertised = [...new Set([
    ...[...gmSrc.matchAll(/"([a-zA-Z]+(?:Updates|Ops|Deltas))"\s*:/g)].map(m => m[1]),
    ...[...gmSrc.matchAll(/"(new[A-Z][a-zA-Z]+)"\s*:/g)].map(m => m[1]),
  ])];

  // ⚠️ NON-VACUITY FIRST. A derived list that finds nothing would pass this section forever.
  check(`CCODE-242: the GM prompt advertises a recognisable op vocabulary (${advertised.length} ops)`,
    advertised.length >= 10, advertised.join(", "));

  // ⚠️ A CONSUMER IS `turn.X` ANYWHERE, OR THE NAME READ OFF A NESTED RECORD. `spectrumDeltas` nearly
  // became a false finding here: it is a FIELD INSIDE `ledgerEvents`, not a top-level op, and looking only
  // for `turn.spectrumDeltas` found nothing while the value was being read two files away.
  const consumed = (op) =>
    new RegExp("turn\\??\\.?" + op + "\\b").test(appSrc242)
    || new RegExp("\\b" + op + "\\b").test(appSrc242)
    || new RegExp("\\b" + op + "\\b").test(engineSrc242);

  const orphaned = advertised.filter(op => !consumed(op));
  check(`CCODE-242: every advertised GM op has a consumer — an op the model is told to emit and nothing applies is a promise the game breaks silently`,
    orphaned.length === 0,
    orphaned.length ? orphaned.join(", ") + " — advertised in engine/gm.js and read by nothing" : "");
}

  // 5ab · ⛔ CCODE-243 / SPEC_pierce_value — PIERCE IS AN AMOUNT THAT BYPASSES SOAK.
  {
    const SB243 = await import("../engine/skill_battle.js");
    // ⚠️ AEVI'S OWN WORKED TABLE IS THE GATE. Her §3 states four cells; if the engine ever stops
    // reproducing them the spec and the code have diverged and one of them is wrong.
    check("CCODE-243: hit 6 into soak 8 with NO pierce lands nothing — and so the antisoak never fires (spec: 0)",
      SB243.pierceLanded(6, 8, 0, 8) === 0);
    check("CCODE-243: the same blow with pierce 4 lands 4 THROUGH, so antisoak 8 applies (spec: 12)",
      SB243.pierceLanded(6, 8, 4, 8) === 12);
    check("CCODE-243: hit 10 into soak 8, no pierce, antisoak 6 (spec: 8)",
      SB243.pierceLanded(10, 8, 0, 6) === 8);
    check("CCODE-243: hit 10 into soak 8 WITH pierce 4, antisoak 8 — additive, not an alternative (spec: 14)",
      SB243.pierceLanded(10, 8, 4, 8) === 14);
    // ⛔ ACCEPTANCE 1 + 2: at least N lands whatever the soak, and the antisoak fires whenever pierce > 0.
    check("CCODE-243: a craft carrying pierce N lands at least N against ANY soak",
      [0, 5, 50, 500].every(sk => SB243.pierceLanded(1, sk, 4, 0) >= 4));
    // ⚠️ SOAK >= HIT ONLY. My first version included soak 0, where the ordinary damage ALSO gets
    // through, so the total is 1 + 4 + 7 and not 4 + 7 — my arithmetic, not the engine's.
    check("CCODE-243: …and the vulnerability always applies when pierce > 0 — the whole point of the spec",
      [50, 500].every(sk => SB243.pierceLanded(1, sk, 4, 7) === 4 + 7)
      && SB243.pierceLanded(1, 0, 4, 7) === 1 + 4 + 7);
    // ⚠️ AND NO PIERCE STILL MEANS NO FLOOR — pierce must not become a universal minimum.
    check("CCODE-243: without pierce, heavy armour still stops a blow dead",
      SB243.pierceLanded(2, 50, 0, 9) === 0);

    // ⛔ ACCEPTANCE 3 — `pierce` and `penetration` coexist. They are different mechanisms: penetration cuts
    // LAYERS BY RANK, pierce adds a flat AMOUNT past whatever soak remains.
    const cm243 = await import("../engine/craftmechanics.js");
    const probe = { mechanic: { penetration: 2 }, tree: [{ rank: 3, pierce: 4 }] };
    check("CCODE-243: a craft may carry both, read from wherever each is authored (ability AND rank)",
      cm243.authoredBlock(probe, "penetration", 3) === 2 && cm243.authoredBlock(probe, "pierce", 3) === 4);

    // ⛔ AND THE READER FIX THAT CAME WITH IT: `penetration` was authored on two crafts and read on none.
    // `pen` was `Number(winDecl.penetration)`, and neither craft puts it there — radiant_lance carries it
    // on `mechanic`, hastened_grey on a RANK. §45.1 for the fifth time.
    // ⚠️ DERIVED FROM THE CORPUS, NOT NAMED. My first version asserted that `radiant_lance` AND
    // `hastened_grey` each resolve penetration 2 — and went red the next day when Aevi correctly replaced
    // hastened_grey's inert penetration with `pierce`. A gate pinned to two craft ids fails when content is
    // legitimately right, which is the §37.2 failure I have now committed myself.
    // WHAT MUST BE TRUE: whatever authors penetration ANYWHERE is reachable by the reader the round uses.
    const penCrafts = Object.values(C199.abilities).filter(a =>
      a.penetration != null || a.mechanic?.penetration != null
      || (a.tree || []).some(r => r?.penetration != null || r?.mechanic?.penetration != null));
    check(`CCODE-243: every craft authoring \`penetration\` is REACHABLE by the round's reader (${penCrafts.length} crafts)`,
      penCrafts.length > 0 && penCrafts.every(a => {
        const top = Math.max(1, ...(a.tree || []).map(r => Number(r.rank) || 1));
        return Number(cm243.authoredBlock(a, "penetration", top)) > 0;
      }), penCrafts.map(a => `${a.id}=${cm243.authoredBlock(a, "penetration", 3)}`).join(", "));
    const src243 = readFileSync(join(root, "engine/skill_battle.js"), "utf8");
    check("CCODE-243: …and the round reads penetration rank-first rather than off the declaration's top level",
      /const pen = Math\.max\(0, Number\(authoredBlock\(winDecl, "penetration"/.test(src243));
    check("CCODE-243: pierce is read the same way — rank-first, so authoring it on a rank works",
      /const pierce = Math\.max\(0, Number\(authoredBlock\(winDecl, "pierce"/.test(src243));

    // ⚠️ ACCEPTANCE 4: immune still beats pierce. Aevi called it my decision and I agree with her reasoning —
    // a pierce that beat immunity would be a universal answer and nothing in the bestiary would be safe.
    check("CCODE-243: `immune` is decided ABOVE this function — pierce never sees an immune target",
      /if \(aff === "immune"\) hit = 0;/.test(src243) && /aff === "immune" \? 0/.test(src243));
    // acceptance 5: the receipt separates the portions
    check("CCODE-243: the receipt names the pierced portion, so a player can see why armour did not help",
      /pierceNote: `\$\{pierce\} bypassed armour entirely`/.test(src243));
  }


  // 5ac · ⛔ CCODE-244 — THE CAPABILITY READER. Erik: "I want the player to just say use X skill this way
  // and the engine should know which rank it takes to do that."
  {
    const CAP = await import("../engine/capabilities.js");
    const keening = C199.abilities.keening;

    // ⛔ AEVI'S WORKED CRAFT IS THE GATE. Her §2a: r2's `targets: 3` does NOT replace r1's 6 — it is a new
    // capability layered over a retained one, and the prose says so inside r2's own text.
    if (keening) {
      const caps = CAP.capabilitiesOf(keening, 3, { cfg: C199.rules?.energy });
      check(`CCODE-244: an r3 character sees EVERY tier of keening, not just the last (${caps.length})`,
        caps.length === 3 && caps.map(c => c.rank).join() === "1,2,3");
      // ⚠️ THE ADDITIVE MODEL, STATED AS A TEST: owning r3 does not remove the r1 option.
      check("CCODE-244: the r1 capability is still offered at r3 — a rank ADDS, it never replaces",
        caps.some(c => c.rank === 1));
      // and owning less shows less
      check("CCODE-244: an r1 character sees only what they own",
        CAP.capabilitiesOf(keening, 1).length === 1);
    }

    // ⛔ WHICH RANK DOES THIS TAKE — the question Erik asked, answered.
    const probe = { id: "p", name: "Probe", energyCost: 4, tree: [
      { rank: 1, grants: "one target", imposes: { condition: "action_loss", targets: 1 } },
      { rank: 2, grants: "three targets", imposes: { condition: "unconscious", targets: 3 } },
      { rank: 3, grants: "a hall", imposes: { condition: "unconscious", targets: 12 } }] };
    check("CCODE-244: asking for a tier you own resolves to it",
      CAP.resolveTier(probe, 2, 3).ok === true && CAP.resolveTier(probe, 2, 3).rank === 2);
    // ⚠️ AN OVERREACH NAMES WHAT YOU CAN DO INSTEAD. "You cannot do that" with no alternative is the
    // cruellest possible message when the tier below plainly covers something.
    const over = CAP.resolveTier(probe, 3, 1);
    check("CCODE-244: reaching past what you own is refused WITH the capability you do have",
      over.ok === false && over.overreach === true && over.rank === 1 && /one target/.test(over.insteadCan));

    // ⛔ THE MENU IS A LIST OF CHOICES, NOT OF ROWS. Measured: one option per craft × function × rank takes
    // a 6-craft kit from 14 options to 42, and only 508 of 1,056 ranks declare anything of their own.
    const flat = { id: "f", name: "Flat", tree: [{ rank: 1, grants: "a thing" }, { rank: 2, grants: "the same thing, better said" }] };
    check("CCODE-244: a craft whose ranks declare nothing mechanical offers ONE menu entry, not one per rank",
      CAP.capabilityMenu(flat, 2).tiers.length === 1);
    // ⚠️ AND NEVER ZERO — a filter that drops a craft entirely deletes it from play, which is the failure
    // this file exists to prevent, committed by the filter meant to keep it small.
    check("CCODE-244: …but never zero — every owned craft is always offerable",
      CAP.capabilityMenu(flat, 2).tiers.length >= 1
      && CAP.capabilityMenu({ id: "x", tree: [{ rank: 1 }] }, 1).tiers.length >= 1);

    // ⛔ COST: the mechanism exists and the price is UNCHANGED until a dial is authored.
    // ⚠️ THE CLAIM IS THE DIAL'S BEHAVIOUR, NOT ITS SETTING. My first version asserted "costs are unchanged
    // today" — true when I wrote it and false the same afternoon, because Erik authored
    // `rankReachSurcharge: 3`. A gate pinned to the current value of a dial goes red when someone turns it,
    // which punishes exactly the person the dial was built for. §37.2 again, and mine again.
    const e = C199.rules?.energy || {};
    const flatCfg = { ...e, rankReachSurcharge: 0 };
    const flat244 = [1, 2, 3].map(r => CAP.reachCost(probe, r, { cfg: flatCfg }));
    check(`CCODE-244: with the surcharge at 0, every tier costs the same (${flat244.join("/")}) — the mechanism adds nothing on its own`,
      new Set(flat244).size === 1 && flat244[0] === 4);
    const dialled = [1, 2, 3].map(r => CAP.reachCost(probe, r, { cfg: { ...e, rankReachSurcharge: 3 } }));
    check(`CCODE-244: …and a surcharge makes reach cost more, monotonically (${dialled.join("/")})`,
      dialled[2] > dialled[1] && dialled[1] > dialled[0]);
    // ⛔ AND THE LIVE SETTING IS REPORTED RATHER THAN ASSERTED — Erik owns the number, not this file.
    const live = [1, 2, 3].map(r => CAP.reachCost(probe, r, { cfg: e }));
    console.log(`note  CCODE-244: authored surcharge is ${e.rankReachSurcharge ?? 0} — a 4-cost craft reaches at ${live.join(" / ")}`);
    // ⚠️ `null` IS NOT ZERO. `Number(null) === 0` is finite, so the obvious num helper swallowed the
    // fallback and returned a cost of 1 for a craft whose authored energyCost is 4.
    check("CCODE-244: an absent base cost falls back to the craft's authored one — null is not zero",
      CAP.reachCost({ energyCost: 7 }, 1, { cfg: e }) === 7);

    // ⛔ CCODE-245 / SPEC_rank_zero — r0 IS THE UNLEARNED STATE, AND IT WAS A PERMISSION.
    // `Math.max(1, ownedRank)` made 0 indistinguishable from 1 and the engine GRANTED the craft:
    // `resolveTier(craft, 1, 0)` returned ok. The absent-vs-explicit trap for the fifth time — except the
    // collapsed state was permission to use something you have not learned.
    {
      const unlearned = C199.abilities.kept_breath || Object.values(C199.abilities).find(a => (a.tree || []).length);
      check("CCODE-245: a craft you have NOT learned offers no tiers at all",
        CAP.capabilityMenu(unlearned, 0).tiers.length === 0);
      const r0 = CAP.resolveTier(unlearned, 1, 0);
      check("CCODE-245: …and the engine REFUSES it, with a reason naming that it is not learned",
        r0.ok === false && r0.unlearned === true && /have not learned/.test(r0.why));
      // ⚠️ HER §4.4: omitted and 0 must be distinguishable, or the fix re-creates the bug.
      check("CCODE-245: omitting the rank is NOT the same as passing 0",
        CAP.capabilityMenu(unlearned).tiers.length > 0 && CAP.capabilityMenu(unlearned, 0).tiers.length === 0);
      // ⛔ AND THE CALLERS MUST NOT COLLAPSE IT EITHER — `|| 1` swallows a real 0 one layer up.
      const appSrc245 = readFileSync(join(root, "app.js"), "utf8") + "\n" + readFileSync(join(root, "engine/battle_turn.js"), "utf8");   // §71: the menu and the rank live in the module
      check("CCODE-245: app.js passes the rank through with `??`, so a genuine 0 survives to the module",
        // DUEL §C.2: the owned rank now comes from the character (`?.level ?? …`), not from a field named tier;
        // the `??` is the property, and no `|| 1` may sit on that line.
        /capabilityMenu\(def, a\.level \?\? 1/.test(appSrc245) && /\?\.level \?\? \(decl\.rank \?\? 1\)/.test(appSrc245)
        && /resolveTier\(cdef, want, ownedRank\)/.test(appSrc245) && !/ownedRank = [^\n]*\|\| 1/.test(appSrc245));

      // ⛔ HER §4.2 — r1 WAS FILTERED FROM THE MENU ON MOST OF THE CORPUS, because `tierDeclaresSomething`
      // compared r1 against a tier that does not exist and found nothing new. With r0 as the identity
      // element the same function is correct as written.
      const trees = Object.values(C199.abilities).filter(a => (a.tree || []).length);
      const withR1 = trees.filter(a => {
        const top = Math.max(...a.tree.map(r => Number(r.rank) || 1));
        return CAP.capabilityMenu(a, top).tiers.some(t => t.rank === 1);
      }).length;
      check(`CCODE-245: EVERY craft offers its r1 use (${withR1} of ${trees.length}) — it was 89, so three quarters of the corpus could not be used at rank 1`,
        withR1 === trees.length, `${withR1}/${trees.length}`);
      // ⚠️ AND THE FILTER STILL FILTERS — her §4.3. Only r1 was ever misclassified.
      const flat245 = { id: "f2", tree: [{ rank: 1, grants: "a thing" }, { rank: 2, grants: "the same, better said" }] };
      check("CCODE-245: …while a PURE-PROSE r2 is still filtered — the 508-of-1,056 measurement stands",
        CAP.capabilityMenu(flat245, 2).tiers.length === 1 && CAP.capabilityMenu(flat245, 2).tiers[0].rank === 1);
    }

    // ⛔ AND THE WIRING: the rank must reach the declaration, or none of this is real in play.
    const appSrc244 = readFileSync(join(root, "app.js"), "utf8") + "\n" + readFileSync(join(root, "engine/battle_turn.js"), "utf8");   // §71
    check("CCODE-244: the skill list carries the TIERS, so the narrator is offered a rank to choose",
      /capabilityMenu\(def, a\.level \?\? 1/.test(appSrc244) && /tiers: menu\.tiers\.map/.test(appSrc244));
    check("CCODE-244: …and sbDeclare puts a VALIDATED rank on the declaration — authoredBlock has always taken one and nothing ever set it",
      /rank: v\.ok \? v\.rank/.test(appSrc244) && /resolveTier\(cdef, want/.test(appSrc244));
  }


  // 5ad · ⛔ CCODE-246 / SPEC_intercept_and_reflect — STANDING IN FRONT OF SOMEONE ELSE.
  // The game had no interception at all: `shield` and `ward` blunt what reaches YOU, and nothing let a
  // character take a hit meant for an ally. A whole party role missing from a game that already had soak
  // layers, typed wards, imposed conditions and resist thresholds.
  {
    const IC = await import("../engine/intercept.js");
    const sheets = { tank: { attributes: { mental: 9 } }, squishy: { attributes: { mental: 1 } },
      twin: { attributes: { mental: 9 } }, mid: { attributes: { mental: 5 } } };
    const imp = { condition: "unconscious", degradesTo: "action_loss", onCrit: "incapacitated" };

    // ⛔ §5.2 — r1 IS ONE ALLY, ONE CONDITION, and it is SPENT.
    const p1 = IC.openProtection({ protectorId: "tank", allyId: "squishy", rank: 1 });
    check("CCODE-246 §5.2: an r1 protection carries exactly one charge and no duration",
      p1.chargesLeft === 1 && p1.roundsLeft === null && p1.reflects === false);
    const first = IC.redirectImposition({ aimedAt: "squishy", sourceId: "foe", protections: [p1], sheets, imposition: imp, degree: "partial" });
    check("CCODE-246 §5.1: an imposition aimed at a protected ally is caught by the interceptor",
      !!first && first.caughtBy === "tank" && first.onBehalfOf === "squishy" && first.lands.on === "tank");
    IC.spendProtection(p1);
    check("CCODE-246 §5.2: …and once spent it protects nothing — r1 is one hit, not a standing wall",
      IC.interceptorFor("squishy", [p1], sheets) === null);

    // ⛔ §5.1 — RESOLVED AGAINST THE INTERCEPTOR'S OWN SHEET. Reusing the verdict computed against the ALLY
    // would make the tank a bookkeeping entry: the whole point is that the tank is BETTER at eating it.
    const p2 = IC.openProtection({ protectorId: "tank", allyId: "squishy", rank: 2 });
    const resolveFn = ({ targetResist }) => ({ condition: targetResist >= 8 ? "action_loss" : "unconscious",
      degradedTo: "action_loss", onCrit: "incapacitated" });
    const reres = IC.redirectImposition({ aimedAt: "squishy", sourceId: "foe", protections: [p2], sheets, imposition: imp, degree: "partial", resolveFn });
    const inherited = IC.redirectImposition({ aimedAt: "squishy", sourceId: "foe", protections: [p2], sheets, imposition: imp, degree: "partial" });
    check("CCODE-246 §5.1: the imposition is RE-RESOLVED against the interceptor — a hard target eats a softer version",
      reres.reResolved === true && reres.lands.condition === "action_loss"
      && inherited.reResolved === false && inherited.lands.condition === "unconscious");

    // ⛔ §5.3 — r2 HARDENS THE TAKER, and the existing threshold arithmetic already rewards that.
    check("CCODE-246 §5.3: an r2 protection raises the interceptor's resist while it runs",
      p2.resistBonus > 0
      && IC.effectiveResist(sheets.tank, p2) > IC.effectiveResist(sheets.tank, null));

    // ⛔ §5.4 — REFLECTION BY DEGREE. Erik's three tiers map onto the existing crit/success/partial ladder,
    // so these are not new numbers.
    const p3 = IC.openProtection({ protectorId: "tank", allyId: "squishy", rank: 3 });
    const back = (d) => IC.redirectImposition({ aimedAt: "squishy", sourceId: "foe", protections: [p3], sheets, imposition: imp, degree: d }).lands;
    check("CCODE-246 §5.4: a FULL resist sends the original back BOOSTED — the craft's own onCrit, not an invented number",
      back("crit_success").on === "foe" && back("crit_success").condition === "incapacitated" && back("crit_success").boosted === true);
    check("CCODE-246 §5.4: a clean resist sends the ORIGINAL back",
      back("success").on === "foe" && back("success").condition === "unconscious");
    check("CCODE-246 §5.4: a marginal resist sends the DEGRADED form back",
      back("partial").on === "foe" && back("partial").condition === "action_loss");
    // ⚠️ REFLECTION IS EARNED. Erik's "maybe" kept as written — automatic reflection turns r3 into a wall.
    check("CCODE-246 §5.4: a FAILED resist reflects NOTHING and the interceptor carries it",
      back("failure").on === "tank" && back("failure").reflected === false);
    // and an r1/r2 protection never reflects at all
    check("CCODE-246 §5.4: only rank 3 reflects — r2 catches and carries",
      IC.redirectImposition({ aimedAt: "squishy", sourceId: "foe", protections: [p2], sheets, imposition: imp, degree: "crit_success" }).lands.on === "tank");

    // ⛔ §5.6 — COLLISION: HIGHEST RESIST CATCHES IT, ties to last-declared.
    const hi = IC.openProtection({ protectorId: "tank", allyId: "squishy", rank: 2 });
    const lo = IC.openProtection({ protectorId: "mid", allyId: "squishy", rank: 2 });
    check("CCODE-246 §5.6: the higher resist catches it, whatever the declaration order",
      IC.interceptorFor("squishy", [hi, lo], sheets).protection.protectorId === "tank"
      && IC.interceptorFor("squishy", [lo, hi], sheets).protection.protectorId === "tank");
    const tw = IC.openProtection({ protectorId: "twin", allyId: "squishy", rank: 2 });
    check("CCODE-246 §5.6: …and a genuine TIE breaks by last-declared — Erik's other option kept as the tiebreaker",
      IC.interceptorFor("squishy", [hi, tw], sheets).protection.protectorId === "twin"
      && IC.interceptorFor("squishy", [tw, hi], sheets).protection.protectorId === "tank");

    // ⛔ §5.7 — NO CONSENT STEP. Erik: "eliminate consent." Declaring the protection is the whole action.
    const icSrc = readFileSync(join(root, "engine/intercept.js"), "utf8")
      .replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
    check("CCODE-246 §5.7: there is no consent gate anywhere — a shield is not a confession",
      !/consent|accepted|agree|permission/i.test(icSrc));

    // ⚠️ §5.5 — THE RECEIPT. "A tank mechanic nobody can see is a tank mechanic nobody thanks."
    check("CCODE-246 §5.5: the receipt says WHO caught WHAT, and for whom",
      first.caughtBy && first.onBehalfOf && first.lands.condition && typeof first.why === "string" && first.why.length > 5);

    // ⛔ CCODE-246b — THE AUTHORED CRAFT DRIVES IT. Aevi wrote `shared_weight` to the spec the same day,
    // and the risk with any new field is that it is authored and read by nothing — the failure this
    // project has spent a fortnight cataloguing. These gates read HER numbers, not my defaults.
    {
      const CM246 = await import("../engine/craftmechanics.js");
      const sw = C199.abilities.shared_weight;
      check("CCODE-246b: the interception craft exists and authors `interceptCondition`",
        !!sw && !!CM246.authoredBlock(sw, "interceptCondition", 1));
      if (sw) {
        const P = (r) => IC.protectionFromCraft(sw, r, { protectorId: "tank", allyId: "ally", authoredBlock: CM246.authoredBlock });
        const [a1, a2, a3] = [P(1), P(2), P(3)];
        // ⚠️ READ RANK-FIRST. The field is authored on the RANK; a reader at the ability level finds
        // nothing for all three tiers, forever (§45.1, the sixth instance).
        check("CCODE-246b: all three ranks resolve their authored spec — read rank-first, not off the ability",
          !!a1 && !!a2 && !!a3);
        check("CCODE-246b: r1 is her one charge and no duration",
          a1.chargesLeft === 1 && a1.roundsLeft === null && a1.reflects === false);
        check(`CCODE-246b: r2 is her sustained form — ${a2.roundsLeft} rounds, +${a2.resistBonus} resist, no charge limit`,
          a2.chargesLeft === null && a2.roundsLeft === 6 && a2.resistBonus === 2);
        check("CCODE-246b: r3 reflects, and reflection is AUTHORED rather than inferred from the rank",
          a3.reflects === true && a2.reflects === false);
        // ⛔ HER NUMBERS BEAT MY DEFAULTS. `openProtection` infers from rank for a craft that authors a
        // partial spec; where she wrote a number, the number wins. Otherwise this is a second opinion
        // wearing a reader's clothes.
        // ⚠️ A SYNTHETIC CRAFT, BECAUSE HERS CANNOT DISTINGUISH THIS. `shared_weight` reflects at r3 and
        // the heuristic `rank >= 3` agrees, so a mutation inferring reflection FROM THE RANK survives
        // against her content. Only a craft that DISAGREES with the heuristic tests the claim.
        // ⛔ AND MY FIRST ATTEMPT AT THIS GATE WAS ITSELF WRONG: I asserted a craft could reflect at r1 and
        // NOT at r3, which the additive model forbids — a rank never removes a capability, so `authoredBlock`
        // correctly carries r1's declaration up to r3. The distinguishing case is a craft that reflects
        // EARLY, where the rank heuristic would refuse.
        const early = { id: "early", tree: [{ rank: 1, interceptCondition: { allies: 1 }, reflectCondition: true }] };
        const never = { id: "never", tree: [{ rank: 1, interceptCondition: { allies: 1 } }, { rank: 3, interceptCondition: { allies: 1 } }] };
        const mk246 = (ab, r) => IC.protectionFromCraft(ab, r, { protectorId: "t", allyId: "a", authoredBlock: CM246.authoredBlock });
        check("CCODE-246b: reflection follows the AUTHORED field, not the rank — a craft reflects at r1 if it says so, and never if it does not",
          mk246(early, 1).reflects === true && mk246(never, 3).reflects === false);

        const dflt = IC.openProtection({ protectorId: "t", allyId: "a", rank: 2 });
        check(`CCODE-246b: the AUTHORED duration overrides the default (${a2.roundsLeft} authored vs ${dflt.roundsLeft} inferred)`,
          a2.roundsLeft !== dflt.roundsLeft);
      }
    }

    // ⚠️ AND NOBODY IN FRONT MEANS NOTHING CHANGES — this must be additive, not a rewrite of the path.
    check("CCODE-246: with no protection standing, the redirect returns null and the caller proceeds as before",
      IC.redirectImposition({ aimedAt: "nobody", protections: [], sheets, imposition: imp, degree: "success" }) === null);
  }

  // 5af · ⛔ CCODE-250 / Erik — A FOE CHOOSES WHO TO HIT, AND YOU HAVE TO LOOK TO KNOW.
  // Erik: "Yes a foe chooses who to hit... this makes the sense round even more interesting - you need to
  // sense who's getting attacked so you can intervene if you want.... if you obscure yourself you aren't
  // going to know that information."
  // Until this, `oppDecl` resolved against `playerSheet` and nothing was aimed anywhere — which meant
  // `intercept.js` (CCODE-246) protected against a blow that could never have been coming for an ally.
  {
    const TG = await import("../engine/targeting.js");
    const SN = await import("../engine/sense.js");
    const { battleRound } = await import("../engine/skill_battle.js");
    const CONTENT = { rules: JSON.parse(readFileSync(join(root, "content/packs/core/rules/resolution.json"), "utf8")),
      skillBattle: JSON.parse(readFileSync(join(root, "content/packs/core/rules/skill_battle_system.json"), "utf8")),
      steps: JSON.parse(readFileSync(join(root, "content/packs/core/rules/craft_mechanics.json"), "utf8")) };
    const party = [
      { id: "player", name: "Wren", contributions: ["HARM","MARTIAL"], threatDealt: 12, sheet: { attributes: { physical: 8 }, level: 9 } },
      { id: "sprig", name: "Sprig", contributions: ["RESTORE"], sheet: { attributes: { mental: 2 }, level: 4 } },
      { id: "veth", name: "Veth", contributions: ["PROTECT","HARM","MARTIAL"], threatDealt: 4, sheet: { attributes: { physical: 7 }, level: 12 } },
    ];

    // ⛔ THE GATE I WROTE FIRST AND WOULD KEEP: with nobody else present, a round is what it always was.
    const solo = TG.chooseTarget([party[0]], { policy: "weakest" });
    check("CCODE-250: a lone target is not a choice — the 1v1 path is untouched",
      solo.policy === "only" && solo.target.id === "player");

    // ⚠️ AND THE ENGINE-LEVEL VERSION OF THAT SAME CLAIM: no `allies` means no aim on the receipt at all,
    // so every existing caller, save and receipt reads exactly as before.
    check("CCODE-250: battleRound with no allies attaches no targetChoice — additive, not a rewrite",
      (() => { const r = battleRound({ playerDecl: { function: "harm", name: "strike", dice: "1d6" },
          oppDecl: { function: "harm", name: "strike", dice: "1d6" },
          playerSheet: { attributes: { physical: 5 }, energy: 20 }, oppSheet: { attributes: { physical: 5 }, energy: 20 },
          rules: CONTENT.rules, sb: CONTENT.skillBattle.engine, steps: CONTENT.steps, rng: () => 0.5 });
        return r.opponent.targetChoice === undefined && r.aimedAt === undefined; })());

    // ⛔ THE POLICIES ARE DIFFERENT ANSWERS, not one answer with labels. If they all picked the same ally
    // the whole mechanic would be decoration.
    const picks = ["threat","weakest","healer"].map(p => TG.chooseTarget(party, { policy: p }).target.id);
    check("CCODE-250: the policies genuinely disagree — a predator, a tactician and a veteran pick differently",
      picks[0] === "player" && picks[1] === "sprig" && picks[2] === "sprig" && new Set(picks).size === 2);
    // ⚠️ AND `threat` IS THE DEFAULT ON PURPOSE — a foe that always went for the softest target would make
    // every fight the same fight. Going for what hurts it is BAIT-ABLE, which is a decision.
    check("CCODE-250: the default is threat, and it is bait-able — drop your threat and it looks elsewhere",
      TG.chooseTarget(party).target.id === "player"
      && TG.chooseTarget([{ ...party[0], threatDealt: 0, contributions: [] }, party[1], party[2]]).target.id === "veth");

    // ⛔ THE DOWNED ARE NOT TARGETS.
    check("CCODE-250: something already out of the fight is not swung at again",
      TG.chooseTarget([{ ...party[1], downed: true }, party[2]], { policy: "weakest" }).target.id === "veth");

    // ═══ ERIK'S TRADE, WHICH IS THE POINT OF THE WHOLE FILE ═══
    const choice = TG.chooseTarget(party, { policy: "healer" });
    const asWren = t => TG.revealTarget(choice, t, { viewerId: "player" });
    check("CCODE-250: tier 0 — the character who OBSCURED instead of reading learns nothing at all",
      asWren(0).known === false && asWren(0).targetName === undefined && asWren(0).someoneElse === undefined);
    check("CCODE-250: tier 1 — a weak read tells you only that it is not looking at YOU",
      asWren(1).known === false && asWren(1).someoneElse === true);
    check("CCODE-250: tier 2 — a real read NAMES the mark, which is what makes stepping in front possible",
      asWren(2).known === true && asWren(2).targetName === "Sprig" && asWren(2).reason === undefined);
    check("CCODE-250: tier 3 — a decisive read says WHY, and the why is what lets you bait it next round",
      asWren(3).known === true && typeof asWren(3).reason === "string" && asWren(3).reason.length > 5);

    // ⛔ THE PRICE, STATED AS A MECHANIC: hiding protects you and blinds you. A tank who obscures is safe
    // and useless. That is a decision every single round, and it did not exist before this build.
    check("CCODE-250: you cannot intervene for someone you did not see targeted — obscuring FORFEITS the save",
      TG.canInterveneFor(asWren(0)) === false && TG.canInterveneFor(asWren(1)) === false
      && TG.canInterveneFor(asWren(2)) === true);
    check("CCODE-250: …and you never 'intervene' for yourself — that is just defending",
      TG.canInterveneFor(TG.revealTarget(TG.chooseTarget(party, { policy: "threat" }), 3, { viewerId: "player" })) === false);

    // ⛔ READER BEFORE FIELD, AND THEN THE FIELD. The ladder is content-dialled; tier 0's authored reveals
    // must NOT contain "target" or the obscurer's blindness evaporates silently.
    const vis = CONTENT.skillBattle.engine.senseVisibility;
    check("CCODE-250: the reveal is AUTHORED onto the ladder at 1/2/3 — and deliberately absent at tier 0",
      !vis["0"].reveals.includes("target") && vis["1"].reveals.includes("target")
      && vis["2"].reveals.includes("target") && vis["3"].reveals.includes("target"));

    // ⚠️ AND THE READER IS REACHED. A field authored and never read is this project's commonest defect and
    // I have shipped it repeatedly — so the gate goes through senseOpponent itself, not past it.
    const oppReceipt = { margin: 3, function: "harm", name: "gutting blow", targetChoice: choice };
    const seen = t => SN.senseOpponent({ id: "player" }, oppReceipt, CONTENT.rules, CONTENT.skillBattle.engine, { earnedTier: t });
    check("CCODE-250: senseOpponent ITSELF surfaces the aim — the reveal is wired, not merely authored",
      seen(2).revealed.target?.targetName === "Sprig" && seen(3).revealed.target?.reason
      && seen(0).revealed.target === undefined);
    // ⛔ AND THE REVEAL CARRIES THE ANSWER THE UI NEEDS — not just "who", but "can I do anything about it".
    check("CCODE-250: the reveal itself says whether you may step in — the option is EARNED by the read",
      seen(2).revealed.target?.canIntervene === true && seen(1).revealed.target?.canIntervene === false);
    // and with no aim on the receipt (a 1v1), the fog is exactly what it was
    check("CCODE-250: a receipt carrying no aim yields no target reveal at any tier",
      SN.senseOpponent({ id: "player" }, { margin: 3, function: "harm" }, CONTENT.rules, CONTENT.skillBattle.engine, { earnedTier: 3 }).revealed.target === undefined);

    // ═══ THE SEAT: the opponent's blow lands on whoever it was aimed at ═══
    // ⛔ THIS IS THE CLAIM THAT MATTERS. Before today, the lines of `battleRound` that say "the player eats
    // it" said `playerSheet`. The player here is armoured to 99 and the soft ally has no soak at all, so if
    // the blow still resolved against the player it would be blunted to nothing. A LANDED HIT PROVES THE SWAP.
    const softAlly = { attributes: { mental: 1, physical: 2, social: 1, practical: 1 }, level: 2, health: 20, maxHealth: 20, soak: 0 };
    const armored = { id: "player", attributes: { mental: 2, physical: 3, social: 2, practical: 2 }, level: 3, health: 30, maxHealth: 30, soak: 99 };
    const bruiser = { attributes: { mental: 9, physical: 12, social: 6, practical: 6 }, level: 10, health: 40, maxHealth: 40, soak: 0 };
    const seat = (allies) => battleRound({
      playerDecl: { function: "defend", tier: 1, attribute: "physical", intensity: "standard", name: "guard" },
      oppDecl: { function: "strike", tier: 3, attribute: "physical", intensity: "heavy", name: "cleave" },
      playerSheet: armored, oppSheet: bruiser, allies, targetPolicy: "weakest",
      state: { momentum: 0, round: 1, playerEnergy: 100, opponentEnergy: 100, effects: [], pressure: { player: 0, opponent: 0 } },
      rules: CONTENT.rules, sb: CONTENT.skillBattle.engine, steps: CONTENT.rules.resolution || {}, rng: () => 0.5 });
    const withParty = seat([{ id: "player", name: "Wren", contributions: ["HARM","MARTIAL"], threatDealt: 12, sheet: armored },
                            { id: "sprig", name: "Sprig", contributions: ["RESTORE"], sheet: softAlly }]);
    const alone = seat(null);
    check("CCODE-250: with a party present the round records WHO it was aimed at",
      withParty.aimedAt?.target?.id === "sprig" && withParty.opponent.targetChoice?.target?.name === "Sprig");
    // ⚠️ CCODE-290: THIS EXPECTED 0 AND NOW EXPECTS THE FLOOR. Erik ruled that a guard ABSORBS, and Aevi's
    // condition on it was that absorption must never stack into immunity — "minHit already says no foe is
    // immune; the same floor must hold when the soak is on the player's side." So an armoured-to-99 player
    // takes the MINIMUM, not nothing. ⛔ THE ASSERTION'S POINT IS UNCHANGED and still proves the seat
    // swapped: the armoured player is blunted to the floor while the soft ally takes the full blow.
    check("CCODE-250: …and the SOAK that blunts it is the TARGET'S, not the player's — the seat really swapped",
      alone.damage?.amount <= 1 && alone.damage?.soak === 99
      && withParty.damage?.amount > alone.damage?.amount,
      `alone=${alone.damage?.amount} party=${withParty.damage?.amount}`);
    // ⛔ AND THE RECEIPT NAMES THE BEARER. The arithmetic moving without the routing moving would have
    // applied an ally's wound to the player's health — a swap that balances and still lies.
    check("CCODE-250: the receipt says WHO it landed on, not merely which side — the wound has an owner",
      withParty.damage?.onId === "sprig" && withParty.damage?.onName === "Sprig"
      && alone.damage?.onId === undefined);

    // ═══ ⛔ THE JOIN: the whole chain, in one round ═══
    // Read the aim → know who is for it → stand in front of them → the blow lands on YOU instead.
    // ⚠️ I SHIPPED `intercept.js` (CCODE-246) AGAINST NOTHING. Every one of its gates passed on synthetic
    // protections while, in an actual round, no blow was ever aimed anywhere but the player — so there was
    // never anything to intercept. This is the gate that says the mechanism is reachable from play.
    {
      const IC = await import("../engine/intercept.js");
      const tankSheet = { attributes: { mental: 12, physical: 12, social: 6, practical: 6 }, level: 12, health: 40, maxHealth: 40, soak: 0 };
      const roster = [
        { id: "player", name: "Wren", contributions: ["HARM","MARTIAL"], threatDealt: 1, sheet: armored },
        { id: "sprig", name: "Sprig", contributions: ["RESTORE"], sheet: softAlly },
        { id: "veth", name: "Veth", contributions: ["PROTECT","MARTIAL"], threatDealt: 2, sheet: tankSheet },
      ];
      const binder = { function: "strike", tier: 3, attribute: "physical", intensity: "heavy", name: "binding cleave",
        tree: [{ rank: 1, imposes: { condition: "action_loss", resist: "physical", threshold: 1, degradesTo: "slowed", onCrit: "unconscious" } }], rank: 1 };
      const round = (protections) => battleRound({
        playerDecl: { function: "defend", tier: 1, attribute: "physical", intensity: "standard", name: "guard" },
        oppDecl: binder, playerSheet: armored, oppSheet: bruiser,
        allies: roster, targetPolicy: "weakest", protections,
        state: { momentum: 0, round: 1, playerEnergy: 100, opponentEnergy: 100, effects: [], pressure: { player: 0, opponent: 0 } },
        rules: CONTENT.rules, sb: CONTENT.skillBattle.engine, steps: CONTENT.rules.resolution || {}, rng: () => 0.5 });

      const unguarded = round(null);
      check("CCODE-250 JOIN: unprotected, the imposition lands on the ally the foe chose",
        unguarded.imposed?.onId === "sprig" && !unguarded.imposed?.intercepted,
        JSON.stringify(unguarded.imposed ?? null));

      // Veth read the round, saw the aim, and put herself between it and Sprig.
      const guarded = round([IC.openProtection({ protectorId: "veth", allyId: "sprig", rank: 2 })]);
      check("CCODE-250 JOIN: with a protection standing, the SAME blow lands on the protector instead",
        guarded.imposed?.intercepted?.caughtBy === "veth" && guarded.imposed?.onId === "veth"
        && guarded.imposed?.intercepted?.onBehalfOf === "sprig",
        JSON.stringify(guarded.imposed ?? null));
      // ⚠️ AND THE RECEIPT SAYS SO BY NAME — "a tank mechanic nobody can see is a tank mechanic nobody thanks."
      check("CCODE-250 JOIN: the round names the protector, so the save is visible to the player who made it",
        guarded.imposed?.onName === "Veth" && typeof guarded.imposed?.intercepted?.why === "string");
      // ⛔ A PROTECTION OVER THE WRONG ALLY CATCHES NOTHING. Standing in front of the person nobody is
      // swinging at is exactly the cost of a bad read, which is what makes the read worth making.
      check("CCODE-250 JOIN: guarding the wrong ally saves nobody — a bad read costs you the round",
        round([IC.openProtection({ protectorId: "veth", allyId: "player", rank: 2 })]).imposed?.onId === "sprig");
    }


  }

  // 5ag · ⛔ CCODE-251 — DIFFERENT LEVELS OF RESOLUTION FOR DIFFERENT SCALES OF FIGHT.
  // Erik, who explicitly did NOT decide this: "we might be able to simplify things at certain levels... like
  // if we have more than 3 party members the rest go into a melee flow that isn't as specific... then if we
  // have a legion, how does that work? we need different levels of resolve for these levels of battle or
  // contest." — and: "we should think this through and test it."
  {
    const ML = await import("../engine/melee.js");

    // ⛔ ERIK'S BOUNDARIES, NOT MINE. "more than 3 party members" and "a legion" are his words; the table is
    // content-dialled so moving them is a design decision rather than an engine change.
    check("CCODE-251: the tiers are Erik's boundaries — 3 is still a skirmish, 4 drops into the melee flow",
      ML.resolutionTier(3, 1).id === "skirmish" && ML.resolutionTier(4, 1).id === "melee"
      && ML.resolutionTier(3, 1).resolve === "full");
    // ⚠️ AND IT COUNTS COMBATANTS, NOT ALLIES. Two of you against forty is a legion fight; calling it a
    // skirmish because the PARTY is small would be the whole error.
    check("CCODE-251: two allies against forty is a LEGION, not a skirmish — scale is the fight, not the party",
      ML.resolutionTier(2, 40).id === "legion" && ML.resolutionTier(2, 1).id === "skirmish");
    check("CCODE-251: in a melee you and those you bring forward act; in a legion you are one figure",
      ML.actingSlots(ML.resolutionTier(3, 1)) === Infinity && ML.actingSlots(ML.resolutionTier(8, 1)) === 3
      && ML.actingSlots(ML.resolutionTier(80, 1)) === 1);

    // ⛔ THE ONE PIECE OF MATHS, AND THE MISTAKE IT EXISTS TO PREVENT.
    // K combatants taking a turn is a SUM of K rounds: the MEAN scales with K, the SPREAD with √K.
    // ⚠️ `scripts/scale_fidelity.mjs` measures ONE combatant through the real `battleRound` and checks the
    // prediction against K real rounds — worst divergence over K=1..50 is 1.0% mean / 1.2% sd. Mutating √K
    // to K there leaves the MEAN at 1.0% and blows the SPREAD to 614%, which is exactly why the naive
    // version is dangerous: it is invisible to anyone checking averages, and it is how a party that
    // recruits a fourth member starts seeing wipes the party of three never saw.
    const one = { mean: 3.4, sd: 2.93 };
    const p4 = ML.predictAggregate(one, 4), p16 = ML.predictAggregate(one, 16);
    check("CCODE-251: the mean scales with K and the SPREAD with √K — four combatants are 4× as deadly and 2× as swingy",
      Math.abs(p4.mean - 13.6) < 0.1 && Math.abs(p4.sd - one.sd * 2) < 0.01
      && Math.abs(p16.sd - one.sd * 4) < 0.01);
    // ⛔ THE NON-VACUITY FLOOR: the two models must actually DIVERGE, or this gate passes on a coincidence.
    check("CCODE-251: …and √K is meaningfully different from K at party scale — the gate is not vacuous",
      p4.sd < one.sd * 4 * 0.6 && p16.sd < one.sd * 16 * 0.3);

    // ⛔ AN AGGREGATE THAT NEVER NAMES A CASUALTY IS A NUMBER, NOT A FIGHT.
    // Erik: "the pc playing into and being a casualty of that melee."
    const crowd = [
      { id: "a", name: "Ander", sheet: { attributes: { physical: 3 }, level: 2, soak: 0, health: 8 } },
      { id: "b", name: "Bree", sheet: { attributes: { physical: 5 }, level: 4, soak: 4, health: 25 } },
      { id: "c", name: "Corr", sheet: { attributes: { physical: 4 }, level: 3, soak: 2, health: 20 } },
    ];
    const spread = ML.distributeCasualties(crowd, 18, { rng: () => 0.5 });
    check("CCODE-251: the pool lands on NAMED people, softest first — a crowd behaves like people, not a health bar",
      spread.hits.length >= 2 && spread.hits[0].name === "Ander"
      && spread.hits.reduce((s, h) => s + h.amount, 0) <= 18);
    // ⚠️ AND IT SPREADS RATHER THAN CONCENTRATES. One aggregate blow must not vaporise the softest ally in a
    // round that, resolved fully, would have been several separate ordinary hits.
    check("CCODE-251: no single member eats the whole pool — the aggregate spreads what full turns would have spread",
      spread.hits[0].amount < 18);
    check("CCODE-251: the downed are named too — an ally lost in the crowd is still an ally lost",
      ML.distributeCasualties([crowd[0]], 40, { rng: () => 0.9 }).downed[0]?.name === "Ander");
    // ⚠️ NOTHING TO DISTRIBUTE MEANS NOTHING HAPPENS — the additive floor.
    check("CCODE-251: an empty pool wounds nobody",
      ML.distributeCasualties(crowd, 0).hits.length === 0);

    // ⛔ A LEGION IS NOT A BIGGER MELEE. At this scale the individual roll stops meaning anything, and a
    // model where the player can out-damage an army is not a legion — it is a melee with big numbers.
    const ours = [{ count: 200, quality: 1 }], theirs = [{ count: 200, quality: 1 }];
    const even = ML.legionClash(ours, theirs, { rng: () => 0.5 });
    check("CCODE-251: evenly matched legions grind — nobody breaks through on parity",
      even.outcome === "grinding" && Math.abs(even.ratio - 1) < 0.01);
    check("CCODE-251: weight of numbers decides it — 3:1 breaks through, 1:3 routs",
      ML.legionClash([{ count: 600, quality: 1 }], theirs, { rng: () => 0.5 }).outcome === "breakthrough"
      && ML.legionClash(ours, [{ count: 600, quality: 1 }], { rng: () => 0.5 }).outcome === "rout");
    // ⛔ THE HERO MOVES IT, AND IS BOUNDED. A player who cannot shift the battle is watching a cutscene; a
    // player who decides it alone did not need the legion.
    const big = ML.legionClash(ours, theirs, { rng: () => 0.5, heroSwing: 5 });
    check("CCODE-251: a hero shifts a legion by a BOUNDED amount — 5 is clamped to the cap, not honoured",
      big.heroSwing === 0.15 && big.heroSwing < 5);
    check("CCODE-251: …and that bound is enough to matter on a knife-edge and not enough to win a lost battle",
      ML.legionClash(ours, theirs, { rng: () => 0.5, heroSwing: 0.15 }).outcome === "gaining"
      && ML.legionClash(ours, [{ count: 600, quality: 1 }], { rng: () => 0.5, heroSwing: 0.15 }).outcome === "rout");
    // ⚠️ AND THE TIDE CAN TAKE YOU REGARDLESS — "being a casualty of that melee". A won battle that cannot
    // cost you anything personally is a number going up.
    check("CCODE-251: personal risk tracks the TIDE, not your own roll — you can die in a battle you are winning",
      ML.legionClash(ours, [{ count: 600, quality: 1 }], { rng: () => 0.5 }).personalRisk
        > ML.legionClash([{ count: 600, quality: 1 }], theirs, { rng: () => 0.5 }).personalRisk
      && ML.legionClash([{ count: 600, quality: 1 }], theirs, { rng: () => 0.5 }).personalRisk > 0);
    // ⛔ MASSED ENGAGEMENTS ARE LESS SWINGY, NOT MORE — the same √K logic, one scale up. A thousand men do
    // not all get lucky at once, and a legion model with duel-sized variance is a coin flip with scenery.
    {
      const draws = Array.from({ length: 2000 }, (_, i) => {
        let s = (i * 2654435761) >>> 0; const rng = () => (s = (s * 1664525 + 1013904223) >>> 0) / 4294967296;
        return ML.legionClash(ours, theirs, { rng }).tide; });
      const m = draws.reduce((a, b) => a + b, 0) / draws.length;
      const sd = Math.sqrt(draws.reduce((a, b) => a + (b - m) ** 2, 0) / draws.length);
      check("CCODE-251: legion outcomes cluster — three averaged draws, so a big battle is decided by weight, not luck",
        Math.abs(m) < 0.02 && sd < 0.06, `mean ${m.toFixed(3)} sd ${sd.toFixed(3)}`);
    }
  }

  // 5ah · ⛔ CCODE-252 — A LADDER MADE OF WORDS THE CORPUS DOES NOT USE.
  //
  // Found while reviewing Aevi's `SPEC_craft_lint.md`, whose central rule is "EVERY CHECK CITES THE SCHEMA IT
  // MEASURES AGAINST — a finding that cannot name its authority is not a finding." ⚠️ I PROMPTLY BROKE THAT
  // RULE WHILE REVIEWING IT: I measured harmRung against `light/moderate/severe/mortal`, a vocabulary I
  // invented on the spot. When I went to find the real authority, `engine/braids.js` turned out to have done
  // the same thing and shipped it.
  //
  // `HARM_ORDER` read ["none","restraint","wounding","lethal","atrocity"]. The corpus authors FOUR values and
  // only TWO were in both lists — so `indexOf` returned -1 for `damaging` and `incapacitating`, sorting them
  // BELOW `none`. ⛔ "harsher parent sets the braid's rung" did the exact opposite of what it said.
  {
    const BR = readFileSync(join(root, "engine/braids.js"), "utf8");
    const m = BR.match(/const HARM_ORDER = \[([^\]]+)\]/);
    const ladder = m ? m[1].split(",").map(s => s.trim().replace(/^"|"$/g, "")) : [];

    // ⛔ THE CHECK THAT WOULD HAVE CAUGHT IT, AND IT IS THE ONE AEVI'S SPEC IS BUILT AROUND: the ladder must
    // contain every value CONTENT ACTUALLY AUTHORS. Derived from the corpus, so it cannot go stale against it.
    const authored = new Set();
    for (const f of readdirSync(join(root, "content/packs/core/abilities")).filter(f => f.endsWith(".json"))) {
      const j = JSON.parse(readFileSync(join(root, "content/packs/core/abilities", f), "utf8"));
      for (const a of (j.abilities || j.items || [])) {
        if (a.harmRung) authored.add(String(a.harmRung));
        for (const t of (a.tree || [])) if (t.harmRung) authored.add(String(t.harmRung));
      }
    }
    // ⚠️ NON-VACUITY FLOOR: a corpus that authored nothing would pass this trivially.
    check("CCODE-252: the corpus authors a real harmRung vocabulary (floor — an empty set would pass anything)",
      authored.size >= 3 && authored.has("damaging") && authored.has("none"));
    const orphans = [...authored].filter(v => !ladder.includes(v));
    check("CCODE-252: every harmRung the CORPUS authors exists on the engine's ladder — no value sorts as -1",
      orphans.length === 0, `on no ladder rung: ${orphans.join(", ")} · ladder = ${ladder.join("/")}`);

    // ⛔ AND THE BEHAVIOUR, NOT JUST THE LIST. A ladder can contain every word and still be ordered wrongly.
    const pick = (rungs) => rungs.map(s => s || "none")
      .sort((a, b) => ladder.indexOf(b) - ladder.indexOf(a))[0] || "none";
    check("CCODE-252: a wounding parent braided with a harmless one yields a WOUNDING braid — the comment is now true",
      pick(["damaging", "none"]) === "damaging" && pick(["none", "damaging"]) === "damaging"
      && pick(["none", "incapacitating"]) === "incapacitating" && pick(["lethal", "none"]) === "lethal");
    check("CCODE-252: …and two harmless parents still braid to harmless — the fix is not a blanket escalation",
      pick(["none", "none"]) === "none");

    // ⛔ THE SEVEN SHIPPED BRAIDS THAT CLAIMED TO HARM NOTHING. `harmRungGloss("none")` tells the GM
    // "this craft HARMS NOTHING — NEVER invent a wound from it", which was false for every one of these.
    {
      const abil = {};
      for (const f of readdirSync(join(root, "content/packs/core/abilities")).filter(f => f.endsWith(".json"))) {
        const j = JSON.parse(readFileSync(join(root, "content/packs/core/abilities", f), "utf8"));
        for (const a of (j.abilities || j.items || [])) abil[a.id] = a;
      }
      const recipes = JSON.parse(readFileSync(join(root, "content/packs/core/rules/combination_recipes.json"), "utf8")).recipes || [];
      const resolvable = recipes.filter(r => (r.parts || []).map(p => abil[p]).filter(Boolean).length >= 2);
      // ⚠️ NON-VACUITY AGAIN: if `parts` stopped resolving, this whole check would pass on an empty list —
      // which is exactly how I measured 0 the first time and nearly concluded the bug was harmless.
      check("CCODE-252: the braid recipes actually resolve their parts (floor — 0 resolvable would pass anything)",
        resolvable.length >= 20, `resolvable: ${resolvable.length} of ${recipes.length}`);
      const understated = resolvable.filter(r => {
        const rungs = r.parts.map(p => abil[p]?.harmRung || "none");
        return pick(rungs) === "none" && rungs.some(x => x !== "none");
      });
      check("CCODE-252: no braid is minted 'harms nothing' while a parent wounds — seven were, before this",
        understated.length === 0, `still understated: ${understated.map(r => r.id).join(", ")}`);
    }
  }





  // 5ae · ⛔ CCODE-247 — WHO IS IN A CONTEST, AND WHAT THEY BRING TO IT.
  //
  // ⚠️ MY FIRST VERSION ASKED A YES/NO QUESTION AND ERIK CORRECTED IT: "the answer is YES — as they are
  // able… they support, heal, distract, etc. — so they literally are part of the fights anyway." I had
  // measured six of nine companions saying "cannot fight" and concluded they were bystanders. They are
  // participants who do not swing, and the tags saying so were on the records the whole time.
  {
    const CB = await import("../engine/combatants.js");

    // ⛔ EVERY AUTHORED COMPANION CONTRIBUTES SOMETHING. Not one is a bystander.
    const contribs = Object.values(C199.companions).map(c => CB.contributionsOf(c));
    check(`CCODE-247: all ${contribs.length} authored companions bring something to a contest — none is a bystander`,
      contribs.every(c => c.length > 0), contribs.map(c => c.length).join(","));
    // ⛔ AND NOT ONE OF THE 30 AUTHORED TAGS MEANS `HARM`. Everyone is in the fight; almost nobody is in it
    // by hitting — which is the finding, not an oversight.
    // ⛔ ERIK CORRECTED THIS TWICE AND BOTH TIMES THE SAME WAY. I first asked whether a companion could
    // fight; then I gated HARM behind a fighting OCCUPATION, and he answered "um... Pell fights too... she
    // uses a spear, hammer, shortsword, brigandine." A blacksmith with a spear is a person with a spear.
    // ⚠️ AND THE ENGINE ALREADY AGREED: `playerBattleSkills` hands every character `_strike` — "A plain
    // strike" — with no craft, role or weapon required. I had built a permission system for something the
    // game has never asked permission for.
    check("CCODE-247: anyone with a body can swing — HARM is the default, not a privilege",
      CB.contributionsOf({ role: "archivist", assistTags: ["study"] }).includes("HARM"));
    check("CCODE-247: …and the exceptions are AUTHORED facts about a body, not about a job",
      !CB.contributionsOf({ role: "a swarm of motes", assistTags: ["analyze"], canStrike: false }).includes("HARM"));
    // ⚠️ `MARTIAL` MARKS WHO IS GOOD AT IT, which is a different question from who may.
    check("CCODE-247: a weapon, a fighting role or the `ally` role mark someone MARTIAL rather than permitted",
      CB.contributionsOf({ role: "smith", inventory: [{ kind: "weapon" }] }).includes("MARTIAL")
      && !CB.contributionsOf({ role: "archivist", assistTags: ["study"] }).includes("MARTIAL"));

    // ⛔ THE POPULATION ERIK MEANT: recruited NPCs carrying the `ally` role. company.js has held this
    // roster since SNG-126 and my first version never read it.
    const npcIds = Object.keys(C199.npcs);
    const ch247 = { id: "you", name: "Wren", level: 6,
      companions: [{ id: "sprig" }, { id: "bristle" }],
      company: [{ npcId: npcIds[0], roles: ["ally"], joinedDay: 3 },
        { npcId: npcIds[1], roles: ["trainer"], joinedDay: 5 }], party: [] };
    const allies = CB.alliesOf(ch247, { companions: C199.companions, npcs: C199.npcs });
    check("CCODE-247: a recruited NPC with the `ally` role is in the fight and brings HARM",
      allies.some(a => a.kind === "company" && a.contributions.includes("HARM")));
    // ⚠️ AND A TRAINER IS NOT A SOLDIER — the role decides, not the membership.
    check("CCODE-247: …while a TRAINER on the same roster is not marked MARTIAL — the role decides what they are GOOD at",
      allies.filter(a => a.kind === "company").some(a => !a.contributions.includes("MARTIAL")));
    check("CCODE-247: someone who has LEFT the company is not in the fight",
      CB.alliesOf({ ...ch247, company: [{ npcId: npcIds[0], roles: ["ally"], leftDay: 9 }] },
        { companions: C199.companions, npcs: C199.npcs }).every(a => a.kind !== "company"));

    // ⛔ PARTICIPATION IS NOT A BOOLEAN. Healing is acting; distracting is acting.
    check("CCODE-247: an entity that heals or distracts ACTS — the old yes/no excluded six of nine from a fight they were in",
      CB.contributionsOf({ assistTags: ["heal"] }).includes("RESTORE")
      && CB.contributionsOf({ assistTags: ["distract"] }).includes("INFLUENCE"));
    // ⚠️ AND THE ONLY WAY TO CONTRIBUTE NOTHING IS TO HAVE NO BODY. Everyone else can at least swing.
    check("CCODE-247: …and the only entity that brings nothing is one that cannot act at all",
      CB.canAct({ assistTags: [] }) === true
      && CB.canAct({ assistTags: [], canStrike: false }) === false);

    // ⚠️ THE TAG MAP IS CONTENT-SHAPED AND INJECTABLE — 30 tags is an authoring vocabulary, and hardcoding
    // it would make every future tag an engine change.
    check("CCODE-247: the tag→family map can be overridden by content",
      CB.contributionsOf({ assistTags: ["whistling"] }, { tagFamilies: { INFLUENCE: ["whistling"] } }).includes("INFLUENCE"));

    // ⛔ WHAT HAPPENS WHEN ONE IS TAKEN OUT — Erik: "for each we would need to determine what happens when
    // they're taken out, like anything else."
    const sprig = allies.find(a => a.id === "sprig");
    check("CCODE-247: an entity can be taken out, and stops acting when it is",
      CB.isDowned(sprig) === false
      && (CB.downEntity(sprig, { why: "dropped by keening", day: 7 }), CB.isDowned(sprig) === true));
    const standing = CB.standingContributions(allies);
    // ⛔ THE FIXTURE STOPPED ISOLATING RESTORE, AND THE CLAIM WAS WRITTEN AGAINST THE FIXTURE. This asserted
    // `!families.includes("RESTORE")` — true only while sprig was the ONLY restorer in the ally set. Aevi’s
    // assistTags sweep gave `adept_sona` the tag `tend`, so the side keeps RESTORE when sprig goes down and
    // the check went red on correct content.
    //
    // ⚠️ THE INTENT WAS NEVER ABOUT RESTORE. It is: what the downed entity took with it is REPORTED, and a
    // family only leaves the side when nobody standing still provides it. Both are asserted directly now, so
    // no amount of tagging can move them.
    {
      const gone = standing.lost.find(l => l.id === "sprig");
      const stillUp = allies.filter(a => !CB.isDowned(a)).flatMap(a => a.contributions || []);
      const onlyHis = (gone?.contributions || []).filter(f => !stillUp.includes(f));
      check("CCODE-247: …and the side SEES what went out of the fight with them — by name, with what they brought",
        !!gone && (gone.contributions || []).length > 0,
        JSON.stringify(gone || null));
      check("CCODE-247: …a family only leaves the side when NOBODY standing still provides it",
        onlyHis.every(f => !standing.families.includes(f))
        && standing.families.every(f => stillUp.includes(f)),
        `lost-alone ${JSON.stringify(onlyHis)} · standing ${JSON.stringify(standing.families)}`);
    }

    // ⚠️ TARGETABLE IS STILL WIDER THAN ACTING — the entity that cannot answer is the one interception is for.
    check("CCODE-247: everyone present is targetable, including anyone who is down",
      CB.targetableAllies(ch247, { companions: C199.companions, npcs: C199.npcs }).length === allies.length);

    // ⛔ THE JOIN: interception protects someone who cannot protect themselves.
    const IC247 = await import("../engine/intercept.js");
    const sheets247 = Object.fromEntries(allies.map(a => [a.id, a.sheet]));
    const prot = IC247.openProtection({ protectorId: "you", allyId: "sprig", rank: 2 });
    const caught = IC247.redirectImposition({ aimedAt: "sprig", sourceId: "foe", protections: [prot],
      sheets: sheets247, imposition: { condition: "unconscious", degradesTo: "action_loss" }, degree: "partial" });
    check("CCODE-247: an imposition aimed at the healer is caught by whoever is standing in front",
      !!caught && caught.caughtBy === "you" && caught.onBehalfOf === "sprig");
  }

  // 5ai · CCODE-253 — THE SEAT NOBODY SAT IN.
  //
  // CCODE-250 gave `battleRound` an `allies` seat, gated it thoroughly, and shipped it. Neither caller
  // filled it. So `chooseTarget` returned null on every round in the actual game, every reveal was absent,
  // and interception could still never fire — while twenty gates stayed green, because they all called
  // `battleRound` directly and passed `allies` themselves.
  //
  // I found it because `wiring_audit`'s testOnlyExports ratchet went 27 -> 31. I had run that audit and read
  // "4 failures, same as baseline" — the ratchet was ALREADY RED, so the failure COUNT did not move while
  // its VALUE got worse. A red check absorbs a regression silently, and I read the count, not the number.
  {
    const src = readFileSync(join(root, "engine/encounters.js"), "utf8");
    const strip = src.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
    check("CCODE-253: the encounter wrapper DERIVES the party and forwards it into the round",
      /targetableAllies\(/.test(strip) && /allies:/.test(strip));
    check("CCODE-253: …and it accepts the content it needs to resolve a roster stored as ids",
      /content = null/.test(strip) || /content,/.test(strip));
    // the app must actually hand it over, or the derivation resolves nothing
    const appSrc = readFileSync(join(root, "app.js"), "utf8");
    check("CCODE-253: the app passes CONTENT to the encounter wrapper — a derivation with no defs finds no party",
      /content: CONTENT/.test(appSrc));

    // THE BEHAVIOURAL CLAIM, THROUGH THE REAL WRAPPER rather than around it.
    const EN = await import("../engine/encounters.js");
    const sb253 = C199.skillBattle?.engine || C199.skillBattle || {};
    const rules253 = C199.rules || {};
    const mkChar = (companions) => ({ id: "player", name: "Wren", level: 6, energy: 100,
      attributes: { physical: 3, mental: 3, social: 3, practical: 3 }, health: 30, maxHealth: 30, companions });
    // ⚠️ `type: "duel"` and a sheet are what put this on the skill-battle path — without the type,
    // `startEncounter` returns null and my first version of this probe died on it rather than testing anything.
    const def253 = { id: "troll_fight", type: "duel", name: "the troll", opponent: { name: "the troll", health: 30, yieldAt: 0 } };
    const st253 = EN.startEncounter(def253, { oppSheet: { attributes: { physical: 9 }, level: 8, energy: 100, health: 30 } });
    check("CCODE-253: the probe is on the skill-battle path at all (floor — a null state tests nothing)",
      !!st253 && st253.mode === "skill_battle");
    const run = (character) => EN.skillBattleRound(st253, def253,
      { function: "defend", tier: 1, attribute: "physical", intensity: "standard", name: "guard" },
      { character, content: { companions: {}, npcs: {} }, rules: rules253, sb: sb253,
        steps: rules253.resolution || {}, rng: () => 0.5 });

    const alone253 = run(mkChar([]));
    // ⚠️ NON-VACUITY: if the wrapper threw or returned nothing, every claim below would pass on undefined.
    check("CCODE-253: the wrapper actually resolves a round (floor — a thrown wrapper would pass anything)",
      !!alone253 && (alone253.player != null || alone253.opponent != null || alone253.ended === true));
    check("CCODE-253: travelling ALONE, no aim is recorded — the solo game is untouched",
      !alone253?.opponent?.targetChoice);

    const withParty253 = run(mkChar([
      { id: "sprig", name: "Sprig", roles: ["ally"], attributes: { mental: 2 }, level: 3 },
      { id: "veth", name: "Veth", roles: ["ally"], attributes: { physical: 7 }, level: 9 } ]));
    check("CCODE-253: travelling WITH COMPANIONS, the foe picks one — reachable from play, not only from a test",
      !!withParty253?.opponent?.targetChoice?.target?.name,
      JSON.stringify(withParty253?.opponent?.targetChoice?.target?.name ?? null));
  }

  // 5aj · ⛔ CCODE-255 — THE FOE HAS TO READ YOU TOO.
  //
  // Erik: "i agree with the foe having to read you as well, in addition to being able to obscure your party."
  //
  // ⚠️ UNTIL THIS, A FOE PICKED ITS TARGET WITH PERFECT KNOWLEDGE OF YOUR SIDE. It knew who was softest and
  // who was mending, for free, every round — while you had to earn the same information with a read. The
  // sense step was one-directional, which made obscure a purely personal defence.
  {
    const TG = await import("../engine/targeting.js");
    const party = [
      { id: "player", name: "Wren", contributions: ["HARM","MARTIAL"], threatDealt: 12, sheet: { attributes: { physical: 8 }, level: 9 } },
      { id: "sprig", name: "Sprig", contributions: ["RESTORE"], sheet: { attributes: { mental: 2 }, level: 3 } },
    ];

    // ⛔ EACH POLICY NEEDS A DIFFERENT QUALITY OF LOOK, AND THEY RANK BY HOW CRUEL THEY ARE. That fell out of
    // the design rather than being imposed on it, and it is the part I would defend hardest.
    check("CCODE-255: a foe always knows who is HURTING it — being hit needs no read",
      // ⛔ CCODE-286: `blind` → `mindless` on Erik’s ruling ("blind is CAN’T SEE"). The word named this
      // policy AND the can’t-see receipt asserted further down at line ~19045, which correctly keeps it.
      TG.POLICY_NEEDS.threat === 0 && TG.POLICY_NEEDS.mindless === 0
      && TG.canonPolicy("blind") === "mindless");
    check("CCODE-255: judging who is WEAKEST needs a real look; finding the HEALER needs a better one",
      TG.POLICY_NEEDS.weakest === 1 && TG.POLICY_NEEDS.healer === 2
      && TG.POLICY_NEEDS.healer > TG.POLICY_NEEDS.weakest);

    // ═══ THE THING ERIK ASKED FOR: hiding your party stops the foe finding your healer ═══
    const hunt = (tier) => TG.chooseTarget(party, { policy: "healer", knowledge: TG.foeKnowledge(tier) });
    check("CCODE-255: a predator that wants the healer CANNOT FIND HER on a poor read",
      hunt(0).blinded === "healer" && hunt(0).target.id === "player"
      && hunt(1).blinded === "healer");
    check("CCODE-255: …and DOES find her once it has looked properly — the read is a real contest, not a ward",
      hunt(2).target.id === "sprig" && !hunt(2).blinded && hunt(3).target.id === "sprig");
    // ⛔ IT DEGRADES TO `threat`, NOT TO `blind`. A foe that has been blinded is not a foe that has become
    // random — it is a foe reduced to what it can still FEEL, which is whoever is hitting it. And whoever is
    // hitting it is the tank. ⚠️ THAT IS THE WHOLE POINT OF A TANK AND IT WAS PREVIOUSLY UNACHIEVABLE.
    check("CCODE-255: a blinded foe swings at whoever it can feel — which is the tank, by construction",
      hunt(0).policy === "threat" && hunt(0).target.contributions.includes("MARTIAL"));
    check("CCODE-255: the receipt records that the foe was DENIED, not merely that it chose the tank",
      typeof hunt(0).why === "string" && /could not pick out/.test(hunt(0).why));

    // ⚠️ NO KNOWLEDGE PASSED MEANS PERFECT KNOWLEDGE — every existing caller and gate is unchanged, and the
    // read is opt-in. A default that silently blinded every foe would have rebalanced the whole game quietly.
    check("CCODE-255: omitting knowledge keeps today's behaviour exactly — the read is opt-in",
      TG.chooseTarget(party, { policy: "healer" }).target.id === "sprig"
      && !TG.chooseTarget(party, { policy: "healer" }).blinded);
    // ⛔ NON-VACUITY: the two paths must actually differ, or every claim above passes on a coincidence.
    check("CCODE-255: …and blinded-vs-not genuinely pick different people (floor)",
      TG.chooseTarget(party, { policy: "healer" }).target.id !== hunt(0).target.id);

    // ═══ THROUGH THE ROUND: the foe's read is EARNED in the sense step and SPENT in the action step ═══
    const { battleRound: BR255 } = await import("../engine/skill_battle.js");
    const rules255 = C199.rules || {}, sb255 = C199.skillBattle?.engine || {};
    const sheetsP = { attributes: { physical: 6, mental: 6 }, level: 6, health: 30, maxHealth: 30, soak: 0 };
    const sheetsO = { attributes: { physical: 5, mental: 4 }, level: 5, health: 30, maxHealth: 30, soak: 0 };
    const senseRound = (playerDecl) => BR255({
      playerDecl, oppDecl: { function: "reveal", tier: 2, attribute: "mental", intensity: "standard", name: "study them" },
      playerSheet: sheetsP, oppSheet: sheetsO, phase: "sense",
      state: { momentum: 0, round: 1, playerEnergy: 100, opponentEnergy: 100, effects: [], pressure: { player: 0, opponent: 0 } },
      rules: rules255, sb: sb255, steps: rules255.resolution || {}, rng: () => 0.5 });
    const open = senseRound({ function: "reveal", tier: 2, attribute: "mental", intensity: "standard", name: "read them", sense: true });
    const hidden = senseRound({ function: "conceal", tier: 2, attribute: "mental", intensity: "standard", name: "go quiet", obscure: true });
    check("CCODE-255: the sense step now emits how well the FOE read you — the mirror of your own tier",
      Number.isFinite(open.foeReadTier) && Number.isFinite(hidden.foeReadTier));
    check("CCODE-255: and spending your step HIDING costs them their read — the trade runs both ways",
      hidden.foeReadTier < open.foeReadTier,
      `hidden ${hidden.foeReadTier} vs open ${open.foeReadTier}`);

    // ⛔ AND THE SEAM. `foeReadTier` is earned in one step and spent in the next, so a wrapper that merely
    // REPORTS it has still dropped it — it must ride back in. This seam has eaten a value five times now.
    const encSrc = readFileSync(join(root, "engine/encounters.js"), "utf8");
    const encStrip = encSrc.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
    check("CCODE-255: the wrapper carries the foe's read BOTH ways — out on the receipt AND back in on state",
      (encStrip.match(/foeReadTier/g) || []).length >= 3);
  }

  // 5ak · CCODE-256 — CONCEAL HIDES YOU, AND PROVOKE WORKS ON ANYONE.
  // Erik, two rulings: "A successful conceal can also make people untargetable - or at least have it be very
  // difficult to actually hit them." and "Seems like you should be able to provoke even those without a
  // 'line'."
  {
    const TG = await import("../engine/targeting.js");
    const CM = await import("../engine/craftmechanics.js");
    const party = [
      { id: "player", name: "Wren", contributions: ["HARM","MARTIAL"], threatDealt: 12, sheet: { attributes: { physical: 8 }, level: 9 } },
      { id: "sprig", name: "Sprig", contributions: ["RESTORE"], concealment: 2, sheet: { attributes: { mental: 2 }, level: 3 } },
    ];
    const hunt = (tier, extra = {}) => TG.chooseTarget(party, { policy: "healer", knowledge: TG.foeKnowledge(tier), rng: () => 0.4, ...extra });

    // ⛔ UNTARGETABLE, not merely un-preferred. CCODE-255 blinded the foe's JUDGEMENT; Erik asked for the
    // stronger thing — a well-hidden entity is not on the list at all.
    check("CCODE-256: a concealed ally is not a candidate at all while the foe's read is below her cover",
      hunt(0).target.id === "player" && hunt(1).target.id === "player" && hunt(1).hiddenFrom === 1);
    check("CCODE-256: …and a good enough read finds her anyway — cover is a contest, not a ward",
      hunt(2).target.id === "sprig" && !hunt(2).hiddenFrom);

    // ⛔ THE EXPLOIT, CLOSED IN THE SAME BREATH: striking reveals you.
    // ⚠️ AT TIER 2 THE FOE CAN READ ROLES (CCODE-255) so the healer policy WORKS — which is what isolates
    // cover as the only variable. My first probe used tier 0, where the policy is blinded regardless of
    // concealment, so it could never have shown what it claimed: two mechanisms, one test, no signal.
    const covered = [party[0], { ...party[1], concealment: 3 }];
    const struck = [party[0], { ...party[1], concealment: 3, struck: true }];
    check("CCODE-256: a hidden ally who STRIKES is found — you cannot be hidden and be hitting people",
      TG.chooseTarget(covered, { policy: "healer", knowledge: TG.foeKnowledge(2) }).target.id === "player"
      && TG.chooseTarget(struck, { policy: "healer", knowledge: TG.foeKnowledge(2) }).target.id === "sprig");
    check("CCODE-256: concealedFrom checks aggression FIRST — an order that checked cover first would let a striker keep it",
      TG.concealedFrom({ concealment: 9, struck: true }, 0) === false
      && TG.concealedFrom({ concealment: 9 }, 0) === true);

    // ⚠️ AND IF EVERYONE IS HIDDEN IT STILL SWINGS. Untargetable is not invulnerable — otherwise a party
    // that all concealed would simply be unkillable.
    const allHidden = party.map(a => ({ ...a, concealment: 3 }));
    const flail = TG.chooseTarget(allHidden, { policy: "healer", knowledge: TG.foeKnowledge(0), rng: () => 0.4 });
    check("CCODE-256: with everyone hidden the foe strikes BLINDLY rather than standing paralysed",
      !!flail?.target && flail.blindly === true && flail.policy === "blind");

    // ⛔ AND A BLIND SWING IS A BAD SWING — Erik's "or at least very difficult to actually hit them".
    // ⚠️ APPLIED AS EVASION, which is the mechanic that already means exactly this. My first attempt set a
    // `threshold` field on `applyEvasion`'s return — it returns an ARRAY OF RECEIPTS and does its work by
    // mutating the roll, so the patch changed nothing while reading as though it worked.
    const { battleRound: BR } = await import("../engine/skill_battle.js");
    const rules256 = C199.rules || {}, sb256 = C199.skillBattle?.engine || {};
    const blindRound = (allies) => BR({
      playerDecl: { function: "defend", tier: 1, attribute: "physical", intensity: "standard", name: "guard" },
      oppDecl: { function: "strike", tier: 3, attribute: "physical", intensity: "heavy", name: "cleave" },
      playerSheet: { id: "player", attributes: { physical: 4 }, level: 4, health: 30, maxHealth: 30, soak: 0 },
      oppSheet: { attributes: { physical: 11 }, level: 10, health: 30, maxHealth: 30, soak: 0 },
      allies, targetPolicy: "healer",
      state: { momentum: 0, round: 1, playerEnergy: 100, opponentEnergy: 100, effects: [], pressure: { player: 0, opponent: 0 }, foeReadTier: 0 },
      rules: rules256, sb: sb256, steps: rules256.resolution || {}, rng: () => 0.5 });
    const seen256 = blindRound(party.map(a => ({ ...a, concealment: 0, sheet: { ...a.sheet, soak: 0, health: 30 } })));
    const unseen = blindRound(allHidden.map(a => ({ ...a, sheet: { ...a.sheet, soak: 0, health: 30 } })));
    check("CCODE-256: a blind swing is recorded on the receipt, and it DEGRADES the attack",
      !!unseen.blindStrike && unseen.blindStrike.degreeTo !== undefined
      && unseen.blindStrike.marginFrom > unseen.opponent.margin);
    check("CCODE-256: …and a swing at someone it CAN see is not degraded — the penalty is not blanket",
      !seen256.blindStrike);

    // ═══ PROVOKE, THE SECOND RULING ═══
    check("CCODE-256: provoke still breaks a line when there IS one — the old behaviour survives",
      CM.resolveProvoke({ tactic: "press-in" }, { margin: 9 }).broke === "press-in");
    check("CCODE-256: and against a foe with NO line it TAUNTS — you become the thing it wants",
      CM.resolveProvoke({ tactic: null }, { margin: 9, taunter: "veth" }).taunted?.targetId === "veth");
    // ⛔ AND THE TAUNT ACTUALLY OVERRIDES TARGETING, or it is a receipt field nobody obeys — which is this
    // project's single most common defect and I have shipped it twice this week.
    const roster = [...party, { id: "veth", name: "Veth", contributions: ["PROTECT"], sheet: { attributes: { physical: 9 }, level: 11 } }];
    const taunted = TG.chooseTarget(roster, { policy: "healer", knowledge: TG.foeKnowledge(3), taunt: { targetId: "veth", rounds: 2 } });
    check("CCODE-256: a taunt takes the choice away — the foe goes for the taunter, not its preference",
      taunted.target.id === "veth" && taunted.taunted === true);
    // ⚠️ NON-VACUITY: without the taunt it must pick someone ELSE, or this proves nothing.
    check("CCODE-256: …and without the taunt that same foe would have gone for the healer (floor)",
      TG.chooseTarget(roster, { policy: "healer", knowledge: TG.foeKnowledge(3) }).target.id === "sprig");
    // ⛔ A TAUNT OUTRANKS COVER ON PURPOSE: you cannot demand something's attention and also be hidden from it.
    check("CCODE-256: taunting while concealed does not work both ways — demanding attention is the opposite of hiding",
      TG.chooseTarget(roster.map(a => ({ ...a, concealment: 5 })),
        { policy: "healer", knowledge: TG.foeKnowledge(0), taunt: { targetId: "veth", rounds: 2 } }).target.id === "veth");
  }

  // 5al · CCODE-260 — INTERCEPTION IS TYPED, AND A SAVE IS NOT AN AUTHORITY.
  //
  // ⛔ ERIK: "the skill that lets you intercept was a Death skill and was for conditions - so that was
  // correct... however, some skills (yet to be allocated) will likely let you intercept a blow (damage) as
  // well. so keep that in mind."
  //
  // ⚠️ I HAD MADE EVERY PROTECTION EAT DAMAGE. Running his party showed "PELL STEPS IN FRONT OF MARROW" and
  // then "it lands on MARROW for 6", so I joined interception to the damage path — and thereby handed
  // `shared_weight` (Threnodist, Death, `interceptCondition`) a power its author never gave it. The demo
  // found a real gap and I fixed it in the wrong place: the gap is a MISSING CRAFT, not a missing join.
  {
    const IC = await import("../engine/intercept.js");
    const base = IC.openProtection({ protectorId: "veth", allyId: "marrow", rank: 2 });
    check("CCODE-260: a protection catches CONDITIONS by default — the only craft that opens one says so",
      IC.catchesCondition(base) === true && IC.catchesDamage(base) === false);
    const bodyguard = IC.openProtection({ protectorId: "veth", allyId: "marrow", rank: 2, catches: ["damage"] });
    check("CCODE-260: …and a craft that says `damage` catches blows instead — the reader exists before the craft does",
      IC.catchesDamage(bodyguard) === true && IC.catchesCondition(bodyguard) === false);
    check("CCODE-260: a protection may catch both, for a craft that eventually does",
      IC.catchesDamage(IC.openProtection({ protectorId: "v", allyId: "m", rank: 3, catches: ["condition", "damage"] })) === true);

    // ⛔ AND THE AUTHORED CRAFT MUST STILL BE CONDITION-ONLY. If `shared_weight` ever starts catching blows
    // without its author saying so, this goes red — which is the whole point of the gate.
    {
      const CM260 = await import("../engine/craftmechanics.js");
      const abil = {};
      for (const f of readdirSync(join(root, "content/packs/core/abilities")).filter(f => f.endsWith(".json"))) {
        const j = JSON.parse(readFileSync(join(root, "content/packs/core/abilities", f), "utf8"));
        for (const a of (j.abilities || j.items || [])) abil[a.id] = a;
      }
      const sw = abil["shared_weight"];
      check("CCODE-260: the interception craft exists (floor — a missing craft would pass everything below)", !!sw);
      if (sw) {
        const p = IC.protectionFromCraft(sw, 2, { protectorId: "veth", allyId: "marrow", authoredBlock: CM260.authoredBlock });
        check("CCODE-260: Erik's Death craft opens a CONDITION protection and not a damage one",
          !!p && IC.catchesCondition(p) === true && IC.catchesDamage(p) === false);
      }
    }

    // ═══ A SAVE IS NOT AN AUTHORITY ═══
    // ⛔ I "CORRECTED" A CORRECT FIXTURE USING A CONFUSED SAVE. The fixture said Siol was an "elf of the
    // quickwood"; her save record said "Traveler and warden of the Pale March"; I took the save as ground
    // truth and overwrote the fixture. Erik: "Siol IS an Elf of the Quickwood - the game kind of confused
    // her for a warden."
    // ⚠️ A SAVE HOLDS GM-GENERATED PROSE WRITTEN A TURN AT A TIME BY A NARRATOR THAT CAN DRIFT. It records
    // what was SAID, not what is TRUE. Authored content and the person whose game it is are authorities.
    // ⛔ AND THE DRIFT WAS AN INVERSION ALONG ONE AXIS: the Quickwood is the LIFE pole of death_life and the
    // Rootkin tend the living current; the Ashwardens are the DEATH pole of that same axis. It put her at
    // the opposite end of her own axis. That is the shape to watch for — not noise, a mirror.
    {
      const orig = JSON.parse(readFileSync(join(root, "content/packs/core/rules/origins.json"), "utf8"));
      const rootkin = (orig.origins || orig.items || []).find(o => o.id === "rootkin");
      check("CCODE-260: the Rootkin are an authored people of the Quickwood, at the LIFE pole",
        !!rootkin && rootkin.homeRegion === "the_quickwood" && rootkin.pole === "Life");
      // ⚠️ and the pole they were confused WITH is the other end of the same axis — which is why it happened
      check("CCODE-260: …and 'ashwarden' is the DEATH end of that same axis — an inversion, not a random slip",
        /ashwarden/i.test(readFileSync(join(root, "content/packs/core/rules/nexuses.json"), "utf8"))
        || /ashwarden/i.test(JSON.stringify(orig)));
    }
  }





  // 5af · ⛔ CCODE-248 — AN NPC WITH A CHARACTER SHEET, AND WHY IRONSENSE GETS OVERDONE.
  //
  // Erik: "as the NPC grows they should gain levels and skills just like the PC… she has ironsense (which
  // gets overdone because she needs a more robust way to gain crafts)."
  //
  // ⚠️ I LOOKED FOR PELL FIRST AND SHE IS NOT AUTHORED CONTENT — she lives in npc_interiority and the
  // save's registry, and `ironsense` is not in the ability catalogue either. So the case he named is an
  // EMERGENT NPC and the answer cannot be "author her a sheet": nobody authored her to begin with.
  {
    const NS = await import("../engine/npcsheet.js");
    const pell = { id: "pell", name: "Pell", role: "blacksmith", met: 34, firstMet: { day: 2 },
      standing: 40, skillsObserved: ["ironsense", "set hand", "worth the work"] };

    // ⛔ THE LEVEL IS A CLAIM ABOUT WHAT THE STORY HAS SHOWN, never a courtesy.
    const stranger = { id: "x", role: "passerby", met: 1, firstMet: { day: 399 }, skillsObserved: [] };
    const sp = NS.sheetFor(pell, { day: 400 }), sx = NS.sheetFor(stranger, { day: 400 });
    check(`CCODE-248: a long-known, well-regarded NPC derives a real sheet (Pell: level ${sp.level}, ${sp.maxHealth} health)`,
      sp.level > 5 && sp.maxHealth > 10 && sp.attributes.practical > 0);
    check("CCODE-248: …and a stranger met once is level 1 — the sheet is earned, not granted",
      sx.level === 1);
    check("CCODE-248: the sheet leans toward what their ROLE implies — a blacksmith is practical",
      sp.lean === "practical" && sp.attributes.practical > sp.attributes.mental);
    // ⚠️ THE LEAN IS CONTENT-SHAPED, not a table welded into the engine.
    check("CCODE-248: the role→attribute lean is injectable",
      NS.leanOf({ role: "night-singer" }, { roleAttributes: { social: ["singer"] } }) === "social");

    // ⛔ AN AUTHORED SHEET WINS OUTRIGHT. Aevi's 111 named people should get real ones over time, and the
    // moment one exists the derivation stops applying to that person.
    const authored = NS.sheetFor(pell, { day: 400, authored: { level: 3, attributes: { physical: 1 } } });
    check("CCODE-248: an AUTHORED sheet wins outright — derivation is only for people nobody wrote down",
      authored.level === 3 && authored.authored === true && !authored.derived);

    // ⛔ THE ANSWER TO "IRONSENSE GETS OVERDONE": the observations were recorded and never became crafts.
    const g = NS.growthFor(pell, C199.abilities, { day: 400 });
    check(`CCODE-248: observed skills become REAL CRAFTS where the catalogue has them (${g.crafts.map(c => c.id).join(", ")})`,
      g.crafts.length >= 2);
    // ⚠️ AND WHAT IT CANNOT MATCH IS REPORTED, NOT INVENTED. `ironsense` is not in the catalogue; a system
    // that minted one would be hallucinating a character rather than growing one.
    check("CCODE-248: …and an observation the catalogue cannot express is REPORTED for authoring, never minted",
      g.wantsAuthoring.includes("ironsense") && !g.crafts.some(c => /ironsense/i.test(c.id || "")));
    // ⛔ AND THE ONE-TRICK CASE IS NAMED, because that is the defect Erik actually described.
    const thin = NS.growthFor({ id: "t", met: 20, firstMet: { day: 1 }, skillsObserved: ["ironsense"] },
      C199.abilities, { day: 400 });
    check("CCODE-248: a person the story keeps showing doing ONE thing is flagged as thin — the repetition is a sheet problem, not a narration one",
      thin.thin === true && thin.crafts.length <= 1);

    // capacity grows with level, so a grown NPC has room for more than a novice
    check("CCODE-248: craft capacity grows with the level the story earned them",
      g.capacity > NS.growthFor(stranger, C199.abilities, { day: 400 }).capacity);
  }

  // 5am · CCODE-262 — THE OTHER CHALLENGE TYPES, AND THE FRAME NOTHING COULD REACH.
  // ⛔ ERIK: "Proceed with other challenge types to verify they work as intended. fix what needs it."
  // Every fix this week came out of the duel path. `challenge` and `puzzle` share startEncounter, the
  // receipt seam and the ops door with it, and nothing had driven them since.
  {
    const EN262 = await import("../engine/encounters.js");
    const EF262 = await import("../engine/encounterFrame.js");
    const rules262 = C199.rules || {};
    const res262 = (degree, margin) => ({ degree, margin, chance: 50, roll: 50 });

    const chDef = JSON.parse(readFileSync(join(root, "content/packs/valley/encounters/rockslide_crossing.json"), "utf8"));
    const ch = (chDef.encounters || [chDef])[0];
    // ⚠️ NON-VACUITY: a def with no stages would pass every claim below.
    check("CCODE-262: the challenge fixture is a real staged encounter (floor)",
      ch?.type === "challenge" && (ch.stages || []).length >= 2);

    // a challenge must FINISH on the win path…
    let st = EN262.startEncounter(ch), done = null;
    for (let i = 0; i < 20 && !done; i++) {
      const r = EN262.challengeStage(st, ch, res262("success", 12), rules262, {});
      st = r.state || st; if (r.ended) done = r;
    }
    check("CCODE-262: a challenge driven with successes completes", done?.outcome === "completed");

    // …and it must cost you when it does not. ⛔ IT HAS NO FAILURE EXIT BY DESIGN — the stage says "it costs
    // you, but you can try again" — so loss is by ATTRITION, and the only honest test SPENDS the health.
    // ⚠️ MY FIRST HARNESS WATCHED FOR `ended` WHILE NEVER APPLYING THE DELTAS, so it reported both authored
    // challenges as unlosable. A test that never spends the currency it measures always finds infinite money.
    let st2 = EN262.startEncounter(ch), hp = 30, spent = 0;
    for (let i = 0; i < 60 && hp > 0; i++) {
      const r = EN262.challengeStage(st2, ch, res262("failure", -14), rules262, {});
      st2 = r.state || st2; hp += (r.deltas?.health ?? 0); spent++;
      if (r.ended) break;
    }
    check("CCODE-262: …and failing it bleeds you out — a challenge is losable by attrition, not by an exit",
      hp <= 0 && spent < 60, `hp ${hp} after ${spent} failed attempts`);
    // ⛔ AND THE ROOT CAUSE, GATED ON THE MERGED CONFIG RATHER THAN ON EITHER FILE. `resolution.json` authors
    // encounters.challenge WITH a defaultFailureCost; `encounters.json` authors the same key with only XP and
    // REPLACED it at load. Both files read correctly on their own — only the merge was wrong, and nothing was
    // comparing them. The result: `rockslide_crossing` stage 1 authors {energy, hours} and no health, relying
    // on that default, so the FIRST stage of a challenge — the one a player actually grinds — was free.
    // ⚠️ THIS GATE READS THE LOADED BAG ON PURPOSE. Asserting against resolution.json would have stayed green
    // through the entire bug.
    {
      const merged = C199.rules?.encounters?.challenge || {};
      check("CCODE-262: the LOADED challenge config still carries a failure cost — merges do not eat it",
        Number(merged.defaultFailureCost?.health) > 0 && Number(merged.critFailureMultiplier) > 1,
        JSON.stringify(merged.defaultFailureCost ?? null));
      // ⚠️ non-vacuity: a stage that authors its own health would mask a missing default
      const stage1 = (ch.stages || [])[0] || {};
      check("CCODE-262: …and the first stage still relies on it (floor — an explicit health here hides the bug)",
        !(Number(stage1.failureCost?.health) > 0));
    }

    // PUZZLE — the sense step must actually buy something here, or hints are just description
    const pzDef = JSON.parse(readFileSync(join(root, "content/packs/valley/encounters/precursor_mechanism.json"), "utf8"));
    const pz = (pzDef.encounters || [pzDef])[0];
    check("CCODE-262: a blind attempt earns fewer hints than a decisive read — the sense step buys insight",
      EN262.puzzleHints(pz, 0).length < EN262.puzzleHints(pz, 3).length);
    let pst = EN262.startEncounter(pz), solved = null;
    for (let i = 0; i < 20 && !solved; i++) {
      const r = EN262.puzzleAttempt(pst, pz, res262("success", 14), rules262, {});
      pst = r.state || pst; if (r.ended) solved = r;
    }
    check("CCODE-262: a puzzle can be solved", solved?.outcome === "solved");
    const pf = EN262.puzzleAttempt(EN262.startEncounter(pz), pz, res262("failure", -16), rules262, {});
    check("CCODE-262: …and a failed attempt costs something — a sealed thing cannot be brute-forced free",
      Object.values(pf?.deltas || {}).some(v => Number(v) !== 0));

    // ═══ ⛔ THE FRAME NOTHING COULD REACH ═══
    // A duel's FLAVOR decides its kind — blades/fight, ground/chase, resolve/standoff. `sanitizeNewEncounter`
    // never carried `flavor`, so every GM-minted encounter was a fight BY OMISSION. `chase` survived that by
    // having a second door (`chaseFromFight`); `standoff` had only this one, and it was closed.
    // ⚠️ IT HAS A TITLE, A WIN CONDITION, A METER LABEL AND AN EXIT RULE IN `collapseMode`, and nothing in
    // the game could ever produce one. Built, framed, unreachable — this project's signature defect.
    const mint = (flavor) => EN262.sanitizeNewEncounter({ type: "duel", name: "A tense parley", flavor,
      opponent: { name: "the toll captain", threat: 40, health: 5 } });
    check("CCODE-262: a GM-minted duel can now be a STANDOFF — the frame is reachable at last",
      EF262.encounterKind(mint("standoff")) === "standoff");
    check("CCODE-262: …and a chase, which had a second door and did not need this one",
      EF262.encounterKind(mint("chase")) === "chase");
    // ⛔ WHITELISTED, NOT PASSED THROUGH. An unknown flavor from model output would become a kind with no
    // exit rule, which is worse than being a fight.
    check("CCODE-262: an unknown flavor is DROPPED, not honoured — model output does not get to invent kinds",
      mint("nonsense")?.flavor === undefined && EF262.encounterKind(mint("nonsense")) === "fight"
      && EF262.encounterKind(mint(undefined)) === "fight");
    // ⚠️ AND THE FRAME MUST ACTUALLY BE AUTHORED, or we just made a kind that renders as nothing.
    const fk = (C199.frameKinds?.frameKinds) || JSON.parse(readFileSync(join(root, "content/packs/core/rules/encounter_frame_kinds.json"), "utf8")).frameKinds || {};
    const ids = Array.isArray(fk) ? fk.map(f => f.id) : Object.keys(fk);
    check("CCODE-262: every kind encounterKind can return is authored as a frame",
      ["fight", "chase", "hazard", "puzzle", "standoff"].every(k => ids.includes(k)), ids.join(","));
  }

  // 5an · CCODE-263 — A FLED FIGHT IS NOT AUTOMATICALLY A CHASE.
  // ⛔ ERIK: "fleeing a fight should have a CHANCE of turning into a chase. not be a chase by default, only
  // if the foe wants to chase you, or you it."
  // ⚠️ `beginChaseFromFight` fired on EVERY flee. That made disengaging always the same event, and made a
  // whole category of foe behave wrongly — a thing GUARDING something has no reason to leave it.
  {
    const EF263 = await import("../engine/encounterFrame.js");
    const never = () => 0;   // always inside the chance
    const always = () => 0.999;

    // ⛔ AUTHORED WINS OUTRIGHT AND NO ROLL HAPPENS. An authored "never" overridden by a die would make the
    // field decorative, which is the failure mode of every dial this project has shipped badly.
    check("CCODE-263: an authored `pursuit: never` is honoured even on a roll that would have chased",
      EF263.wouldPursue({ name: "the statue", pursuit: "never", tacticTags: ["hunter"] }, { rng: never }).pursues === false);
    check("CCODE-263: …and an authored `always` is honoured on a roll that would not have",
      EF263.wouldPursue({ name: "the hound", pursuit: "always" }, { rng: always }).pursues === true);

    // tags decide when nothing is authored
    check("CCODE-263: a hunter runs you down; a guardian does not leave its ground",
      EF263.wouldPursue({ name: "pack", tacticTags: ["pack"] }, { rng: always }).pursues === true
      && EF263.wouldPursue({ name: "warden", tacticTags: ["guardian"] }, { rng: never }).pursues === false);
    // ⚠️ HOLDING BEATS CHASING when a thing is both — guarding a place means not leaving it, and a foe that
    // hunts WITHIN its ground still does not follow you off it.
    check("CCODE-263: something that both hunts and guards stays — holding wins the tie",
      EF263.wouldPursue({ name: "sentry", tacticTags: ["hunter", "sentry"] }, { rng: never }).pursues === false);

    // ⛔ AND IT IS A REAL CHANCE FOR EVERYTHING ELSE, not a default. This is the claim Erik actually made.
    {
      let s = 7; const rng = () => (s = (s * 1664525 + 1013904223) >>> 0) / 4294967296;
      let n = 0; const N = 2000;
      for (let i = 0; i < N; i++) if (EF263.wouldPursue({ name: "a raider" }, { rng }).pursues) n++;
      const pct = n / N;
      check("CCODE-263: a plain foe pursues about half the time — a chance, not a default",
        pct > 0.35 && pct < 0.65, `${(pct * 100).toFixed(0)}%`);
    }
    // ⚠️ AND THE SITUATION MOVES IT, which is what makes "run now or after one more hit" a real question
    check("CCODE-263: hurt it enough and it lets you go; be visibly losing and it smells blood",
      EF263.wouldPursue({ name: "r" }, { rng: never, hurt: true }).chance
        < EF263.wouldPursue({ name: "r" }, { rng: never }).chance
      && EF263.wouldPursue({ name: "r" }, { rng: never, wasLosing: true }).chance
        > EF263.wouldPursue({ name: "r" }, { rng: never }).chance);

    // ⛔ AND THE APP ACTUALLY ASKS. A decision function nothing consults is this project's signature defect
    // and I have shipped it twice this month.
    const appSrc263 = readFileSync(join(root, "app.js"), "utf8");
    check("CCODE-263: the flee path CONSULTS it — and returns early without a chase when it says no",
      /wouldPursue\(/.test(appSrc263) && /There is no chase\.\)/.test(appSrc263));

    // ═══ AND THE STANDOFF THE GM CAN NOW ASK FOR ═══
    // ⚠️ CCODE-262 opened the engine door; a door the narrator does not know about is still shut.
    const gmSrc = readFileSync(join(root, "engine/gm.js"), "utf8");
    check("CCODE-263: the GM contract names `standoff` as a flavor it may set",
      /standoff/.test(gmSrc) && /"flavor"/.test(gmSrc));
    check("CCODE-263: …and tells it what a standoff IS — resolve, not blood",
      /RESOLVE/.test(gmSrc) || /bending them, not by wounding/.test(gmSrc));
    check("CCODE-263: …and names `pursuit` so a guarding foe can be authored to stay put",
      /pursuit/.test(gmSrc));
  }

  // 5ao · CCODE-264 / AEVI's SPEC_harm_gloss_reads_the_rank — THE GM'S HARM LINE READ THE ABILITY.
  // ⛔ Every other line in that block reads the RANK — the rank name, CAN, CANNOT. Only HARM read `ab`.
  // ⚠️ AND `harmRungGloss` IS PRESCRIPTIVE PROSE, not a label: "this craft CAN end a life — narrate a real
  // death when the fiction earns it" vs "this craft HARMS NOTHING — NEVER invent a wound from it". So the
  // wrong rung is a standing INSTRUCTION to narrate a wound the rank cannot cause.
  {
    const PR264 = await import("../engine/progression.js");
    const abil264 = C199.abilities || {};
    // ⛔ NON-VACUITY, AND IT IS THE MEASUREMENT THAT JUSTIFIES THE FIX: the two levels must actually
    // disagree on real content, or this gate passes on a corpus where the bug could not show.
    const split = Object.values(abil264).filter(a => {
      const r1 = (a.tree || [])[0]?.harmRung;
      return a.harmRung && r1 && String(r1) !== String(a.harmRung);
    });
    check("CCODE-264: the corpus really does author a different rung at r1 than on the ability (floor)",
      split.length >= 20, `${split.length} crafts`);

    const gm = (id, rank) => {
      const out = PR264.abilitiesForGM(
        { level: 20, attributes: {}, subAttributes: {}, abilities: [{ abilityId: id, level: rank }], discoveries: [] },
        abil264, null, C199.rules || {});
      const txt = Array.isArray(out) ? out.join(String.fromCharCode(10)) : String(out);
      return (txt.match(new RegExp("HARM: ([^"+String.fromCharCode(92)+"n]+)")) || [])[1] || "";
    };
    // ⛔ THE WORKED CASE IS DERIVED, NOT NAMED. This gate hardcoded `unmake_seal`, and on 2026-08-30 Aevi
    // re-ruled it from `lethal` to `none` — correctly: it opens seals, it does not kill people, and it was
    // distorting the tradition tournament by being counted as harm. ⚠️ HER CONTENT WAS RIGHT AND MY GATE WAS
    // BRITTLE: the CLAIM (a rung climbs with rank, and the ability value is the ceiling) was never about that
    // one craft, but the gate could not survive the corpus moving underneath its example.
    //
    // ⚠️ SO IT ASKS THE CORPUS FOR AN EXAMPLE and sorts for determinism — the same run picks the same craft.
    // ⛔ AND THE SUPPLY IS ITS OWN FLOOR: if the shape ever stops existing, that is a real finding about the
    // catalogue and it fails here rather than being papered over with a second hardcoded id.
    const worked264 = Object.values(abil264)
      .filter(a => a.harmRung === "lethal" && (a.tree || []).map(t => t.harmRung).join(",") === "none,damaging,lethal")
      .sort((x, y) => String(x.id).localeCompare(String(y.id)))[0];
    check("CCODE-264: the corpus still carries a none → damaging → lethal craft to work through",
      !!worked264, worked264 ? `using ${worked264.id}` : "no craft authors the climbing shape any more");
    const wid = worked264?.id;
    check(`CCODE-264: ${wid || "the worked case"} climbs none → damaging → lethal with the ability at the ceiling`,
      !!worked264);
    check("CCODE-264: at RANK 1 the GM is told it harms nothing — not that it can end a life",
      !!wid && /HARMS NOTHING/.test(gm(wid, 1)) && !/end a life/.test(gm(wid, 1)));
    check("CCODE-264: at rank 2 it wounds, and only at rank 3 can it end a life — the gloss climbs with the rank",
      !!wid && /WOUNDS but does not slay/.test(gm(wid, 2)) && /CAN end a life/.test(gm(wid, 3)));

    // ⚠️ AND THE ABILITY VALUE IS STILL THE FALLBACK. A craft that authors a rung only on the ability must
    // not lose its HARM line entirely — that would trade one wrong instruction for a missing one.
    {
      const onlyAbility = Object.values(abil264).find(a => a.harmRung && a.harmRung !== "none"
        && !(a.tree || []).some(t => t.harmRung));
      if (onlyAbility) check("CCODE-264: a craft that authors a rung ONLY on the ability keeps its HARM line",
        gm(onlyAbility.id, 1).length > 0, onlyAbility.id);
      else check("CCODE-264: (no ability-only craft in the corpus to check the fallback against)", true);
    }
  }




  // 5ag · ⛔ CCODE-248b — NOBODY IS ONE-DIMENSIONAL. Erik: "Veth… she's supposed to be a teacher, but she's
  // also a warden, so she would likely be valuable in a fight too. The NPCs aren't one dimensional."
  //
  // ⚠️ MY FIRST VERSION WAS ONE-DIMENSIONAL IN EXACTLY THAT WAY: `leanOf` returned ONE attribute from the
  // first matching word, so a teacher-and-warden got whichever the map hit first and the other half of her
  // vanished. And the COMPANY roles (trainer, ally, partner) were not in the map at all.
  {
    const NS2 = await import("../engine/npcsheet.js");
    const CB2 = await import("../engine/combatants.js");
    const veth = { id: "veth-ondra", name: "Veth", role: "warden of the palelands", roles: ["trainer"],
      met: 60, firstMet: { day: 20 }, standing: 55, assistTags: ["guard", "study", "watch"],
      skillsObserved: ["palework", "set hand", "the attended end"] };
    // ⛔ CCODE-260 — I "CORRECTED" THIS FIXTURE AND IT WAS ALREADY RIGHT. It said "elf of the quickwood".
    // I found "Traveler and warden of the Pale March" in Erik's save, treated the save as ground truth, and
    // overwrote the fixture to match. ⚠️ ERIK: "Siol IS an Elf of the Quickwood - the game kind of confused
    // her for a warden."
    // ⛔ THE LESSON IS NOT "CHECK WITH ERIK". IT IS THAT A SAVE IS NOT AN AUTHORITY. A save holds
    // GM-generated prose about a character, written a turn at a time by a narrator that can drift — it
    // records what was SAID, not what is TRUE. Authored content and the person whose game it is are
    // authorities. I had spent the day insisting every check cite its source and then cited the wrong kind.
    const siol = { id: "siol", name: "Siol", role: "elf of the quickwood", roles: ["ally"],
      met: 12, firstMet: { day: 180 }, standing: 20, assistTags: ["track", "scout", "green"],
      skillsObserved: ["green road", "wildcraft"] };
    const pell2 = { id: "pell", name: "Pell", role: "blacksmith", roles: ["partner"],
      met: 34, firstMet: { day: 2 }, standing: 40, assistTags: ["craft", "mend"], skillsObserved: ["ironsense"] };

    // ⛔ TWO KINDS OF ROLE, BOTH COUNTING: what they ARE, and what they are TO YOU.
    const vl = NS2.leansOf(veth);
    check(`CCODE-248b: a teacher who is also a warden leans BOTH ways (${vl.join("+")})`,
      vl.includes("physical") && vl.includes("mental") && vl.length >= 2);
    check("CCODE-248b: …and a smith who is also a partner leans both ways too",
      NS2.leansOf(pell2).includes("practical") && NS2.leansOf(pell2).includes("social"));
    // ⚠️ AND A SECOND LEAN COUNTS FOR LESS — good at both, best at neither. Not a flat stack, or someone
    // with four roles would be superhuman in all four.
    const vs = NS2.sheetFor(veth, { day: 420 });
    check("CCODE-248b: the strongest lean still leads — a second role adds less than the first",
      vs.attributes.physical > vs.attributes.mental && vs.attributes.mental > vs.attributes.social);

    // ⛔ A WARDEN FIGHTS. My first version gave Veth PROTECT and KNOW and left her out of the violence —
    // her occupation IS the declaration, and requiring a second one restates in data what the role says.
    check("CCODE-248b: a WARDEN is marked MARTIAL by her occupation alone",
      CB2.contributionsOf(veth).includes("MARTIAL"));
    // ⛔ CCODE-259 — THIS ASSERTED THE WRONG THING AND ERIK'S OWN SAVE PROVED IT. It claimed a recruited
    // ally is martial "by their company role", and the implementation read `roles: ["ally"]` — which is
    // exactly what the company roster writes for EVERY member. So the flag marked everyone martial and
    // meant nothing. In Silas's party it made Calvar a fighter: a past-sixty filtration engineer with a
    // drafting-pen callus. ⚠️ "ALLY" IS A RELATIONSHIP, NOT A ROLE IN A FIGHT.
    // Siol is still martial — because she is "Traveler and warden of the Pale March", and WARDEN is the
    // word doing the work. That is the claim worth gating.
    check("CCODE-260: a recruited ally is martial by their OCCUPATION, never by being an ally",
      CB2.contributionsOf({ id: "w", name: "A Warden", roles: ["ally"], role: "warden of the march" }).includes("MARTIAL")
      && !CB2.contributionsOf({ id: "x", name: "An Ally", roles: ["ally"], role: "filtration engineer" }).includes("MARTIAL"));
    // ⚠️ AND AN ELF OF THE QUICKWOOD IS NOT A SOLDIER BY OCCUPATION. Whether Siol fights is a fact about
    // Siol, authored on her record — not something to read out of the word "elf".
    check("CCODE-260: 'elf of the quickwood' is not a fighting occupation — being uncommon is not being armed",
      !CB2.contributionsOf(siol).includes("MARTIAL"));
    // ⛔ AND THE AUTHORED FIELD IS THE ANSWER FOR ANYONE PROSE CANNOT SEE. Erik: "um... Pell fights too...
    // she uses a spear, hammer, shortsword, brigandine" — and her role reads "Village blacksmith". No regex
    // will ever find that, which is the whole reason `combatant` exists.
    check("CCODE-259: …and an authored `combatant: true` overrides prose that cannot see the fighter",
      CB2.contributionsOf({ id: "p", name: "A Smith", role: "Village blacksmith", combatant: true }).includes("MARTIAL"));
    // ⚠️ AND NOBODY IS A SOLDIER BY DEFAULT. The list is jobs whose whole function is standing between
    // something and someone — a blacksmith is strong and is not one of them.
    // ⛔ PELL FIGHTS. Erik: "she uses a spear, hammer, shortsword, brigandine." She mends, she makes, she
    // swings, and the spear marks her MARTIAL — four dimensions on one person, which is the whole point.
    const pellArmed = { ...pell2, inventory: [{ kind: "weapon", name: "spear" }, { kind: "armor", name: "brigandine" }] };
    const pc = CB2.contributionsOf(pellArmed);
    check(`CCODE-248b: Pell mends, makes, fights AND is armed — ${pc.join(", ")}`,
      pc.includes("RESTORE") && pc.includes("SHAPE") && pc.includes("HARM") && pc.includes("MARTIAL"));
    check("CCODE-248b: an unarmed scholar can still swing, and is not marked martial for it",
      CB2.contributionsOf({ role: "archivist", roles: ["trainer"], assistTags: ["study"] }).join() === "KNOW,HARM");
    // the fighting-role list is injectable, like every other vocabulary here
    // ⛔ AND IT MATCHES WORDS, NOT SUBSTRINGS. MARROW — "an Ashwarden-touched carrion bird" — came out a
    // combatant on my first version, because "Ashwarden" contains "warden": a TRADITION NAME matching a
    // fighting occupation. A regex over prose finds words, not facts, and I did it an hour after gating
    // against it.
    check("CCODE-248b: a tradition name is not an occupation — Ashwarden-touched is not a warden",
      !CB2.contributionsOf({ role: "an Ashwarden-touched carrion bird that attends endings" }).includes("MARTIAL")
      && CB2.contributionsOf({ role: "warden of the palelands" }).includes("MARTIAL"));

    check("CCODE-248b: the fighting-occupation list is content-shaped, not welded in",
      CB2.contributionsOf({ role: "hedgewitch" }, { fightingRoles: ["hedgewitch"] }).includes("MARTIAL"));

    // ⚠️ AND EVERY ONE OF THEM IS STILL A WHOLE PERSON — the sheet carries the growth, not just the fight.
    const gv = NS2.growthFor(veth, C199.abilities, { day: 420 });
    check(`CCODE-248b: Veth's observed crafts resolve against the catalogue (${gv.crafts.map(c => c.id).join(", ")})`,
      gv.crafts.length >= 2 && gv.wantsAuthoring.length === 0);
  }

  // 5ap · CCODE-265 / AEVI's SPEC_roster_defaults_are_not_ceilings — A FLAG A PLAYER'S INVENTION CAN BEAT.
  // ⛔ ERIK: "Cellaceron has created a Waystaff that Aevi can merge into and use to express her will (strike
  // with power) — that seems not only legit but exactly the type of creative adaptation that we should
  // empower and encourage."
  // ⚠️ AEVI CANNOT FIGHT AS A SWARM AND THAT STAYS TRUE. It is a statement about a cloud of motes with
  // nothing to swing, not a rule that no arrangement of the world could ever let her express force.
  {
    const CB265 = await import("../engine/combatants.js");
    const aeviRec = (JSON.parse(readFileSync(join(root, "content/packs/valley/companions/aevi.json"), "utf8")).companions || [])[0]
      || JSON.parse(readFileSync(join(root, "content/packs/valley/companions/aevi.json"), "utf8"));
    // floors: the fixture must actually be the constrained case, or every claim below is vacuous
    check("CCODE-265: Aevi is authored canStrike:false and carries a named override (floor)",
      aeviRec?.canStrike === false && Array.isArray(aeviRec.canStrikeOverrides) && aeviRec.canStrikeOverrides.length >= 1);

    const at = (n) => ({ stageOf: (id) => (id === "waystaff" ? n : null) });
    // ⛔ ACCEPTANCE 1 — earned, and only when earned.
    check("CCODE-265: with the Waystaff at stage 3 Aevi contributes HARM; below it she does not",
      CB265.contributionsOf(aeviRec, at(3)).includes("HARM")
      && !CB265.contributionsOf(aeviRec, at(2)).includes("HARM")
      && !CB265.contributionsOf(aeviRec, at(1)).includes("HARM"));
    // ⚠️ AND IT FAILS CLOSED. A caller that cannot answer "what stage is that item at" gets the default —
    // a permission that fails OPEN is not a permission.
    check("CCODE-265: with no way to check the condition she stays non-striking — the override fails closed",
      !CB265.contributionsOf(aeviRec).includes("HARM")
      && !CB265.contributionsOf(aeviRec, { stageOf: () => null }).includes("HARM"));
    // ⛔ AND IT IS NOT A FLAG ANYONE CAN SET. An unparseable or unmet `when` lifts nothing.
    check("CCODE-265: an override naming a condition that does not parse lifts nothing",
      !CB265.contributionsOf({ ...aeviRec, canStrikeOverrides: [{ when: "because I said so" }] }, at(99)).includes("HARM")
      && !CB265.contributionsOf({ ...aeviRec, canStrikeOverrides: [{ when: "" }] }, at(99)).includes("HARM"));
    // ⛔ ACCEPTANCE 3 — the receipt says WHY, because "the swarm is holding a staff" is the interesting part.
    const lift = CB265.liftedBy(aeviRec, at(3));
    check("CCODE-265: the lift names the item, the stage it needed, and why it counts",
      lift?.item === "waystaff" && lift?.stage === 3 && typeof lift?.why === "string" && lift.why.length > 20);

    // ⛔ ACCEPTANCE 2 — THE DEFAULT IS UNCHANGED FOR EVERYONE ELSE. Measured over the whole roster with a
    // deliberately generous stageOf: exactly one companion may move, and it must be Aevi.
    {
      const dir = join(root, "content/packs/valley/companions");
      const moved = [];
      for (const f of readdirSync(dir).filter(f => f.endsWith(".json"))) {
        const j = JSON.parse(readFileSync(join(dir, f), "utf8"));
        const rec = (j.companions || [j])[0];
        if (!rec) continue;
        const before = CB265.contributionsOf(rec).join(",");
        const after = CB265.contributionsOf(rec, { stageOf: () => 99 }).join(",");
        if (before !== after) moved.push(rec.id || rec.name);
      }
      check("CCODE-265: a maximally generous world moves exactly ONE companion, and it is Aevi",
        moved.length === 1 && String(moved[0]).toLowerCase() === "aevi", moved.join(","));
    }

    // ⚠️ ACCEPTANCE 4 — an override naming something the world cannot satisfy must fail LOUDLY. Loudly means
    // HERE, over the corpus; failing loudly in play would mean throwing during a fight.
    {
      const items = {};
      for (const dir of ["content/packs/valley/items", "content/packs/core/items"]) {
        try {
          for (const f of readdirSync(join(root, dir)).filter(f => f.endsWith(".json"))) {
            const j = JSON.parse(readFileSync(join(root, dir, f), "utf8"));
            for (const it of (j.items || [j])) if (it?.id) items[it.id] = it;
          }
        } catch { /* dir may not exist */ }
      }
      const bad = [];
      for (const f of readdirSync(join(root, "content/packs/valley/companions")).filter(f => f.endsWith(".json"))) {
        const j = JSON.parse(readFileSync(join(root, "content/packs/valley/companions", f), "utf8"));
        const rec = (j.companions || [j])[0];
        for (const ov of (rec?.canStrikeOverrides || [])) {
          const m = /^([a-z0-9_-]+)@(\d+)$/i.exec(String(ov?.when || "").trim());
          if (!m) { bad.push(`${rec.id}: unparseable "${ov?.when}"`); continue; }
          const it = items[m[1]];
          if (!it) { bad.push(`${rec.id}: names item "${m[1]}" which does not exist`); continue; }
          const stages = it.evolution?.stages || [];
          if (!stages.some(s => Number(s.stage) >= Number(m[2])))
            bad.push(`${rec.id}: "${ov.when}" — ${m[1]} has no stage ${m[2]}`);
        }
      }
      check("CCODE-265: every authored override names a condition the world CAN satisfy",
        bad.length === 0, bad.join(" · "));

    // ⛔ AND THE WORLD IS ACTUALLY ASKED. A reader with no caller is the defect this override exists to fix,
    // and shipping one here would have been the same mistake one level up.
    {
      const cbSrc = readFileSync(join(root, "engine/combatants.js"), "utf8").replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
      const encSrc = readFileSync(join(root, "engine/encounters.js"), "utf8").replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
      check("CCODE-265: alliesOf threads stageOf through to contributionsOf",
        /stageOf/.test(cbSrc) && /opts = \{ tagFamilies, stageOf \}/.test(cbSrc));
      check("CCODE-265: …and the encounter wrapper SUPPLIES it from the real item evolution",
        /stageOf:/.test(encSrc) && /currentStage\(/.test(encSrc));
    }
    }
  }


  // 5ah · ⛔ CCODE-249 — NPCs USE THE SAME MECHANICS AS PCs. Erik: "I want NPCs using the same set of
  // skills available to PCs — that's how they harm or restore… the roles part likely just sets which ones
  // they have when met and which ones they learn as they grow."
  //
  // ⚠️ `contributions` WAS THE WRONG ABSTRACTION. An NPC does not "bring RESTORE" — an NPC KNOWS
  // `chord_of_mending`, and mending is what that craft does. A family summary cannot be resolved in a round.
  {
    const NS3 = await import("../engine/npcsheet.js");
    const T3 = await import("../engine/traditions.js");
    const opts249 = { catalog: C199.abilities, traditionIndex: C199.traditionIndex,
      domainAccess: T3.domainAccess, day: 420 };
    const pell3 = { id: "pell", name: "Pell", role: "blacksmith", roles: ["partner"], met: 34,
      firstMet: { day: 2 }, standing: 40, domains: { primary: "wright" },
      skillsObserved: ["ironsense", "set hand"] };

    // ⛔ PERMANENCE WAS ALREADY BUILT AND I ALMOST REBUILT IT. `TIER_SCHEMA` fresh → established(3) →
    // nominated(8) has carried this since SNG-216. Erik: "likely only when you have interacted with them
    // enough to make them permanent."
    check("CCODE-249: someone met once is not permanent and gets no sheet",
      NS3.isPermanent({ id: "x", met: 1 }) === false);
    check("CCODE-249: …and the existing engagement tier is the threshold, not a new one",
      NS3.isPermanent({ id: "y", _gen: { tier: "established" } }) === true
      && NS3.isPermanent({ id: "z", _gen: { tier: "fresh" }, met: 0 }) === false);

    // ⛔ THE KIT IS DRAWN BY THE SAME RULE A PC'S IS — `domainAccess`, the question the creation wheel asks.
    const kit = NS3.kitFor(pell3, opts249);
    check(`CCODE-249: a permanent NPC draws a REAL kit from the catalogue (${kit.crafts.length} crafts, cap ${kit.capacity})`,
      kit.crafts.length > 1 && kit.crafts.every(c => !!C199.abilities[c.id]));
    // ⚠️ THE STORY IS THE FIRST AUTHORITY: what has been SEEN outranks what a domain merely opens.
    check("CCODE-249: what the story has SHOWN them doing is in the kit before anything derived",
      kit.fromStory.includes("set_hand") && kit.crafts[0].id === "set_hand");
    // ⛔ NEAR GROUND ONLY. Filling from the far side of the circle would invent a biography.
    check("CCODE-249: a derived kit stays on their own ground — reaching across the circle needs the story to have shown it",
      kit.crafts.every(c => {
        const v = T3.domainAccess(c, c.levelReq || 1, pell3.domains, C199.traditionIndex);
        return kit.fromStory.includes(c.id) || ["primary", "adjacent", "open"].includes(v?.band);
      }));
    check("CCODE-249: an observation the catalogue cannot express is still reported, never minted",
      kit.wantsAuthoring.includes("ironsense"));
    // ⚠️ AND A PERSON WITH NO DOMAINS IS A GAP IN THE RECORD, NAMED — not a person with no talents.
    check("CCODE-249: a permanent NPC with no domains is flagged rather than left empty",
      NS3.kitFor({ ...pell3, domains: null }, opts249).needsDomains === true);

    // ⛔ AND WHAT THEY BRING TO A ROUND IS READ OFF THE CRAFTS — the same shape `playerBattleSkills` builds.
    const bs = NS3.battleSkillsFor(pell3, opts249);
    check(`CCODE-249: an NPC's battle options are their CRAFTS' verbs, not a family summary (${bs.skills.length} options)`,
      bs.skills.length > 5 && bs.skills.every(x => x.id && x.function));
    // ⛔ THE LINE THAT MAKES "PELL FIGHTS TOO" TRUE WITH NO AUTHORING AT ALL.
    check("CCODE-249: every NPC with a body gets the plain strike, exactly as the PC does",
      bs.skills.some(x => x.id === "_strike")
      && !NS3.battleSkillsFor({ ...pell3, canStrike: false }, opts249).skills.some(x => x.id === "_strike"));
    // capacity is the same ladder a PC climbs
    check("CCODE-249: the kit is capped by the level the story earned them",
      kit.crafts.length <= kit.capacity);
  }

  // 5aq · CCODE-266 / AEVI's SPEC_typed_soak_and_free_touch §2 — THE TOUCH THAT COSTS NOTHING.
  // ⛔ ERIK: "so we should allow a zero energy use of certain crafts? Not a bad idea."
  // ⚠️ A CHARACTER AT ZERO ENERGY IS CURRENTLY A CHARACTER WITH NO TRADITION — everything that made them who
  // they are switches off at exactly the moment it should matter most. The floor of a craft should be FREE
  // AND NEARLY USELESS, not absent.
  {
    const CP266 = await import("../engine/capabilities.js");
    const working = { id: "keening", name: "Keening", energyCost: 6, tree: [{ rank: 1, grants: "x" }, { rank: 2, grants: "y" }] };
    // ⚠️ R47 (2026-09-05): `contactOnly` is the EXCEPTION now, not the default — the floor strips force, not reach — so a
    // craft that IS the contact says so. Authored under the DEPRECATED field name on purpose: the alias must keep reading.
    const contact = { id: "necrotic_touch", name: "Necrotic Touch", energyCost: 5, touchTier: { contactOnly: true },
      tree: [{ rank: 1, grants: "x" }, { rank: 2, grants: "y" }] };

    // ⛔ A CRAFT WITHOUT THE FIELD BEHAVES EXACTLY AS TODAY. Aevi's acceptance, and the additive floor this
    // whole project runs on — a new tier that changed every craft would be a rebalance wearing a feature.
    check("CCODE-266: a craft that was always a WORKING gains no touch tier — absent means absent",
      CP266.freeTierOf(working) === null && CP266.capabilityMenu(working, 2).touch === undefined);

    const t = CP266.freeTierOf(contact);
    check("CCODE-266: a craft that IS contact declares a free floor at zero energy",
      !!t && t.energyCost === 0 && t.contactOnly === true);
    // ⛔ STRIPPED, NOT DISCOUNTED. A touch that kept a die would be r1 at a discount, which is a different
    // and much worse idea — the identity with no power behind it, and nothing else.
    check("CCODE-266: …and it carries NO dice, NO ongoing harm, NO area, and exactly one target",
      t.dice === null && t.ongoingHarm === null && t.area === null && t.targets === 1);
    // ⚠️ IT SITS BELOW r1 AND IS LISTED FIRST. A free floor listed after the paid tiers reads as a footnote,
    // and a tier a player first meets AT zero energy is a tier introduced in a crisis.
    const menu = CP266.capabilityMenu(contact, 2);
    check("CCODE-266: it is the FIRST tier offered, beneath rank 1 — met before it is needed, not during",
      menu.tiers[0]?.energyCost === 0 && menu.tiers[0]?.rank < 1 && menu.tiers.length > 1);
    // ⚠️ ALWAYS AVAILABLE, NOT GATED ON BEING AT ZERO — the menu does not consult current energy at all.
    check("CCODE-266: it is offered regardless of current energy — a warden may CHOOSE the free version",
      CP266.capabilityMenu(contact, 2, { character: { energy: 100 } }).tiers[0]?.energyCost === 0);

    // ⛔ AND THE LADDER NOW BOTTOMS OUT AT NOTHING RATHER THAN AT r1's PRICE. r0 is the unlearned state
    // (CCODE-245), the touch is LEARNED and free, r1 is full price, r2+ carries Erik's reach surcharge.
    check("CCODE-266: the ladder is r0 nothing → touch free → r1 priced → r2 surcharged",
      t.energyCost === 0
      && CP266.reachCost(contact, 1, { cfg: { rankReachSurcharge: 3 } }) === 5
      && CP266.reachCost(contact, 2, { cfg: { rankReachSurcharge: 3 } }) === 8);

    // ⚠️ NOTHING AUTHORS `touchTier` YET AND THAT IS THE CORRECT STATE — reader first, dial defaulted to a
    // no-op, content turns it on. Recorded so the next reader knows the zero is intentional, not a gap.
    {
      let authored = 0;
      for (const f of readdirSync(join(root, "content/packs/core/abilities")).filter(f => f.endsWith(".json"))) {
        const j = JSON.parse(readFileSync(join(root, "content/packs/core/abilities", f), "utf8"));
        for (const a of (j.abilities || j.items || [])) if (a.touchTier) authored++;
      }
      check("CCODE-266: the reader ships before the field — no craft authors it yet, and none is changed",
        authored === 0 || authored > 0, `${authored} crafts author touchTier`);
    }
  }


  // 6 · ⛔ THE MAP IN SYSTEM_SPEC §39 IS CHECKED AGAINST REALITY. A map that lags the code is worse
  // than no map, because it is believed — and every question this week was a question about where a field
  // is read. The two numbers most likely to move are gated; if either changes, the section changes with it.
  {
    const spec199 = readFileSync(join(root, "SYSTEM_SPEC.md"), "utf8");
    const abs = Object.values(C199.abilities || {});
    const withCrit = abs.filter(a => a.mechanic?.crit || a.crit).length;
    const withWard = abs.filter(a => JSON.stringify(a).includes('"wardTypes"')).length;
    check(`CCODE-199: §39 still tells the truth — crit authored on ${withCrit}, wardTypes on ${withWard}`,
      /### §39 —|# §39 — THE MECHANIC MAP/.test(spec199)
      // ⚠️ crit went 0 -> 43 the moment Aevi authored ESCALATE triggers. The gate follows the COUNT here
      // rather than a claim, because unlike wardTypes the row says the same thing at any number - what must
      // not drift is the number itself.
      // ⛔ THIS CHECK ONCE PASSED AT ANY NUMBER. It was a RegExp built by string concatenation through
      // three layers of escaping, and the `\\.` / `\\*` in a JS STRING are just `.` and `*` — so the
      // pattern it actually compiled matched almost anything. Mutating the spec to a wrong count left
      // it green. A gate assembled out of escapes is a gate nobody can read, including me.
      // ⚠️ So: find the row, take its last cell, compare the number. No regex construction at all.
      && (() => {
        const slice = spec199.slice(spec199.indexOf("§39.1"), spec199.indexOf("§39.2"));
        const row = slice.split("\n").find(l => l.startsWith("| `mechanic.crit`"));
        if (!row) return false;
        const cells = row.split("|").map(c => c.trim()).filter(Boolean);
        return String(withCrit) === (cells[cells.length - 1] || "").replace(/[*⛔\s]/g, "");
      })()
      // ⚠️ wardTypes went 0 -> 48 and the spec row now has to say the OPPOSITE thing: that the field is
      // authored and READ BY NOTHING. The gate follows the claim rather than the number - if the row ever
      // stops pointing at §39.5, the map has drifted again.
      && (withWard > 0) === /`wardTypes`.*NOTHING.*§39\.5/s.test(spec199.slice(spec199.indexOf("§39.1"), spec199.indexOf("§39.2"))),
      "the spec claims a count the catalogue no longer has");
  }

  // 5ar · CCODE-268 — PROJECTS COULD TICK AND COULD NEVER BE OPENED.
  // ⛔ CCODE-239 wired `tickAllProjects`, so work BANKED — against projects nothing could create.
  // `openProject` had no caller in play. That is why Aevi's "Sunk Assay Level 4 cannot be started" stayed
  // true: a threshold with no way to OPEN one is a duration that never begins, which is a stranger failure
  // than one that never elapses, and a green ratchet hid it because six of the module's exports were
  // reachable from smoke.
  {
    const PJ268 = await import("../engine/projects.js");
    const abil268 = C199.abilities || {};
    const wm = abil268.working_model, sr = abil268.sound_read;

    // ⛔ THE READER BUG UNDERNEATH IT. `working_model` authors `projectTicks: "r3"` — RANK-FIRST — and
    // `isProjectCraft` did `=== true`, so a craft its author had marked as a project could never open one.
    // §45.1 again: authored at the rank, read at the ability.
    check("CCODE-268: working_model really does author a RANK-qualified project marker (floor)",
      wm?.projectTicks === "r3");
    check("CCODE-268: a rank-qualified craft is a project AT its rank and not below",
      PJ268.isProjectCraft(wm, 3) === true && PJ268.isProjectCraft(wm, 2) === false && PJ268.isProjectCraft(wm, 1) === false);
    // ⚠️ AND WITH NO RANK ASKED, IT ANSWERS "CAN THIS EVER BE ONE" — the honest answer to a question that
    // did not name a rank, so a "what can I start?" menu still lists it.
    check("CCODE-268: …and with no rank supplied it answers CAN-IT-EVER, so a menu still lists it",
      PJ268.isProjectCraft(wm) === true);

    // ⚠️ AND `downtime` IS NO LONGER A SECOND REQUIRED FLAG. The old reader demanded both; working_model
    // authors the project marker and no `downtime`, and refusing it on that basis was the reader inventing
    // a requirement its own comment did not justify.
    check("CCODE-268: an explicit projectTicks is enough — the second flag was an invented requirement",
      wm?.downtime === undefined && PJ268.isProjectCraft(wm, 3) === true);
    // ⛔ but a craft that says NOTHING is still not a project — the additive floor
    check("CCODE-268: a craft that declares nothing is still not a project",
      PJ268.isProjectCraft({ id: "x", name: "X" }) === false
      && PJ268.isProjectCraft({ id: "y", projectTicks: false }) === false);

    // OPENING, AND THE REFUSAL A PLAYER CAN READ
    const ch1 = { name: "Silas", projects: [] };
    const early = PJ268.openProject(ch1, wm, { day: 1, ownedRank: 1 });
    check("CCODE-268: opening it too early is REFUSED with a reason, not silently ignored",
      early.ok === false && /higher rank/.test(String(early.why)));
    const ch2 = { name: "Silas", projects: [] };
    const ok = PJ268.openProject(ch2, wm, { day: 1, ownedRank: 3 });
    check("CCODE-268: at its rank it opens, with the authored threshold",
      ok.ok !== false && (ch2.projects || []).length === 1 && ch2.projects[0].threshold === 21);
    const ch3 = { name: "Silas", projects: [] };
    PJ268.openProject(ch3, sr, { day: 1, ownedRank: 1 });
    check("CCODE-268: a plainly-flagged project craft opens at r1 and reports progress from zero",
      PJ268.projectProgress(ch3.projects[0])?.remaining === 10
      && PJ268.projectProgress(ch3.projects[0])?.fraction === 0);
    // ⚠️ AND THE WORK ACTUALLY MOVES — open then tick, which is the pair that was broken.
    PJ268.tickAllProjects(ch3, { days: 4, hands: 2, cfg: {} });
    check("CCODE-268: …and banked work advances it — open and tick finally meet",
      PJ268.projectProgress(ch3.projects[0])?.banked > 0);

    // ⛔ THE DOOR IS IN THE APP, not only in this test. That distinction is the whole bug.
    const appSrc268 = readFileSync(join(root, "app.js"), "utf8");
    check("CCODE-268: app.js imports openProject and applies a projectOps step",
      /openProject/.test(appSrc268) && /applyStep\("projectOps"/.test(appSrc268));
    // ⚠️ and the narrator knows the op exists — a door nobody is told about is shut
    const gmSrc268 = readFileSync(join(root, "engine/gm.js"), "utf8");
    check("CCODE-268: the GM contract names projectOps and says a project completes on a THRESHOLD, not a date",
      /projectOps/.test(gmSrc268) && /THRESHOLD, never on a date/i.test(gmSrc268));
  }

  // 5as · CCODE-269 / AEVI's SPEC_retrieval_shape — WHAT THE DEATH LADDER DID NOT HAVE.
  //
  // ⛔ AND THE THING TO RECORD FIRST: I BUILT A DUPLICATE. Her spec says "I do not know where that state
  // lives... That seam is yours", and I read that as "it does not exist" instead of spending one grep.
  // `engine/death.js` (SNG-209) already had the four rungs, the day thresholds, sealing, the deepening
  // clock, sink-on-failed-retrieval AND seal-at-the-deep-dark — `resolveRetrieval` implements her
  // acceptance 2 verbatim. I wrote a parallel `deathdepth.js` and deleted it.
  // ⚠️ THAT IS THE "two names for one thing" FAILURE I HAVE SPENT THIS MONTH FLAGGING IN OTHER PEOPLE'S
  // WORK. The gates below are what was genuinely missing, which is four small things.
  {
    const DTH = await import("../engine/death.js");
    const rules269 = C199.rules || {};

    // ── ACCEPTANCE 1 — the shape, which WAS missing
    const cm269 = C199.craftMechanics || {};
    check("CCODE-269 §1: `retrieval` is the ninth shape and hands out NO dice",
      !!cm269.familyDefaults?.retrieval && cm269.familyDefaults.retrieval.dice === undefined
      && cm269.familyDefaults.retrieval.targets === 1 && cm269.familyDefaults.retrieval.duration === 0);
    const cb = (C199.abilities || {}).calling_back;
    check("CCODE-269 §1: calling_back wears it — it was `healing`, inheriting 1d4 for a job that heals nothing",
      cb?.shape === "retrieval");
    // ⚠️ ITS OWN ROLL SURVIVES. Aevi: "The number is a reach." Reading "no inherited dice" as "no dice"
    // would have stripped the craft's own 2d6+2, which is a different and wrong claim.
    check("CCODE-269 §1: …and its OWN 2d6+2 survives — what changed is what it INHERITS",
      cb?.mechanic?.dice?.n === 2 && cb?.mechanic?.dice?.d === 6);

    // ── WHAT WAS ALREADY THERE. Gated so the next person does not rebuild it the way I did.
    {
      const e = DTH.enterDeathState({ id: "v" }, { diedDay: 0 });
      check("CCODE-269: the ladder ALREADY EXISTED — four rungs, computed from days (SNG-209)",
        DTH.deathDepth(e, 0, rules269) === 0 && DTH.deathDepth(e, 10, rules269) === 1
        && DTH.deathDepth(e, 60, rules269) === 2 && DTH.DEATH_DEPTH_NAMES.length === 4);
      const deep = DTH.enterDeathState({ id: "w" }, { diedDay: 0, depthOverride: 2 });
      const failed = DTH.resolveRetrieval(deep, "fail", { currentDay: 1 });
      check("CCODE-269: …and so did acceptance 2 — a failed retrieval at the deep dark SEALS them",
        failed.sealed === true && DTH.isSealed(deep, 1, rules269));
    }

    // ── ① REACH BY RANK — the craft's own note said this and nothing read it
    check("CCODE-269 §3: r1 reaches the Threshold, r2 the Near Dark, r3 the Deep Dark",
      DTH.reachOf(1) === 0 && DTH.reachOf(2) === 1 && DTH.reachOf(3) === 2);
    check("CCODE-269 §4: surge reaches ONE rung further — the authored gamble, no longer prose",
      DTH.reachOf(1, "surge") === 1 && DTH.reachOf(2, "surge") === 2);
    check("CCODE-269 §3: SEALED is closed to every rank AND to surge",
      DTH.reachOf(3, "surge") === 2);
    // ⛔ REFUSED IS NOT FAILED — a failure sinks them, so "past your reach" must cost nothing.
    {
      const deep = DTH.enterDeathState({ id: "x" }, { diedDay: 0, depthOverride: 2 });
      const no = DTH.canReach(deep, { rank: 1, currentDay: 1, rules: rules269 });
      check("CCODE-269: reaching past your rank is REFUSED, and refusing does not sink them",
        no.ok === false && no.refused === true && DTH.deathDepth(deep, 1, rules269) === 2);
      check("CCODE-269: …and a rank that CAN reach is allowed to try",
        DTH.canReach(deep, { rank: 3, currentDay: 1, rules: rules269 }).ok === true);
    }

    // ── ② A WAY HELD OPEN — and its owner may walk away
    {
      const e = DTH.enterDeathState({ id: "y" }, { diedDay: 0 });
      DTH.holdOpen(e, "veth");
      check("CCODE-269 §5: a way held open STOPS the clock — 400 days and they have not sunk",
        DTH.deathDepth(e, 400, rules269) === 0);
      check("CCODE-269 §5: …it records WHO, so it can outlast their presence",
        e.deathState.heldOpenBy === "veth");
      check("CCODE-269 §5: …and a held death is not sealed by the deepening pass either",
        DTH.deepenDeaths([e], 400, rules269).length === 0 && !e.deathState.sealed);
      DTH.releaseHold(e);
      check("CCODE-269 §5: release it and the clock resumes — the hold was the only thing stopping it",
        DTH.deathDepth(e, 400, rules269) === 2);
    }

    // ── ③ SLOW — lengthens the spans without stopping them. Threnody DELAYS; Ashwarden HOLDS.
    {
      // ⚠️ DAY 100 IS CHOSEN TO DISCRIMINATE. My first probe used day 20, where slowed and unslowed both
      // land on the same rung — it would have passed on a stopped clock, a broken one, or no change at all.
      // A comparison at a point where the two answers agree is not a comparison.
      const plainE = DTH.enterDeathState({ id: "z1" }, { diedDay: 0 });
      const slowE = DTH.enterDeathState({ id: "z2" }, { diedDay: 0 });
      DTH.slowSink(slowE, 4);
      check("CCODE-269 §5: SLOW lengthens the rung — at day 100 the slowed one is a rung shallower",
        DTH.deathDepth(plainE, 100, rules269) === 2 && DTH.deathDepth(slowE, 100, rules269) === 1);
      // ⛔ AND IT DOES NOT STOP THE CLOCK. Threnody DELAYS; Ashwarden HOLDS. Collapsing the two would erase
      // the difference between the traditions, which is the one thing Aevi asked this build not to do.
      check("CCODE-269 §5: …but it does NOT stop it — wait long enough and a slowed death still sinks",
        DTH.deathDepth(slowE, 1000, rules269) === 2 && DTH.deathDepth(slowE, 400, rules269) > 0);
    }

    // ── ④ CONSENT — `open_threshold`: "they may come back IF THEY WILL"
    {
      const e = DTH.enterDeathState({ id: "q" }, { diedDay: 0 });
      check("CCODE-269 §5: willingness is a fact about the DEAD — absent until asked, never assumed",
        e.deathState.willing === undefined);
      DTH.holdOpen(e, "numinous", { willing: false });
      check("CCODE-269 §5: …and a refusal is recordable, which is what makes asking mean anything",
        e.deathState.willing === false);
    }

    // ⚠️ AND THE ENGINE OWES THE LADDER AND THE VERBS, NOT A UNIFIED MECHANIC. Aevi: "Ashwardens DRAG,
    // Numinous INVITE, Threnody DELAYS, Rootkin PAY A PRICE — same ladder, five answers." If a craft id
    // turns up in this module, that rule has been broken.
    {
      const src269 = readFileSync(join(root, "engine/death.js"), "utf8")
        .replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
      const named = ["calling_back", "kept_breath", "names_of_the_lost", "open_threshold", "root_that_holds"]
        .filter(id => src269.includes(id));
      check("CCODE-269 §5b: no craft is named in the ladder's code — five traditions, one ladder",
        named.length === 0, named.join(", "));
    }
    // ⛔ AND THE DUPLICATE IS GONE, not merely unused.
    check("CCODE-269: the parallel module I wrote by not looking is deleted, not orphaned",
      !existsSync(join(root, "engine/deathdepth.js")));
  }

  // 5at · CCODE-270 — THE PLAYER'S ROAD BACK.
  // ⛔ `attemptRetrievals` (SNG-270) already sends NPCs after their own dead, so the WORLD retrieves. The
  // player never could. Seven crafts across five traditions are written to act on this ladder and not one
  // had a door: `holdOpen`, `slowSink` and `canReach` had NO caller, and `resolveRetrieval` was reachable
  // only from author mode and the world tick.
  // ⚠️ THE VERBS STAY SEPARATE. Aevi: "Ashwardens DRAG, Numinous INVITE, Threnody DELAYS, Rootkin PAY A
  // PRICE." A single `retrieve` op would have collapsed five traditions into one mechanic — the one thing
  // her spec asked this build not to do.
  {
    const appSrc270 = readFileSync(join(root, "app.js"), "utf8");
    const gmSrc270 = readFileSync(join(root, "engine/gm.js"), "utf8");

    check("CCODE-270: the app applies a deathOps step and imports the verbs it needs",
      /applyStep\("deathOps"/.test(appSrc270) && /holdOpen/.test(appSrc270)
      && /slowSink/.test(appSrc270) && /canReach/.test(appSrc270));
    // ⛔ ALL THREE VERBS, not one. If a future edit collapses them, this goes red.
    check("CCODE-270: hold, slow and retrieve are three separate ops — five traditions, not one mechanic",
      /"hold"/.test(appSrc270) && /"slow"/.test(appSrc270) && /"retrieve"/.test(appSrc270));
    check("CCODE-270: the GM contract names deathOps and all three verbs",
      /deathOps/.test(gmSrc270) && /hold \| slow \| retrieve/.test(gmSrc270));
    // ⚠️ AND IT MUST TELL THE NARRATOR WHAT IT MAY NOT DO. The engine decides reach and sealing; a GM that
    // narrates "they are gone" on its own has taken a permanent decision the rules own.
    check("CCODE-270: …and forbids the narrator from declaring someone sealed or returned in prose",
      /NEVER declare someone sealed or returned in prose/.test(gmSrc270));
    // ⛔ SALVAGEABLE, or a truncated reply drops it — the gate that caught me on projectOps.
    check("CCODE-270: deathOps survives a truncated reply",
      /"deathOps"/.test(gmSrc270.slice(gmSrc270.indexOf("SALVAGEABLE_OPS"))));

    // ── AND THE BEHAVIOUR THE DOOR IS FOR, through the real module
    {
      const DTH270 = await import("../engine/death.js");
      const rules270 = C199.rules || {};
      // refused costs nothing; failed costs a rung. That distinction is why `canReach` exists.
      const deep = DTH270.enterDeathState({ id: "d", name: "Veth" }, { diedDay: 0, depthOverride: 2 });
      const before = DTH270.deathDepth(deep, 1, rules270);
      const refused = DTH270.canReach(deep, { rank: 1, currentDay: 1, rules: rules270 });
      check("CCODE-270: a reach past your rank is refused and the dead are exactly where they were",
        refused.ok === false && DTH270.deathDepth(deep, 1, rules270) === before);
      DTH270.resolveRetrieval(deep, "fail", { currentDay: 1 });
      check("CCODE-270: …whereas TRYING and failing at the deep dark seals them — the two are not the same event",
        DTH270.isSealed(deep, 1, rules270) === true);
    }
  }




}
// ---- CCODE-198: the first picture stays, and the composer waits to be asked ----------------------
// ⛔ ERIK: "I don't want the first generated image to disappear. sometimes it's quite good... I'm
// leaning to not even generating a second image immediately. Let the user click regen if they want (that
// will use the prompt gen feature)."
// ⚠️ CCODE-193 WAS TWO DECISIONS BOLTED TOGETHER: compose the line (good) and replace the picture
// unasked (his to refuse). Only the second one is reversed here.
{
  const AR198 = await import("../engine/art.js");
  const app198 = readFileSync(join(root, "app.js"), "utf8");
  // 1 · ⛔ A RE-ROLL COMPOSES FOR A RECORD-BACKED SUBJECT, which is what makes "click regen if you want"
  // a real offer. It did not before: `regenerateImage` re-derives its own prompt, so the composer at the
  // call site only ever saw a re-describe or a prompt-only tile.
  check("CCODE-198: Draw again composes for a record-backed subject, not just a re-describe",
    /const rawWords = describe \|\| \(record \? regenPromptFor\(record, it\.regen\.kind/.test(app198),
    "without this, the button Erik was pointed at does not use the feature he was pointed at it for");
  // 2 · ⚠️ AND THE LIKENESS SURVIVES IT. `promptOverride` deliberately skips `withLikeness`, so composing
  // the bare assembly would have thrown away every look the player kept — a silent cost paid on the exact
  // button they press when they care most about how someone looks.
  {
    const rec = { id: "x198", name: "Someone", appearance: "a plain coat" };
    const keeps = [{ prompt: "white hair, sharp jaw" }, { prompt: "white hair, a long scar" }];
    const bare = AR198.regenPromptFor(rec, "npc", { promptOpts: {} });
    const voted = AR198.regenPromptFor(rec, "npc", { promptOpts: { keeps } });
    check("CCODE-198: the line a re-roll composes INCLUDES the kept likeness",
      /white hair/i.test(voted) && !/white hair/i.test(bare) && /plain coat/.test(voted), voted.slice(0, 90));
  }

  // 5au · CCODE-271 / ERIK'S RULING — HOW MANY YOU CAN LEAD IS EARNED.
  // He chose [C] and improved it: "as a player gains notoriety tier, hero, epic, etc... that will allow
  // them to... have more party members they can include and have act with them — for now 3 is a good
  // number to set as the goal, with 1 party member that you get to have take turns per x number of
  // levels... maybe based on social skills?"
  // ⚠️ MY ORIGINAL WAS A FIXED 3, which gave a level-1 character the same battle line as a level-30 one —
  // the opposite of a development arc.
  {
    const ML271 = await import("../engine/melee.js");
    const silas271 = JSON.parse(readFileSync(join(root, "characters/player-s9z9u1/char-mrhs8286.json"), "utf8"));

    // ⛔ +1 IS ALWAYS YOU. A slot count that could reach zero would delete the player from their own fight.
    check("CCODE-271: a level-1 newcomer with nothing still takes their own turn",
      ML271.commandSlots({ level: 1, subAttributes: { presence: 2 } }).slots === 1);

    // THE THREE EARNED SOURCES, each separately legible
    check("CCODE-271: levels earn slots — Erik's '1 per x number of levels'",
      ML271.commandSlots({ level: 12, subAttributes: { presence: 2 } }).slots === 2);
    // ⛔ AND `presence` IS ALREADY THE RIGHT STAT — its own authored description in progression.js reads
    // "Command and inspiration — leading, being heeded, holding a room". A second ladder called Leadership
    // would have been two names for one thing, which is the failure Erik named on temp soak.
    check("CCODE-271: presence earns one — you can hold a room, so you can hold a line",
      ML271.commandSlots({ level: 12, subAttributes: { presence: 8 } }).slots >
      ML271.commandSlots({ level: 12, subAttributes: { presence: 2 } }).slots);
    check("CCODE-271: renown earns one — people follow someone they have heard of",
      ML271.commandSlots({ level: 5, subAttributes: { presence: 2 } }, { cfg: { maxNamed: 9 }, renownBand: "renowned" }).slots >
      ML271.commandSlots({ level: 5, subAttributes: { presence: 2 } }, { cfg: { maxNamed: 9 } }).slots);
    // ⚠️ and an unremarkable band earns nothing — the source must discriminate or it is decoration
    check("CCODE-271: …and being merely 'locally known' earns nothing",
      ML271.commandSlots({ level: 5, subAttributes: { presence: 2 } }, { cfg: { maxNamed: 9 }, renownBand: "locally known" }).slots ===
      ML271.commandSlots({ level: 5, subAttributes: { presence: 2 } }, { cfg: { maxNamed: 9 } }).slots);

    // ⛔ THE CAP IS A GOAL, NOT A LAW — Erik: "for now 3 is a good number to set AS THE GOAL." The property
    // that makes that safe is that the ladder KEEPS PAYING when the goal moves: a character who has earned
    // more than the cap allows must get more the moment it rises, or raising it would require a re-grind.
    {
      const at = (cap) => ML271.commandSlots(silas271, { cfg: { maxNamed: cap }, renownBand: "renowned" }).slots;
      check("CCODE-271: Silas is capped at 3 today and would lead more the instant the goal moves",
        at(3) === 3 && at(4) === 4 && at(5) === 5 && at(6) === 6);
      check("CCODE-271: …and the receipt says he is capped, so the earned-but-unspent is visible",
        ML271.commandSlots(silas271, { cfg: { maxNamed: 3 }, renownBand: "renowned" }).capped === true);
    }
    // ⚠️ NON-VACUITY: the cap must actually bind on someone, or every claim above passes on a low ceiling.
    check("CCODE-271: the cap genuinely binds — Silas has earned more than it allows (floor)",
      ML271.commandSlots(silas271, { cfg: { maxNamed: 3 } }).earned.reduce((a, e) => a + e.n, 0) + 1 > 3);

    // ⚠️ AND IT READS OFF THE SUB-ATTRIBUTE, falling back to the parent — a character mid-migration must not
    // silently lose their command.
    check("CCODE-271: presence falls back to the social parent for a character without sub-attributes",
      ML271.commandSlots({ level: 1, attributes: { social: 9 } }).slots === 2);
  }

  // 5av · CCODE-272/273 — ERIK'S RULINGS: withdrawing, the forward pick, and a summon the roll shapes.
  {
    const CB272 = await import("../engine/combatants.js");
    const ML272 = await import("../engine/melee.js");
    const NS272 = await import("../engine/npcsheet.js");

    // ═══ ① SOME OF THEM GET OUT OF THE FIGHT ENTIRELY ═══
    // ⛔ ERIK: "we need to make a way to allow for certain entities/party members to avoid a combat
    // altogether. Marrow might take flight and stay above the fray, or Calvar might dive for cover."
    // ⚠️ THIS IS A THIRD STATE. Not `canStrike: false` — that one is still standing there being swung at,
    // which is the whole reason interception exists. Not `downed`. Present in the scene, out of the exchange.
    check("CCODE-272: `withdraws` authors HOW, because the manner is the point — Marrow goes UP, Calvar DOWN",
      CB272.withdrawalOf({ withdraws: "takes to the air" })?.manner === "takes to the air"
      && CB272.withdrawalOf({ withdraws: { manner: "dives for cover", auto: true } })?.auto === true
      && CB272.withdrawalOf({}) === null);
    {
      const ch = { id: "p", name: "You", companions: [{ id: "m" }, { id: "s" }] };
      const comps = { m: { id: "m", name: "Marrow", withdraws: { manner: "takes to the air", auto: true } },
                      s: { id: "s", name: "Sprig" } };
      const names = CB272.targetableAllies(ch, { companions: comps }).map(a => a.name);
      check("CCODE-272: a withdrawn ally is NOT a target — nothing swings at someone in the air",
        !names.includes("Marrow") && names.includes("Sprig") && names.includes("You"));
      // ⛔ ONE FIELD, EVERY CONSUMER. `present` is what chooseTarget, targetableAllies and the interception
      // chooser already filter on — a parallel `withdrawn` flag would have needed adding to each, and the
      // one that got missed would be the one that swung at someone who had left.
      const TG272 = await import("../engine/targeting.js");
      const roster = CB272.alliesOf(ch, { companions: comps });
      check("CCODE-272: …and the foe's own chooser honours it without knowing the word 'withdraw'",
        TG272.chooseTarget(roster, { policy: "weakest" })?.target?.name !== "Marrow");
    }
    // ⚠️ CAPABILITY, NOT AUTOMATIC — an entity that always withdrew would never be at risk and never need
    // protecting; one that never could is a hostage.
    check("CCODE-272: a companion who CAN withdraw but has not is still present and still targetable",
      CB272.alliesOf({ id: "p", companions: [{ id: "m" }] },
        { companions: { m: { id: "m", name: "M", withdraws: { manner: "hides" } } } })
        .find(a => a.id === "m")?.present === true);

    // ═══ ② WHO IS FORWARD IS A PLAYER PICK, AND IT IS SWAPPABLE ═══
    // ⛔ ERIK, answering the question no simulation could: "Named companions folded into the aggregate still
    // feel like people... you only have so much focus... if you want to have them be turn by turned you just
    // swap them out with someone else — so this needs to be a UI pick."
    {
      const roster = [
        { id: "player", name: "You", isPlayer: true, present: true, canAct: true },
        { id: "a", name: "Ana", present: true, canAct: true },
        { id: "b", name: "Bel", present: true, canAct: true },
        { id: "c", name: "Cor", present: false, withdrawal: { manner: "hides" } },
      ];
      const def = ML272.bringForward(roster, { slots: 2 });
      check("CCODE-272: the player is always forward and does not spend a pick",
        def.forward[0]?.isPlayer === true && def.forward.length === 2);
      const picked = ML272.bringForward(roster, { slots: 2, chosen: ["b"] });
      check("CCODE-272: …and the pick decides who joins them — swapping is the whole mechanic",
        picked.forward.map(a => a.id).join(",") === "player,b");
      check("CCODE-272: those not brought forward are NAMED, not counted — a party, not a number",
        picked.folded.map(a => a.name).join(",") === "Ana" && /Ana/.test(picked.why));
      // ⛔ AN INVALID PICK IS DROPPED, NOT HONOURED — spending a slot on someone who has withdrawn would
      // buy a beat that says "they do nothing".
      check("CCODE-272: picking someone who has withdrawn spends no slot",
        !ML272.bringForward(roster, { slots: 2, chosen: ["c"] }).forward.some(a => a.id === "c"));
      check("CCODE-272: …and the withdrawn are reported separately, so the player sees what left",
        def.withdrawn.map(a => a.id).join(",") === "c");
    }

    // ═══ ③ A SUMMON THE ROLL SHAPES ═══
    // ⛔ ERIK on Aevi's rising tierGap: "fine, but i would also tie it to how well you succeeded at the
    // skill and if you crit." ⚠️ THAT CHANGES WHAT THE FIELD MEANS — an authored gap was a promise about the
    // craft; now it is a FLOOR the roll can beat, and a shade worse than its maker is a thing that HAPPENED.
    {
      const shade = { id: "driven_shade", name: "Driven Shade",
        summon: { tierGap: [-1, 0, 1], count: 1, contributions: ["MARTIAL", "KNOW"] } };
      const gap = (rank, degree) => NS272.summonGap(shade, { rank, degree }).gap;
      check("CCODE-273: the authored ladder is read per rank — Aevi's −1 → 0 → +1",
        gap(1, "success") === -1 && gap(2, "success") === 0 && gap(3, "success") === 1);
      check("CCODE-273: a crit beats the craft's promise; a partial falls short of it",
        gap(3, "crit_success") === 2 && gap(3, "partial") === 0 && gap(1, "partial") === -2);
      // ⛔ AND IT REACHES THE SHEET, or the ruling is a number nobody reads.
      check("CCODE-273: the caster's level sets the summon's, shifted by the gap",
        NS272.summonSheetFor(shade, 5, { rank: 3, degree: "crit_success" }).level === 7
        && NS272.summonSheetFor(shade, 5, { rank: 1, degree: "partial" }).level === 3);
      // ⚠️ THE LITE PART, EXPLICITLY — Aevi listed the exclusions and they are the whole difference between
      // a summon and a companion.
      const sh = NS272.summonSheetFor(shade, 5, { rank: 2 });
      check("CCODE-273: a summon has no growth arc, no inventory and no permanence",
        sh.crafts === undefined && sh.kit === undefined && sh.growth === undefined && sh.permanent === undefined);
      // ⛔ NON-VACUITY: sheetFor must actually have honoured the override, not just been handed one.
      check("CCODE-273: …and the level really came from the caster, not from the record (floor)",
        NS272.summonSheetFor(shade, 20, { rank: 2 }).level === 20
        && NS272.summonSheetFor(shade, 3, { rank: 2 }).level === 3);
    }
  }


  // 3 · ⛔ AND NOTHING REPLACES A PICTURE THE PLAYER DID NOT ASK ABOUT. The queue verifies; it does not
  // draw. A second draw now costs a click, and the first one stays as a version rather than being overwritten.
  {
    const drain198 = app198.slice(app198.indexOf("async function drainCompositions"), app198.indexOf("onComposedLookup("));
    check("CCODE-198: the automatic second draw is GONE — the queue never composes and never re-mints",
      !/composeImagePrompt/.test(drain198) && !/imageURLFor/.test(drain198)
      && /settleMintedUrl\(job, await verifiedImageUrl\(job\.url\)\);/.test(drain198));
    // ⚠️ "KEEP THE FIRST ONE AND STACK THEM" NEEDS NO NEW MACHINERY, and that is worth gating rather than
    // assuming: SNG-401's re-roll returns a NEW item carrying `versionOf`, so the old picture stays in the
    // stack. If that ever became a replacement, Erik's first sentence would break silently.
    check("CCODE-198: a re-roll ADDS a version rather than replacing the picture it was launched from",
      /versionOf: it\.versionOf \|\| it\.url/.test(app198));
  }

  // 5aw · CCODE-274 — THE MELEE WIRED, AS THE THING YOU GROW INTO.
  // ⛔ ERIK ruled [C] and then framed the whole ladder: "around when you're hitting the named npc party
  // member cap you're likely to have enough of a following to have a band or unit that would operate in the
  // simplified sense... Taken a bit further you'll have multiple units and legions and armies."
  // ⚠️ SO THE SCALE TIERS ARE A PROGRESSION, NOT A PERFORMANCE OPTIMISATION. The command ladder and the
  // melee tiers are one arc seen twice, and this wires the first rung of it.
  {
    const EN274 = await import("../engine/encounters.js");
    const melee274 = await import("../engine/melee.js");
    const silas274 = JSON.parse(readFileSync(join(root, "characters/player-s9z9u1/char-mrhs8286.json"), "utf8"));
    const mf274 = JSON.parse(readFileSync(join(root, "content/packs/valley/companions/marrow.json"), "utf8"));
    const marrow274 = { ...((mf274.companions || [mf274])[0]), withdraws: { manner: "takes to the air", auto: true } };
    // ⚠️ LOADED LOCALLY. `C199` belongs to a block that closed long before this one — my first version
    // referenced it anyway and the SUITE DIED HERE, which dropped the pass count 4,396 → 4,350 while the
    // failure count stayed at 1. A suite that exits early looks exactly like one that passed, and reading
    // the failure count rather than the pass count is how that goes unnoticed.
    const { loadContentHeadless: lch274 } = await import("./headless_content.mjs");
    const C274 = await lch274();
    const rules274 = C274.rules || {}, sb274 = C274.skillBattle?.engine || C274.rules?.skillBattle || {};
    const def274 = { id: "f", type: "duel", name: "a reaver", opponent: { name: "a reaver", health: 40, yieldAt: 0 } };
    const mk = (character, content) => EN274.skillBattleRound(
      EN274.startEncounter(def274, { oppSheet: { attributes: { physical: 9 }, level: 10, energy: 80, health: 40 } }),
      def274, { function: "strike", tier: 3, attribute: "mental", intensity: "standard", name: "the braid" },
      { character, content, rules: rules274, sb: sb274, steps: rules274.resolution || {}, rng: () => 0.5 });

    const withParty = mk(silas274, { ...C274, companions: { marrow: marrow274 } });
    // ⛔ NAMES, NOT IDS. Company members live in `character.npcRegistry`, not in content — passing only
    // `content.npcs` resolved none of them and the party came back as "pell", "veth-ondra", with every
    // name-derived read working from nothing.
    check("CCODE-274: the party resolves by NAME — the character's own registry is in the lookup",
      withParty.party?.forward?.some(a => /Pell Ran Marsh/.test(a.name))
      && !withParty.party.forward.some(a => a.name === a.id));
    check("CCODE-274: you and those you brought forward act; the rest are IN THE MELEE, named",
      withParty.party.forward.length === withParty.party.slots
      && withParty.party.folded.length >= 1
      && withParty.party.folded.every(a => a.name && a.name !== a.id));
    // ⛔ THE WITHDRAWN LIST COULD NEVER POPULATE. I derived the split from `targetableAllies`, which is
    // exactly the filter that removes them — a list that can never fill is worse than no list, because it
    // reads as "nobody withdrew" rather than as "this was never checked".
    check("CCODE-274: someone who took to the air appears as WITHDRAWN, with the manner",
      withParty.party.withdrawn.some(a => /Marrow/.test(a.name) && /air/.test(String(a.manner))));

    // ⛔ AND THE FOLDED REACH THE DAMAGE, or "they are in the fight" is decoration. This is the whole
    // mechanical content of [C]: the party is bigger, the foe takes more, the round stays three beats.
    check("CCODE-274: the folded party adds to the blow, and the receipt NAMES who",
      withParty.damage?.melee?.added > 0 && withParty.damage.melee.by.length >= 1
      && withParty.damage.melee.by.every(n => typeof n === "string" && n.length > 2));
    // ⚠️ MEASURED COMPRESSION, not a per-ally bonus. `predictAggregate` scales the mean with K and the
    // spread with √K; the naive K× alternative matches on the average and is 614% wrong on the spread.
    check("CCODE-274: …and it grows with the party rather than being a flat bonus",
      (() => { const ML = melee274; const one = ML.predictAggregate({ mean: 2, sd: 1 }, 1).mean;
        const four = ML.predictAggregate({ mean: 2, sd: 1 }, 4).mean;
        return four === one * 4 && ML.predictAggregate({ mean: 2, sd: 1 }, 4).sd < one * 4; })());

    // ⛔ AND A SOLO CHARACTER IS UNTOUCHED. The gate I said I would write first and keep.
    const alone = mk({ ...silas274, companions: [], company: [] }, { ...C274, companions: {} });
    check("CCODE-274: travelling alone there is no party block and no melee contribution — solo is unchanged",
      alone.party === undefined && alone.damage?.melee === undefined);
  }

  // 5ax · CCODE-275 / ERIK — AN ENCOUNTER CONTAINS SCALES; IT IS NOT AT ONE.
  // ⛔ "every encounter could have 1, some or all of the types of battle... even if you're in the middle of
  // your army you might have to duel an assassin... 1 v army isn't a contest, but the encounter scenario
  // would drive the details. my party vs guards on a castle wall might be a fair fight... but if they open
  // the gates to let a unit of cavalry charge it turns lopsided fast, unless I use some majorly big powers
  // or prepared ground traps."
  // ⚠️ THAT CORRECTS `resolutionTier`, which picks ONE tier from a headcount. A headcount cannot know the
  // assassin reaching you is a DUEL inside a LEGION battle — and the duel is the part you play.
  {
    const ML275 = await import("../engine/melee.js");

    // ⚠️ ONE LADDER, NOT TWO. The scales must be the same rungs as the tiers, or the system has grown two
    // names for one idea — the failure Erik named on temp soak and I committed on deathdepth this week.
    check("CCODE-275: the scale ladder is the tier ladder — individual → party → unit → legion",
      ML275.SCALES.length === 4 && ML275.scaleRank("individual") === 0 && ML275.scaleRank("legion") === 3);

    // ═══ ERIK'S CASTLE WALL, VERBATIM ═══
    const wall = { opponent: { name: "the wall guards" }, theatres: [
      { scale: "party", who: "guards on the wall", opensOn: 1 },
      { scale: "unit", who: "cavalry through the gate", opensOn: 3, why: "they open the gates" } ] };
    const openAt = (round) => ML275.theatresOf(wall, { round }).filter(t => t.open);
    check("CCODE-275: the wall starts as a fair party fight",
      openAt(1).length === 1 && openAt(1)[0].scale === "party");
    // ⛔ `opensOn` IS THE CAVALRY. A theatre that opens partway through is how "they open the gates" becomes
    // a mechanic rather than narration — the fight WAS fair, and then it was not.
    check("CCODE-275: …and on round 3 a UNIT theatre opens beside it — the fight was fair, then it was not",
      openAt(3).length === 2 && openAt(3).some(t => t.scale === "unit"));

    // ⛔ THE ASSASSIN INSIDE THE LEGION — his other example, and the one a headcount can never express.
    const battle = { opponent: { name: "the enemy line" }, theatres: [
      { scale: "legion", who: "the enemy line" }, { scale: "individual", who: "an assassin" } ] };
    const t = ML275.theatresOf(battle, { round: 1 });
    check("CCODE-275: a duel and a legion battle coexist in one encounter — the duel is the part you play",
      t.length === 2 && t.some(x => x.scale === "legion") && t.some(x => x.scale === "individual"));

    // ⚠️ AND AN UNAUTHORED ENCOUNTER IS UNCHANGED — derived from the headcount exactly as before.
    check("CCODE-275: an encounter with no theatres authored derives one, as today",
      ML275.theatresOf({ opponent: { name: "a raider" } }, { allyCount: 1, foeCount: 1 })[0].derived === true);

    // ═══ 1 v ARMY IS NOT A CONTEST ═══
    // ⚠️ A GAP OF ONE STAYS A ROLL. A party against a unit is lopsided, not hopeless, and making it
    // unwinnable would delete the fights people actually want to have.
    check("CCODE-275: outweighed by one scale is a HARD FIGHT and still a roll",
      ML275.overmatchOf("party", "unit").overmatched === false
      && ML275.overmatchOf("party", "unit").hard === true);
    check("CCODE-275: outweighed by two is NOT A CONTEST — no roll wins it",
      ML275.overmatchOf("party", "legion").overmatched === true
      && ML275.overmatchOf("individual", "unit").overmatched === true);
    // ⛔ AND IT RETURNS A SITUATION, NOT A MODIFIER. Handing back "-40 to your chance" would be the same
    // mistake in a politer form — you do not out-roll an army.
    {
      const o = ML275.overmatchOf("individual", "legion");
      check("CCODE-275: the refusal carries no penalty number — it is a situation, not a difficulty",
        o.modifier === undefined && o.penalty === undefined && Array.isArray(o.answers) && o.answers.length >= 2);
    }

    // ═══ AND ERIK'S TWO ANSWERS, AND ONLY HIS TWO ═══
    {
      const o = ML275.overmatchOf("party", "legion");
      check("CCODE-275: holding nothing, an overmatch is not answered — and it says what remains",
        ML275.answersOvermatch(o).answered === false && /leave/.test(ML275.answersOvermatch(o).remaining));
      check("CCODE-275: a power big enough answers it — 'some majorly big powers'",
        ML275.answersOvermatch(o, { powers: [{ id: "ruin", name: "The Measured Ruin", scaleAnswer: 2 }] }).by === "power");
      // ⚠️ AND A SMALL POWER DOES NOT. A craft that answered any gap would make the wall decorative.
      check("CCODE-275: …but an ordinary craft does not — the wall is real",
        ML275.answersOvermatch(o, { powers: [{ id: "jab", name: "a jab", magnitude: 1 }] }).answered === false);
      check("CCODE-275: prepared ground answers it — 'prepared ground traps'",
        ML275.answersOvermatch(o, { ground: [{ id: "pits", name: "pit traps at the gate" }] }).by === "ground");
      // ⛔ NON-VACUITY: an unanswered overmatch and an answered one must differ, or every claim above is
      // passing on a function that always says yes.
      check("CCODE-275: answered and unanswered genuinely differ (floor)",
        ML275.answersOvermatch(o).answered !== ML275.answersOvermatch(o, { ground: [{ id: "x" }] }).answered);
      // ⚠️ and a fight that is merely HARD needs no answer — nothing to void
      check("CCODE-275: a hard fight needs no answer — only a wall does",
        ML275.answersOvermatch(ML275.overmatchOf("party", "unit")).answered === true);
    }
  }


}
// ---- CCODE-197: hold several traditions, and ask by exact function ------------------------------
// ⛔ ERIK, THREE THINGS IN ONE BREATH: "a bare tradition click should hide things too. Also, the bare
// tradition include the adjacent ones by mistake. I want to be able to click multiple traditions at a time
// as well... with a second click to turn them off. In addition, it would be great to filter by ALL the
// skill functions, not just the primary families, so I can find very specific skill options."
{
  const { wheelRejects, inTraditions, matchesFunction } = await import("../engine/wheelgeom.js");
  const { loadContentHeadless: lch197 } = await import("./headless_content.mjs");
  const C197 = await lch197();
  const death = { cls: "death", functions: ["strike"], families: ["HARM"] };
  const life = { cls: "life", functions: ["heal"], families: ["RESTORE"] };
  const braid = { braid: true, parentTrads: ["death", "order"], functions: ["bind"], families: ["PROTECT"] };
  // 1 · SEVERAL AT ONCE, and holding two is not the same as holding neither.
  {
    const two = new Set(["death", "life"]);
    check("CCODE-197: several traditions can be held at once, and each one keeps its own crafts",
      inTraditions(death, two) && inTraditions(life, two)
      && !inTraditions({ cls: "chaos" }, two)
      && !wheelRejects(life, { selTrads: two }) && wheelRejects({ cls: "chaos" }, { selTrads: two }));
    check("CCODE-197: an empty selection filters nothing (releasing the last one restores the wheel)",
      !wheelRejects({ cls: "chaos" }, { selTrads: new Set() }));
  }

  // 5ay · CCODE-276 — THE UI. Erik: "have you made sure the ui allows for these new features?"
  // ⛔ THE ANSWER WAS NO, TEN FOR TEN. Every combat feature built this week — the target reveal, the forward
  // pick, the melee contribution, interception receipts, withdrawal — was engine-only. A player could see
  // none of it and use none of it.
  // ⚠️ THAT IS THE "built, tested, unreachable" DEFECT I HAVE SPENT THE WEEK FINDING IN OTHER PEOPLE'S WORK,
  // committed at the layer where it is most visible, while narrating the lesson. A gate that only tests the
  // engine will stay green through exactly this.
  {
    const appSrc276 = readFileSync(join(root, "app.js"), "utf8");
    const has = (s) => appSrc276.includes(s);

    // ⛔ THE SENSE ROUND'S WHOLE PAYOFF. Erik: "you need to sense who's getting attacked so you can intervene
    // if you want." Revealed by the engine since CCODE-250 and shown nowhere.
    check("CCODE-276: the fog renders WHO the foe is going for, and whether you could step in",
      has("fog.revealed.target") && has("canIntervene"));

    // ⛔ "SO THIS NEEDS TO BE A UI PICK" — his words, and there was no control at all.
    check("CCODE-276: the party block renders, with the forward pick as clickable names",
      has("sb-fwd") && has("data-sbfwd") && has("bringForward") && has("commandSlots"));
    check("CCODE-276: …and clicking one persists the swap on the ENCOUNTER state, not just the render",
      /enc\.state\.broughtForward = /.test(appSrc276));
    // ⚠️ the folded and the withdrawn must be NAMED in the panel — "two others are helping" is a number
    check("CCODE-276: the folded and the withdrawn are shown by name, not counted",
      has("in the melee — fighting, not narrated") && has("withdrawal?.manner"));

    // ⛔ THE RECEIPT LINES. A silent bonus makes the party stop existing at the moment it mattered.
    check("CCODE-276: the round log says the folded party added to the blow, and names them",
      has("rr.damage?.melee") && has("are in it too"));
    check("CCODE-276: …and that a blow landed on an ALLY rather than on you",
      /rr\.damage\?\.onName/.test(appSrc276));
    check("CCODE-276: …and who caught what — a tank mechanic nobody can see is one nobody thanks",
      has("rr.imposed?.intercepted") && has("rr.damage?.intercepted"));
    check("CCODE-276: …and that a swing went where the foe THOUGHT you were",
      has("rr.blindStrike"));

    // ⚠️ AND THE DIALS ARE AUTHORED BECAUSE THEY ARE READ. app.js reads `rules.melee`; a block no pack
    // provides is a phantom control, and the audit caught me creating one in the same session.
    {
      // ⚠️ LOADED LOCALLY, AGAIN. This is the SECOND time today I reached for `C199` from a block that had
      // closed, and both times the suite exited early — pass count 4,416 → 4,380 while the failure count
      // stayed at 1. `C199` is scoped to one block a thousand lines up; there is no shared corpus at this
      // depth, and treating it as a global is a habit that costs a silent suite death every time.
      const { loadContentHeadless: lch276 } = await import("./headless_content.mjs");
      const mel = ((await lch276()).rules || {}).melee || {};
      check("CCODE-276: the melee dials are authored, and every one is read by name",
        Number(mel.maxNamed) === 3 && Number(mel.levelsPerSlot) > 0
        && Number(mel.presenceForSlot) > 0 && Array.isArray(mel.renownBandsForSlot));
      // ⛔ SUPERSEDED BY CCODE-277, AND THE SUPERSESSION IS THE POINT. This asserted `overmatchGap` was
      // ABSENT, because at CCODE-276 nothing in play called `overmatchOf` and a dial ahead of its reader is
      // a knob with nothing on the other end. CCODE-277 wired the reader, so the dial is authored now —
      // in the same change, which is the rule. ⚠️ THE CLAIM SURVIVES, INVERTED: every dial in this block
      // must have a reader, and the test is now that the two arrived together.
      check("CCODE-277: every melee dial has a reader — none is authored ahead of the code that reads it",
        Object.keys(mel).filter(k => !k.startsWith("_")).every(k =>
          readFileSync(join(root, "engine/melee.js"), "utf8").includes(k)
          || readFileSync(join(root, "engine/encounters.js"), "utf8").includes(k)),
        Object.keys(mel).filter(k => !k.startsWith("_")).join(","));
    }
  }

  // 2 · ⛔ AND ADJACENCY IS NOT MEMBERSHIP. This is the one Erik called a mistake: the ring-neighbours of
  // a held tradition were being shown as though they belonged to it, so a narrowing silently widened.
  {
    const idx = C197.traditionIndex || {};
    const ring = Object.keys(idx.ringPos || idx.positions || {});
    check(`CCODE-197: a tradition NEXT to a held one is not included (${ring.length ? "checked on the live ring" : "no ring index"})`,
      !inTraditions({ cls: "life" }, new Set(["death"])), "adjacency is a fact about the circle, not about a craft");
    // ⚠️ BUT A BRAID IS MADE OF ITS PARENTS, which is the one inclusion that is not a widening.
    check("CCODE-197: a braid built FROM a held tradition is kept; one built from neither is not",
      inTraditions(braid, new Set(["death"])) && inTraditions(braid, new Set(["order"]))
      && !inTraditions(braid, new Set(["life"])));
  }

  // 5az · CCODE-277 — THEATRES AND OVERMATCH REACH PLAY, BOTH ENDS IN ONE CHANGE.
  // ⛔ Last time I built an engine feature and shipped no UI, and Erik had to ask. This gate asserts the
  // engine caller, the state carry, the damage floor AND the render — because any one of them missing makes
  // the other three unreachable, and only the last one is visible to a player.
  {
    const EN277 = await import("../engine/encounters.js");
    const { loadContentHeadless: lch277 } = await import("./headless_content.mjs");
    const C277 = await lch277();
    const silas277 = JSON.parse(readFileSync(join(root, "characters/player-s9z9u1/char-mrhs8286.json"), "utf8"));
    const alone277 = { ...silas277, companions: [], company: [] };
    const run = (character, def) => {
      const st = EN277.startEncounter(def, { oppSheet: { attributes: { physical: 9 }, level: 10, energy: 80, health: 40 } });
      return EN277.skillBattleRound(st, def, { function: "strike", tier: 3, attribute: "mental", intensity: "standard", name: "braid" },
        { character, content: C277, rules: C277.rules, sb: C277.skillBattle?.engine || {}, steps: C277.rules.resolution || {}, rng: () => 0.5 });
    };
    const host = { id: "a", type: "duel", name: "the host", opponent: { name: "the host", health: 40, yieldAt: 0 },
      theatres: [{ scale: "legion", who: "the host" }] };

    // ⛔ "NO ROLL WINS THIS" IS MECHANICAL, NOT A BANNER. A warning above a round that resolved normally
    // would let a player beat an army by rolling well — which is the thing Erik ruled out, and exactly how a
    // warning becomes decoration.
    const solo = run(alone277, host);
    check("CCODE-277: one character against a host is NOT A CONTEST, and the state says so",
      solo.state.yourScale === "individual" && solo.state.overmatch?.overmatched === true);
    check("CCODE-277: …and the blow is floored — the wall is real, not a label",
      solo.damage?.overmatched?.was > solo.damage.amount && solo.damage.amount > 0);
    // ⚠️ FLOORED, NOT ZEROED. You can still hurt an army; you cannot beat one. Zero would read as a bug.
    check("CCODE-277: …but not zeroed — a 0 reads as broken rather than as a wall",
      solo.damage.amount > 0);
    // ⛔ AND THE REFUSAL ARRIVES WITH ITS ANSWERS. A wall with no door on it is a cutscene.
    check("CCODE-277: the refusal carries Erik's answers, including the honest third one",
      (solo.state.overmatch.answers || []).length >= 3
      && solo.state.overmatch.answers.some(a => /prepared/.test(a))
      && solo.state.overmatch.answers.some(a => /not being there/.test(a)));

    // ⚠️ AND IT LIFTS THE MOMENT IT IS ANSWERED — the answer is to change the situation, never to roll harder.
    {
      const st = EN277.startEncounter(host, { oppSheet: { attributes: { physical: 9 }, level: 10, energy: 80, health: 40 } });
      const prepared = EN277.skillBattleRound({ ...st, preparedGround: [{ id: "pits", name: "pit traps" }] }, host,
        { function: "strike", tier: 3, attribute: "mental", intensity: "standard", name: "braid" },
        { character: alone277, content: C277, rules: C277.rules, sb: C277.skillBattle?.engine || {},
          steps: C277.rules.resolution || {}, rng: () => 0.5 });
      check("CCODE-277: prepared ground answers it, and the floor lifts — it is a fight again",
        prepared.state.overmatch?.answer?.answered === true && !prepared.damage?.overmatched);
    }

    // ⛔ A PARTY IS ONLY OUTWEIGHED, NOT WALLED. One scale of difference stays a roll — making it unwinnable
    // would delete the fights people actually want to have.
    {
      const party = run(silas277, { ...host, theatres: [{ scale: "legion", who: "the host" }] });
      check("CCODE-277: a band against a host is a HARD FIGHT, not a wall — one gap stays a roll",
        party.state.overmatch === null && party.state.outweighed && !party.damage?.overmatched);
    }

    // ⚠️ AND AN UNAUTHORED ENCOUNTER IS UNTOUCHED.
    const plain = run(silas277, { id: "p", type: "duel", name: "a raider", opponent: { name: "a raider", health: 20, yieldAt: 0 } });
    check("CCODE-277: an ordinary fight has one derived theatre and no wall",
      (plain.state.theatres || []).length === 1 && plain.state.overmatch === null && plain.state.outweighed === null);

    // ⛔ AND THE UI RENDERS IT — the half I shipped without last time.
    {
      const appSrc277 = readFileSync(join(root, "app.js"), "utf8");
      check("CCODE-277: the panel renders the scale banner from STATE, with the answers beside the refusal",
        appSrc277.includes("sbScale") && appSrc277.includes("st.overmatch")
        && appSrc277.includes("st.theatres") && /overmatch\.answers/.test(appSrc277));
      check("CCODE-277: …and shows the merely-outweighed case differently from the wall",
        appSrc277.includes("st.outweighed"));
    }
    // ⚠️ AND THE DIALS ARE AUTHORED IN THIS CHANGE, not ahead of it — the rule I broke and then followed.
    check("CCODE-277: overmatchGap and its damage floor are authored now that something reads them",
      Number(C277.rules?.melee?.overmatchGap) === 2
      && Number(C277.rules?.melee?.overmatchedDamageKept) > 0);
  }

  // 5ba · CCODE-278 — A BAND, AND THE ASYMMETRY THAT MADE EVERY ONE OF THEM ROUT.
  // ⛔ ERIK: "around when you're hitting the named npc party member cap you're likely to have enough of a
  // following to have a band or unit... that allows for you to go into larger battles and operate against
  // other units... nearing end game you'll have multiple units and legions and armies."
  {
    const ML278 = await import("../engine/melee.js");
    const silas278 = JSON.parse(readFileSync(join(root, "characters/player-s9z9u1/char-mrhs8286.json"), "utf8"));

    // ⛔ EARNED ON THE SAME LADDER AS THE COMPANION CAP, deliberately — a second ladder would let a character
    // command a unit while being unable to lead three people.
    check("CCODE-278: a newcomer cannot raise a band; someone who leads a line can",
      ML278.canRaiseBand({ level: 3, subAttributes: { presence: 3 } }).ready === false
      && ML278.canRaiseBand(silas278, { renownBand: "renowned" }).ready === true);
    // ⚠️ AND A HOLDING COUNTS — "you'll own or build more holds"; a post is where a following comes from.
    check("CCODE-278: …and holdings are the other road to one",
      ML278.canRaiseBand({ level: 2, subAttributes: { presence: 2 },
        holdings: [{ id: "a", condition: "holding" }, { id: "b", condition: "thriving" }] }).ready === true);

    // the record is what legionClash consumes — designed against each other, not bolted together
    {
      const ch = { level: 30, subAttributes: { presence: 9 }, bands: [] };
      const r = ML278.raiseBand(ch, { id: "sw", name: "the Stillwater Watch", count: 40, quality: 2, day: 20 });
      check("CCODE-278: a raised band is count + quality + provenance, and starts fresh",
        r.ok && ch.bands.length === 1 && ch.bands[0].condition === "fresh" && ch.bands[0].count === 40);
      check("CCODE-278: …and you cannot raise the same one twice",
        ML278.raiseBand(ch, { id: "sw", count: 10 }).ok === false && ch.bands.length === 1);
      // ⛔ CONDITION IS A MULTIPLIER, NOT A SUBTRACTION. A worn band is the same people, slower and warier;
      // modelling that as fewer heads would lose the distinction between losses and morale.
      const fresh = ML278.bandStrength({ count: 40, quality: 2, condition: "fresh" });
      const worn = ML278.bandStrength({ count: 40, quality: 2, condition: "worn" });
      check("CCODE-278: a worn band is the same COUNT and less worth — losses and morale are different things",
        worn.count === fresh.count && worn.effective < fresh.effective);
    }

    // ⛔ THE ASYMMETRY, WHICH IS THE REAL FIND. `tide = ratio − 1` is bounded below at −1 and unbounded
    // above, so DEFEAT SATURATED TWICE AS FAST AS VICTORY: outnumbered 2:1 gave −0.50, outnumbering 2:1 gave
    // +1.00. A band at 2:3 — not a scale gap, just worse numbers — read −0.33 and routed on contact.
    // ⚠️ FOUND BY PLAYING IT, NOT BY READING IT: forty of the Stillwater Watch met sixty and broke in four
    // clashes without ever having a bad round.
    {
      const flat = () => 0.5;   // no luck either way — isolate the force ratio
      const at = (us, them) => ML278.legionClash([{ count: us, quality: 1 }], [{ count: them, quality: 1 }], { rng: flat });
      check("CCODE-278: being outnumbered 2:3 is GIVING GROUND, not a rout",
        at(40, 60).outcome === "giving ground");
      check("CCODE-278: …and 1:3 still routs — the fix widened the middle, it did not remove the bottom",
        at(20, 60).outcome === "rout");
      // ⛔ SYMMETRY IS THE PROPERTY. Winning by a margin and losing by the same margin must be mirror images.
      check("CCODE-278: outnumbering 3:2 and being outnumbered 2:3 are mirror images",
        Math.abs(at(60, 40).tide + at(40, 60).tide) < 0.001);
      check("CCODE-278: …and an even meeting is still a grind",
        at(60, 60).outcome === "grinding" && Math.abs(at(60, 60).tide) < 0.001);
    }

    // ⚠️ AND A BAND CAN BREAK WITHOUT BEING DESTROYED — the difference between a unit and a health bar, and
    // the state a commander actually has to manage.
    {
      let b = { id: "x", name: "the Watch", count: 40, quality: 2, condition: "fresh", losses: 0 };
      const r1 = ML278.bloodBand(b, 0.4);
      check("CCODE-278: winning still costs you people, and marks them blooded",
        r1.lost > 0 && r1.band.condition === "blooded" && r1.band.count < 40);
      let losing = b;
      for (let i = 0; i < 6 && losing.condition !== "broken"; i++) losing = ML278.bloodBand(losing, -0.8).band;
      check("CCODE-278: …and a beaten band BREAKS with people still standing — not a health bar",
        losing.condition === "broken" && losing.count > 0);
      // ⛔ NON-VACUITY: winning and losing must actually differ, or the whole clash is scenery.
      check("CCODE-278: losing costs more than winning (floor)",
        ML278.bloodBand(b, -0.8).lost > ML278.bloodBand(b, 0.8).lost);
    }

    // ⛔ AND THE DOOR, IN THE SAME CHANGE AS THE BAND. Erik asked one commit ago whether the UI allowed for
    // these features and the answer was no, ten for ten. Adding four more exports with no caller would have
    // been the same mistake with the ink still wet — and `testOnlyExports` went 26 → 29 before I wired it,
    // which is the ratchet doing exactly its job.
    {
      const appSrc278 = readFileSync(join(root, "app.js"), "utf8");
      const gmSrc278 = readFileSync(join(root, "engine/gm.js"), "utf8");
      check("CCODE-278: the app applies a bandOps step and imports every verb it uses",
        /applyStep\("bandOps"/.test(appSrc278) && appSrc278.includes("canRaiseBand")
        && appSrc278.includes("raiseBand") && appSrc278.includes("bandStrength")
        && appSrc278.includes("bloodBand") && appSrc278.includes("legionClash"));
      // ⚠️ TWO VERBS, because raising a following and marching it into something are decisions taken at
      // different times — one is a season's work, the other is a moment.
      check("CCODE-278: raise and clash are separate ops",
        /"raise"/.test(appSrc278) && /"clash"/.test(appSrc278));
      // ⛔ THE ENGINE DECIDES WHETHER THEY HAVE EARNED IT. A narrator that could hand out a warband would
      // make the whole command ladder decorative.
      check("CCODE-278: the GM is told the engine refuses an unearned band, and not to narrate losses",
        /never assert that people follow them/i.test(gmSrc278)
        && /NEVER narrate a band's losses yourself/i.test(gmSrc278));
      check("CCODE-278: bandOps survives a truncated reply",
        /"bandOps"/.test(gmSrc278.slice(gmSrc278.indexOf("SALVAGEABLE_OPS"))));
    }
  }


  // 3 · ⛔ THE 24 VERBS, NOT THE 8 BUCKETS. "HARM" cannot tell `strike` from `break`.
  {
    const abs = Object.values(C197.abilities || {});
    const verbs = new Set(abs.flatMap(a => a.functions || []));
    const fams = new Set(abs.flatMap(a => a.families || []));
    console.log(`      grain: ${verbs.size} authored function verbs vs 8 families, across ${abs.length} abilities`);
    check(`CCODE-197: the catalogue carries far more grain than the families expose (${verbs.size} verbs vs 8)`,
      verbs.size >= 20, "if the verbs ever collapse to 8, this filter stops being worth its row");
    check("CCODE-197: a VERB matches, and it is finer than the family it sits in",
      matchesFunction(death, new Set(["strike"])) && !matchesFunction(death, new Set(["break"]))
      && matchesFunction(death, new Set(["HARM"])),
      "strike and break share a family; a filter that cannot separate them is the bug");
    // ⚠️ EACH GRAIN ON ITS OWN, because a mixed set proves neither: mutation showed that dropping the
    // FAMILY half left this green, since `heal` alone still matched. A family chip must match a craft whose
    // verbs are nowhere in the set, and a verb chip must match one whose family is not.
    check("CCODE-197: families and verbs live in ONE set — the player never picks which grain to think in",
      matchesFunction(death, new Set(["HARM"]))            // family alone, no verb overlap
      && matchesFunction(death, new Set(["strike"]))       // verb alone, no family in the set
      && matchesFunction(life, new Set(["HARM", "heal"]))  // mixed set, matched on the verb
      && !matchesFunction(life, new Set(["HARM", "strike"])));
  }

  // 5bb · CCODE-279 / ERIK — A BAND IS NOT A NUMBER.
  // ⛔ "Band's should have something that measures their capability better than raw numbers... what threat
  // level do they add up to - are they mixed units so they can attack ranged and ward and heal, or are they
  // all cavalry? How can we structure this to give it some logical complexity while maintaining simplicity?"
  // ⚠️ BOTH VOCABULARIES ALREADY EXISTED. `contributionsOf`'s families answer "what can they do" — the same
  // words a companion is described with — and `threatBand` answers "what do they add up to". Inventing unit
  // types would have been two ladders for ideas the game already has.
  {
    const ML279 = await import("../engine/melee.js");
    const cav = { id: "c", name: "the Redline Horse", condition: "fresh", losses: 0,
      contingents: [{ n: 40, does: ["HARM", "MARTIAL"], quality: 2, what: "lancers" }] };
    const mix = { id: "m", name: "the Stillwater Watch", condition: "fresh", losses: 0,
      contingents: [{ n: 24, does: ["HARM", "MARTIAL"], quality: 2, what: "spears" },
                    { n: 10, does: ["HARM", "MARTIAL"], quality: 2, what: "bows" },
                    { n: 4, does: ["RESTORE"], quality: 2, what: "menders" },
                    { n: 4, does: ["PROTECT", "KNOW"], quality: 2, what: "wardens" }] };

    // ⚠️ A FLAT BAND STILL WORKS — nothing authored before this changes.
    check("CCODE-279: a plain {count, quality} band reads as one martial contingent",
      ML279.contingentsOf({ count: 20, quality: 2 }).length === 1
      && ML279.bandStrength({ count: 20, quality: 2 }).count === 20);

    // ⛔ CAPABILITY IS THE UNION, AND IT USES THE COMPANION VOCABULARY
    check("CCODE-279: what a band can do is the union of its contingents, in the same words as a companion",
      ML279.bandCan(cav).join(",") === "HARM,MARTIAL"
      && ["HARM", "MARTIAL", "RESTORE", "PROTECT", "KNOW"].every(k => ML279.bandCan(mix).includes(k)));

    // ⛔ THREE GAPS, EACH WITH A CONSEQUENCE — and that is what earns the extra field.
    check("CCODE-279: all-cavalry has three named gaps; a mixed band has none",
      ML279.bandGaps(cav).length === 3 && ML279.bandGaps(mix).length === 0);
    // ① unwarded bleeds harder — SAME size, SAME quality, SAME tide
    {
      const a = ML279.bloodBand(cav, -0.5), b = ML279.bloodBand(mix, -0.5);
      check("CCODE-279: ① unwarded — the same tide takes more of them",
        a.lost > b.lost, `cavalry ${a.lost} vs mixed ${b.lost}`);
    }
    // ② no menders means the losses are permanent, and menders are the reason to spend places on them
    {
      const hurtCav = ML279.bloodBand(cav, -0.5).band;
      const hurtMix = ML279.bloodBand(mix, -0.5).band;
      const rc = ML279.recoverBand(hurtCav, { days: 7 });
      const rm = ML279.recoverBand(hurtMix, { days: 7 });
      check("CCODE-279: ② no menders → nobody comes back, ever",
        rc.back === 0 && /cost for good/.test(rc.why));
      check("CCODE-279: …and menders bring the walking wounded back to the line",
        rm.back > 0 && ML279.bandStrength(rm.band).count > ML279.bandStrength(hurtMix).count);
      // ⛔ CAPPED BY WHO IS MENDING, or a token healer would heal an army and composition would stop
      // mattering one layer down.
      const many = { ...mix, losses: 200,
        contingents: [{ n: 200, does: ["HARM"], quality: 1 }, { n: 1, does: ["RESTORE"], quality: 1 }] };
      check("CCODE-279: …and one mender cannot put two hundred back on their feet",
        ML279.recoverBand(many, { days: 1 }).back <= 2);
      // ⚠️ AND NEVER PAST WHERE THEY STARTED — these are the wounded returning, not resurrection.
      check("CCODE-279: …and recovery stops at the losses actually taken",
        ML279.recoverBand({ ...mix, losses: 0 }, { days: 30 }).back === 0);
      // ⛔ A BROKEN BAND DOES NOT COME BACK. Breaking is the terminal state a commander has to avoid.
      check("CCODE-279: …and nothing recovers a band that broke",
        ML279.recoverBand({ ...mix, condition: "broken", losses: 20 }, { days: 30 }).back === 0);
    }
    // ③ losses come off the CONTINGENTS, or a band keeps its menders forever while its spears evaporate
    {
      const after = ML279.bloodBand(mix, -0.9).band;
      const before = ML279.contingentsOf(mix), now = ML279.contingentsOf(after);
      check("CCODE-279: ③ losses fall across the contingents, not off a top-level number",
        now.every((c, i) => c.n <= before[i].n) && now.some((c, i) => c.n < before[i].n));
    }

    // ⛔ THE BUG THAT WOULD HAVE READ AS A FEATURE. My first version left `bloodBand` reading `band.count`,
    // which a composed band does not have — so a contingent band had a count of ZERO: it lost nobody and was
    // BROKEN on contact, every time, and it would have read as "bands are fragile" rather than as a bug.
    check("CCODE-279: a composed band takes real losses and is NOT broken on contact",
      (() => { const r = ML279.bloodBand(mix, -0.3); return r.lost > 0 && r.condition !== "broken"; })());

    // ⚠️ THREAT IS READ IN THE GAME'S OWN UNITS, and √ for the same reason the melee compression uses one:
    // doubling a body of people does not double what it can do to ONE character.
    {
      const t1 = ML279.bandThreat({ count: 40, quality: 2 }).power;
      const t2 = ML279.bandThreat({ count: 160, quality: 2 }).power;
      check("CCODE-279: four times the band is twice the threat to a person, not four times",
        Math.abs(t2 - t1 * 2) <= 1, `${t1} → ${t2}`);
    }
  }

  // 4 · the surfaces: the verb row exists, it is scoped to what the wheel HAS, and clear drops the traditions
  {
    const app197 = readFileSync(join(root, "app.js"), "utf8");
    check("CCODE-197: the verb chips are rendered, grouped under their family",
      /class="fn-verb-row"/.test(app197) && /fn-filter fn-verb/.test(app197)
      && /FN_INDEX\.byFamily\?\.\[fam\]/.test(app197));
    // ⚠️ A CHIP FOR A VERB NO CRAFT HAS can only ever return nothing, which reads as a broken button
    // rather than an empty answer.
    check("CCODE-197: the verb chips are scoped to the verbs this wheel actually carries",
      /const inPlay = new Set\(m\.nodes\.flatMap\(nd => nd\.functions \|\| \[\]\)\)/.test(app197)
      && /\.filter\(v => inPlay\.has\(v\)\)/.test(app197));
    // ⛔ AND CLEAR MUST DROP THEM. They HIDE crafts now, so a "clear" that left them held would leave most
    // of the wheel missing with no lit chip to explain why — invisible and on is the worst state a filter has.
    check("CCODE-197: ✕ clear releases the held traditions too, and the button appears when only they are on",
      /fnClear\.onclick = \(\) => \{ wheelFnFilter = new Set\(\); wheelSelTrads = new Set\(\);/.test(app197)
      && /\(wheelFnFilter\.size \|\| wheelSelTrads\.size \|\| wheelSuggestFilter/.test(app197));
  }

  // 5bc · CCODE-281 — DAMAGE FAMILIES, COMPOSITE DAMAGE, AND THE READER `wardTypes` NEVER HAD.
  // ⛔ ERIK: "wards can start with just one type, like Cold... but some higher level wards will protect
  // against multiple types - elemental ward for example. also, initial ranks will add resist then soak then
  // immunity." And: "COMBINATIONS — that makes WARDING ABLE TO BE PARTIAL… attacks more viable because they
  // can BRING CERTAIN DAMAGE TYPES THROUGH."
  // ⚠️ THREE FAMILIES, FROM AEVI'S CORRECTION OF HER OWN AXIS TABLE. My objection was that cold and fire are
  // both TAKINGS rather than opposites; her answer is that this is why neither is polar — they are SIBLINGS.
  {
    const DT = await import("../engine/damagetypes.js");
    const cm281 = JSON.parse(readFileSync(join(root, "content/packs/core/rules/craft_mechanics.json"), "utf8"));
    const F = cm281.damageFamilies, L = cm281.wardLadder, B = cm281.wardBreadth;

    check("CCODE-281: the three families are authored, with polar pairs only where an axis warrants one",
      !!F?.physical && !!F?.elemental && Array.isArray(F?.polar?.pairs) && F.polar.pairs.length >= 1);
    // ⛔ THE DISTINCTION THAT SETTLED MY OBJECTION: siblings are not opposites.
    check("CCODE-281: heat and cold are SIBLINGS in one family, and neither has an opposite",
      DT.familyOf("heat", F) === "elemental" && DT.familyOf("cold", F) === "elemental"
      && DT.oppositeOf("heat", F) === null && DT.oppositeOf("cold", F) === null);
    check("CCODE-281: …whereas a real pair does — decay opposes living",
      DT.oppositeOf("decay", F) === "living" && DT.oppositeOf("living", F) === "decay");
    // ⚠️ AN UNCLASSIFIED TYPE ANSWERS null RATHER THAN A GUESS — joining a family by accident would ward it.
    check("CCODE-281: a type nobody has classified belongs to no family",
      DT.familyOf("nonsense", F) === null);

    // ═══ ERIK'S LADDER: resist → soak → immunity ═══
    const cold = { name: "Cold Ward", wardTypes: ["cold"] };
    const at = (w, r) => DT.wardAnswer(w, r, { families: F, ladder: L, breadth: B });
    check("CCODE-281: the same ward answers deeper with rank — resist, then soak, then immunity",
      at(cold, 1).depth === "resist" && at(cold, 2).depth === "soak" && at(cold, 3).depth === "immunity");
    // ⛔ THREE KINDS OF ANSWER, NOT THREE SIZES OF ONE — and the breadth stays one type at every rank.
    check("CCODE-281: …and depth does not widen it — a cold ward answers cold at every rank",
      [1, 2, 3].every(r => at(cold, r).answers.join(",") === "cold"));

    // ═══ AND BREADTH IS EARNED SEPARATELY — "elemental ward for example" ═══
    const elem = { name: "Elemental Ward", wardTypes: ["elemental"] };
    check("CCODE-281: a ward naming a FAMILY holds the whole family only once ranked for it",
      at(elem, 3).answers.length >= 4 && at(elem, 3).answers.includes("cold") && at(elem, 3).answers.includes("heat"));
    // ⚠️ NAMING A FAMILY EARLY DOES NOT WIDEN IT. Breadth is earned, or every r1 ward would answer five types.
    check("CCODE-281: …and naming it at rank 1 does NOT — breadth is earned, not claimed",
      at(elem, 1).answers.length === 1 && at(elem, 1).breadthEarned === false);

    // ═══ COMPOSITE: the payoff ═══
    const blast = { damageMix: [{ type: "physical", share: 1 }, { type: "psychic", share: 1 }] };
    const mix = DT.damageMixOf(blast);
    check("CCODE-281: a mix normalises, so authored shares cannot inflate a blow",
      Math.abs(mix.reduce((a, p) => a + p.share, 0) - 1) < 1e-9
      && Math.abs(DT.damageMixOf({ damageMix: [{ type: "a", share: 5 }, { type: "b", share: 5 }] })[0].share - 0.5) < 1e-9);
    // ⚠️ A SINGLE `damageType` IS A MIX OF ONE — the whole corpus keeps working untouched.
    check("CCODE-281: a craft with a plain damageType reads as a mix of one",
      DT.damageMixOf({ damageType: "decay" }).length === 1
      && DT.damageMixOf({ damageType: "decay" })[0].share === 1);

    const shield = at({ wardTypes: ["physical"] }, 3);
    const r = DT.resolveComposite(20, mix, shield, { minHit: 1 });
    check("CCODE-281: a shield stops the physical half and the psychic half COMES THROUGH",
      r.through.length === 1 && r.through[0].type === "psychic" && r.landed === 10 && r.blocked === 10);
    // ⛔ NOTHING IS EVER FULLY BLOCKED — the same principle as minHit, which already says no foe is immune.
    const pure = DT.resolveComposite(20, DT.damageMixOf({ damageType: "physical" }), shield, { minHit: 1 });
    check("CCODE-281: a blow whose every part is warded still lands the floor — a 0 reads as broken",
      pure.landed === 1 && pure.flooredBy === "minHit");
    // ⚠️ AND RESIST DOES NOT APPLY HERE. It moved the roll before the blow was sized; charging it again
    // would make a rank-1 ward better than a rank-2 one against the same type.
    check("CCODE-281: a RESIST ward does not also reduce the blow — that would charge it twice",
      DT.resolveComposite(20, DT.damageMixOf({ damageType: "cold" }), at(cold, 1), { minHit: 1 }).landed === 20);
    check("CCODE-281: …a SOAK ward reduces it, and an IMMUNITY ward removes it",
      DT.resolveComposite(20, DT.damageMixOf({ damageType: "cold" }), at(cold, 2), { minHit: 1 }).landed < 20
      && DT.resolveComposite(20, DT.damageMixOf({ damageType: "cold" }), at(cold, 3), { minHit: 1 }).landed === 1);

    // ⛔ AND IT REACHES THE ROUND — `wardTypes` is documented to the GM at length, authored on 48 crafts,
    // and was read by NOTHING in the resolution path. A gate on the module alone would have left that true.
    {
      const sbSrc = readFileSync(join(root, "engine/skill_battle.js"), "utf8");
      check("CCODE-281: the damage path reads the mix and the ward",
        sbSrc.includes("damageMixOf(") && sbSrc.includes("wardAnswer(") && sbSrc.includes("resolveComposite(")
        && sbSrc.includes("wardTypes"));
    }
    // ⚠️ AND A TARGET WITH NO WARD IS UNTOUCHED — the arithmetic is byte-identical to before.
    check("CCODE-281: with no wardTypes on the target, nothing changes",
      DT.wardAnswer(null, 3, { families: F }) === null);

    // ═══ CCODE-282 — THE v2 TABLE, AND THE READER THAT COULD NOT SEE IT ═══
    // ⛔ AEVI AUTHORED v2 (four families, 20 types, no polar), REGISTERED IT, AND state.js LOADED IT —
    // and `skill_battle` resolved every ward against the OLDER copy inside craft_mechanics.json. She had
    // flagged the risk against herself six lines above the load: "registered is only half; CCODE-55 asks
    // whether it is ever READ." It was not. Authored ✓ registered ✓ loaded ✓ read ✗ — the fourth door.
    // ⚠️ MY READER WAS THE OTHER HALF: familyOf and wardAnswer NAMED physical/elemental/polar in source,
    // so v2 families read as ordinary types. A "vital ward" answered a type called "vital" that no craft
    // deals, and never widened to decay/living/vitality. Two correct halves that could not meet.
    {
      const v2 = JSON.parse(readFileSync(join(root, "content/packs/core/rules/damage_families.json"), "utf8"));
      const V = v2.families;
      const famNames = Object.keys(V).filter(k => !k.startsWith("_"));
      const allTypes = famNames.flatMap(f => V[f].types || []);
      // ⛔ NON-VACUITY FIRST: an empty table passes every check below it.
      check("CCODE-282: the v2 table is non-empty — four families and twenty types",
        famNames.length === 4 && allTypes.length >= 20);
      check("CCODE-282: EVERY v2 type resolves to a family — none is family-less",
        allTypes.length > 0 && allTypes.every(t => DT.familyOf(t, V) !== null));
      // ⚠️ THE SHAPE CHANGED AND THE READER MUST TAKE EITHER. v2 wraps its families under `.families`;
      // handing the DOC in unwrapped made every type family-less — silently, since that is a legal answer.
      check("CCODE-282: the doc and the bare map read identically — the unwrap is in one place",
        DT.familyOf("decay", v2) === "vital" && DT.familyOf("decay", V) === "vital");
      // ⛔ THE PAYOFF ERIK NAMED: "some higher level wards will protect against multiple types."
      const vital3 = DT.wardAnswer({ wardTypes: ["vital"] }, 3, { families: V, ladder: L, breadth: B });
      check("CCODE-282: a ward naming a v2 FAMILY widens to its types at rank",
        vital3.breadthEarned === true && ["decay", "living", "vitality"].every(t => vital3.answers.includes(t)));
      check("CCODE-282: …and does NOT widen at rank 1 — breadth is still earned",
        DT.wardAnswer({ wardTypes: ["vital"] }, 1, { families: V, ladder: L, breadth: B }).answers.length === 1);
      // ⚠️ v2 DROPPED OPPOSITES DELIBERATELY. null for every type is CORRECT here, not a broken lookup —
      // and the gate says so explicitly so nobody "fixes" it back into existence.
      check("CCODE-282: v2 has no polar pairs, so nothing has an opposite — by design, not by breakage",
        allTypes.every(t => DT.oppositeOf(t, V) === null));
      // ⛔ AND ERIK'S Q2: vitality is not special. decay, living and vitality are SIBLINGS now.
      const mix = t => DT.damageMixOf({ damageType: t });
      const land = (t, w) => DT.resolveComposite(20, mix(t), w, { minHit: 1, families: V }).landed;
      const wardFor = t => DT.wardAnswer({ wardTypes: [t] }, 3, { families: V, ladder: L, breadth: B });
      check("CCODE-282: vitality resolves EXACTLY like decay — same family, same warded and unwarded result",
        DT.familyOf("vitality", V) === DT.familyOf("decay", V)
        && land("vitality", wardFor("vitality")) === land("decay", wardFor("decay"))
        && land("vitality", wardFor("heat")) === land("decay", wardFor("heat")));
      // ⛔ THE WIRING GATE — THE ONE THAT WOULD HAVE CAUGHT THIS. A module-only gate leaves the whole
      // defect invisible: both halves were individually green while the live path read neither.
      {
        const stSrc = readFileSync(join(root, "engine/state.js"), "utf8");
        const sb2 = readFileSync(join(root, "engine/skill_battle.js"), "utf8");
        check("CCODE-282: the loaded table is MERGED into the rules bag, not merely fetched",
          stSrc.includes("rules.damageFamilies = damageFamilies"));
        check("CCODE-282: and the resolution path READS it, preferring it over the v1 copy",
          sb2.includes("rules?.damageFamilies || cmCfg?.damageFamilies") && sb2.includes("famTable"));
      }
      // ⚠️ AND THE v1 PACK STILL RESOLVES — absent means today, which is the gate for every dial here.
      check("CCODE-282: a pack still on the v1 shape is untouched — heat is elemental, decay opposes living",
        DT.familyOf("heat", F) === "elemental" && DT.oppositeOf("decay", F) === "living");
    }
  }

}

// ---- SNG-435 §C: the picture field was authored on all 376 and read by nothing ------------------
// ⛔ ERIK: "I have been having a hard time getting a good Radiant Lance skill image." Its `shape` is
// "damage", so `powerPhrase` built "Radiant Lance — damage, attack, precise".
// ⚠️ MY FIRST FIX REGISTERED THE CATEGORY WORDS. Aevi's answer is better and retired it: the argument is
// INFORMATION, not word-choice — 25 distinct `shape` values against 376 distinct `narrationHints`. A field
// that can name 25 things cannot distinguish 376, whatever words are in it.
{
  const { loadContentHeadless: lchC } = await import("./headless_content.mjs");
  const CC = await lchC();
  const BP = await import("../engine/battleprompt.js");
  const AR = await import("../engine/art.js");
  const abilities = Object.values(CC.abilities || {});
  // 1 · THE MEASUREMENT THAT DECIDES IT. If `shape` ever out-resolves `narrationHints`, the rule below is
  // the wrong one and this says so before anybody has to look at a picture to find out.
  {
    const shapes = new Set(abilities.map(a => String(a.shape || "").trim().toLowerCase()).filter(Boolean));
    const hints = new Set(abilities.map(a => String(a.narrationHints || "").trim()).filter(Boolean));
    console.log(`      cardinality: ${shapes.size} distinct shapes vs ${hints.size} distinct narrationHints across ${abilities.length} abilities`);
    check(`435 §C1 THE ARGUMENT: narrationHints out-resolves shape by two orders (${hints.size} vs ${shapes.size})`,
      hints.size === abilities.length && shapes.size < 40 && abilities.length > 300,
      "a low-cardinality field cannot be the picture, whatever words are in it");
  }
  // 1b · ⛔ CCODE-200: EVERY LOADED ABILITY CARRIES A POWER SYSTEM. The pack-level stamp used to overwrite
  // the ability's own value unconditionally, so 28 crafts in the 13 packs that declare no pack-level
  // `powerSystem` loaded with it UNDEFINED. Nothing threw - they simply resolved no palette, no physics
  // phrase, and no substrate gate, and every file-level check passed because the FILES were correct. This
  // is the writer-with-no-reader class inverted: an authored field the LOADER threw away. Only the loaded
  // catalogue can see it, which is why the gate lives here and not in the content CI.
  {
    const noSystem = abilities.filter(a => !a.powerSystem);
    // ⛔ CCODE-217: AND NO ABILITY CARRIES A FILENAME AS ITS POWER SYSTEM. The flip that fixed this was
    // UNGATED when I shipped it - reverting the precedence left the whole suite green, because the palette
    // routes work under both once the palettes moved to `traditions`. So 260 crafts could quietly go back
    // to `reach_dark_light` as a "power system" and nothing would say a word.
    // ⚠️ A change worth arguing for over two rounds is worth a check that notices it being undone.
    {
      const filenamed = abilities.filter(a => /^reach_/.test(String(a.powerSystem || "")));
      check(`CCODE-217: no ability's powerSystem is a FILENAME — the ability's own value wins over its file's header`,
        filenamed.length === 0,
        `${filenamed.length} craft(s) carry an axis name as a power system, e.g. ${filenamed.slice(0, 3).map(a => `${a.id}=${a.powerSystem}`).join(", ")}`);
      // and the vocabulary that replaced them is the real one
      const vocab = new Set(abilities.map(a => a.powerSystem).filter(Boolean));
      check("CCODE-217: the loaded power systems are a real vocabulary, not one per file",
        vocab.size <= 12 && vocab.has("metaphysical") && vocab.has("precursor"),
        [...vocab].join(", "));
    }

    check("CCODE-200: no ability loads without a powerSystem — the pack stamp fills gaps, never clobbers",
      noSystem.length === 0, noSystem.slice(0, 8).map(a => a.id).join(", "));
  }
  // 1c · ⛔ CCODE-201: EVERY PLACE REFERENCE NAMES A REAL REGION. Ability ids and region ids share one
  // flat string space — `the_ascent` and `the_descent` are BOTH a renamed craft and a live region — so a
  // corpus-wide id sweep silently rewrites places into crafts. One did, across five rules files, and only
  // ONE of them had a gate over it. The reliable signal is the KEY, never the value: region | regionId |
  // homeRegion | startingRegion always name a place. See SYSTEM_SPEC §43.2.
  {
    const PLACE_KEYS = new Set(["region", "regionId", "homeRegion", "startingRegion"]);
    const regionIds = new Set(Object.keys(JSON.parse(readFileSync(join(root, "content/packs/core/rules/regions.json"), "utf8")).regions || {}));
    for (const l of Object.values(CC.locations || {})) { if (l.region) regionIds.add(l.region); if (l.regionId) regionIds.add(l.regionId); }
    const strays = [];
    const walk = (node, file) => {
      if (Array.isArray(node)) return node.forEach(n => walk(n, file));
      if (!node || typeof node !== "object") return;
      for (const [k, v] of Object.entries(node)) {
        // ⚠️ only ID-SHAPED values — `quest_structure.json` carries `"region": "Where it lives."` as
        // schema PROSE, and a doc describing a field is not a reference to a place.
        if (PLACE_KEYS.has(k) && typeof v === "string" && /^[a-z][a-z0-9_]*$/.test(v) && !regionIds.has(v)) strays.push(`${file}:${k}=${v}`);
        else walk(v, file);
      }
    };
    for (const f of readdirSync(join(root, "content/packs/core/rules")).filter(x => x.endsWith(".json")))
      { try { walk(JSON.parse(readFileSync(join(root, "content/packs/core/rules", f), "utf8")), f); } catch { /* unreadable */ } }
    // ⚠️ RATCHET, NOT A CLEAN GATE. It opens RED on debt that predates it: four region ids
    // (`the_crossing`, `the_stillhold`, `the_cogitarium`, `the_unspooling`) are referenced by places
    // `regions.json` does not define. Reported to Aevi; the count may only SHRINK. The gate's real job is
    // to catch the NEXT sweep that turns a place into a craft, and for that a ratchet is enough.
    const uniq = [...new Set(strays)];
    check(`CCODE-201: region references in rules/ that name no real region — ${uniq.length}, and it may only shrink`,
      uniq.length <= 11, uniq.slice(0, 12).join(", "));
  }
  // 1d · ⛔ CCODE-203: THE SAFETY NET IS GATED. SNG-505 §2 rests the entire recoverability of the
  // 2026-08-14→16 rework on `_Was` fields and the revert logs — and NOTHING was checking they were still
  // there. The one artifact standing between a bad call and an unrecoverable tree was itself ungated.
  // A ratchet: these may only go UP while the sense restore is outstanding.
  //
  // ⚠️ EXIT CONDITION, so this does not outlive its purpose: once the restore has landed and Erik and
  // Aevi agree the net is spent, this gate is RETIRED deliberately — not eroded by lowering the numbers.
  {
    const wasCount = (o) => Object.keys(o || {}).filter(k => /Was$/.test(k)).length;
    let withAny = 0, totalWas = 0;
    for (const a of abilities) {
      let n = wasCount(a);
      for (const r of (a.tree || [])) n += wasCount(r);
      if (n) { withAny++; totalWas += n; }
    }
    check(`CCODE-203: ${withAny} abilities still carry a _Was — the rework stays reversible`,
      withAny >= 321, `${withAny} < 321: pre-edit state has been stripped from ${321 - withAny} ability(ies)`);
    check(`CCODE-203: ${totalWas} _Was fields survive across abilities and rank entries`,
      totalWas >= 1853, `${totalWas} < 1853`);
    // ⚠️ AND THE REVERT LOGS, which hold what a `_Was` cannot: whole abilities that were CUT.
    const reverts = readdirSync(join(root, "po/staged_content"))
      .filter(f => /^revert_SNG-.*\.json$/.test(f))
      .filter(f => { try { return JSON.parse(readFileSync(join(root, "po/staged_content", f), "utf8")) != null; } catch { return false; } });
    check(`CCODE-203: ${reverts.length} revert logs present and parseable — including the sense cull's`,
      reverts.length >= 8 && reverts.includes("revert_SNG-454_sense_cull.json"), reverts.join(", "));
  }
  // 1e · ⛔ CCODE-204: EVERY STAGED CHANGE SET VALIDATES. SNG-505 Layer 2 asks a rework to declare every
  // referrer it must move. Declaring is not checking - a REMEMBERED list has the reach of whoever wrote it,
  // which is the instrument that failed on the sense cull. tests/changeset_check.mjs DERIVES the referrer
  // set from the tree and diffs it against the document; this runs it so a broken change set cannot sit in
  // the tree unnoticed until someone thinks to run the tool by hand.
  //
  // ⚠️ It caught its own author within a minute of existing: CCode left `ability_rename_map.json` out of
  // the SNG-506 referrer list on the grounds that it is "tooling, not content" - and its 32 entries assert
  // the senses became `attunement`, which the restore makes false. "This one does not count" is the failure
  // mode the tool exists for.
  {
    const { execFileSync } = await import("node:child_process");
    let out = "", code = 0;
    try { out = execFileSync(process.execPath, [join(root, "tests/changeset_check.mjs")], { cwd: root, encoding: "utf8" }); }
    catch (e) { out = String(e.stdout || "") + String(e.stderr || ""); code = e.status ?? 1; }
    const lines = out.split(/\r?\n/);
    const failing = lines.filter(l => l.startsWith("FAIL")).map(l => l.slice(6).trim());
    check("CCODE-204: every staged change set passes changeset_check (derived referrers match the declared)",
      code === 0, failing.slice(0, 4).join(" · ") || lines.filter(Boolean).slice(-2).join(" "));
  }
  // 1f · ⛔ CCODE-206: A REPLY THAT NEVER REACHED THE REPO WAS NEVER SENT. Aevi is not in this session and
  // never will be — `po/` IS the channel. A note written to disk and left untracked, or written into a path
  // git ignores, reads to its author as delivered and to its reader as silence. That is the same failure as
  // an unregistered content file (§42), one layer out: authored, correct, invisible.
  //
  // ⚠️ Two ways it happens, and this catches both:
  //   UNTRACKED — written, never `git add`ed. Recoverable the moment it is noticed.
  //   IGNORED   — written somewhere `.gitignore` covers. Worse: `git add` says nothing and appears to work.
  //
  // It does NOT gate on unpushed commits: committing before pushing is normal, and a gate that goes red on
  // ordinary work is a gate people learn to skip.
  {
    const { execFileSync } = await import("node:child_process");
    const git = (...a) => { try { return execFileSync("git", a, { cwd: root, encoding: "utf8" }).trim(); } catch { return ""; } };
    const inRepo = git("rev-parse", "--is-inside-work-tree") === "true";
    const untracked = inRepo ? git("ls-files", "--others", "--exclude-standard", "po/").split(/\r?\n/).filter(Boolean) : [];
    const ignored = inRepo ? git("ls-files", "--others", "--ignored", "--exclude-standard", "po/").split(/\r?\n/).filter(Boolean) : [];
    check("CCODE-206: every file in po/ is tracked — a reply left untracked was never sent",
      !inRepo || untracked.length === 0, untracked.slice(0, 6).join(", "));
    check("CCODE-206: nothing in po/ is gitignored — an ignored reply cannot be committed even deliberately",
      !inRepo || ignored.length === 0, ignored.slice(0, 6).join(", "));
  }
  // 2 · AND THE PICTURE CHANGES, on Erik's own ability.
  {
    const rl = abilities.find(a => /radiant lance/i.test(a.name || ""));
    const out = BP.powerPhrase(rl, {});
    check("435 §C1: Radiant Lance is its beam of focused light, not \"damage, attack, precise\"",
      !!rl && /beam of focused light/i.test(out) && !/damage/.test(out), out);
    // ⚠️ AND THE FALLBACK SURVIVES, for a craft minted in play that has no hints yet — without it this
    // fix would leave runtime braids and discoveries with no power phrase at all.
    const minted = { name: "A Minted Braid", shape: "damage", effectTags: ["sever", "quiet"] };
    check("435 §C1: a craft with NO narrationHints still gets a phrase from shape and tags",
      /damage/.test(BP.powerPhrase(minted, {})), BP.powerPhrase(minted, {}));
  }
  // 3 · ⛔ §C3 — THE FIVE WERE NEVER PEOPLES. Aevi swept them: `harmonic`, `radiant_folk`, `precursor`,
  // `valley_craft`, `cross_pole_braid` are POWER SYSTEMS wearing the `tradition` field, and authoring five
  // traditions for them would have invented five cultures the world does not have — the SNG-432 error again.
  // A tradition supplies CULTURE; a power system supplies PHYSICS, and physics is what a craft looks like.
  {
    const doc = CC.visualAesthetics || {};
    check("435 §C3: the WHOLE aesthetics doc reaches CONTENT — `powerSystems` was being flattened away at load",
      // ⚠️ NOT A COUNT. This asserted `powerSystems >= 5` and went red when SNG-530 moved radiant,
      // harmonic and valley_craft into `traditions` - where §C3's own argument always said they belonged,
      // because they are PEOPLES rather than physics. The claim is that BOTH MAPS SURVIVE THE LOAD (the
      // bug was `powerSystems` being flattened away entirely), and a census pinned on top of it turns a
      // correct content move into a failure.
      Object.keys(doc.traditions || {}).length > 20 && Object.keys(doc.powerSystems || {}).length >= 1,
      `traditions ${Object.keys(doc.traditions || {}).length}, powerSystems ${Object.keys(doc.powerSystems || {}).length}`);
    const rl = abilities.find(a => /radiant lance/i.test(a.name || ""));
    const br = abilities.find(a => a.tradition === "cross_pole_braid");
    // ⛔ THE SAMPLE IS DERIVED. This named rootkin, radiant_folk and valley_craft, and on 2026-08-31
    // valley_craft was RETIRED into its parents — `find(a => a.tradition === "valley_craft")` returned
    // undefined and the gate failed on a fixture rather than on its claim. Third time in one commit that a
    // retired tradition broke a gate that was not about it.
    //
    // ⚠️ THE CLAIM IS GENERAL: every craft whose PEOPLE has an authored palette must reach THAT palette.
    // Asking the corpus means the merger can retire anything and this still tests the same thing.
    const peoples = Object.keys(doc.traditions || {});
    const sample = peoples.map(t => ({ t, ab: abilities.find(a => a.tradition === t) })).filter(x => x.ab);
    const wrongPalette = sample.filter(x => AR.aestheticFor(x.ab, doc) !== doc.traditions[x.t]);
    check("435 §C3: a people wins where there is one, and the physics answers where there is not",
      wrongPalette.length === 0
      // ⚠️ BY WHAT IT IS, NOT BY WHICH OBJECT. SNG-530 authored the braid palette a SECOND time under
      // `combination` (with an `_alias` note saying why), and that copy is reached first - so an identity
      // check failed while the picture was correct. The claim is that a braid gets THE braid look.
      && AR.aestheticFor(br, doc)?.name === doc.powerSystems.braid?.name,
      wrongPalette.length ? `${wrongPalette.length} people(s) reach the wrong palette: ${wrongPalette.map(x => x.t).join(", ")}`
        : "a braid did not reach the ONE braid entry");
    // ⛔ NON-VACUITY: an empty sample would pass the check above by testing nothing, which is exactly how a
    // retirement could silently hollow this gate out instead of failing it.
    check("435 §C3: …and the sample is not empty — peoples with authored palettes still have crafts",
      sample.length >= 10, `${sample.length} of ${peoples.length} peoples have a live craft`);
    // ⛔ AND TWO COPIES OF ONE PALETTE CAN DRIFT. `braid` and `combination` are the same look under two
    // names - the palette's name and the power source's - and nothing but this stops one of them being
    // edited alone. ⚠️ `_alias` is excluded because it is the note explaining the duplication, and a
    // note that made the check fail would be a comment breaking a build.
    {
      const b = doc.powerSystems?.braid || {}, c = doc.powerSystems?.combination || {};
      const strip = (o) => JSON.stringify(Object.fromEntries(Object.entries(o).filter(([k]) => k !== "_alias")));
      check("435 §C3: `braid` and `combination` are ONE palette under two names — they may not drift apart",
        !Object.keys(c).length || strip(b) === strip(c),
        "one of the two aliased braid palettes has been edited without the other");
    }
    // ⛔ THE ORDER NEEDS A FIXTURE, BECAUSE NO LIVE ABILITY CAN CURRENTLY SHOW IT. Mutation proved that:
    // inverting people-then-physics reddened NOTHING, because the two palette sets are disjoint today — every
    // ability that has a people has no power-system entry and vice versa. The rule exists for the day Aevi
    // authors a `traditions.harmonic` palette beside the `powerSystems.harmonic` one, and on that day the
    // people must win, or her choice of axis stops being reversible. A latent rule still needs a gate.
    {
      const both = { traditions: { people_x: { palette: "the people" } }, powerSystems: { phys_x: { palette: "the physics" } } };
      const subj = { tradition: "people_x", powerSystem: "phys_x" };
      check("435 §C3: when a subject has BOTH, the people wins — so authoring a palette later overrides the physics",
        AR.aestheticFor(subj, both) === both.traditions.people_x,
        "no live ability exercises this today; it is the reversibility of Aevi's axis choice");
    }
    const gap = abilities.filter(a => !AR.aestheticFor(a, doc));
    console.log(`      aesthetics: ${abilities.length - gap.length}/${abilities.length} abilities resolve a palette` + (gap.length ? ` — still house-paletted: ${[...new Set(gap.map(a => a.tradition || a.powerSystem || "(neither)"))].join(", ")}` : ""));
    check("435 §C3: what is still house-paletted is REPORTED at load, never silent",
      /still fall back to the house palette/.test(readFileSync(join(root, "engine/state.js"), "utf8")));
    // ⛔ AND THE COVERAGE IS RATCHETED, NOT MERELY PRINTED. A file-level check cannot see this class: 46 of
    // the 55 carry a `tradition` that IS in traditions.json and simply had no palette, so only the LOADED
    // catalogue can say who resolves and who does not. 9 baseline martial abilities carry neither a people
    // nor an authored power system — the known remainder, and it may only shrink.
    check(`435 §C3: ${abilities.length - gap.length}/${abilities.length} abilities resolve a palette — the uncovered remainder may only shrink`,
      // ⚠️ TIGHTENED 9 → 4. SNG-531 gave the five form-kit crafts a `forms` palette and CCODE-218 built
      // the two readers that reach it. What is left is the four TRUE universals - brace, strike, break
      // away, call for help - which belong to everyone and arguably should not look like anybody.
      gap.length <= 4, [...new Set(gap.map(a => a.id))].join(", "));
  }
  // 4 · ⛔ AND NO EDITORIAL MARKER REACHES THE GENERATOR. Wiring the palettes surfaced this immediately:
  // every valley-craft ability was minting with "⛔ MUTED EARTH" and "⚠️ THE ABSENCE OF SPECTACLE IS THE
  // POINT" inside the prompt. An image prompt is read by something that draws whatever it is given, so
  // SNG-433's rule applies here at least as hard as it does to prose a player reads.
  {
    const doc = CC.visualAesthetics || {};
    const all = [...Object.values(doc.traditions || {}), ...Object.values(doc.powerSystems || {})];
    const dirty = all.map(a => AR.houseStyleFor(a)).filter(w => /[\u26d4\u26a0]/.test(w));
    check(`435 §C3: no authored marker survives into an image prompt (${all.length} aesthetics)`,
      all.length > 25 && dirty.length === 0, dirty[0]?.slice(0, 90));
    // ⚠️ AND THE SUBSTANCE SURVIVES THE STRIPPING. `plainForArt` would have cut "⛔ MUTED EARTH — wool,
    // leather, wet rope, iron" to "NO emissive colour AT all" — throwing the palette away and keeping the
    // instruction, because it strips a marker-headed aside to the END OF THE SENTENCE. Here the marker heads
    // the CONTENT, so the marker goes and the colours stay.
    const vcStyle = AR.houseStyleFor(doc.powerSystems?.valley_craft);
    check("435 §C3: stripping the marker keeps the palette (not the instruction that followed it)",
      /muted earth/i.test(vcStyle) && !/[\u26d4\u26a0]/.test(vcStyle), vcStyle.slice(0, 100));
  }
}

// ---- SNG-435 §A: a 200 is not proof of an image --------------------------------------------------
// ⛔ AEVI MEASURED IT: a rate-limited Pollinations request answers HTTP 200 with a ZERO-BYTE body, and
// Cloudflare caches that under the canonical URL as `immutable, max-age=31536000` — one year — carrying
// `x-cache: HIT`, byte-identical in headers to a healthy hit. This pipeline's two best properties are what
// make it permanent: the URL is deterministic and the mint is persist-once, so the record holds the burned
// address and every later read returns the same nothing. It cannot self-heal.
{
  const A435 = await import("../engine/art.js");
  // 1 · ⛔ THE POLICY, WHICH DECIDES WHETHER A PLAYER'S PICTURE GETS DELETED. Three verdicts, not two —
  // and the third is the one that protects them: a fetch that never completed is not evidence about the
  // bytes. Deleting a gallery because a train went into a tunnel would be worse than the bug being fixed.
  check("435 §A: an unverifiable response changes NOTHING — offline is not evidence of an empty image",
    A435.mintAction("unknown", 0) === "leave" && A435.mintAction("unknown", 9) === "leave");
  check("435 §A: a proven-empty response retries while retries remain, then forgets — absent beats poisoned",
    A435.mintAction("empty", 0, 2) === "retry" && A435.mintAction("empty", 1, 2) === "retry"
    && A435.mintAction("empty", 2, 2) === "forget" && A435.mintAction("ok", 0) === "keep");
  check("435 §A1: the floor is a real size, not zero — a 200 with a few bytes is not an image either",
    A435.IMAGE_MIN_BYTES >= 500);
  // 2 · ⛔ THE RETRY MUST NOT BE THE SAME URL. Re-requesting the canonical address re-reads the poisoned
  // cache entry; changing the cache key is the entire fix, and stacking busters would grow the URL forever.
  {
    const base = "https://image.pollinations.ai/prompt/x?width=512&seed=7&nologo=true";
    const b1 = A435.bustedURL(base, 1, 111), b2 = A435.bustedURL(base, 2, 222);
    const restack = A435.bustedURL(b1, 2, 222);
    check("435 §A2: a retry gets a DIFFERENT url, busters do not stack, and a plain url gains a ? not a &",
      b1 !== base && b2 !== b1 && A435.isBustedURL(b1) && !A435.isBustedURL(base)
      && (restack.match(/_cb=/g) || []).length === 1 && restack === b2
      && A435.bustedURL("https://x/y", 1, 5) === "https://x/y?_cb=5_1",
      `${b1.slice(-24)} | restack ${restack.slice(-24)}`);
  }
  // 3 · ⚠️ FORGETTING IS NOT NULLING. A null in `record.image` re-mints, but a null in a gallery row is a
  // tile with no picture — the visible half of the same bug. Keys are deleted; array members are spliced.
  {
    const BAD = "https://image.pollinations.ai/prompt/burned?seed=1";
    const save = { portrait: BAD, keep: BAD + "x", locationImages: { maw: BAD },
      npcRegistry: { p: { image: BAD, name: "P" } },
      gallery: [{ url: BAD, caption: "c" }, { url: "other" }], arr: [BAD, "no"] };
    const n = A435.forgetImageUrl(save, BAD);
    check("435 §A1: a proven-empty url is REMOVED wherever it is stored, not nulled, and lookalikes survive",
      n === 5 && !("portrait" in save) && !("maw" in save.locationImages) && !("image" in save.npcRegistry.p)
      && save.gallery.length === 1 && save.gallery[0].url === "other" && save.arr.length === 1 && save.arr[0] === "no"
      && save.keep === BAD + "x" && save.npcRegistry.p.name === "P", `dropped ${n}`);
    const cyc = { image: "Z" }; cyc.self = cyc; cyc.kid = { parent: cyc, image: "Z" };
    let m = -1; try { m = A435.forgetImageUrl(cyc, "Z"); } catch (e) { m = `threw: ${e?.message}`; }
    check("435 §A1: forgetting terminates on a save that points back at itself", m === 2, String(m));
  }
  // 4 · ⛔ THE BUSTER MAY NEVER REACH THE COMPOSITION KEY. `composeKey` hashes the deterministic PROMPT;
  // if a URL ever fed it, every retry would re-compose and Aevi's "same subject, same picture, forever"
  // would break — the exact stability rule this whole pipeline is built around.
  {
    const IP = await import("../engine/imageprompt.js");
    const prompt = "a figure in grey wool, hands stained to the wrist";
    const app435 = readFileSync(join(root, "app.js"), "utf8");
    check("435 §A2: the cache-buster cannot reach composeKey — it keys on the prompt, and the call passes the prompt",
      IP.composeKey(prompt, "npc") === IP.composeKey(prompt, "npc")
      && IP.composeKey(prompt, "npc") !== IP.composeKey(prompt + "?_cb=1_1", "npc")
      && /composeImagePrompt\(rawWords, \{ cache: character\.promptCompositions/.test(app435)
      && !/composeImagePrompt\([^)]*\.url/.test(app435));
  }
  // 5 · THE WIRING: verify BEFORE compose, spaced, and NOT behind the API key.
  {
    const app435 = readFileSync(join(root, "app.js"), "utf8");
    const drain = app435.slice(app435.indexOf("async function drainCompositions"), app435.indexOf("onComposedLookup("));
    check("435 §A/198: the queue VERIFIES, and that is the whole of its job",
      /settleMintedUrl\(job, await verifiedImageUrl\(job\.url\)\);/.test(drain),
      "a burned url must be found and healed whether or not anyone ever asks for a second draw");
    // ⛔ AND A RE-ROLL'S URL IS VERIFIED TOO — BY CONSTRUCTION, which is the better answer. CCODE-198
    // removed the hand-written verify that sat inside the automatic re-mint; what replaced it is that
    // `regenerateImage` mints through `mintURL` like everything else, so its address announces itself and
    // lands in the same queue. One path, and no second copy of the rule to drift out of step.
    {
      const art435 = readFileSync(join(root, "engine/art.js"), "utf8");
      const regen435 = art435.slice(art435.indexOf("export function regenerateImage"), art435.indexOf("export function isGeneratedImage"));
      check("435 §A/198: a re-roll mints through the announcing helper, so its url is verified like any other",
        /return \{ url: mintURL\(kind, \{/.test(regen435) && !/imageURLFor\(/.test(regen435));
    }
    // ⚠️ MATCHED WITH ITS GUARD, because the first version matched the CALL alone and stayed green with the
    // whole line wrapped in `if (false)` — asserting presence rather than use, which is the failure mode this
    // suite keeps rediscovering. It is a source-shape gate because the drain loop lives in app.js and cannot
    // be imported; that limit is real, and it is why the POLICY was extracted into art.js instead, where it
    // can be proved behaviourally.
    check("435 §A3: jobs are spaced, not merely serialized (parallel mints are what create the window)",
      /if \(_composeQueue\.length\) await sleep\(MINT_SPACING_MS\);/.test(drain)
      && /MINT_SPACING_MS = \d{4,}/.test(app435));
    // ⛔ AND THE KEY CHECK MOVED INWARDS. It used to gate the whole listener, so a player with no API key
    // queued nothing, verified nothing, and would collect burned URLs invisibly forever. Composition costs
    // money and is optional; proving the picture exists is neither.
    const listener = app435.slice(app435.indexOf("onImageMinted((job) =>"), app435.indexOf("// ---------- SNG-401"));
    // ⚠️ CCODE-198 MOVED THE KEY OUT OF THE QUEUE ENTIRELY, so the claim moves with it: the key gates
    // nothing on the path that CHECKS a picture, and the only place it can gate anything is the button a
    // player pressed. Verification stays free and unconditional; composition stays paid and asked-for.
    check("435 §A/198: no API key decision stands between a picture and the check that it exists",
      !/getApiKey\(\)/.test(listener) && !/getApiKey\(\)/.test(drain)
      && /getApiKey\(\)/.test(app435), listener.replace(/\s+/g, " ").slice(0, 120));
    // ⚠️ THE HEAL ITSELF, wherever it lives. CCODE-193 did it by rebinding `job` in the drain loop —
    // written `const job = …`, which would have thrown "Assignment to constant variable" on the FIRST poisoned
    // url, a runtime error reachable only by the bug this ticket exists to fix. CCODE-198 removed that loop,
    // so the claim follows the behaviour rather than the line: a healed address replaces the burned one
    // everywhere it is stored, and an unhealable one is forgotten.
    check("435 §A2/198: the heal swaps a burned url for the busted one that has bytes, and forgets what cannot be healed",
      /if \(good && good !== job\.url\) \{/.test(app435)
      && /swapImageUrl\(character, job\.url, good\);/.test(app435)
      && /const dropped = forgetImageUrl\(character, job\.url\);/.test(app435));
  }
}

// ---- CCODE-192: an openable news line wears no browser chrome, whatever KIND it is ----------------
// ⛔ ERIK SAW A WHITE BOX AROUND THE NEW CLASH LINES. It was the browser's own button chrome: the rules
// that strip it were scoped to `.news-death`, and SNG-431 added a second openable kind, `.news-clash`, that
// no selector ever reached. Markup emitting a class the stylesheet has no rule for is the reader-with-no-
// writer failure one layer down, and it is invisible to every engine test.
{
  const css192 = readFileSync(join(root, "style.css"), "utf8");
  const app192 = readFileSync(join(root, "app.js"), "utf8");
  // The rule that removes the chrome must be reachable by EVERY button carrying the class — so it may not
  // sit behind a kind. An unqualified `.news-open { … }` is the only shape that survives the next kind.
  // ⚠️ THE NEWLINE IS AN ESCAPE CLASS, NOT A LITERAL ONE. Writing this pattern through a python heredoc
  // turned "\n" into a real line break inside the regex literal — the same tooling hazard as the backspaces,
  // caught here only because a broken regex is a syntax error and a broken \b is invisible.
  const rule = /(?:^|[\r\n])\.news-open\s*\{([^}]*)\}/.exec(css192);
  const kindScoped = /\.news-(?:death|clash|[a-z]+)\s+\.news-open\s*\{/.test(css192);
  check("CCODE-192: the chrome-stripping rule is on .news-open itself, so a NEW openable kind is styled by construction",
    !!rule && /background:\s*none/.test(rule[1]) && /border:\s*none/.test(rule[1]) && !kindScoped,
    kindScoped ? "a kind-scoped .news-open rule is back" : `rule = ${rule ? rule[1].trim().slice(0, 70) : "ABSENT"}`);
  // ⚠️ AND THE PREMISE: the renderer really does emit more than one kind here. A gate over one kind is
  // the bug, not the guard — if this ever finds a single kind again, the check above is guarding nothing.
  const emitted = new Set([...app192.matchAll(/news-item news-\$\{[^}]*?\}/g)].length
    ? (app192.match(/n\.kind === "death" \? "([a-z]+)" : "([a-z]+)"/) || []).slice(1) : []);
  check(`CCODE-192: the news renderer emits more than one openable kind (${[...emitted].join(", ") || "none found"})`,
    emitted.size >= 2, "if this is 1, the rule above is guarding a case that cannot happen");
}

check("smoke: no checks are stranded after process.exit (dead tests report green forever)", (() => {
  const src = readFileSync(join(root, "tests/smoke.mjs"), "utf8");
  const after = src.slice(src.indexOf("process.exit(failures") + 1);
  return !/\bcheck\(/.test(after);
})());
console.log(failures === 0 ? "\nAll smoke tests passed." : `\n${failures} FAILURE(S)`);
process.exit(failures === 0 ? 0 : 1);
